public class GooglePubSubMessageConsumptionTask implements MessageConsumptionTask {

   /** Get a JBoss logging logger. */
   private final Logger logger = Logger.getLogger(getClass());

   /** The string for Regular Expression that helps validating acceptable endpoints. */
   public static final String ENDPOINT_PATTERN_STRING = "googlepubsub://(?<projectId>[a-zA-Z0-9-_]+)/(?<topic>[a-zA-Z0-9-_\\.]+)(\\?(?<options>.+))?";
   /** The Pattern for matching groups within the endpoint regular expression. */
   public static final Pattern ENDPOINT_PATTERN = Pattern.compile(ENDPOINT_PATTERN_STRING);

   private static final String CLOUD_OAUTH_SCOPE = "https://www.googleapis.com/auth/cloud-platform";

   private static final String SUBSCRIPTION_PREFIX = "-microcks-test";

   private AsyncTestSpecification specification;

   protected Map<String, String> optionsMap;

   private CredentialsProvider credentialsProvider;

   private SubscriptionName subscriptionName;

   private Subscriber subscriber;

   /**
    * Creates a new consumption task from an Async test specification.
    * @param testSpecification The specification holding endpointURL and timeout.
    */
   public GooglePubSubMessageConsumptionTask(AsyncTestSpecification testSpecification) {
      this.specification = testSpecification;
   }

   /**
    * Convenient static method for checking if this implementation will accept endpoint.
    * @param endpointUrl The endpoint URL to validate
    * @return True if endpointUrl can be used for connecting and consuming on endpoint
    */
   public static boolean acceptEndpoint(String endpointUrl) {
      return endpointUrl != null && endpointUrl.matches(ENDPOINT_PATTERN_STRING);
   }

   @Override
   public List<ConsumedMessage> call() throws Exception {
      // As initialization can be long (circa 1 sec), we have to remove this time from wait time.
      long start = System.currentTimeMillis();
      if (subscriber == null) {
         initializePubSubSubscriber();
      }
      List<ConsumedMessage> messages = new ArrayList<>();

      // Subscribe to PubSub.
      MessageReceiver receiver = (message, consumer) -> {
         logger.info("Received a new PubSub Message: " + message.getData().toStringUtf8());
         // Build a ConsumedMessage from PubSub message.
         ConsumedMessage consumedMessage = new ConsumedMessage();
         consumedMessage.setReceivedAt(System.currentTimeMillis());
         consumedMessage.setPayload(message.getData().toByteArray());
         messages.add(consumedMessage);

         consumer.ack();
      };

      // Create a new subscriber for subscription.
      subscriber = Subscriber
            .newBuilder(ProjectSubscriptionName.of(subscriptionName.getProject(), subscriptionName.getSubscription()),
                  receiver)
            .setCredentialsProvider(credentialsProvider).build();
      subscriber.startAsync().awaitRunning();

      // Wait and stop async receiver.
      Thread.sleep(specification.getTimeoutMS() - (System.currentTimeMillis() - start));
      subscriber.stopAsync();

      return messages;
   }

   @Override
   public void close() throws IOException {
      if (subscriber != null && subscriber.isRunning()) {
         subscriber.stopAsync();
      }
   }

   /** Initialize Google Pub Sub consumer from test properties. */
   private void initializePubSubSubscriber() throws Exception {
      Matcher matcher = ENDPOINT_PATTERN.matcher(specification.getEndpointUrl().trim());
      // Call matcher.find() to be able to use named expressions.
      matcher.find();

      String projectId = matcher.group("projectId");
      String topic = matcher.group("topic");
      String options = matcher.group("options");

      // Parse options if specified.
      if (options != null && !options.isBlank()) {
         optionsMap = ConsumptionTaskCommons.initializeOptionsMap(options);
      }

      // Build credential provider from secret token.
      if (specification.getSecret() != null && specification.getSecret().getToken() != null) {
         byte[] decode = Base64.getDecoder().decode(specification.getSecret().getToken());
         ByteArrayInputStream is = new ByteArrayInputStream(decode);
         credentialsProvider = FixedCredentialsProvider
               .create(GoogleCredentials.fromStream(is).createScoped(CLOUD_OAUTH_SCOPE));
      } else {
         credentialsProvider = NoCredentialsProvider.create();
      }

      // Ensure connection is possible and subscription exists.
      TopicName topicName = TopicName.of(projectId, topic);
      subscriptionName = SubscriptionName.of(projectId, topic + SUBSCRIPTION_PREFIX);

      SubscriptionAdminSettings subscriptionAdminSettings = SubscriptionAdminSettings.newBuilder()
            .setCredentialsProvider(credentialsProvider).build();
      SubscriptionAdminClient subscriptionAdminClient = SubscriptionAdminClient.create(subscriptionAdminSettings);

      try {
         subscriptionAdminClient.getSubscription(subscriptionName);
      } catch (NotFoundException nfe) {
         logger.infof("Subscription {%s} does not exist yet, creating it", subscriptionName);

         // Customize subscription to avoid retention and let google auto-cleanup it.
         // Put the durations to the minimum values accepted by Google cloud.
         Subscription subscriptionRequest = Subscription.newBuilder().setName(subscriptionName.toString())
               .setTopic(topicName.toString()).setPushConfig(PushConfig.getDefaultInstance()).setAckDeadlineSeconds(10)
               .setRetainAckedMessages(false).setMessageRetentionDuration(Duration.newBuilder().setSeconds(600).build())
               .setExpirationPolicy(
                     ExpirationPolicy.newBuilder().setTtl(Duration.newBuilder().setSeconds(24 * 3600L)).build())
               .setEnableMessageOrdering(false).setEnableExactlyOnceDelivery(false).build();
         subscriptionAdminClient.createSubscription(subscriptionRequest);
      } finally {
         subscriptionAdminClient.close();
      }
   }
}

public class KafkaMessageConsumptionTask implements MessageConsumptionTask {

   /** Get a JBoss logging logger. */
   private final Logger logger = Logger.getLogger(getClass());

   /** The string for Regular Expression that helps validating acceptable endpoints. */
   public static final String ENDPOINT_PATTERN_STRING = "kafka://(?<brokerUrl>[^:]+(:\\d+)?)/(?<topic>[a-zA-Z0-9-_\\.]+)(\\?(?<options>.+))?";
   /** The Pattern for matching groups within the endpoint regular expression. */
   public static final Pattern ENDPOINT_PATTERN = Pattern.compile(ENDPOINT_PATTERN_STRING);

   /** The endpoint URL option representing schema registry URL. */
   public static final String REGISTRY_URL_OPTION = "registryUrl";
   /** The endpoint URL option representing schema registry username. */
   public static final String REGISTRY_USERNAME_OPTION = "registryUsername";
   /** The endpoint URL option representing schema registry auth credentials source. */
   public static final String REGISTRY_AUTH_CREDENTIALS_SOURCE = "registryAuthCredSource";

   /** The endpoint URL option representing the offset we should start consume from. */
   public static final String START_OFFSET = "startOffset";
   /** The endpoint URL option representing the offset whe should end consumer to. */
   public static final String END_OFFSET = "endOffset";

   private File trustStore;

   private AsyncTestSpecification specification;

   protected Map<String, String> optionsMap;

   protected KafkaConsumer<String, byte[]> consumer;

   protected KafkaConsumer<String, GenericRecord> avroConsumer;

   protected Long startOffset;
   protected Long endOffset;


   /**
    * Create a new consumption task from an Async test specification.
    * @param testSpecification The specification holding endpointURL and timeout.
    */
   public KafkaMessageConsumptionTask(AsyncTestSpecification testSpecification) {
      this.specification = testSpecification;
   }

   /**
    * Convenient static method for checking if this implementation will accept endpoint.
    * @param endpointUrl The endpoint URL to validate
    * @return True if endpointUrl can be used for connecting and consuming on endpoint
    */
   public static boolean acceptEndpoint(String endpointUrl) {
      return endpointUrl != null && endpointUrl.matches(ENDPOINT_PATTERN_STRING);
   }

   @Override
   public List<ConsumedMessage> call() throws Exception {
      if (consumer == null && avroConsumer == null) {
         initializeKafkaConsumer();
      }
      List<ConsumedMessage> messages = new ArrayList<>();

      // Start polling with appropriate consumer for records.
      // Do not forget to close the consumer before returning results.
      if (consumer != null) {
         consumeByteArray(messages);
         consumer.close();
      } else {
         consumeAvro(messages);
         avroConsumer.close();
      }
      return messages;
   }

   /**
    * Close the resources used by this task. Namely the Kafka consumer(s) and the optionally created truststore holding
    * Kafka client SSL credentials.
    * @throws IOException should not happen.
    */
   @Override
   public void close() throws IOException {
      if (consumer != null) {
         consumer.close();
      }
      if (avroConsumer != null) {
         avroConsumer.close();
      }
      if (trustStore != null && trustStore.exists()) {
         Files.delete(trustStore.toPath());
      }
   }

   /** Initialize Kafka consumer from built properties and subscribe to target topic. */
   private void initializeKafkaConsumer() {
      Matcher matcher = ENDPOINT_PATTERN.matcher(specification.getEndpointUrl().trim());
      // Call matcher.find() to be able to use named expressions.
      matcher.find();
      String endpointBrokerUrl = matcher.group("brokerUrl");
      String endpointTopic = matcher.group("topic");
      String options = matcher.group("options");

      // Parse options if specified.
      if (options != null && !options.isBlank()) {
         optionsMap = ConsumptionTaskCommons.initializeOptionsMap(options);
      }

      Properties props = new Properties();
      props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, endpointBrokerUrl);

      // Generate a unique GroupID for no collision with previous or other consumers.
      props.put(ConsumerConfig.GROUP_ID_CONFIG, specification.getTestResultId() + "-" + System.currentTimeMillis());
      props.put(ConsumerConfig.CLIENT_ID_CONFIG, "microcks-async-minion-test");

      props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());

      // Value deserializer depends on schema registry presence.
      if (hasOption(REGISTRY_URL_OPTION)) {
         props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, KafkaAvroDeserializer.class.getName());
         props.put(AbstractKafkaSchemaSerDeConfig.SCHEMA_REGISTRY_URL_CONFIG, optionsMap.get(REGISTRY_URL_OPTION));
         // Configure schema registry credentials if any.
         if (hasOption(REGISTRY_USERNAME_OPTION) || hasOption(REGISTRY_AUTH_CREDENTIALS_SOURCE)) {
            props.put(AbstractKafkaSchemaSerDeConfig.USER_INFO_CONFIG, optionsMap.get(REGISTRY_USERNAME_OPTION));
            props.put(AbstractKafkaSchemaSerDeConfig.BASIC_AUTH_CREDENTIALS_SOURCE,
                  optionsMap.get(REGISTRY_AUTH_CREDENTIALS_SOURCE));
         }
      } else {
         props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, ByteArrayDeserializer.class.getName());
      }

      // Only retrieve incoming messages and do not persist offset.
      props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "latest");
      props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, false);

      if (specification.getSecret() != null && specification.getSecret().getCaCertPem() != null) {
         try {
            // Because Kafka Java client does not support any other sources for SSL configuration,
            // we need to create a Truststore holding the secret certificate and credentials. See below:
            // https://cwiki.apache.org/confluence/display/KAFKA/KIP-486%3A+Support+custom+way+to+load+KeyStore+and+TrustStore
            trustStore = ConsumptionTaskCommons.installBrokerCertificate(specification);

            // Then we have to add SSL specific properties.
            props.put("security.protocol", "SSL");
            props.put(SslConfigs.SSL_TRUSTSTORE_LOCATION_CONFIG, trustStore.getAbsolutePath());
            props.put(SslConfigs.SSL_TRUSTSTORE_PASSWORD_CONFIG, ConsumptionTaskCommons.TRUSTSTORE_PASSWORD);
         } catch (Exception e) {
            logger.error("Exception while installing custom truststore: " + e.getMessage());
         }
      }

      instanciateKafkaConsumer(props, endpointTopic);
   }

   private void instanciateKafkaConsumer(Properties props, String endpointTopic) {
      if (hasOption(START_OFFSET)) {
         try {
            startOffset = Long.parseLong(optionsMap.get(START_OFFSET));
         } catch (NumberFormatException nfe) {
            logger.warnf("The startOffset endpoint option {%s} is not a Long", optionsMap.get(START_OFFSET));
         }
      }
      if (hasOption(END_OFFSET)) {
         try {
            endOffset = Long.parseLong(optionsMap.get(END_OFFSET));
         } catch (NumberFormatException nfe) {
            logger.warnf("The endOffset endpoint option {%s} is not a Long", optionsMap.get(END_OFFSET));
         }
      }

      // Create the consumer from properties and subscribe to given topic.
      if (hasOption(REGISTRY_URL_OPTION)) {
         avroConsumer = new KafkaConsumer<>(props);
         avroConsumer.subscribe(Arrays.asList(endpointTopic), new StartOffsetSeeker());
      } else {
         consumer = new KafkaConsumer<>(props);
         consumer.subscribe(Arrays.asList(endpointTopic), new StartOffsetSeeker());
      }
   }

   /**
    * Safe method for checking if an option has been set.
    * @param optionKey Check if that option is available in options map.
    * @return true if option is present, false if undefined.
    */
   protected boolean hasOption(String optionKey) {
      if (optionsMap != null) {
         return optionsMap.containsKey(optionKey);
      }
      return false;
   }

   /** Consume simple byte[] on default consumer. Fill messages array. */
   private void consumeByteArray(List<ConsumedMessage> messages) {
      long startTime = System.currentTimeMillis();
      long timeoutTime = startTime + specification.getTimeoutMS();

      while (System.currentTimeMillis() - startTime < specification.getTimeoutMS()) {
         ConsumerRecords<String, byte[]> records = consumer
               .poll(Duration.ofMillis(timeoutTime - System.currentTimeMillis()));

         boolean oufOfOffsetRange = false;
         for (ConsumerRecord<String, byte[]> consumerRecord : records) {
            // Check current offset if a limit was set.
            if (endOffset != null && consumerRecord.offset() > endOffset) {
               oufOfOffsetRange = true;
               break;
            }
            // Build a ConsumedMessage from Kafka record.
            ConsumedMessage message = new ConsumedMessage();
            message.setReceivedAt(System.currentTimeMillis());
            message.setHeaders(buildHeaders(consumerRecord.headers()));
            message.setPayload(consumerRecord.value());
            messages.add(message);
         }
         // Exit main waiting loop if we reach the end.
         if (oufOfOffsetRange) {
            break;
         }
      }
   }

   /** Consumer avro records when connected to registry. Fill messages array. */
   private void consumeAvro(List<ConsumedMessage> messages) {
      long startTime = System.currentTimeMillis();
      long timeoutTime = startTime + specification.getTimeoutMS();

      while (System.currentTimeMillis() - startTime < specification.getTimeoutMS()) {
         ConsumerRecords<String, GenericRecord> records = avroConsumer
               .poll(Duration.ofMillis(timeoutTime - System.currentTimeMillis()));

         boolean oufOfOffsetRange = false;
         for (ConsumerRecord<String, GenericRecord> consumerRecord : records) {
            // Check current offset if a limit was set.
            if (endOffset != null && consumerRecord.offset() > endOffset) {
               oufOfOffsetRange = true;
               break;
            }
            // Build a ConsumedMessage from Kafka record.
            ConsumedMessage message = new ConsumedMessage();
            message.setReceivedAt(System.currentTimeMillis());
            message.setHeaders(buildHeaders(consumerRecord.headers()));
            message.setPayloadRecord(consumerRecord.value());
            messages.add(message);
         }
         // Exit main waiting loop if we reach the end.
         if (oufOfOffsetRange) {
            break;
         }
      }
   }

   /** Build set of Microcks headers from Kafka headers. */
   private Set<Header> buildHeaders(Headers headers) {
      Set<Header> results = new HashSet<>();
      if (headers == null || !headers.iterator().hasNext()) {
         return results;
      }
      Iterator<org.apache.kafka.common.header.Header> headersIterator = headers.iterator();
      while (headersIterator.hasNext()) {
         org.apache.kafka.common.header.Header header = headersIterator.next();
         Header result = new Header();
         result.setName(header.key());
         result.setValues(Set.of(new String(header.value())));
         results.add(result);
      }
      return results;
   }

   private class StartOffsetSeeker implements ConsumerRebalanceListener {
      @Override
      public void onPartitionsRevoked(Collection<TopicPartition> partitions) {
         // Nothing to do on revocation.
      }

      @Override
      public void onPartitionsAssigned(Collection<TopicPartition> partitions) {
         if (startOffset != null) {
            partitions.forEach(p -> {
               if (consumer != null) {
                  consumer.seek(p, startOffset);
               }
               if (avroConsumer != null) {
                  avroConsumer.seek(p, startOffset);
               }
            });
         }
      }
   }
}

public class MQTTMessageConsumptionTask implements MessageConsumptionTask {

   /** Get a JBoss logging logger. */
   private final Logger logger = Logger.getLogger(getClass());

   /** The string for Regular Expression that helps validating acceptable endpoints. */
   public static final String ENDPOINT_PATTERN_STRING = "mqtt://(?<brokerUrl>[^:]+(:\\d+)?)/(?<topic>.+)(\\?(?<options>.+))?";
   /** The Pattern for matching groups within the endpoint regular expression. */
   public static final Pattern ENDPOINT_PATTERN = Pattern.compile(ENDPOINT_PATTERN_STRING);

   private File trustStore;

   private final AsyncTestSpecification specification;

   private IMqttClient subscriber;

   private String endpointTopic;

   private String options;

   /**
    * Create a new consumption task from an Async test specification.
    * @param testSpecification The specification holding endpointURL and timeout.
    */
   public MQTTMessageConsumptionTask(AsyncTestSpecification testSpecification) {
      this.specification = testSpecification;
   }

   /**
    * Convenient static method for checking if this implementation will accept endpoint.
    * @param endpointUrl The endpoint URL to validate
    * @return True if endpointUrl can be used for connecting and consuming on endpoint
    */
   public static boolean acceptEndpoint(String endpointUrl) {
      return endpointUrl != null && endpointUrl.matches(ENDPOINT_PATTERN_STRING);
   }

   @Override
   public List<ConsumedMessage> call() throws Exception {
      if (subscriber == null) {
         intializeMQTTClient();
      }
      List<ConsumedMessage> messages = new ArrayList<>();

      // Start subscribing to the server endpoint topic.
      subscriber.subscribe(endpointTopic, (topic, mqttMessage) -> {
         logger.info("Received a new MQTT Message: " + new String(mqttMessage.getPayload()));
         // Build a ConsumedMessage from MQTT message.
         ConsumedMessage message = new ConsumedMessage();
         message.setReceivedAt(System.currentTimeMillis());
         message.setPayload(mqttMessage.getPayload());
         messages.add(message);
      });

      Thread.sleep(specification.getTimeoutMS());

      // Disconnect the subscriber before returning results.
      subscriber.disconnect();
      return messages;
   }

   /**
    * Close the resources used by this task. Namely the MQTT subscriber and the optionally created truststore holding
    * server client SSL credentials.
    * @throws IOException should not happen.
    */
   @Override
   public void close() throws IOException {
      if (subscriber != null) {
         try {
            subscriber.close();
         } catch (MqttException e) {
            logger.warn("Closing MQTT subscriber raised an exception", e);
         }
      }
      if (trustStore != null && trustStore.exists()) {
         Files.delete(trustStore.toPath());
      }
   }

   /** */
   private void intializeMQTTClient() throws Exception {
      Matcher matcher = ENDPOINT_PATTERN.matcher(specification.getEndpointUrl().trim());
      // Call matcher.find() to be able to use named expressions.
      matcher.find();
      String endpointBrokerUrl = matcher.group("brokerUrl");
      endpointTopic = matcher.group("topic");
      options = matcher.group("options");

      MqttConnectOptions connectOptions = new MqttConnectOptions();
      connectOptions.setAutomaticReconnect(false);
      connectOptions.setCleanSession(true);
      connectOptions.setConnectionTimeout(10);

      // Initialize default protocol pragma for connection string.
      String protocolPragma = "tcp://";

      if (specification.getSecret() != null) {
         if (specification.getSecret().getUsername() != null && specification.getSecret().getPassword() != null) {
            logger.debug("Adding username/password authentication from secret " + specification.getSecret().getName());
            connectOptions.setUserName(specification.getSecret().getUsername());
            connectOptions.setPassword(specification.getSecret().getPassword().toCharArray());
         }

         if (specification.getSecret().getCaCertPem() != null) {
            logger.debug("Installing a broker certificate from secret " + specification.getSecret().getName());
            trustStore = ConsumptionTaskCommons.installBrokerCertificate(specification);

            // Find the list of SSL properties here:
            // https://www.eclipse.org/paho/files/javadoc/org/eclipse/paho/client/mqttv3/MqttConnectOptions.html#setSSLProperties-java.util.Properties-
            Properties sslProperties = new Properties();
            sslProperties.put("com.ibm.ssl.trustStore", trustStore.getAbsolutePath());
            sslProperties.put("com.ibm.ssl.trustStorePassword", ConsumptionTaskCommons.TRUSTSTORE_PASSWORD);
            sslProperties.put("com.ibm.ssl.trustStoreType", "JKS");
            connectOptions.setSSLProperties(sslProperties);

            // We also have to change the prococolPragma to ssl://
            protocolPragma = "ssl://";
         }
      }

      // Create the subscriber and connect it to server using the properties.
      // Generate a unique clientId for each publication to avoid collisions (cleanSession is true).
      subscriber = new MqttClient(protocolPragma + endpointBrokerUrl,
            "microcks-async-minion-test-" + System.currentTimeMillis());
      subscriber.connect(connectOptions);
   }
}

public class WebSocketMessageConsumptionTask implements MessageConsumptionTask {

   /** Get a JBoss logging logger. */
   private final Logger logger = Logger.getLogger(getClass());

   /** The string for Regular Expression that helps validating acceptable endpoints. */
   public static final String ENDPOINT_PATTERN_STRING = "ws://(?<wsHost>[^:]+(:\\d+)?)/(?<channel>.*)(\\?(?<options>.+))?";
   /** The Pattern for matching groups within the endpoint regular expression. */
   public static final Pattern ENDPOINT_PATTERN = Pattern.compile(ENDPOINT_PATTERN_STRING);

   private File trustStore;

   private AsyncTestSpecification specification;

   private Session session;

   /**
    * Create a new consumption task from an Async test specification.
    * @param testSpecification The specification holding endpointURL and timeout.
    */
   public WebSocketMessageConsumptionTask(AsyncTestSpecification testSpecification) {
      this.specification = testSpecification;
   }

   /**
    * Convenient static method for checking if this implementation will accept endpoint.
    * @param endpointUrl The endpoint URL to validate
    * @return True if endpointUrl can be used for connecting and consuming on endpoint
    */
   public static boolean acceptEndpoint(String endpointUrl) {
      return endpointUrl != null && endpointUrl.matches(ENDPOINT_PATTERN_STRING);
   }

   @Override
   public List<ConsumedMessage> call() throws Exception {
      WebSocketClient client = new WebSocketClient();
      try {
         WebSocketContainer container = ContainerProvider.getWebSocketContainer();

         if (specification.getSecret() != null && specification.getSecret().getCaCertPem() != null) {
            // We neet to create a Truststore holding secret certificxate.
            trustStore = ConsumptionTaskCommons.installBrokerCertificate(specification);

            SSLContext sslContext = SSLContexts.custom()
                  .loadTrustMaterial(trustStore, ConsumptionTaskCommons.TRUSTSTORE_PASSWORD.toCharArray(), null)
                  .build();

            // Then configure the Client Endpoint using a property specific to Undertow impl (from Quarkus).
            ClientEndpointConfig config = ClientEndpointConfig.Builder.create().build();
            config.getUserProperties().put("io.undertow.websocket.SSL_CONTEXT", sslContext);

            // Then connect replacing ws:// by wss://
            session = container.connectToServer(client, config,
                  URI.create(specification.getEndpointUrl().replace("ws://", "wss://")));
         } else {
            // Simply connect to plain text WebSocket...
            session = container.connectToServer(client, URI.create(specification.getEndpointUrl()));
         }
      } catch (Exception e) {
         logger.errorf("Connection error while try to reach {%s}", specification.getEndpointUrl());
         throw e;
      }

      Thread.sleep(specification.getTimeoutMS());
      if (session != null) {
         try {
            session.close();
         } catch (Exception e) {
            logger.info("Exception while closing the WebSocket session: " + e.getMessage());
         }
      }
      return client.getMessages();
   }

   /**
    * Close the resources used by this task. Namely the WS client session and the optionally created truststore holding
    * server client SSL credentials.
    * @throws IOException should not happen.
    */
   @Override
   public void close() throws IOException {
      if (session != null) {
         try {
            session.close();
         } catch (Exception e) {
            logger.warn("Closing WebSocket session raised an exception", e);
         }
      }
      if (trustStore != null && trustStore.exists()) {
         trustStore.delete();
      }
   }
}

public class NATSMessageConsumptionTask implements MessageConsumptionTask {

   /**
    * Get a JBoss logging logger.
    */
   private final Logger logger = Logger.getLogger(getClass());

   /**
    * The string for Regular Expression that helps validating acceptable endpoints.
    */
   public static final String ENDPOINT_PATTERN_STRING = "nats://(?<brokerUrl>[^:]+(:\\d+)?)/(?<topic>.+)";

   /**
    * The Pattern for matching groups within the endpoint regular expression.
    */
   public static final Pattern ENDPOINT_PATTERN = Pattern.compile(ENDPOINT_PATTERN_STRING);

   private AsyncTestSpecification specification;

   private Connection subscriber;

   private String endpointTopic;

   private String options;

   /**
    * Create a new consumption task from an Async test specification.
    * @param testSpecification The specification holding endpointURL and timeout.
    */
   public NATSMessageConsumptionTask(AsyncTestSpecification testSpecification) {
      this.specification = testSpecification;
   }

   /**
    * Convenient static method for checking if this implementation will accept endpoint.
    * @param endpointUrl The endpoint URL to validate
    * @return True if endpointUrl can be used for connecting and consuming on endpoint
    */
   public static boolean acceptEndpoint(String endpointUrl) {
      return endpointUrl != null && endpointUrl.matches(ENDPOINT_PATTERN_STRING);
   }

   @Override
   public List<ConsumedMessage> call() throws Exception {
      if (subscriber == null) {
         intializeNATSClient();
      }
      List<ConsumedMessage> messages = new ArrayList<>();

      // Start subscribing to the broker endpoint topic.
      Dispatcher d = subscriber.createDispatcher((msg) -> {
         String msgString = new String(msg.getData(), StandardCharsets.UTF_8);
         logger.info("Received a new NATS Message: " + msgString);
         // Build a ConsumedMessage from NATS message.
         ConsumedMessage message = new ConsumedMessage();
         message.setReceivedAt(System.currentTimeMillis());
         message.setHeaders(buildHeaders(msg.getHeaders()));
         message.setPayload(msg.getData());
         messages.add(message);
      });

      d.subscribe(endpointTopic);

      Thread.sleep(specification.getTimeoutMS());

      // Disconnect the subscriber before returning results.
      subscriber.close();
      return messages;
   }

   /** Build set of Microcks headers from NATS headers. */
   private Set<Header> buildHeaders(Headers headers) {
      if (headers == null || headers.isEmpty()) {
         return null;
      }
      Set<Header> results = new HashSet<>();
      for (Map.Entry<String, List<String>> entry : headers.entrySet()) {
         Header result = new Header();
         result.setName(entry.getKey());
         result.setValues(new HashSet<>(entry.getValue()));
         results.add(result);
      }
      return results;
   }

   /**
    * Close the resources used by this task. Namely the NATS subscriber and the option truststore.
    * @throws IOException should not happen.
    */
   @Override
   public void close() throws IOException {
      if (subscriber != null) {
         try {
            subscriber.close();
         } catch (InterruptedException e) {
            logger.warn("Closing NATS subscriber raised an exception", e);
         }
      }
   }

   private void intializeNATSClient() throws Exception {
      Matcher matcher = ENDPOINT_PATTERN.matcher(specification.getEndpointUrl().trim());
      // Call matcher.find() to be able to use named expressions.
      matcher.find();
      String endpointBrokerUrl = matcher.group("brokerUrl");
      endpointTopic = matcher.group("topic");

      Options.Builder optionsBuilder = new Options.Builder().server(endpointBrokerUrl).maxReconnects(10);

      if (specification.getSecret() != null) {
         if (specification.getSecret().getUsername() != null && specification.getSecret().getPassword() != null) {
            logger.debug("Adding username/password authentication from secret " + specification.getSecret().getName());
            optionsBuilder.userInfo(specification.getSecret().getUsername(), specification.getSecret().getPassword());
         } else if (specification.getSecret().getToken() != null) {
            logger.debug("Adding token authentication from secret " + specification.getSecret().getName());
            optionsBuilder.token(specification.getSecret().getToken().toCharArray());
         }
      }
      subscriber = Nats.connect(optionsBuilder.build());
   }
}

public class SchemaMap {

   /** The internal map backing schemas storage. This is an in-memory map. */
   private Map<String, String> schemaEntries;

   /** Build a new schema map with empty content. */
   public SchemaMap() {
      schemaEntries = new HashMap<>();
   }

   /**
    * Initialize a new schema map with provided content.
    * @param schemaEntries Map of schema entries. Keys are schema paths, Values are schema string representation.
    */
   public SchemaMap(Map<String, String> schemaEntries) {
      this.schemaEntries = schemaEntries;
   }

   /**
    * Put a new schema entry in map.
    * @param schemaPath The path of this new entry.
    * @param content    The string representation of schema content
    */
   public void putSchemaEntry(String schemaPath, String content) {
      schemaEntries.put(schemaPath, content);
   }

   /**
    * Check if we've got an entry for this schema path.
    * @param schemaPath The path of searched entry.
    * @return True if we've got a corresponding entry, false otherwise.
    */
   public boolean hasSchemaEntry(String schemaPath) {
      return schemaEntries.containsKey(schemaPath);
   }

   /**
    * Get schema entry string content.
    * @param schemaPath The path of searched entry.
    * @return The string representation of schema content
    */
   public String getSchemaEntry(String schemaPath) {
      return schemaEntries.get(schemaPath);
   }
}

public class AsyncAPISchemaUtil {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(AsyncAPISchemaUtil.class);

   public static final String ASYNC_SCHEMA_PAYLOAD_ELEMENT = "payload";
   private static final String ONE_OF_STRUCT = "oneOf";


   /** Private constructor to hide the implicit one. */
   private AsyncAPISchemaUtil() {
   }

   /** Define the JSON pointer expression to access the operation messages. */
   public static String findMessagePathPointer(JsonNode specificationNode, String operationName) {
      String messagePathPointer = "";
      String[] operationElements = operationName.split(" ");

      String asyncApi = specificationNode.path("asyncapi").asText("2");
      if (asyncApi.startsWith("3")) {
         // Assume we have an AsyncAPI v3 document.
         String operationNamePtr = "/operations/" + operationElements[1].replace("/", "~1");
         messagePathPointer = operationNamePtr + "/messages";
      } else {
         // Assume we have an AsyncAPI v2 document.
         String operationNamePtr = "/channels/" + operationElements[1].replace("/", "~1");
         if ("SUBSCRIBE".equals(operationElements[0])) {
            operationNamePtr += "/subscribe";
         } else {
            operationNamePtr += "/publish";
         }
         messagePathPointer = operationNamePtr + "/message";
      }
      return messagePathPointer;
   }

   /**
    * Retrieve the Avro schema corresponding to a message using its JSON pointer in Spec. Complete the {@code schemaMap}
    * if provided. Raise a simple exception with message if problem while navigating the spec.
    */
   public static Schema retrieveMessageAvroSchema(JsonNode specificationNode, String messagePathPointer,
         SchemaMap schemaMap) throws Exception {
      // Extract Json node for message pointer.
      JsonNode messageNode = specificationNode.at(messagePathPointer);
      if (messageNode == null || messageNode.isMissingNode()) {
         log.debug("messagePathPointer {} is not a valid JSON Pointer", messagePathPointer);
         throw new Exception("messagePathPointer does not represent a valid JSON Pointer in AsyncAPI specification");
      }
      // Message node can be just a reference.
      messageNode = followRefIfAny(messageNode, specificationNode);

      if (messageNode.isArray()) {
         // In the case of AsyncAPI v3, we always got messages even if there's just one element.
         // Wrapping them in oneOf, make us lose details on validation errors so just do it if necessary.
         ArrayNode messagesNode = (ArrayNode) messageNode;
         if (messagesNode.size() > 1) {
            return buildOneOfMessagesAvroSchemas(specificationNode, (ArrayNode) messageNode, schemaMap);
         }
         return buildSingleMessageAvroSchema(followRefIfAny(messagesNode.get(0), specificationNode), schemaMap);
      } else if (messageNode.has(ONE_OF_STRUCT)) {
         ArrayNode oneOfMessageNode = (ArrayNode) messageNode.get(ONE_OF_STRUCT);
         return buildOneOfMessagesAvroSchemas(specificationNode, oneOfMessageNode, schemaMap);
      } else {
         return buildSingleMessageAvroSchema(messageNode, schemaMap);
      }
   }

   /** Build an array of Avro schemas for messages expressed as a direct oneOf structure. */
   private static Schema buildOneOfMessagesAvroSchemas(JsonNode specificationNode, ArrayNode oneOfMessageNode,
         SchemaMap schemaMap) throws Exception {
      // Initialize a oneOf schema with array.
      Schema[] schemas = new Schema[oneOfMessageNode.size()];

      // Extract the schema payload for each alternative of the message.
      for (int i = 0; i < oneOfMessageNode.size(); i++) {
         JsonNode altMessageNode = oneOfMessageNode.get(i);
         // Extract a schema for each messages
         altMessageNode = followRefIfAny(altMessageNode, specificationNode);
         schemas[i] = buildSingleMessageAvroSchema(altMessageNode, schemaMap);
      }

      return Schema.createUnion(schemas);
   }

   /** Build an Avro schema for spring message definition. */
   private static Schema buildSingleMessageAvroSchema(JsonNode messageNode, SchemaMap schemaMap) throws Exception {
      // Check that message node has a payload attribute.
      if (!messageNode.has(ASYNC_SCHEMA_PAYLOAD_ELEMENT)) {
         log.debug("messageNode {} has no 'payload' attribute", messageNode);
         throw new Exception("message definition has no valid payload in AsyncAPI specification");
      }

      // Navigate to payload definition.
      messageNode = messageNode.path(ASYNC_SCHEMA_PAYLOAD_ELEMENT);

      // Payload node can be just a reference to another schema... But in the case of Avro, this is an external schema
      // as #/components/schemas can only hold JSON schemas. So we have to use a registry for resolving and accessing
      // this Avro schema. We'll have to build an Avro Schema either from payload content or registry content.
      String schemaContent = null;

      if (messageNode.has("$ref")) {
         // Remove trailing anchor marker if any.
         // './user-signedup.avsc#/User' => './user-signedup.avsc'
         String ref = messageNode.path("$ref").asText();
         log.debug("Looking for an external Avro schema in registry: {}", ref);
         if (ref.contains("#")) {
            ref = ref.substring(0, ref.indexOf("#"));
         }
         if (schemaMap != null) {
            schemaContent = schemaMap.getSchemaEntry(ref);
         }
         if (schemaContent == null) {
            log.info("No schema content found in SchemaMap. {} is not found", ref);
            throw new Exception("no schema content found for " + ref + " in used SchemaMap.");
         }
      } else {
         // Schema is specified within the payload definition.
         schemaContent = messageNode.toString();
      }

      // Now build and return the schema.
      return AvroUtil.getSchema(schemaContent);
   }

   /** Check if a node has a reference and follow it to target node in the document. */
   public static JsonNode followRefIfAny(JsonNode referencableNode, JsonNode documentRoot) {
      if (referencableNode.has("$ref")) {
         String ref = referencableNode.path("$ref").asText();
         return followRefIfAny(documentRoot.at(ref.substring(1)), documentRoot);
      }
      return referencableNode;
   }
}

public class AsyncAPISchemaValidator {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(AsyncAPISchemaValidator.class);

   public static final String ASYNC_SCHEMA_PAYLOAD_ELEMENT = "payload";

   private static final String ONE_OF_STRUCT = "oneOf";
   private static final String[] STRUCTURES = { "allOf", "anyOf", ONE_OF_STRUCT, "not", "items",
         "additionalProperties" };
   private static final String[] NOT_SUPPORTED_ATTRIBUTES = { "discriminator", "externalDocs", "deprecated" };


   /** Private constructor to hide the implicit one. */
   private AsyncAPISchemaValidator() {
   }

   /**
    * Check if a Json object is valid against the given AsyncAPI schema specification.
    * @param schemaText The AsyncAPI schema specification as a string
    * @param jsonText   The Json object as a string
    * @return True if Json object is valid, false otherwise
    * @throws IOException if string representations cannot be parsed
    */
   public static boolean isJsonValid(String schemaText, String jsonText) throws IOException {
      List<String> errors = validateJson(schemaText, jsonText);
      if (!errors.isEmpty()) {
         log.debug("Get validation errors, returning false");
         return false;
      }
      return true;
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of AsyncAPI schema
    * spec semantics regarding additional or unknown attributes: schema must explicitely set
    * <code>additionalProperties</code> to false if you want to consider unknown attributes as validation errors. It
    * returns a list of validation error messages.
    * @param schemaText The AsyncAPI schema specification as a string
    * @param jsonText   The Json object as a string
    * @return The list of validation failures. If empty, json object is valid !
    * @throws IOException if json string representations cannot be parsed
    */
   public static List<String> validateJson(String schemaText, String jsonText) throws IOException {
      return validateJson(getJsonNodeForSchema(schemaText), JsonSchemaValidator.getJsonNode(jsonText));
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of AsyncAPI schema
    * spec semantics regarding additional or unknown attributes: schema must explicitely set
    * <code>additionalProperties</code> to false if you want to consider unknown attributes as validation errors. It
    * returns a list of validation error messages.
    * @param schemaNode The AsyncAPI schema specification as a Jackson node
    * @param jsonNode   The Json object as a Jackson node
    * @return The list of validation failures. If empty, json object is valid !
    */
   public static List<String> validateJson(JsonNode schemaNode, JsonNode jsonNode) {
      return validateJson(schemaNode, jsonNode, null);
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of AsyncAPI schema
    * spec semantics regarding additional or unknown attributes: schema must explicitely set
    * <code>additionalProperties</code> to false if you want to consider unknown attributes as validation errors. It
    * returns a list of validation error messages.
    * @param schemaNode The AsyncAPI schema specification as a Jackson node
    * @param jsonNode   The Json object as a Jackson node
    * @param namespace  Namespace definition to resolve relative dependencies in Json schema
    * @return The list of validation failures. If empty, json object is valid !
    */
   public static List<String> validateJson(JsonNode schemaNode, JsonNode jsonNode, String namespace) {
      schemaNode = convertAsyncAPISchemaToJsonSchema(schemaNode);
      return JsonSchemaValidator.validateJson(schemaNode, jsonNode, namespace);
   }

   /**
    * Validate a Json object representing an AsyncAPI message against a node representing a full AsyncAPI specification
    * (and not just a schema node). Specify the message by providing a valid JSON pointer for {@code messagePathPointer}
    * to allow finding the correct schema information. Validation is a deep one: its pursue checking children nodes on a
    * failed parent. Validation is respectful of AsyncAPI schema spec semantics regarding additional or unknown
    * attributes: schema must explicitly set {@code additionalProperties} to false if you want to consider unknown
    * attributes as validation errors. It returns a list of validation error messages.
    * @param specificationNode  The AsyncAPI full specification as a Jackson node
    * @param jsonNode           The Json object representing actual message as a Jackson node
    * @param messagePathPointer A JSON Pointer for accessing expected message definition within spec
    * @return The list of validation failures. If empty, json object is valid !
    */
   public static List<String> validateJsonMessage(JsonNode specificationNode, JsonNode jsonNode,
         String messagePathPointer) {
      return validateJsonMessage(specificationNode, jsonNode, messagePathPointer, null);
   }

   /**
    * Validate a Json object representing an AsyncAPI message against a node representing a full AsyncAPI specification
    * (and not just a schema node). Specify the message by providing a valid JSON pointer for {@code messagePathPointer}
    * to allow finding the correct schema information. Validation is a deep one: its pursue checking children nodes on a
    * failed parent. Validation is respectful of AsyncAPI schema spec semantics regarding additional or unknown
    * attributes: schema must explicitly set {@code additionalProperties} to false if you want to consider unknown
    * attributes as validation errors. It returns a list of validation error messages.
    * @param specificationNode  The AsyncAPI full specification as a Jackson node
    * @param jsonNode           The Json object representing actual message as a Jackson node
    * @param messagePathPointer A JSON Pointer for accessing expected message definition within spec
    * @param namespace          Namespace definition to resolve relative dependencies in OpenAPI schema
    * @return The list of validation failures. If empty, json object is valid !
    */
   public static List<String> validateJsonMessage(JsonNode specificationNode, JsonNode jsonNode,
         String messagePathPointer, String namespace) {
      // Extract specific content type node for message node.
      JsonNode messageNode = specificationNode.at(messagePathPointer);
      if (messageNode == null || messageNode.isMissingNode()) {
         log.debug("messagePathPointer {} is not a valid JSON Pointer", messagePathPointer);
         return List.of("messagePathPointer does not represent a valid JSON Pointer in AsyncAPI specification");
      }
      // Message node can be just a reference.
      messageNode = followRefIfAny(messageNode, specificationNode);

      // We need to build a node holding schema information.
      JsonNode schemaNode = null;
      try {
         if (messageNode.isArray()) {
            // In the case of AsyncAPI v3, we always got messages even if there's just one element.
            // Wrapping them in oneOf, make us lose details on validation errors so just do it if necessary.
            ArrayNode messagesNode = (ArrayNode) messageNode;
            if (messagesNode.size() > 1) {
               schemaNode = buildOneOfMessageSchemaNode(specificationNode, (ArrayNode) messageNode);
            } else {
               schemaNode = retrieveSingleMessageSchemaNode(specificationNode,
                     followRefIfAny(messagesNode.get(0), specificationNode));
            }
         } else if (messageNode.has(ONE_OF_STRUCT)) {
            ArrayNode oneOfMessageNode = (ArrayNode) messageNode.get(ONE_OF_STRUCT);
            schemaNode = buildOneOfMessageSchemaNode(specificationNode, oneOfMessageNode);
         } else {
            schemaNode = retrieveSingleMessageSchemaNode(specificationNode, messageNode);
         }
      } catch (Exception e) {
         // Just return exception message as validation message.
         return Collections.singletonList(e.getMessage());
      }
      // Import all the common parts that may be referenced by references.
      ((ObjectNode) schemaNode).set(JSON_SCHEMA_COMPONENTS_ELEMENT,
            specificationNode.path(JSON_SCHEMA_COMPONENTS_ELEMENT).deepCopy());

      return validateJson(schemaNode, jsonNode, namespace);
   }

   /**
    * Validate an Avro binary representing an AsyncAPI message against a node representing a full AsyncAPI specification
    * (and not just a schema node). Specify the message by providing a valid JSON pointer for {@code messagePathPointer}
    * within specification to allow finding the correct schema information. Validation with avro binary is a shallow
    * one: because we do not have the schema used for writing the bytes, we can only check the given bytes are fitting
    * into the read schema from AsyncAPI document. It returns a list of validation error messages.
    * @param specificationNode  The AsyncAPI full specification as a Jackson node
    * @param avroBinary         The avro binary representing actual message
    * @param messagePathPointer A JSON Pointer for accessing expected message definition within spec
    * @param schemaMap          An optional local Schema registry snapshot for resolving Avro schemas
    * @return The list of validation failures. If empty, avro binary is valid !
    */
   public static List<String> validateAvroMessage(JsonNode specificationNode, byte[] avroBinary,
         String messagePathPointer, SchemaMap schemaMap) {
      // Retrieve the schema to validate binary against.
      Schema avroSchema;
      try {
         avroSchema = retrieveMessageAvroSchema(specificationNode, messagePathPointer, schemaMap);
      } catch (Exception e) {
         return List.of(e.getMessage());
      }

      List<String> errors = new ArrayList<>();
      try {
         // Validation is shallow: we cannot detect schema incompatibilities as we do not
         // have the schema used for writing. Just checking we can read with given schema.
         AvroUtil.avroToAvroRecord(avroBinary, avroSchema);
         // We're satisfying at least one schema. Exit here.
         return List.of();
      } catch (AvroTypeException ate) {
         errors.add("Avro schema cannot be used to read message: " + ate.getMessage());
      } catch (IOException ioe) {
         errors.add("IOException while trying to validate message: " + ioe.getMessage());
      }
      return errors;
   }

   /**
    * Validate an Avro binary representing an AsyncAPI message against a node representing a full AsyncAPI specification
    * (and not just a schema node). Specify the message by providing a valid JSON pointer for {@code messagePathPointer}
    * within specification to allow finding the correct schema information. Validation with avro binary is a deep one:
    * each element of the reading schema from AsyncAPI spec is checked in terms of type compatibility, name and
    * required/optional property. It returns a list of validation error messages.
    * @param specificationNode  The AsyncAPI full specification as a Jackson node
    * @param avroRecord         The avro record representing actual message
    * @param messagePathPointer A JSON Pointer for accessing expected message definition within spec
    * @param schemaMap          An optional local Schema registry snapshot for resolving Avro schemas
    * @return The list of validation failures. If empty, avro record is valid !
    */
   public static List<String> validateAvroMessage(JsonNode specificationNode, GenericRecord avroRecord,
         String messagePathPointer, SchemaMap schemaMap) {
      // Retrieve the schema to validate record against.
      Schema avroSchema = null;
      try {
         avroSchema = retrieveMessageAvroSchema(specificationNode, messagePathPointer, schemaMap);
      } catch (Exception e) {
         return List.of(e.getMessage());
      }

      // Validation is a deep one. Each element should be checked.
      if (AvroUtil.validate(avroSchema, avroRecord)) {
         return List.of();
      }
      // Produce some insights on what's going wrong. We'll accumulate the errors on different schemas.
      return AvroUtil.getValidationErrors(avroSchema, avroRecord);
   }

   /**
    * Get a Jackson JsonNode representation for Json object.
    * @param jsonText The Json object as a string
    * @return The Jackson JsonNode corresponding to json object string
    * @throws IOException if json string representation cannot be parsed
    */
   public static JsonNode getJsonNode(String jsonText) throws IOException {
      return JsonSchemaValidator.getJsonNode(jsonText);
   }

   /**
    * Get a Jackson JsonNode representation for AsyncAPI schema text. This handles the fact that AsyncAPI spec may be
    * formatted in YAML. In that case, it handles the conversion.
    * @param schemaText The JSON or YAML string for AsyncAPI schema
    * @return The Jackson JsonNode corresponding to AsyncAPI schema string
    * @throws IOException if schema string representation cannot be parsed
    */
   public static JsonNode getJsonNodeForSchema(String schemaText) throws IOException {
      boolean isYaml = true;

      // Analyse first lines of content to guess content format.
      String line = null;
      BufferedReader reader = new BufferedReader(new StringReader(schemaText));
      while ((line = reader.readLine()) != null) {
         line = line.trim();
         // Check is we start with json object or array definition.
         if (line.startsWith("{") || line.startsWith("[")) {
            isYaml = false;
            break;
         }
         if (line.startsWith("---") || line.startsWith("-") || line.startsWith("asyncapi: ")) {
            break;
         }
      }
      reader.close();

      // Convert them to Node using Jackson object mapper.
      ObjectMapper mapper = null;
      if (isYaml) {
         log.debug("Guessing AsyncAPI spec format is YAML");
         mapper = new ObjectMapper(new YAMLFactory());
      } else {
         log.debug("Guessing AsyncAPI spec format is JSON");
         mapper = new ObjectMapper();
      }
      return mapper.readTree(schemaText);
   }

   /** Entry point method for converting an AsyncAPI schema node to Json schema. */
   private static JsonNode convertAsyncAPISchemaToJsonSchema(JsonNode jsonNode) {
      // Convert components.
      if (jsonNode.has("components")) {
         convertProperties(jsonNode.path("components").path("schemas").elements());
      }
      // Convert schema for all structures.
      for (String structure : STRUCTURES) {
         if (jsonNode.has(structure) && jsonNode.path(structure).isArray()) {
            ArrayNode arrayNode = (ArrayNode) jsonNode.path(structure);
            for (int i = 0; i < arrayNode.size(); i++) {
               JsonNode structureNode = arrayNode.get(i);
               structureNode = convertAsyncAPISchemaToJsonSchema(structureNode);
            }
         }
      }

      // Convert properties and types.
      if (jsonNode.has("type") && jsonNode.path("type").asText().equals("object")) {
         convertProperties(jsonNode.path(JSON_SCHEMA_PROPERTIES_ELEMENT).elements());
      } else {
         convertType(jsonNode);
      }

      // Remove all unsupported attributes.
      for (String notSupported : NOT_SUPPORTED_ATTRIBUTES) {
         if (jsonNode.has(notSupported)) {
            ((ObjectNode) jsonNode).remove(notSupported);
         }
      }

      return jsonNode;
   }

   /** Deal with converting properties of a Json node object. */
   private static void convertProperties(Iterator<JsonNode> properties) {
      while (properties.hasNext()) {
         JsonNode property = properties.next();
         property = convertAsyncAPISchemaToJsonSchema(property);
      }
   }

   /** Deal with converting type of a Json node object. */
   private static void convertType(JsonNode node) {
      // Convert nullable in additional type and remove node.
      if (node.has("type") && !node.path("type").asText().equals("object") && node.path("nullable").asBoolean()) {
         String type = node.path("type").asText();
         ArrayNode typeArray = ((ObjectNode) node).putArray("type");
         typeArray.add(type).add("null");
      }
   }

   /** Build a Json schema node for messages expressed as a direct oneOf structure. */
   private static JsonNode buildOneOfMessageSchemaNode(JsonNode specificationNode, ArrayNode oneOfMessageNode)
         throws Exception {
      // Initialize a oneOf schema with array.
      ObjectMapper mapper = new ObjectMapper();
      ObjectNode schemaNode = mapper.createObjectNode();
      ArrayNode oneOfNode = mapper.createArrayNode();
      schemaNode.set(ONE_OF_STRUCT, oneOfNode);

      // Extract the schema payload for each alternative of the message.
      for (int i = 0; i < oneOfMessageNode.size(); i++) {
         JsonNode altMessageNode = oneOfMessageNode.get(i);
         // Extract the alternative message node.
         altMessageNode = followRefIfAny(altMessageNode, specificationNode);
         oneOfNode.add(retrieveSingleMessageSchemaNode(specificationNode, altMessageNode));
      }
      // Common parts that may be referenced by references should be imported at a upper level/
      return schemaNode;
   }

   /** Retrieve the Json schema node corresponding to a single message definition. */
   private static JsonNode retrieveSingleMessageSchemaNode(JsonNode specificationNode, JsonNode messageNode)
         throws Exception {
      // Check that message node has a payload attribute.
      if (!messageNode.has(ASYNC_SCHEMA_PAYLOAD_ELEMENT)) {
         log.debug("messageNode {} has no 'payload' attribute", messageNode);
         throw new Exception("message definition has no valid payload in AsyncAPI specification");
      }
      // Navigate to payload definition.
      messageNode = messageNode.path(ASYNC_SCHEMA_PAYLOAD_ELEMENT);

      // Payload node can be just a reference to another schema...
      messageNode = followRefIfAny(messageNode, specificationNode);

      // Build a schema object with messageNode as root.
      // Common parts that may be referenced by references should be imported at a upper level
      return messageNode.deepCopy();
   }
}

