@org.springframework.stereotype.Service
public class ProxyService {

   private static final Logger log = LoggerFactory.getLogger(ProxyService.class);

   private static final RestTemplate restTemplate = new RestTemplate();

   /**
    * Call an external Http service url, propagating current method, headers and body.
    * @param externalUrl The target backend service url.
    * @param method      The Http method to propagate
    * @param headers     The Http headers to propagate
    * @param body        The Http body to propagate
    * @return The response entity returned by external service as is
    */
   public ResponseEntity<byte[]> callExternal(URI externalUrl, HttpMethod method, HttpHeaders headers, String body) {
      headers.put("Host", List.of(externalUrl.getHost()));

      if (log.isDebugEnabled()) {
         log.debug("Proxy request url: {}", externalUrl);
         log.debug("Proxy request headers: {}", headers);
         log.debug("Proxy request body: {}", body);
      }

      try {
         ResponseEntity<byte[]> response = restTemplate.exchange(externalUrl, method, new HttpEntity<>(body, headers),
               byte[].class);

         if (log.isDebugEnabled()) {
            log.debug("Proxy returned: {}", response.getStatusCode());
            log.debug("Proxy response headers: {}", response.getHeaders());
            log.debug("Proxy response body: {}", new String(response.getBody(), StandardCharsets.UTF_8));
         }
         return response;
      } catch (RestClientResponseException ex) {
         if (log.isDebugEnabled()) {
            log.debug("Proxy raised: {}", ex.getStatusCode());
            log.debug("Proxy exception body: {}", ex.getResponseBodyAsString());
         }
         return new ResponseEntity<>(ex.getResponseBodyAsByteArray(), ex.getResponseHeaders(), ex.getStatusCode());
      }
   }
}

public class ServiceStateStore implements StateStore {

   private static final int DEFAULT_SECONDS_TTL = 10;

   private final ServiceStateRepository repository;
   private final String serviceId;

   /**
    * Build a ServiceStateStore for required elements.
    * @param repository The MongoDB repository to use for persistence
    * @param serviceId  The ID of Service this state store will be scoped to
    */
   public ServiceStateStore(ServiceStateRepository repository, String serviceId) {
      this.repository = repository;
      this.serviceId = serviceId;
   }

   public void put(String key, String value) {
      put(key, value, DEFAULT_SECONDS_TTL);
   }

   public void put(String key, String value, int secondsTTL) {
      ServiceState state = repository.findByServiceIdAndKey(serviceId, key);
      if (state == null) {
         state = new ServiceState(serviceId, key);
      }
      state.setValue(value);
      state.setExpireAt(new Date(System.currentTimeMillis() + (secondsTTL * 1000L)));
      repository.save(state);
   }

   @Nullable
   public String get(String key) {
      ServiceState state = repository.findByServiceIdAndKey(serviceId, key);
      if (state != null) {
         return state.getValue();
      }
      return null;
   }

   public void delete(String key) {
      ServiceState state = repository.findByServiceIdAndKey(serviceId, key);
      if (state != null) {
         repository.delete(state);
      }
   }
}

public class AbsoluteUrlMatcher {
   static final String regex = ".+://.*";

   static final Pattern pattern = Pattern.compile(regex, Pattern.MULTILINE);

   public static boolean matches(String url) {
      return pattern.matcher(url).matches();
   }
}

public class DispatchCriteriaHelper {

   private static final String CURLY_PART_PATTERN = "(\\{[^\\}]+\\})";
   private static final String CURLY_PART_EXTRACTION_PATTERN = "\\\\{(.+)\\\\}";

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(DispatchCriteriaHelper.class);

   private DispatchCriteriaHelper() {
      // Hide default no argument constructor as it's a utility class.
   }

   /**
    * Extract a dispatch rule string from URI parameters (specified using example values)
    * @param uri The URI containing parameters
    * @return A string representing dispatch rules for the corresponding incoming request.
    */
   public static String extractParamsFromURI(String uri) {
      if (uri.contains("?") && uri.contains("=")) {
         String parameters = uri.substring(uri.indexOf("?") + 1);
         StringBuilder params = new StringBuilder();

         for (String parameter : parameters.split("&")) {
            String[] pair = parameter.split("=");
            String key = URLDecoder.decode(pair[0], StandardCharsets.UTF_8);
            if (!params.isEmpty()) {
               params.append(" && ");
            }
            params.append(key);
         }
         return params.toString();
      }
      return "";
   }

   /**
    * Extract the common prefix between a set of URIs
    * @param uris A set of URIs that are expected to share a common prefix
    * @return A string representing the common prefix of given URIs
    */
   public static String extractCommonPrefix(List<String> uris) {
      String commonURIPath = uris.getFirst();

      // 1st pass on collection: find a common prefix.
      for (int prefixLen = 0; prefixLen < uris.getFirst().length(); prefixLen++) {
         char c = uris.getFirst().charAt(prefixLen);
         for (int i = 1; i < uris.size(); i++) {
            if (prefixLen >= uris.get(i).length() || uris.get(i).charAt(prefixLen) != c) {
               // Mismatch found.
               String commonString = uris.get(i).substring(0, prefixLen);
               return commonString.substring(0, commonString.lastIndexOf('/'));
            }
         }
      }
      return commonURIPath;
   }

   /**
    * Extract the common suffix between a set of URIs
    * @param uris A set of URIs that are expected to share a common suffix
    * @return A string representing the common suffix of given URIs
    */
   public static String extractCommonSuffix(List<String> uris) {
      // 1st pass on collection: find a common suffix.
      for (int suffixLen = 0; suffixLen < uris.getFirst().length(); suffixLen++) {
         char c = uris.getFirst().charAt(uris.getFirst().length() - suffixLen - 1);
         for (int i = 1; i < uris.size(); i++) {
            if (suffixLen >= uris.get(i).length() || uris.get(i).charAt(uris.get(i).length() - suffixLen - 1) != c) {
               // Mismatch found. Have we found at least one common char ?
               if (suffixLen > 0) {
                  String commonString = uris.get(i).substring(uris.get(i).length() - suffixLen - 1);
                  if (commonString.indexOf('/') != -1) {
                     return commonString.substring(commonString.indexOf('/'));
                  }
                  return null;
               } else {
                  return null;
               }
            }
         }
      }
      return null;
   }

   /**
    * Extract from given URIs a dispatching rule representing the number of variable parts in this different URIs. For
    * example, given 'http://s/r/f//d/m/s' and 'http://s/r/f/d', method will detect 2 variable parts ('m' and 's').
    * Because it does know anything about the semantics of this parts, it produces a generic dispatch rule
    * <code>'part1 &amp;&amp; part2'</code> telling that URIs can be templatized like 'http://s/r/f/d/{part1}/{part2}
    * and that this 2 parts should be taken into account when dispatching request to response.
    * @param uris A set of URIs that are expected to share a common prefix
    * @return A string representing dispatch rules for the corresponding incoming request.
    */
   public static String extractPartsFromURIs(List<String> uris) {
      // 1st pass on collection: find a common prefix.
      String commonURIPath = extractCommonPrefix(uris);

      // 2nd pass on collection: find a common suffix.
      String commonURIEnd = extractCommonSuffix(uris);

      // 3rd pass on collection: guess the max number of part.
      int partsLen = 0;
      for (String uri : uris) {
         String parts = uri.substring(commonURIPath.length() + 1);
         if (commonURIEnd != null) {
            parts = parts.substring(0, parts.lastIndexOf(commonURIEnd));
         }
         int numOfParts = parts.split("/").length;
         if (numOfParts > partsLen) {
            partsLen = numOfParts;
         }
      }

      if (partsLen > 0) {
         StringBuilder parts = new StringBuilder();
         for (int i = 0; i < partsLen; i++) {
            parts.append("part").append(i + 1);
            if (i < partsLen - 1) {
               parts.append(" && ");
            }
         }
         return parts.toString();
      }
      return "";
   }

   /**
    * Build a template URL like 'http://s/r/f/d/{part1}/{part2}' with parts extracted from given URIs. For example,
    * given 'http://s/r/f/d/m/s' and 'http://s/r/f/d', method will detect 2 variable parts ('m' and 's'). Because it
    * does know anything about the semantics of this parts, it produces a generic dispatch rule
    * <code>'part1 &amp;&amp; part2'</code> telling that URIs can be templatized like 'http://s/r/f/d/{part1}/{part2}'
    * @param uris A set of URIs that are expected to share a common prefix
    * @return A templatized URL containing parts.
    */
   public static String buildTemplateURLWithPartsFromURIs(List<String> uris) {
      // 1st pass on collection: find a common prefix.
      String commonURIPath = extractCommonPrefix(uris);

      // 2nd pass on collection: find a common suffix.
      String commonURIEnd = extractCommonSuffix(uris);

      StringBuilder partsURI = new StringBuilder();
      partsURI.append(commonURIPath);

      int partsLen = 0;
      for (String uri : uris) {
         String parts = uri.substring(commonURIPath.length() + 1);
         if (commonURIEnd != null) {
            parts = parts.substring(0, parts.lastIndexOf(commonURIEnd));
         }
         int numOfParts = parts.split("/").length;
         if (numOfParts > partsLen) {
            partsLen = numOfParts;
         }
      }

      if (partsLen > 0) {
         for (int i = 0; i < partsLen; i++) {
            if (i == 0) {
               partsURI.append("/");
            }
            partsURI.append("{part").append(i + 1).append("}");
            if (i < partsLen - 1) {
               partsURI.append("/");
            }
         }
      }

      if (commonURIEnd != null) {
         partsURI.append("/").append(commonURIEnd);
      }

      return partsURI.toString();
   }

   /**
    * Extract a dispatch rule string from URI pattern (containing variable parts within {}) in order to explain which
    * parts are variables.
    * @param pattern The URI pattern containing variables parts ({} or :part patterns)
    * @return A string representing dispatch rules for the corresponding incoming request.
    */
   public static String extractPartsFromURIPattern(String pattern) {
      // Sanitize pattern as it may contains query params expressed using '{{}}'.
      if (pattern.contains("?")) {
         pattern = pattern.substring(0, pattern.indexOf('?'));
      }
      // and as it may contains variables using '{{}}'.
      if (pattern.contains("{{") && pattern.contains("}}")) {
         pattern = pattern.replace("{{", "");
         pattern = pattern.replace("}}", "");
      }
      // and as it may contains $ signs with forms like '/items/$count'.
      if (pattern.contains("$")) {
         pattern = pattern.replace("$", "");
      }

      // Build a pattern for extracting parts from pattern.
      String partsPattern = null;
      if (pattern.contains("/{")) {
         partsPattern = pattern.replaceAll(CURLY_PART_PATTERN, CURLY_PART_EXTRACTION_PATTERN);
      } else if (pattern.contains("/:")) {
         // We should add a leading / to avoid getting port number ;-)
         partsPattern = pattern.replaceAll("(/:[^:^/]+)", "\\/:(.+)");
      }
      return buildPartsDispatchRule(pattern, partsPattern);
   }

   /**
    * Extract a dispatch rule string from String pattern (containing variable parts within {}) in order to explain which
    * parts are variables.
    * @param pattern The String pattern containing variables parts ({} patterns)
    * @return A string representing dispatch rules for the corresponding incoming request.
    */
   public static String extractPartsFromStringPattern(String pattern) {
      // Build a pattern for extracting parts from pattern.
      String partsPattern = null;
      if (pattern.contains("{")) {
         partsPattern = pattern.replaceAll(CURLY_PART_PATTERN, CURLY_PART_EXTRACTION_PATTERN);
      }
      return buildPartsDispatchRule(pattern, partsPattern);
   }

   /** Apply a regexp on pattern to extract parts and create a dispatch rule. */
   private static String buildPartsDispatchRule(String pattern, String partsExtractPattern) {
      if (partsExtractPattern != null) {
         Pattern partsP = Pattern.compile(partsExtractPattern);
         Matcher partsM = partsP.matcher(pattern);

         if (partsM.matches()) {
            StringBuilder parts = new StringBuilder();
            for (int i = 1; i < partsM.groupCount() + 1; i++) {
               parts.append(partsM.group(i));
               if (i < partsM.groupCount()) {
                  parts.append(" && ");
               }
            }
            return parts.toString();
         }
      }
      return "";
   }

   /**
    * Extract and build a dispatch criteria string from URI pattern (containing variable parts within {} or prefixed
    * with :), projected onto a real instanciated URI.
    * @param paramsRuleString The dispatch rules referencing parameters to consider
    * @param pattern          The URI pattern containing variables parts ({})
    * @param realURI          The real URI that should match pattern.
    * @return A string representing dispatch criteria for the corresponding incoming request.
    */
   public static String extractFromURIPattern(String paramsRuleString, String pattern, String realURI) {
      Map<String, String> criteriaMap = extractMapFromURIPattern(paramsRuleString, pattern, realURI);

      // Just appends sorted entries, separating them with /.
      StringBuilder result = new StringBuilder();
      for (Map.Entry<String, String> criteria : criteriaMap.entrySet()) {
         result.append("/").append(criteria.getKey()).append("=").append(criteria.getValue());
      }
      return result.toString();
   }

   /**
    * Extract a map of parameters from URI pattern (containing variable parts within '{}' or prefixed with ':'),
    * projected onto a real instantiated URI. The extracted map only contains values for parameters referenced in
    * {@code paramsRuleString}.
    * @param paramsRuleString The dispatch rules referencing parameters to consider
    * @param pattern          The URI pattern containing variables parts ({})
    * @param realURI          The real URI that should match pattern.
    * @return A map of parameters extracted from the URI for the corresponding incoming request.
    * @see #extractMapFromURIPattern(String, String)
    */
   public static Map<String, String> extractMapFromURIPattern(String paramsRuleString, String pattern, String realURI) {
      // Rule string can be a URI_ELEMENT rule and containers ?? elements.
      // We must remove them before parsing the URI parts.
      if (paramsRuleString.contains("??")) {
         paramsRuleString = paramsRuleString.split("\\?\\?")[0];
      }
      final var paramsRule = Arrays.stream(paramsRuleString.split("&&")).map(String::trim).distinct()
            .collect(Collectors.toUnmodifiableSet());

      // Ensure realURI does not contain query string.
      if (realURI.contains("?")) {
         realURI = realURI.substring(0, realURI.indexOf('?'));
      }

      // Filter the extracted parameter map by the referenced parameters in paramsRule
      return extractMapFromURIPattern(pattern, realURI).entrySet().stream()
            .filter(entry -> paramsRule.contains(entry.getKey()))
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
   }

   /**
    * Extract a map of parameters from URI pattern (containing variable parts within '{}' or prefixed with ':'),
    * projected onto a real instantiated URI.
    * @param pattern The URI pattern containing variables parts ({})
    * @param realURI The real URI that should match pattern.
    * @return A map of parameters extracted from the URI for the corresponding incoming request.
    * @see #extractMapFromURIPattern(String, String, String)
    */
   public static Map<String, String> extractMapFromURIPattern(String pattern, String realURI) {
      Map<String, String> criteriaMap = new TreeMap<>();
      pattern = sanitizeURLForRegExp(pattern);
      realURI = sanitizeURLForRegExp(realURI);

      // Build a pattern for extracting parts from pattern and a pattern for extracting values
      // from realURI. Supporting both {id} and :id.
      String partsPattern = null;
      String valuesPattern = null;
      if (pattern.contains("/{")) {
         partsPattern = pattern.replaceAll(CURLY_PART_PATTERN, CURLY_PART_EXTRACTION_PATTERN);
         valuesPattern = pattern.replaceAll(CURLY_PART_PATTERN, "(.+)");
      } else {
         partsPattern = pattern.replaceAll("(:[^:^/]+)", "\\:(.+)");
         valuesPattern = pattern.replaceAll("(:[^:^/]+)", "(.+)");
      }
      if (pattern.contains("$")) {
         partsPattern = partsPattern.replace("$", "\\$");
         valuesPattern = valuesPattern.replace("$", "\\$");
      }
      Pattern partsP = Pattern.compile(partsPattern);
      Matcher partsM = partsP.matcher(pattern);

      Pattern valuesP = Pattern.compile(valuesPattern);
      Matcher valuesM = valuesP.matcher(realURI);

      // Both should match and have the same group count.
      if (valuesM.matches() && partsM.matches() && valuesM.groupCount() == partsM.groupCount()) {
         for (int i = 1; i < partsM.groupCount() + 1; i++) {
            final String paramName = partsM.group(i);
            final String paramValue = valuesM.group(i);
            criteriaMap.put(paramName, paramValue);
         }
      }
      return criteriaMap;
   }

   /**
    * Build a dispatch criteria string from map of parts (key is part name, value is part real value)
    * @param partsRule The dispatch rules referencing parts to consider
    * @param partsMap  The Map containing parts (not necessarily sorted)
    * @return A string representing dispatch criteria for the corresponding incoming request.
    */
   public static String buildFromPartsMap(String partsRule, Map<String, String> partsMap) {
      if (partsMap != null && !partsMap.isEmpty()) {
         Multimap<String, String> multimap = partsMap.entrySet().stream().collect(ArrayListMultimap::create,
               (m, e) -> m.put(e.getKey(), e.getValue()), Multimap::putAll);
         return buildFromPartsMap(partsRule, multimap);
      }
      return "";
   }

   /**
    * Build a dispatch criteria string from map of parts (key is part name, value is part real value)
    * @param partsRule The dispatch rules referencing parts to consider
    * @param partsMap  The Multimap containing parts (not necessarily sorted)
    * @return A string representing dispatch criteria for the corresponding incoming request.
    */
   public static String buildFromPartsMap(String partsRule, Multimap<String, String> partsMap) {
      // We may have a partsRule for URI_ELEMENT with params parts, ignore this part.
      if (partsRule.contains("??")) {
         partsRule = partsRule.split("\\?\\?")[0];
      }

      if (partsMap != null && !partsMap.isEmpty()) {
         Multimap<String, String> criteriaMap = TreeMultimap.create(partsMap);

         // Just appends sorted entries, separating them with /.
         StringBuilder result = new StringBuilder();
         for (Map.Entry<String, String> criteria : criteriaMap.entries()) {
            /*
             * Check that criteria is embedded into the rule. Simply check word boundary with \b is not enough as - are
             * valid in params (according RFC 3986) but not included into word boundary - so "word-ext" string is
             * matching ".*\\bword\\b.*" We need to tweak it a bit to prevent matching when there's a - before or after
             * the criteria we're looking for (see
             * https://stackoverflow.com/questions/32380375/hyphen-dash-to-be-included-in-regex-word-boundary-b)
             */
            if (partsRule.matches(".*(^|[^-])\\b" + criteria.getKey() + "\\b([^-]|$).*")) {
               result.append("/").append(criteria.getKey()).append("=").append(criteria.getValue());
            }
         }
         return result.toString();
      }
      return "";
   }

   /**
    * Build a dispatch criteria string from URI parameters contained into a map
    * @param paramsRule The dispatch rules referencing parameters to consider
    * @param paramsMap  The Map containing URI params (not necessarily sorted)
    * @return A string representing a dispatch criteria for the corresponding incoming request.
    */
   public static String buildFromParamsMap(String paramsRule, Multimap<String, String> paramsMap) {
      // We may have a paramsRule for URI_ELEMENT with path parts, ignore this part.
      if (paramsRule.contains("??")) {
         paramsRule = paramsRule.split("\\?\\?")[1];
      }

      if (paramsMap != null && !paramsMap.isEmpty()) {
         Multimap<String, String> criteriaMap = TreeMultimap.create(paramsMap);

         // Just appends sorted entries, separating them with ?.
         StringBuilder result = new StringBuilder();
         for (Map.Entry<String, String> criteria : criteriaMap.entries()) {
            /*
             * Check that criteria is embedded into the rule. Simply check word boundary with \b is not enough as - are
             * valid in params (according RFC 3986) but not included into word boundary - so "word-ext" string is
             * matching ".*\\bword\\b.*" We need to tweak it a bit to prevent matching when there's a - before or after
             * the criteria we're looking for (see
             * https://stackoverflow.com/questions/32380375/hyphen-dash-to-be-included-in-regex-word-boundary-b)
             */
            if (paramsRule.matches(".*(^|[^-])\\b" + criteria.getKey() + "\\b([^-]|$).*")) {
               result.append("?").append(criteria.getKey()).append("=").append(criteria.getValue());
            }
         }
         return result.toString();
      }
      return "";
   }

   /**
    * Extract and build a dispatch criteria string from URI parameters
    * @param paramsRule The dispatch rules referencing parameters to consider
    * @param uri        The URI from which we should build a specific dispatch criteria
    * @return A string representing a dispatch criteria for the corresponding incoming request.
    */
   public static String extractFromURIParams(String paramsRule, String uri) {
      Multimap<String, String> criteriaMap = extractMapFromURIParams(paramsRule, uri);

      // Just appends sorted entries, separating them with ?.
      StringBuilder result = new StringBuilder();
      for (Map.Entry<String, String> criteria : criteriaMap.entries()) {
         if (paramsRule.contains(criteria.getKey())) {
            result.append("?").append(criteria.getKey()).append("=").append(criteria.getValue());
         }
      }
      return result.toString();
   }

   /**
    * Extract a map of parameters from URI parameters
    * @param paramsRule The dispatch rules referencing parameters to consider
    * @param uri        The URI from which we should build a specific dispatch criteria
    * @return A map of parameters extracted from the URI for the corresponding incoming request.
    */
   public static Multimap<String, String> extractMapFromURIParams(String paramsRule, String uri) {
      Multimap<String, String> criteriaMap = TreeMultimap.create();

      if (uri.contains("?") && uri.contains("=")) {
         String parameters = uri.substring(uri.indexOf("?") + 1);

         for (String parameter : parameters.split("&")) {
            String[] pair = parameter.split("=");
            if (pair.length > 1) {
               String key = URLDecoder.decode(pair[0], StandardCharsets.UTF_8);
               String value = URLDecoder.decode(pair[1], StandardCharsets.UTF_8);
               if (paramsRule.contains(key)) {
                  criteriaMap.put(key, value);
               }
            }
         }
      }
      return criteriaMap;
   }

   /**
    * Extract and build a dispatch criteria string from URI parameters already stored into a Map.
    * @param paramsRule The dispatch rules referencing parameters to consider
    * @param paramMap   The URI fetched params from which we should build a specific dispatch criteria
    * @return A string representing a dispatch criteria for the corresponding incoming request.
    */
   public static String extractFromParamMap(String paramsRule, Map<String, String> paramMap) {
      Set<String> sortedKeys = paramMap.keySet().stream().sorted().collect(Collectors.toSet());

      StringBuilder result = new StringBuilder();
      for (String param : sortedKeys) {
         if (paramsRule.contains(param)) {
            result.append("?").append(param).append("=").append(paramMap.get(param));
         }
      }
      return result.toString();
   }

   /**
    * Get the root dispatcher and dispatcher rules for an operation, taking into account fallback and proxy-fallback
    * @param operation The operation for which we want to extract dispatcher details
    * @return A DispatcherDetails object containing root dispatcher and dispatcher rules
    */
   public static DispatcherDetails extractDispatcherWithRules(Operation operation) {
      String rootDispatcher = operation.getDispatcher();
      String rootDispatcherRules = operation.getDispatcherRules();

      if (DispatchStyles.FALLBACK.equals(operation.getDispatcher())) {
         try {
            FallbackSpecification fallbackSpec = FallbackSpecification
                  .buildFromJsonString(operation.getDispatcherRules());
            rootDispatcher = fallbackSpec.getDispatcher();
            rootDispatcherRules = fallbackSpec.getDispatcherRules();
         } catch (JsonMappingException e) {
            log.warn("Operation '{}' has a malformed Fallback dispatcher rules", operation.getName());
         }
      }
      if (DispatchStyles.PROXY_FALLBACK.equals(operation.getDispatcher())) {
         try {
            ProxyFallbackSpecification proxyFallbackSpec = ProxyFallbackSpecification
                  .buildFromJsonString(operation.getDispatcherRules());
            rootDispatcher = proxyFallbackSpec.getDispatcher();
            rootDispatcherRules = proxyFallbackSpec.getDispatcherRules();
         } catch (JsonMappingException e) {
            log.warn("Operation '{}' has a malformed Proxy-Fallback dispatcher rules", operation.getName());
         }
      }

      return new DispatcherDetails(rootDispatcher, rootDispatcherRules);
   }

   public record DispatcherDetails(String rootDispatcher, String rootDispatcherRules) {
   }

   private static String sanitizeURLForRegExp(String url) {
      return url.replace("+", " ");
   }
}

@JsonPropertyOrder({ "exp", "operator", "cases" })
public class JsonEvaluationSpecification {

   private String exp;
   private EvaluationOperator operator;
   private DispatchCases cases;

   public String getExp() {
      return exp;
   }

   public void setExp(String exp) {
      this.exp = exp;
   }

   public EvaluationOperator getOperator() {
      return operator;
   }

   public void setOperator(EvaluationOperator operator) {
      this.operator = operator;
   }

   public DispatchCases getCases() {
      return cases;
   }

   public void setCases(DispatchCases cases) {
      this.cases = cases;
   }

   /**
    * Build a specification from a JSON string.
    * @param jsonPayload The JSON payload representing valid specification
    * @return A newly build JsonEvaluationSpecification
    * @throws JsonMappingException if given JSON string cannot be parsed as a JsonEvaluationSpecification
    */
   public static JsonEvaluationSpecification buildFromJsonString(String jsonPayload) throws JsonMappingException {
      JsonEvaluationSpecification specification = null;
      try {
         ObjectMapper mapper = new ObjectMapper();
         specification = mapper.readValue(jsonPayload, JsonEvaluationSpecification.class);
      } catch (Exception e) {
         throw new JsonMappingException("Given JSON string cannot be interpreted as valid JsonEvaluationSpecification");
      }
      return specification;
   }
}

public class JsonExpressionEvaluator {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(JsonExpressionEvaluator.class);

   /**
    * Evaluate a Json payload regarding a specification. Basically, it checks if payload conforms to the given
    * expression and then fond the suitable cases from within specification.
    * @param jsonText      The Json payload to evaluate
    * @param specification The evaluation specification (JSONPointer expression + operator + cases)
    * @return The result of evaluation is whether one of the cases, whether
    * @throws JsonMappingException if incoming Json payload is malformed or invalid
    */
   public static String evaluate(String jsonText, JsonEvaluationSpecification specification)
         throws JsonMappingException {
      // Parse json text ang get root node.
      JsonNode rootNode;
      try {
         ObjectMapper mapper = new ObjectMapper();
         rootNode = mapper.readTree(new StringReader(jsonText));
      } catch (Exception e) {
         log.error("Exception while parsing Json text", e);
         throw new JsonMappingException("Exception while parsing Json payload");
      }

      // Retrieve evaluated node within JSON tree.
      JsonNode evaluatedNode = rootNode.at(specification.getExp());
      String caseKey = evaluatedNode.asText();

      switch (specification.getOperator()) {
         case equals:
            // Consider simple equality.
            String value = specification.getCases().get(caseKey);
            return (value != null ? value : specification.getCases().getDefault());

         case range:
            // Consider range evaluation.
            double caseNumber = 0.000;
            try {
               caseNumber = Double.parseDouble(caseKey);
            } catch (NumberFormatException nfe) {
               log.error(caseKey + " into range expression cannot be parsed as number. Considering default case.");
               return specification.getCases().getDefault();
            }
            return foundRangeMatchingCase(caseNumber, specification.getCases());

         case regexp:
            // Consider regular expression evaluation for each case key.
            for (String choiceKey : specification.getCases().keySet()) {
               if (!"default".equals(choiceKey)) {
                  if (Pattern.matches(choiceKey, caseKey)) {
                     return specification.getCases().get(choiceKey);
                  }
               }
            }
            break;

         case size:
            // Consider size evaluation.
            if (evaluatedNode.isArray()) {
               int size = evaluatedNode.size();
               return foundRangeMatchingCase(size, specification.getCases());
            }
            break;

         case presence:
            // Consider presence evaluation of evaluatedNode directly.
            if (evaluatedNode != null && evaluatedNode.toString().length() > 0) {
               if (specification.getCases().containsKey("found")) {
                  return specification.getCases().get("found");
               }
            } else {
               if (specification.getCases().containsKey("missing")) {
                  return specification.getCases().get("missing");
               }
            }
            break;
      }
      return specification.getCases().getDefault();
   }

   /** Evaluate cases from dispatchCases against caseNumber, considering each key as a range expression. */
   private static String foundRangeMatchingCase(double caseNumber, DispatchCases dispatchCases) {
      // Evaluating each case key.
      for (String choiceKey : dispatchCases.keySet()) {
         boolean match = false;
         if (isValidRangeKey(choiceKey)) {
            try {
               double[] minAndMax = extractMinAndMaxFromRange(choiceKey);
               // Fastidious part... Apply operators depending of brackets orientations.
               if (choiceKey.startsWith("[") && choiceKey.endsWith("]")) {
                  if (caseNumber >= minAndMax[0] && caseNumber <= minAndMax[1]) {
                     match = true;
                  }
               } else if (choiceKey.startsWith("]") && choiceKey.endsWith("]")) {
                  if (caseNumber > minAndMax[0] && caseNumber <= minAndMax[1]) {
                     match = true;
                  }
               } else if (choiceKey.startsWith("[") && choiceKey.endsWith("[")) {
                  if (caseNumber >= minAndMax[0] && caseNumber < minAndMax[1]) {
                     match = true;
                  }
               } else if (choiceKey.startsWith("]") && choiceKey.endsWith("[")) {
                  if (caseNumber > minAndMax[0] && caseNumber < minAndMax[1]) {
                     match = true;
                  }
               }
            } catch (NumberFormatException nfe) {
               log.warn(choiceKey + " expression cannot be parsed as number for min and max range.");
            }
         }
         if (match) {
            return dispatchCases.get(choiceKey);
         }
      }
      return dispatchCases.getDefault();
   }

   /** Validate key is a correct range expression. */
   private static boolean isValidRangeKey(String key) {
      boolean hasCorrectStart = key.startsWith("[") || key.startsWith("]");
      boolean hasCorrectEnd = key.endsWith("[") || key.endsWith("]");
      boolean hasDelimiter = key.contains(";");
      return hasCorrectStart && hasDelimiter && hasCorrectEnd;
   }

   /** Extract minimum and maximum from range expression. Considering min on the left side and max on the right side. */
   private static double[] extractMinAndMaxFromRange(String range) throws NumberFormatException {
      double[] results = new double[2];
      String[] minAndMax = range.split(";");
      results[0] = Double.parseDouble(minAndMax[0].substring(1));
      results[1] = Double.parseDouble(minAndMax[1].substring(0, minAndMax[1].length() - 1));
      return results;
   }
}

public class ScriptEngineBinder {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(ScriptEngineBinder.class);

   /** Private constructor to hide the implicit public one. */
   private ScriptEngineBinder() {
   }

   /**
    * Build a ScriptContext from Http request for a ScriptEngine.
    * @param engine         The engine to enrich with binding environment.
    * @param requestContent The content of request to use as data
    * @param requestContext The execution context of this request
    * @param stateStore     A store to save/get state from script
    * @param request        The wrapped incoming servlet request.
    * @return The evaluation context for the script engine eval() method.
    */
   public static ScriptContext buildEvaluationContext(ScriptEngine engine, String requestContent,
         Map<String, Object> requestContext, StateStore stateStore, HttpServletRequest request) {
      StringToStringsMap headers = HttpHeadersUtil.extractFromHttpServletRequest(request);
      return buildEvaluationContext(engine, requestContent, requestContext, stateStore, headers, request);
   }

   /**
    * Create and bind an environment for a ScriptEngine.
    * @param engine         The engine to enrich with binding environment.
    * @param requestContent The content of request to use as data
    * @param requestContext The execution context of this request
    * @param stateStore     A store to save/get state from script
    * @param request        The wrapped incoming servlet request.
    * @param uriParameters  The URI parameters of the request
    * @return The evaluation context for the script engine eval() method.
    */
   public static ScriptContext buildEvaluationContext(ScriptEngine engine, String requestContent,
         Map<String, Object> requestContext, StateStore stateStore, HttpServletRequest request,
         Map<String, String> uriParameters) {
      StringToStringsMap headers = HttpHeadersUtil.extractFromHttpServletRequest(request);
      return buildEvaluationContext(engine, requestContent, requestContext, stateStore, headers, request,
            uriParameters);
   }

   /**
    * Build an evaluation ScriptContext for a ScriptEngine.
    * @param engine         The engine to enrich with binding environment.
    * @param requestContent The content of request to use as data
    * @param requestContext The execution context of this request
    * @param stateStore     A store to save/get state from script
    * @param headers        The header values of the request
    * @param request        The wrapped incoming servlet request.
    * @return The evaluation context for the script engine eval() method.
    */
   public static ScriptContext buildEvaluationContext(ScriptEngine engine, String requestContent,
         Map<String, Object> requestContext, StateStore stateStore, StringToStringsMap headers,
         HttpServletRequest request) {
      return buildEvaluationContext(engine, requestContent, requestContext, stateStore, headers, request, null);
   }

   /**
    * Build an evaluation ScriptContext for a ScriptEngine.
    * @param engine         The engine to enrich with binding environment.
    * @param requestContent The content of request to use as data
    * @param requestContext The execution context of this request
    * @param stateStore     A store to save/get state from script
    * @param headers        The header values of the request
    * @param request        The wrapped incoming servlet request.
    * @param uriParameters  The URI parameters of the request
    * @return The evaluation context for the script engine eval() method.
    */
   public static ScriptContext buildEvaluationContext(ScriptEngine engine, String requestContent,
         Map<String, Object> requestContext, StateStore stateStore, StringToStringsMap headers,
         HttpServletRequest request, Map<String, String> uriParameters) {

      // Build a fake request container.
      FakeScriptMockRequest mockRequest = new FakeScriptMockRequest(requestContent, headers);
      mockRequest.setRequest(request);
      mockRequest.setURIParameters(uriParameters);

      // Create bindings and put content according to SoapUI binding environment.
      Bindings bindings = engine.createBindings();
      bindings.put("mockRequest", mockRequest);
      bindings.put("log", log);
      bindings.put("requestContext", requestContext);
      bindings.put("store", stateStore);

      SimpleScriptContext scriptContext = new SimpleScriptContext();
      scriptContext.setBindings(bindings, ScriptContext.ENGINE_SCOPE);
      return scriptContext;
   }

   /**
    * Review and adapt a script so that we ensure its compatibility with legacy SoapUI helper.
    * @param script The script to review and adapt
    * @return The script that may have been changed
    */
   public static String ensureSoapUICompatibility(String script) {
      if (script.contains("com.eviware.soapui.support.XmlHolder")) {
         return script.replaceAll("com.eviware.soapui.support.XmlHolder", "io.github.microcks.util.soapui.XmlHolder");
      }
      return script;
   }
}

public class JsonSchemaValidator {

   /** A commons logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(JsonSchemaValidator.class);

   public static final String JSON_V4_SCHEMA_IDENTIFIER = "http://json-schema.org/draft-04/schema#";
   public static final String JSON_V7_SCHEMA_IDENTIFIER = "http://json-schema.org/draft-07/schema#";
   public static final String JSON_V12_SCHEMA_IDENTIFIER = "http://json-schema.org/draft/2020-12/schema#";
   public static final String JSON_SCHEMA_IDENTIFIER_ELEMENT = "$schema";

   public static final String JSON_SCHEMA_COMPONENTS_ELEMENT = "components";
   public static final String JSON_SCHEMA_PROPERTIES_ELEMENT = "properties";
   public static final String JSON_SCHEMA_REQUIRED_ELEMENT = "required";
   public static final String JSON_SCHEMA_ITEMS_ELEMENT = "items";
   public static final String JSON_SCHEMA_ADD_PROPERTIES_ELEMENT = "additionalProperties";

   private static final ObjectMapper mapper = new ObjectMapper()
         .enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
         .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN).enable(SerializationFeature.INDENT_OUTPUT);

   private JsonSchemaValidator() {
      // Private constructor to hide the implicit public one.
   }

   /**
    * Check if a Json object is valid against the given Json schema specification.
    * @param schemaText The Json schema specification as a string
    * @param jsonText   The Json object as a string
    * @return True if Json object is valid, false otherwise
    * @throws IOException if json string representations cannot be parsed
    */
   public static boolean isJsonValid(String schemaText, String jsonText) throws IOException {
      return isJsonValid(schemaText, jsonText, null);
   }

   /**
    * Check if a Json object is valid against the given Json schema specification.
    * @param schemaText The Json schema specification as a string
    * @param jsonText   The Json object as a string
    * @param namespace  Namespace definition to resolve relative dependencies in Json schema
    * @return True if Json object is valid, false otherwise
    * @throws IOException if json string representations cannot be parsed
    */
   public static boolean isJsonValid(String schemaText, String jsonText, String namespace) throws IOException {
      List<String> errors = validateJson(schemaText, jsonText, namespace);
      if (!errors.isEmpty()) {
         log.debug("Get validation errors, returning false");
         return false;
      }
      return true;
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of Json schema spec
    * semantics regarding additional or unknown attributes: schema must explicitly set <code>additionalProperties</code>
    * to false if you want to consider unknown attributes as validation errors. It returns a list of validation error
    * messages.
    * @param schemaText The Json schema specification as a string
    * @param jsonText   The Json object as a string
    * @return The list of validation failure messages. If empty, json object is valid !
    * @throws IOException if json string representations cannot be parsed
    */
   public static List<String> validateJson(String schemaText, String jsonText) throws IOException {
      return validateJson(getJsonNode(schemaText), getJsonNode(jsonText), null);
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of Json schema spec
    * semantics regarding additional or unknown attributes: schema must explicitly set <code>additionalProperties</code>
    * to false if you want to consider unknown attributes as validation errors. It returns a list of validation error
    * messages.
    * @param schemaText The Json schema specification as a string
    * @param jsonText   The Json object as a string
    * @param namespace  Namespace definition to resolve relative dependencies in Json schema
    * @return The list of validation failure messages. If empty, json object is valid !
    * @throws IOException if json string representations cannot be parsed
    */
   public static List<String> validateJson(String schemaText, String jsonText, String namespace) throws IOException {
      return validateJson(getJsonNode(schemaText), getJsonNode(jsonText), namespace);
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of Json schema spec
    * semantics regarding additional or unknown attributes: schema must explicitly set <code>additionalProperties</code>
    * to false if you want to consider unknown attributes as validation errors. It returns a list of validation error
    * messages.
    * @param schemaNode The Json schema specification as a Jackson node
    * @param jsonNode   The Json object as a Jackson node
    * @return The list of validation failures messages. If empty, json object is valid !
    */
   public static List<String> validateJson(JsonNode schemaNode, JsonNode jsonNode) {
      return validateJson(schemaNode, jsonNode, null);
   }

   /**
    * Validate a Json object representing by its text against a schema object representing byt its text too. Validation
    * is a deep one: its pursue checking children nodes on a failed parent. Validation is respectful of Json schema spec
    * semantics regarding additional or unknown attributes: schema must explicitly set <code>additionalProperties</code>
    * to false if you want to consider unknown attributes as validation errors. It returns a list of validation error
    * messages.
    * @param schemaNode The Json schema specification as a Jackson node
    * @param jsonNode   The Json object as a Jackson node
    * @param namespace  Namespace definition to resolve relative dependencies in Json schema
    * @return The list of validation failure messages. If empty, json object is valid !
    */
   public static List<String> validateJson(JsonNode schemaNode, JsonNode jsonNode, String namespace) {
      List<String> errors = new ArrayList<>();

      final JsonSchema jsonSchemaNode = extractJsonSchemaNode(schemaNode, namespace);

      Set<ValidationMessage> messages = jsonSchemaNode.validate(jsonNode, executionContext -> {
         executionContext.getExecutionConfig().setFormatAssertionsEnabled(true);
         executionContext.getExecutionConfig().setLocale(Locale.US);
      });

      if (!messages.isEmpty()) {
         for (ValidationMessage message : messages) {
            errors.add(message.getError());
         }
      }
      return errors;
   }

   /**
    * Get a Jackson JsonNode representation for Json object.
    * @param jsonText The Json object as a string
    * @return The Jackson JsonNode corresponding to json object string
    * @throws IOException if json string representation cannot be parsed
    */
   public static JsonNode getJsonNode(String jsonText) throws IOException {
      return mapper.readTree(jsonText);
   }

   /**
    * Get a Jackson JsonNode representation for Json schema.
    * @param schemaText The Json schema specification as a string
    * @return The Jackson JsonSchema corresponding to json schema string
    * @throws IOException if json string representation cannot be parsed
    */
   public static JsonSchema getSchemaNode(String schemaText) throws IOException {
      final JsonNode schemaNode = getJsonNode(schemaText);
      return extractJsonSchemaNode(schemaNode, null);
   }

   private static JsonSchema extractJsonSchemaNode(JsonNode jsonNode, String namespace) {
      JsonMetaSchema jsonMetaSchema = JsonMetaSchema.builder(JsonMetaSchema.getV202012()).build();
      JsonSchemaFactory jsonSchemaFactory = JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V202012,
            builder -> builder.metaSchema(jsonMetaSchema));

      if (namespace != null) {
         URI baseUri = URI.create(namespace);
         return jsonSchemaFactory.getSchema(baseUri, jsonNode);
      }

      return jsonSchemaFactory.getSchema(jsonNode);
   }
}

public class TestReturn {

   public static final int SUCCESS_CODE = 0;
   public static final int FAILURE_CODE = 1;

   private int code;
   private long elapsedTime;
   private String message;
   private Request request;
   private Response response;
   private EventMessage eventMessage;

   /** Default constructor for enabling bean serialization. */
   public TestReturn() {
   }

   /**
    * Build a TestReturn for event based exchange with its code.
    * @param code         The code (may be success of failure)
    * @param elapsedTime  Time taken for a test
    * @param eventMessage The event message for this test
    */
   public TestReturn(int code, long elapsedTime, EventMessage eventMessage) {
      this.code = code;
      this.elapsedTime = elapsedTime;
      this.eventMessage = eventMessage;
   }

   /**
    * Build a TestReturn for event based exchange with its code.
    * @param code         The code (may be success of failure)
    * @param elapsedTime  Time taken for a test
    * @param message      The return message for this test
    * @param eventMessage The event message for this test
    */
   public TestReturn(int code, long elapsedTime, String message, EventMessage eventMessage) {
      this.code = code;
      this.elapsedTime = elapsedTime;
      this.message = message;
      this.eventMessage = eventMessage;
   }

   /**
    * Build a TestReturn with its code and response.
    * @param code        The code (may be success of failure)
    * @param elapsedTime Time taken for a test
    * @param request     The request for this test
    * @param response    The response for this test
    */
   public TestReturn(int code, long elapsedTime, Request request, Response response) {
      this.code = code;
      this.elapsedTime = elapsedTime;
      this.request = request;
      this.response = response;
   }

   /**
    * Build a TestReturn with its code and response.
    * @param code        The code (may be success of failure)
    * @param elapsedTime Time taken for a test
    * @param message     The return message for this test
    * @param request     The request for this test
    * @param response    The response for this test
    */
   public TestReturn(int code, long elapsedTime, String message, Request request, Response response) {
      this.code = code;
      this.elapsedTime = elapsedTime;
      this.message = message;
      this.request = request;
      this.response = response;
   }

   /** @return Return code */
   public int getCode() {
      return code;
   }

   /** @return Elapsed time */
   public long getElapsedTime() {
      return elapsedTime;
   }

   /** @return Test return message */
   public String getMessage() {
      return message;
   }

   /** @return Request content */
   public Request getRequest() {
      return request;
   }

   /** @return Response content */
   public Response getResponse() {
      return response;
   }

   /** @return EventMessage content */
   public EventMessage getEventMessage() {
      return eventMessage;
   }

   /** @return True is this test return is for a request/response exchange test */
   public boolean isRequestResponseTest() {
      return request != null && response != null;
   }

   /** @return True if this test return is for an asynchronous event test */
   public boolean isEventTest() {
      return eventMessage != null;
   }

   /**
    * Build a TestStepResult from inner elements.
    * @return A new TestStepResult ready to attached to a test case.
    */
   public TestStepResult buildTestStepResult() {
      TestStepResult result = new TestStepResult();
      result.setElapsedTime(elapsedTime);
      result.setSuccess(code == SUCCESS_CODE);
      result.setMessage(message);
      if (request != null) {
         result.setRequestName(request.getName());
      }
      if (eventMessage != null) {
         result.setEventMessageName(eventMessage.getName());
      }
      return result;
   }
}

public class HttpTestRunner extends AbstractTestRunner<HttpMethod> {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(HttpTestRunner.class);

   private static final String IOEXCEPTION_STATUS_CODE = "IOException while getting raw status code in response";

   private Secret secret;

   private ClientHttpRequestFactory clientHttpRequestFactory;

   /**
    * Set the Secret used for securing the requests.
    * @param secret The Secret used or securing the requests.
    */
   public void setSecret(Secret secret) {
      this.secret = secret;
   }

   /**
    * Set the ClientHttpRequestFactory used for reaching endpoint.
    * @param clientHttpRequestFactory The ClientHttpRequestFactory used for reaching endpoint
    */
   public void setClientHttpRequestFactory(ClientHttpRequestFactory clientHttpRequestFactory) {
      this.clientHttpRequestFactory = clientHttpRequestFactory;
   }

   @Override
   public List<TestReturn> runTest(Service service, Operation operation, TestResult testResult, List<Request> requests,
         String endpointUrl, HttpMethod method) throws URISyntaxException, IOException {

      log.debug("Launching test run on {} for {} request(s)", endpointUrl, requests.size());

      if (requests.isEmpty()) {
         return null;
      }

      // Initialize result container.
      List<TestReturn> result = new ArrayList<>();

      for (Request request : requests) {
         // Reset status code, message and request each time.
         int code = TestReturn.SUCCESS_CODE;
         String message = null;
         String customizedEndpointUrl = endpointUrl;
         if (ServiceType.REST.equals(service.getType())) {
            String operationName = operation.getName();
            // Name may start with verb, remove it if present.
            if (operationName.trim().contains(" ")) {
               operationName = operationName.trim().split(" ")[1];
            }

            customizedEndpointUrl += URIBuilder.buildURIFromPattern(operationName, request.getQueryParameters());
            log.debug("Using customized endpoint url: {}", customizedEndpointUrl);
         }
         ClientHttpRequest httpRequest = clientHttpRequestFactory.createRequest(new URI(customizedEndpointUrl), method);

         // Prepare headers on httpRequest and report on request.
         Set<Header> headers = prepareRequestHeaders(operation, httpRequest, request, testResult);

         // Allow extensions to realize some pre-processing of request.
         prepareRequest(request);

         // If there's input content, add it to request.
         if (request.getContent() != null) {
            // Update request content with rendered body if necessary.
            request.setContent(TestRunnerCommons.renderRequestContent(request, headers));
            log.trace("Sending following request content: {}", request.getContent());
            httpRequest.getBody().write(request.getContent().getBytes());
         }

         // Actually execute request.
         long startTime = System.currentTimeMillis();
         ClientHttpResponse httpResponse = null;
         try {
            httpResponse = httpRequest.execute();
         } catch (IOException ioe) {
            log.error("IOException while executing request {} on {}", request.getName(), customizedEndpointUrl, ioe);
            code = TestReturn.FAILURE_CODE;
            message = ioe.getMessage();
         }
         long duration = System.currentTimeMillis() - startTime;

         // Extract and store response body so that stream may not be consumed more than 1 time ;-)
         String responseContent = getResponseContent(httpResponse);

         // If still in success, check if http code is out of correct ranges (20x and 30x).
         if (code == TestReturn.SUCCESS_CODE) {
            code = extractTestReturnCode(service, operation, request, httpResponse, responseContent);
            message = extractTestReturnMessage(service, operation, request, httpResponse);
         }

         // Create a Response object and complete it for returning.
         Response response = new Response();
         completeResponse(response, httpResponse, responseContent);

         result.add(new TestReturn(code, duration, message, request, response));
      }
      return result;
   }

   /**
    * Build the HttpMethod corresponding to string. Default to POST if unknown or unrecognized.
    */
   @Override
   public HttpMethod buildMethod(String method) {
      if (method != null) {
         if ("GET".equals(method.toUpperCase().trim())) {
            return HttpMethod.GET;
         } else if ("PUT".equals(method.toUpperCase().trim())) {
            return HttpMethod.PUT;
         } else if ("DELETE".equals(method.toUpperCase().trim())) {
            return HttpMethod.DELETE;
         } else if ("PATCH".equals(method.toUpperCase().trim())) {
            return HttpMethod.PATCH;
         } else if ("OPTIONS".equals(method.toUpperCase().trim())) {
            return HttpMethod.OPTIONS;
         }
      }
      return HttpMethod.POST;
   }

   /**
    * Manage headers or additional headers preparation on httpRequest and report on request.
    * @param operation   The operation this request is prepared for
    * @param httpRequest The http request to preapre
    * @param request     The recorded microcks request to report values on
    * @param testResult  The results that may contain headers override
    * @return The prepared headers.
    */
   protected Set<Header> prepareRequestHeaders(Operation operation, ClientHttpRequest httpRequest, Request request,
         TestResult testResult) {
      Set<Header> headers = TestRunnerCommons.collectHeaders(testResult, request, operation);

      if (!headers.isEmpty()) {
         for (Header header : headers) {
            log.debug("Adding header {} to request", header.getName());
            httpRequest.getHeaders().add(header.getName(), buildValue(header.getValues()));
         }
      }
      // Update request headers for traceability of possibly added ones.
      request.setHeaders(headers);

      // Now manage specific authorization headers if there's a secret.
      if (secret != null) {
         addAuthorizationHeadersFromSecret(httpRequest, request, secret);
      }
      return headers;
   }

   /**
    * Extract the Http response body as a string.
    * @param httpResponse The http response
    * @return The UTF-8 string representation of response body content
    * @throws IOException if http response cannot be read
    */
   protected String getResponseContent(ClientHttpResponse httpResponse) throws IOException {
      if (httpResponse != null) {
         StringWriter writer = new StringWriter();
         IOUtils.copy(httpResponse.getBody(), writer, StandardCharsets.UTF_8);
         return writer.toString();
      }
      return null;
   }

   /**
    * This is a hook for allowing sub-classes to redefine the criteria for telling a response is a success or a failure.
    * This implementation check raw http code (success if in 20x range, failure if not).
    * @param service         The service under test
    * @param operation       The tested operation
    * @param request         The tested reference request
    * @param httpResponse    The received response from endpoint
    * @param responseContent The response body content if any (may be null)
    * @return The test result code, whether TestReturn.SUCCESS_CODE or TestReturn.FAILURE_CODE
    */
   protected int extractTestReturnCode(Service service, Operation operation, Request request,
         ClientHttpResponse httpResponse, String responseContent) {
      int code = TestReturn.SUCCESS_CODE;
      // Set code to failure if http code out of correct ranges (20x and 30x).
      try {
         if (httpResponse.getStatusCode().value() > 299) {
            log.debug("Http status code is {}, marking test as failed.", httpResponse.getStatusCode().value());
            code = TestReturn.FAILURE_CODE;
         }
      } catch (IOException ioe) {
         log.debug(IOEXCEPTION_STATUS_CODE, ioe);
         code = TestReturn.FAILURE_CODE;
      }
      return code;
   }

   /**
    * This is a hook for allowing sub-classes to realize some pre-processing on request before it is actually issued to
    * test endpoint.
    * @param request The request that will be sent to endpoint
    */
   protected void prepareRequest(Request request) {
      // Nothing to do in this base implementation, use raw request.
   }

   /**
    * This is a hook for allowing sub-classes to redefine the extraction of success or failure message. This
    * implementation just extract raw http code.
    * @param service      The service under test
    * @param operation    The tested operation
    * @param request      The tested reference request
    * @param httpResponse The received response from endpoint
    * @return The test result message.
    */
   protected String extractTestReturnMessage(Service service, Operation operation, Request request,
         ClientHttpResponse httpResponse) {
      String message = null;
      // Set code to failure if http code out of correct ranges (20x and 30x).
      try {
         message = String.valueOf(httpResponse.getStatusCode().value());
      } catch (IOException ioe) {
         log.debug(IOEXCEPTION_STATUS_CODE, ioe);
         message = IOEXCEPTION_STATUS_CODE;
      }
      return message;
   }

   /**
    * Complete the microcks domain response from http response.
    * @param response        The Microcks domain response
    * @param httpResponse    The Http response
    * @param responseContent The Http response body content previously extracted (to prevent reading it multiple time)
    * @throws IOException If status code of response cannot be read
    */
   protected void completeResponse(Response response, ClientHttpResponse httpResponse, String responseContent)
         throws IOException {
      if (httpResponse != null) {
         response.setContent(responseContent);
         response.setStatus(String.valueOf(httpResponse.getStatusCode().value()));
         log.debug("Response Content-Type: {}", httpResponse.getHeaders().getContentType());

         MediaType contentType = httpResponse.getHeaders().getContentType();
         if (contentType != null) {
            response.setMediaType(contentType.toString());
         }
         Set<Header> headers = buildHeaders(httpResponse);
         if (!headers.isEmpty()) {
            response.setHeaders(headers);
         }
         log.debug("Closing http response");
         httpResponse.close();
      }
   }

   /** Build domain headers from ClientHttpResponse ones. */
   private Set<Header> buildHeaders(ClientHttpResponse httpResponse) {
      Set<Header> headers = new HashSet<>();
      if (!httpResponse.getHeaders().isEmpty()) {
         HttpHeaders responseHeaders = httpResponse.getHeaders();
         for (Entry<String, List<String>> responseHeader : responseHeaders.entrySet()) {
            Header header = new Header();
            header.setName(responseHeader.getKey());
            header.setValues(new HashSet<>(responseHeader.getValue()));
            headers.add(header);
         }
      }
      return headers;
   }

   /** Complete the test request with authorization data coming from secret. */
   private void addAuthorizationHeadersFromSecret(ClientHttpRequest httpRequest, Request request, Secret secret) {
      if (secret != null) {
         // If Basic authentication required, set request property.
         if (secret.getUsername() != null && secret.getPassword() != null) {
            log.debug("Secret contains username/password, assuming Authorization Basic");
            // Building a base64 string.
            String encoded = Base64.getEncoder()
                  .encodeToString((secret.getUsername() + ":" + secret.getPassword()).getBytes(StandardCharsets.UTF_8));
            httpRequest.getHeaders().set(HttpHeaders.AUTHORIZATION, "Basic " + encoded);
            // Add to Microcks request for traceability.
            request.getHeaders().add(buildAuthHeaderWithSecret(HttpHeaders.AUTHORIZATION, "Basic "));
         }

         // If Token authentication required, set request property.
         if (secret.getToken() != null) {
            if (secret.getTokenHeader() != null && !secret.getTokenHeader().trim().isEmpty()) {
               log.debug("Secret contains token and token header, adding them as request header");
               httpRequest.getHeaders().set(secret.getTokenHeader().trim(), secret.getToken());
               // Add to Microcks request for traceability.
               request.getHeaders().add(buildAuthHeaderWithSecret(secret.getTokenHeader().trim(), ""));
            } else {
               log.debug("Secret contains token only, assuming Authorization Bearer");
               httpRequest.getHeaders().set(HttpHeaders.AUTHORIZATION, "Bearer " + secret.getToken());
               // Add to Microcks request for traceability.
               request.getHeaders().add(buildAuthHeaderWithSecret(HttpHeaders.AUTHORIZATION, "Bearer "));
            }
         }
      }
   }

   /** Build a Microcks header for traceability. */
   private Header buildAuthHeaderWithSecret(String name, String type) {
      Header authHeader = new Header();
      authHeader.setName(name);
      authHeader.setValues(new TreeSet<>(Arrays.asList(type + "<value-from-secret>")));
      return authHeader;
   }
}

