public class AsyncAPI3Importer extends AbstractJsonRepositoryImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(AsyncAPI3Importer.class);

   private static final List<String> VALID_VERBS = Arrays.asList("send", "receive");


   /**
    * Build a new importer.
    * @param specificationFilePath The path to local AsyncAPI spec file
    * @param referenceResolver     An optional resolver for references present into the AsyncAPI file
    * @throws IOException if project file cannot be found or read.
    */
   public AsyncAPI3Importer(String specificationFilePath, ReferenceResolver referenceResolver) throws IOException {
      super(specificationFilePath, referenceResolver);
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      // Build a new service.
      Service service = new Service();

      service.setName(rootSpecification.path("info").path("title").asText());
      service.setVersion(rootSpecification.path("info").path("version").asText());
      service.setType(ServiceType.EVENT);

      // Complete metadata if specified via extension.
      if (rootSpecification.path("info").has(MetadataExtensions.MICROCKS_EXTENSION)) {
         Metadata metadata = new Metadata();
         MetadataExtractor.completeMetadata(metadata,
               rootSpecification.path("info").path(MetadataExtensions.MICROCKS_EXTENSION));
         service.setMetadata(metadata);
      }

      // Before extraction operations, we need to get and build external reference if we have a resolver.
      initializeReferencedResources(service);

      // Then build its operations.
      service.setOperations(extractOperations());

      result.add(service);
      return result;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) {
      List<Resource> results = new ArrayList<>();

      // Build a suitable name.
      String name = service.getName() + "-" + service.getVersion();
      if (Boolean.TRUE.equals(isYaml)) {
         name += ".yaml";
      } else {
         name += ".json";
      }

      // Build a brand-new resource just with spec content.
      Resource resource = new Resource();
      resource.setName(name);
      resource.setType(ResourceType.ASYNC_API_SPEC);
      results.add(resource);
      // Set the content of main OpenAPI that may have been updated with normalized dependencies with initializeReferencedResources().
      resource.setContent(rootSpecificationContent);

      // Add the external resources that were imported during service discovery.
      results.addAll(externalResources);

      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      List<Exchange> messageDefs = new ArrayList<>();

      // Retrieve default content type, defaulting to application/json.
      String defaultContentType = "application/json";
      if (rootSpecification.has("defaultContentType")) {
         defaultContentType = rootSpecification.get("defaultContentType").asText("application/json");
      }

      // Iterate on specification "operations" nodes.
      Iterator<Map.Entry<String, JsonNode>> operations = rootSpecification.path("operations").fields();
      while (operations.hasNext()) {
         Map.Entry<String, JsonNode> operationEntry = operations.next();
         JsonNode operationNode = operationEntry.getValue();

         // Got to filter out for current operation only.
         String action = operationNode.path("action").asText();
         String operationName = action.toUpperCase() + " " + operationEntry.getKey();

         if (operationName.equals(operation.getName()) && operationNode.path(MESSAGES).isArray()) {
            // Search for event messages.
            List<EventMessage> eventMessages = buildEventMessages(operationNode, defaultContentType);

            if (eventMessages != null && !eventMessages.isEmpty()) {
               // Update dispatch information if necessary.
               completeDispatchingCriteria(operation, operationNode, eventMessages);

               eventMessages.stream().forEach(eventMessage -> messageDefs.add(new UnidirectionalEvent(eventMessage)));
            }
            break;
         }
      }
      return messageDefs;
   }

   /** Extract the list of operations from Specification. */
   private List<Operation> extractOperations() {
      List<Operation> results = new ArrayList<>();

      // Iterate on specification "operations" nodes.
      Iterator<Map.Entry<String, JsonNode>> operations = rootSpecification.path("operations").fields();
      while (operations.hasNext()) {
         Map.Entry<String, JsonNode> operationEntry = operations.next();
         String operationShortName = operationEntry.getKey();

         JsonNode operationNode = operationEntry.getValue();
         String action = operationNode.path("action").asText();
         if (VALID_VERBS.contains(action)) {
            // Build and add this operation to the list.
            Operation operation = buildValidOperation(operationShortName, action, operationNode);
            results.add(operation);
         }
      }

      return results;
   }

   /** Build a single operation having its name, action and Json. */
   private Operation buildValidOperation(String name, String action, JsonNode operationNode) {
      String operationName = action.toUpperCase() + " " + name;

      Operation operation = new Operation();
      operation.setName(operationName);
      operation.setMethod(action.toUpperCase());

      // Complete operation properties if any.
      if (operationNode.has(MetadataExtensions.MICROCKS_OPERATION_EXTENSION)) {
         MetadataExtractor.completeOperationProperties(operation,
               operationNode.path(MetadataExtensions.MICROCKS_OPERATION_EXTENSION));
      }

      // Look for bindings at the operation level.
      if (operationNode.has(BINDINGS)) {
         AsyncAPICommons.completeOperationLevelBindings(operation, operationNode.get(BINDINGS));
      }

      // Then, check the related channels and extract dispatching info and bindings.
      if (operationNode.path(CHANNEL_NODE).isObject()) {
         JsonNode channel = operationNode.get(CHANNEL_NODE);
         JsonNode channelNode = followRefIfAny(channel);

         if (channelNode.has(ADDRESS_NODE)) {
            String address = channelNode.get(ADDRESS_NODE).asText();
            if (AsyncAPICommons.channelAddressHasParts(address)) {
               operation.setDispatcher(DispatchStyles.URI_PARTS);
               operation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromStringPattern(address));
            }
            operation.addResourcePath(address);
         }

         if (channelNode.has(BINDINGS)) {
            AsyncAPICommons.completeChannelLevelBindings(operation, channelNode.get(BINDINGS));
         }
      }

      // Then, check the related messages and complete bindings.
      if (operationNode.path(MESSAGES).isArray()) {
         Iterator<JsonNode> messages = operationNode.path(MESSAGES).elements();
         while (messages.hasNext()) {
            JsonNode messageInChannelNode = followRefIfAny(messages.next());
            JsonNode messageNode = followRefIfAny(messageInChannelNode);
            if (messageNode.has(BINDINGS)) {
               AsyncAPICommons.completeMessageLevelBindings(operation, messageNode.get(BINDINGS));
            }
         }
      }

      return operation;
   }

   /** If necessary, complete an operation and its messages dispatch information. */
   private void completeDispatchingCriteria(Operation operation, JsonNode operationNode,
         List<EventMessage> eventMessages) {
      // Update dispatch information if necessary.
      if (DispatchStyles.URI_PARTS.equals(operation.getDispatcher())) {

         // Retrieve information on channel address and parameters.
         JsonNode channelNode = followRefIfAny(operationNode.get(CHANNEL_NODE));
         String address = channelNode.get(ADDRESS_NODE).asText();

         // We have 2 cases here: parameter value can be dynamic, expressed with a location in message
         // or parameter value can be static, expressed as an examples.
         List<AsyncAPIParameter> dynamicParameters = getDynamicParameters(channelNode);
         Map<String, Map<String, String>> parametersByMessage = getParametersByMessage(channelNode);
         ObjectMapper mapper = getObjectMapper(true);

         for (EventMessage eventMessage : eventMessages) {
            // Start initializing message parameter values with the static ones.
            Map<String, String> parameterValues = parametersByMessage.getOrDefault(eventMessage.getName(),
                  new HashMap<>());

            // Extract each dynamic parameter with its value coming from message.
            for (AsyncAPIParameter parameter : dynamicParameters) {
               String parameterValue = null;

               try {
                  if (parameter.location().startsWith("$message.payload#")) {
                     String location = parameter.location().substring("$message.payload#".length());
                     JsonNode eventMessageRootNode = mapper.readTree(eventMessage.getContent());
                     parameterValue = eventMessageRootNode.at(location).asText();
                  }
               } catch (Exception e) {
                  log.warn("Failed to extract the location value in {} from message {} for operation {}",
                        parameter.location(), eventMessage.getName(), operation.getName());
                  log.warn("Pursuing with the other ones but dispatch will be incomplete");
               }
               if (parameterValue != null) {
                  parameterValues.put(parameter.name(), parameterValue);
               }
            }

            // UPdate operation resource paths and message dispatch criteria.
            String resourcePath = URIBuilder.buildURIFromPattern(address, parameterValues);
            operation.addResourcePath(resourcePath);
            eventMessage.setDispatchCriteria(DispatchCriteriaHelper.buildFromPartsMap(address, parameterValues));
         }
      }
   }

   /** Given a Channel Json node, get its dynamic parameter definitions (those having a location). */
   private List<AsyncAPIParameter> getDynamicParameters(JsonNode channelNode) {
      List<AsyncAPIParameter> results = new ArrayList<>();

      if (channelNode.path(PARAMETERS_NODE).isObject()) {
         Iterator<Entry<String, JsonNode>> parameters = channelNode.get(PARAMETERS_NODE).fields();
         while (parameters.hasNext()) {
            Entry<String, JsonNode> parameterEntry = parameters.next();
            JsonNode parameter = followRefIfAny(parameterEntry.getValue());

            String parameterName = parameterEntry.getKey();

            if (parameter.has(LOCATION_NODE)) {
               if (log.isDebugEnabled()) {
                  log.debug("Processing param {} for channel {}, with location {}", parameterName,
                        channelNode.get("address").asText(), parameter.get(LOCATION_NODE).asText());
               }
               results.add(new AsyncAPIParameter(parameterName, parameter.get(LOCATION_NODE).asText()));
            }
         }
      }
      return results;
   }

   /**
    * Given a Channel Json node, get its static parameter values (those without a location), organized by message
    * example name. Key of value map is parameter name. Value of value map is parameter value ;-)
    */
   private Map<String, Map<String, String>> getParametersByMessage(JsonNode channelNode) {
      Map<String, Map<String, String>> results = new HashMap<>();

      if (channelNode.path(PARAMETERS_NODE).isObject()) {
         Iterator<Entry<String, JsonNode>> parameters = channelNode.get(PARAMETERS_NODE).fields();
         while (parameters.hasNext()) {
            Entry<String, JsonNode> parameterEntry = parameters.next();
            JsonNode parameter = followRefIfAny(parameterEntry.getValue());
            String parameterName = parameterEntry.getKey();
            if (!parameter.has(LOCATION_NODE) && parameter.path(EXAMPLES_NODE).isArray()) {
               Iterator<JsonNode> examples = parameter.get(EXAMPLES_NODE).elements();
               while (examples.hasNext()) {
                  String example = examples.next().asText();
                  if (example.contains(":")) {
                     String exampleKey = example.substring(0, example.indexOf(":"));
                     String exampleValue = example.substring(example.indexOf(":") + 1);

                     if (log.isDebugEnabled()) {
                        log.debug("Processing param {} for channel {} for message {}", parameterName,
                              channelNode.get("address").asText(), exampleKey);
                     }

                     Map<String, String> exampleParams = results.getOrDefault(exampleKey, new HashMap<>());
                     exampleParams.put(parameterName, exampleValue);
                     results.put(exampleKey, exampleParams);
                  }
               }
            }
         }
      }
      return results;
   }


   /** Build a list of EventMessages from an operation Json node. */
   private List<EventMessage> buildEventMessages(JsonNode operationNode, String defaultContentType) {
      List<EventMessage> eventMessages = null;
      Iterator<JsonNode> messages = operationNode.path(MESSAGES).elements();
      while (messages.hasNext()) {
         JsonNode operationMessageNode = messages.next();
         JsonNode messageInChannelNode = followRefIfAny(operationMessageNode);
         JsonNode messageNode = followRefIfAny(messageInChannelNode);

         // Get message content type.
         String contentType = defaultContentType;
         if (messageNode.has("contentType")) {
            contentType = messageNode.path("contentType").asText();
         }

         // Retrieve the messageName from message ref found in operation.
         String messageName = operationMessageNode.path("$ref").textValue();

         if (messageName != null && messageNode.has(EXAMPLES_NODE)) {
            // Compute a short message name if examples have no name attribute.
            messageName = messageName.substring(messageName.lastIndexOf("/") + 1);
            eventMessages = buildEventMessageFromExamples(messageName, contentType, messageNode.get(EXAMPLES_NODE));
         }
      }
      return eventMessages;
   }

   /** Build a list of EventMessages from a Message examples Json node. */
   private List<EventMessage> buildEventMessageFromExamples(String messageName, String contentType,
         JsonNode examplesNode) {
      List<EventMessage> exchanges = new ArrayList<>();

      Iterator<JsonNode> examples = examplesNode.elements();
      while (examples.hasNext()) {
         JsonNode exampleNode = examples.next();

         EventMessage eventMessage = new EventMessage();
         // Use name attribute if present, otherwise generate from message name.
         if (exampleNode.has("name")) {
            eventMessage.setName(exampleNode.get("name").asText());
         } else {
            eventMessage.setName(messageName + "-" + (exchanges.size() + 1));
         }

         eventMessage.setMediaType(contentType);
         eventMessage.setContent(getExamplePayload(exampleNode));

         // Now complete with specified headers.
         List<Header> headers = AsyncAPICommons.getExampleHeaders(exampleNode);
         for (Header header : headers) {
            eventMessage.addHeader(header);
         }

         exchanges.add(eventMessage);
      }
      return exchanges;
   }

   /**
    * Get the value of an example. This can be direct value field or those of followed $ref.
    */
   private String getExamplePayload(JsonNode example) {
      if (example.has(EXAMPLE_PAYLOAD_NODE)) {
         return getValueString(example.path(EXAMPLE_PAYLOAD_NODE));
      }
      if (example.has("$payloadRef")) {
         // $ref: '#/components/examples/param_laurent'
         String ref = example.path("$payloadRef").asText();
         JsonNode component = rootSpecification.at(ref.substring(1));
         return getExamplePayload(component);
      }
      return null;
   }

   private record AsyncAPIParameter(String name, String location) {
   }
}

public class AsyncAPIImporter extends AbstractJsonRepositoryImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(AsyncAPIImporter.class);

   private static final String[] MULTI_STRUCTURES = { "allOf", "anyOf", "oneOf" };
   private static final List<String> VALID_VERBS = Arrays.asList("subscribe", "publish");

   /**
    * Build a new importer.
    * @param specificationFilePath The path to local AsyncAPI spec file
    * @param referenceResolver     An optional resolver for references present into the AsyncAPI file
    * @throws IOException if project file cannot be found or read.
    */
   public AsyncAPIImporter(String specificationFilePath, ReferenceResolver referenceResolver) throws IOException {
      super(specificationFilePath, referenceResolver);
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      // Build a new service.
      Service service = new Service();

      service.setName(rootSpecification.path("info").path("title").asText());
      service.setVersion(rootSpecification.path("info").path("version").asText());
      service.setType(ServiceType.EVENT);

      // Complete metadata if specified via extension.
      if (rootSpecification.path("info").has(MetadataExtensions.MICROCKS_EXTENSION)) {
         Metadata metadata = new Metadata();
         MetadataExtractor.completeMetadata(metadata,
               rootSpecification.path("info").path(MetadataExtensions.MICROCKS_EXTENSION));
         service.setMetadata(metadata);
      }

      // Then build its operations.
      service.setOperations(extractOperations());

      result.add(service);
      return result;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) {
      List<Resource> results = new ArrayList<>();
      Map<String, Resource> resolvedExternalRefResources = new HashMap<>();

      // Build a suitable name.
      String name = service.getName() + "-" + service.getVersion();
      if (Boolean.TRUE.equals(isYaml)) {
         name += ".yaml";
      } else {
         name += ".json";
      }

      // Build a brand-new resource just with spec content.
      Resource resource = new Resource();
      resource.setName(name);
      resource.setType(ResourceType.ASYNC_API_SPEC);
      results.add(resource);

      // Browser operations messages and message traits to see if we have
      // references for external schemas only if we have a resolver available.
      if (referenceResolver != null) {
         for (Operation operation : service.getOperations()) {
            String[] operationElements = operation.getName().split(" ");
            String messageNamePtr = "/channels/" + operationElements[1].replace("/", "~1");
            messageNamePtr += "/" + operationElements[0].toLowerCase() + "/message";

            JsonNode messageNode = rootSpecification.at(messageNamePtr);
            if (messageNode != null) {
               // If it's a $ref, then navigate to it.
               messageNode = followRefIfAny(messageNode);

               // Extract payload schema here.
               if (messageNode.has(EXAMPLE_PAYLOAD_NODE)) {
                  JsonNode payloadNode = messageNode.path(EXAMPLE_PAYLOAD_NODE);

                  // Check we have a reference that is not a local one.
                  if (payloadNode.has("$ref")) {

                     Set<String> references = new HashSet<>();
                     findAllExternalRefsAsyncAPI(payloadNode, references);

                     for (String ref : references) {
                        // We may have already resolved it if referenced more than once.
                        Resource schemaResource = resolvedExternalRefResources.get(ref);
                        if (schemaResource == null) {
                           try {
                              // Remove trailing anchor marker (we may have this in Avro schema to point exact
                              // Resource)
                              if (ref.contains("#")) {
                                 ref = ref.substring(0, ref.indexOf("#"));
                              }

                              // Extract content using resolver.
                              String content = referenceResolver.getReferenceContent(ref, StandardCharsets.UTF_8);
                              String resourceName = ref.substring(ref.lastIndexOf('/') + 1);

                              // Build a new resource from content. Use the escaped operation path.
                              schemaResource = new Resource();
                              schemaResource.setName(IdBuilder.buildResourceFullName(service, resourceName));
                              schemaResource.setPath(ref);
                              schemaResource.setContent(content);

                              // We have to look at schema format to know the type.
                              if (messageNode.has("schemaFormat")) {
                                 String schemaFormat = messageNode.path("schemaFormat").asText();

                                 if (schemaFormat.startsWith("application/vnd.aai.asyncapi")) {
                                    schemaResource.setType(ResourceType.ASYNC_API_SCHEMA);
                                 } else if (schemaFormat.startsWith("application/vnd.oai.openapi")) {
                                    schemaResource.setType(ResourceType.OPEN_API_SCHEMA);
                                 } else if (schemaFormat.startsWith("application/schema+json")
                                       || schemaFormat.startsWith("application/schema+yaml")) {
                                    schemaResource.setType(ResourceType.JSON_SCHEMA);
                                 } else if (schemaFormat.startsWith("application/vnd.apache.avro")) {
                                    schemaResource.setType(ResourceType.AVRO_SCHEMA);
                                 }
                              } else {
                                 // We should probably go deeper here and inspect the content of resolved
                                 // resource
                                 // to actually get the real schema type...
                                 schemaResource.setType(ResourceType.JSON_SCHEMA);
                              }

                              if (!ref.startsWith("http")) {
                                 // If a relative resource, replace with new name.
                                 rootSpecificationContent = rootSpecificationContent.replace(ref,
                                       URLEncoder.encode(schemaResource.getName(), "UTF-8"));
                              }

                              results.add(schemaResource);
                           } catch (IOException ioe) {
                              log.error("IOException while trying to resolve reference " + ref, ioe);
                              log.info("Ignoring the reference {} cause it could not be resolved", ref);
                           }
                           // Mark it as resolved.
                           resolvedExternalRefResources.put(ref, schemaResource);
                        }

                        if (schemaResource != null) {
                           schemaResource.addOperation(operation.getName());
                        } else {
                           log.warn("Cannot add operation because schema resourse is null");
                        }
                     }
                  }
               }
            }
         }
         // Finally try to clean up resolved references and associated resources (files)
         referenceResolver.cleanResolvedReferences();
      }
      // Set the content of main AsyncAPI that may have been updated with dereferenced
      // dependencies.
      resource.setContent(rootSpecificationContent);

      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      List<Exchange> result = new ArrayList<>();

      // Retrieve default content type, defaulting to application/json.
      String defaultContentType = "application/json";
      if (rootSpecification.has("defaultContentType")) {
         defaultContentType = rootSpecification.get("defaultContentType").asText("application/json");
      }

      // Iterate on specification "channels" nodes.
      Iterator<Entry<String, JsonNode>> channels = rootSpecification.path("channels").fields();
      while (channels.hasNext()) {
         Entry<String, JsonNode> channel = channels.next();
         String channelName = channel.getKey();
         Map<String, Map<String, String>> pathParametersByExample = extractParametersByExample(channel.getValue());

         // Iterate on specification path, "verbs" nodes.
         Iterator<Entry<String, JsonNode>> verbs = channel.getValue().fields();
         while (verbs.hasNext()) {
            Entry<String, JsonNode> verb = verbs.next();
            String verbName = verb.getKey();

            // Find the correct operation.
            if (operation.getName().equals(verbName.toUpperCase() + " " + channelName.trim())) {
               JsonNode messageBody = verb.getValue().path("message");

               // If it's a $ref or multi-structure (oneOf, anyOf, allOf), then navigate to
               // them.
               List<JsonNode> messageBodies = followRefsIfAny(messageBody);

               for (JsonNode extractedMsgBody : messageBodies) {
                  // Get message content type.
                  String contentType = defaultContentType;
                  if (extractedMsgBody.has("contentType")) {
                     contentType = extractedMsgBody.path("contentType").asText();
                  }
                  // No need to go further if no examples.
                  if (extractedMsgBody.has(EXAMPLES_NODE)) {
                     Iterator<JsonNode> examples = extractedMsgBody.path(EXAMPLES_NODE).elements();
                     int exampleIndex = 0;
                     while (examples.hasNext()) {
                        JsonNode exampleNode = examples.next();

                        EventMessage eventMessage = null;
                        if (exampleNode.has("name")) {
                           // As of AsyncAPI 2.1.0 () we can now have a 'name' property for examples!
                           eventMessage = extractFromAsyncAPI21Example(contentType, exampleNode);
                        } else if (exampleNode.has(EXAMPLE_PAYLOAD_NODE)) {
                           // As of https://github.com/microcks/microcks/issues/385, we should support the restriction
                           // coming from AsyncAPI GItHub master revision and associated tooling...
                           eventMessage = extractFromAsyncAPIExample(contentType, exampleNode,
                                 channelName.trim() + "-" + exampleIndex);
                        } else {
                           eventMessage = extractFromMicrocksExample(contentType, exampleNode);
                        }
                        // If import succeed, deal with the dispatching criteria stuffs and
                        // add this event message as a valid event in results exchanges.
                        if (eventMessage != null) {
                           if (DispatchStyles.URI_PARTS.equals(operation.getDispatcher())) {
                              String resourcePathPattern = channelName;
                              Map<String, String> parts = pathParametersByExample.get(eventMessage.getName());
                              String resourcePath = URIBuilder.buildURIFromPattern(resourcePathPattern, parts);
                              operation.addResourcePath(resourcePath);
                              eventMessage.setDispatchCriteria(
                                    DispatchCriteriaHelper.buildFromPartsMap(operation.getDispatcherRules(), parts));
                           }

                           result.add(new UnidirectionalEvent(eventMessage));
                        }
                        exampleIndex++;
                     }
                  }
               }
            }
         }
      }
      return result;
   }

   /** Extract the list of operations from Specification. */
   private List<Operation> extractOperations() {
      List<Operation> results = new ArrayList<>();

      // Iterate on specification "channels" nodes.
      Iterator<Entry<String, JsonNode>> channels = rootSpecification.path("channels").fields();
      while (channels.hasNext()) {
         Entry<String, JsonNode> channel = channels.next();
         String channelName = channel.getKey();

         // Iterate on specification path, "verbs" nodes.
         Iterator<Entry<String, JsonNode>> verbs = channel.getValue().fields();
         while (verbs.hasNext()) {
            Entry<String, JsonNode> verb = verbs.next();
            String verbName = verb.getKey();

            // Only deal with real verbs for now.
            if (VALID_VERBS.contains(verbName)) {
               String operationName = verbName.toUpperCase() + " " + channelName.trim();

               Operation operation = new Operation();
               operation.setName(operationName);
               operation.setMethod(verbName.toUpperCase());

               // Complete operation properties if any.
               if (verb.getValue().has(MetadataExtensions.MICROCKS_OPERATION_EXTENSION)) {
                  MetadataExtractor.completeOperationProperties(operation,
                        verb.getValue().path(MetadataExtensions.MICROCKS_OPERATION_EXTENSION));
               }

               // Deal with dispatcher stuffs.
               if (operation.getDispatcher() == null && channelHasParts(channelName)) {
                  operation.setDispatcher(DispatchStyles.URI_PARTS);
                  operation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIPattern(channelName));
               } else {
                  operation.addResourcePath(channelName);
               }

               // We have to look also for bindings. First at the upper channel level.
               if (channel.getValue().has(BINDINGS)) {
                  AsyncAPICommons.completeChannelLevelBindings(operation, channel.getValue().get(BINDINGS));
               }

               // Then look for bindings at the operation level.
               if (verb.getValue().has(BINDINGS)) {
                  AsyncAPICommons.completeOperationLevelBindings(operation, verb.getValue().get(BINDINGS));
               }

               // Then look for bindings at the message level.
               JsonNode messageBody = verb.getValue().path("message");
               messageBody = followRefIfAny(messageBody);
               if (messageBody.has(BINDINGS)) {
                  AsyncAPICommons.completeMessageLevelBindings(operation, messageBody.get(BINDINGS));
               }

               results.add(operation);
            }
         }
      }

      return results;
   }

   /** Browse Json node to extract references and store them into externalRefs. */
   private void findAllExternalRefsAsyncAPI(JsonNode node, Set<String> externalRefs) {
      // If node as a $ref child, it's a stop condition.
      if (node.has("$ref")) {
         String ref = node.path("$ref").asText();
         if (!ref.startsWith("#")) {
            externalRefs.add(ref);
         } else {
            findAllExternalRefsAsyncAPI(followRefIfAny(node), externalRefs);
         }
      } else {
         // Iterate on all other children.
         Iterator<JsonNode> children = node.elements();
         while (children.hasNext()) {
            findAllExternalRefsAsyncAPI(children.next(), externalRefs);
         }
      }
   }

   /** Extract example using the AsyncAPI 2.1 new 'name' property. */
   private EventMessage extractFromAsyncAPI21Example(String contentType, JsonNode exampleNode) {
      // Retrieve name & payload value.
      String exampleName = exampleNode.path("name").asText();
      String exampleValue = getExamplePayload(exampleNode);

      // Build and store a request object.
      EventMessage eventMessage = new EventMessage();
      eventMessage.setName(exampleName);
      eventMessage.setContent(exampleValue);
      eventMessage.setMediaType(contentType);

      // Now complete with specified headers.
      List<Header> headers = AsyncAPICommons.getExampleHeaders(exampleNode);
      for (Header header : headers) {
         eventMessage.addHeader(header);
      }

      return eventMessage;
   }

   /** Extract example using the AsyncAPI master branch restrictions. */
   private EventMessage extractFromAsyncAPIExample(String contentType, JsonNode exampleNode, String exampleName) {
      // Retrieve payload value.
      String exampleValue = getExamplePayload(exampleNode);

      // Build and store a request object.
      EventMessage eventMessage = new EventMessage();
      eventMessage.setName(exampleName);
      eventMessage.setContent(exampleValue);
      eventMessage.setMediaType(contentType);

      // Now complete with specified headers.
      List<Header> headers = AsyncAPICommons.getExampleHeaders(exampleNode);
      for (Header header : headers) {
         eventMessage.addHeader(header);
      }

      return eventMessage;
   }

   /** Extract example using the Microcks (and Apicurio) extended notation. */
   private EventMessage extractFromMicrocksExample(String contentType, JsonNode exampleNode) {
      EventMessage eventMessage = null;

      Iterator<String> exampleNames = exampleNode.fieldNames();
      while (exampleNames.hasNext()) {
         String exampleName = exampleNames.next();
         JsonNode example = exampleNode.path(exampleName);

         // No need to go further if no payload.
         if (example.has(EXAMPLE_PAYLOAD_NODE)) {
            String exampleValue = getExamplePayload(example);

            // Build and store a request object.
            eventMessage = new EventMessage();
            eventMessage.setName(exampleName);
            eventMessage.setContent(exampleValue);
            eventMessage.setMediaType(contentType);

            // Now complete with specified headers.
            List<Header> headers = AsyncAPICommons.getExampleHeaders(example);
            for (Header header : headers) {
               eventMessage.addHeader(header);
            }
         }
      }
      return eventMessage;
   }

   /**
    * Get the value of an example. This can be direct value field or those of followed $ref.
    */
   private String getExamplePayload(JsonNode example) {
      if (example.has(EXAMPLE_PAYLOAD_NODE)) {
         return getValueString(example.path(EXAMPLE_PAYLOAD_NODE));
      }
      if (example.has("$payloadRef")) {
         // $ref: '#/components/examples/param_laurent'
         String ref = example.path("$payloadRef").asText();
         JsonNode component = rootSpecification.at(ref.substring(1));
         return getExamplePayload(component);
      }
      return null;
   }

   /** Check variables parts presence into given channel. */
   private static boolean channelHasParts(String channel) {
      return (channel.indexOf("/{") != -1);
   }

   /**
    * Extract parameters within a channel node and organize them by example. Key of value map is param name. Value of
    * value map is param value ;-)
    */
   private Map<String, Map<String, String>> extractParametersByExample(JsonNode node) {
      Map<String, Map<String, String>> results = new HashMap<>();
      Iterator<Entry<String, JsonNode>> parameters = node.path("parameters").fields();
      while (parameters.hasNext()) {
         Entry<String, JsonNode> parameterEntry = parameters.next();
         JsonNode parameter = parameterEntry.getValue();

         // If parameter is a $ref, navigate to it first.
         parameter = followRefIfAny(parameter);

         String parameterName = parameterEntry.getKey();
         log.debug("Processing param {}", parameterName);

         if (parameter.has(SCHEMA_NODE) && parameter.path(SCHEMA_NODE).has(EXAMPLES_NODE)) {
            JsonNode examplesNode = parameter.path(SCHEMA_NODE).path(EXAMPLES_NODE);

            if (examplesNode.isObject()) {
               Iterator<String> exampleNames = parameter.path(SCHEMA_NODE).path(EXAMPLES_NODE).fieldNames();

               while (exampleNames.hasNext()) {
                  String exampleName = exampleNames.next();
                  log.debug("Processing example {}", exampleName);

                  JsonNode example = parameter.path(SCHEMA_NODE).path(EXAMPLES_NODE).path(exampleName);
                  String exampleValue = getExampleValue(example);
                  log.debug("{} {} {}", parameterName, exampleName, exampleValue);

                  Map<String, String> exampleParams = results.computeIfAbsent(exampleName, k -> new HashMap<>());
                  exampleParams.put(parameterName, exampleValue);
               }
            } else if (examplesNode.isArray()) {
               Iterator<JsonNode> examples = examplesNode.elements();
               while (examples.hasNext()) {
                  JsonNode exampleNode = examples.next();

                  String exampleName = null;
                  String exampleValue = null;

                  // Try processing the "name:value" form
                  if (exampleNode.asText().contains(":")) {
                     String example = exampleNode.asText();
                     exampleName = example.substring(0, example.indexOf(":"));
                     exampleValue = example.substring(example.indexOf(":") + 1);
                  } else {
                     // Try processing the "name: > value: value" form
                     exampleName = exampleNode.fieldNames().next();
                     exampleValue = getExampleValue(exampleNode.fields().next().getValue());
                  }
                  log.debug("{} {} {}", parameterName, exampleName, exampleValue);

                  Map<String, String> exampleParams = results.computeIfAbsent(exampleName, k -> new HashMap<>());
                  exampleParams.put(parameterName, exampleValue);
               }
            }
         }
      }
      return results;
   }

   /**
    * Get the value of an example. This can be direct value field or those of followed $ref
    */
   private String getExampleValue(JsonNode example) {
      if (example.has(EXAMPLE_VALUE_NODE)) {
         JsonNode valueNode = followRefIfAny(example.path(EXAMPLE_VALUE_NODE));
         return getValueString(valueNode);
      }
      if (example.has("$ref")) {
         JsonNode component = followRefIfAny(example);
         return getExampleValue(component);
      }
      return null;
   }

   /** */
   private List<JsonNode> followRefsIfAny(JsonNode referencableNode) {
      List<JsonNode> results = new ArrayList<>();
      if (referencableNode.has("$ref")) {
         // Extract single reference.
         String ref = referencableNode.path("$ref").asText();
         results.add(rootSpecification.at(ref.substring(1)));
      } else {
         // Check for multi-structures.
         for (String structure : MULTI_STRUCTURES) {
            if (referencableNode.has(structure) && referencableNode.path(structure).isArray()) {
               ArrayNode arrayNode = (ArrayNode) referencableNode.path(structure);
               for (int i = 0; i < arrayNode.size(); i++) {
                  JsonNode structureNode = arrayNode.get(i);
                  results.add(followRefIfAny(structureNode));
               }
            }
         }
      }
      // If no reference found, put the node itself.
      if (results.isEmpty()) {
         results.add(referencableNode);
      }
      return results;
   }
}

public class GraphQLImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(GraphQLImporter.class);

   /** The starter marker for the comment referencing microck service and version identifiers. */
   public static final String MICROCKS_ID_STARTER = "microcksId:";

   /** The list of valid operation types. */
   public static final List<String> VALID_OPERATION_TYPES = Arrays.asList("query", "mutation");

   private final String specContent;
   private Document graphqlSchema;

   /**
    * Build a new importer.
    * @param graphqlFilePath The path to local GraphQL schema file
    * @throws IOException if project file cannot be found or read.
    */
   public GraphQLImporter(String graphqlFilePath) throws IOException {
      try {
         // Read spec bytes.
         byte[] bytes = Files.readAllBytes(Paths.get(graphqlFilePath));
         specContent = new String(bytes, StandardCharsets.UTF_8);

         // Parse schema file to a dom.
         graphqlSchema = Parser.parse(specContent);
      } catch (Exception e) {
         log.error("Exception while parsing GraphQL schema file " + graphqlFilePath, e);
         throw new IOException("GraphQL schema file parsing error");
      }
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> results = new ArrayList<>();

      Service service = new Service();
      service.setType(ServiceType.GRAPHQL);

      // 1st thing: look for comments to get service and version identifiers.
      for (Comment comment : graphqlSchema.getComments()) {
         String content = comment.getContent().trim();
         if (content.startsWith(MICROCKS_ID_STARTER)) {
            String identifiers = content.substring(MICROCKS_ID_STARTER.length());

            if (identifiers.indexOf(":") != -1) {
               String[] serviceAndVersion = identifiers.split(":");
               service.setName(serviceAndVersion[0].trim());
               service.setVersion(serviceAndVersion[1].trim());
               break;
            }
            log.error("microcksId comment is malformed. Expecting \'microcksId: <API_name>:<API_version>\'");
            throw new MockRepositoryImportException(
                  "microcksId comment is malformed. Expecting \'microcksId: <API_name>:<API_version>\'");
         }
      }
      if (service.getName() == null || service.getVersion() == null) {
         log.error("No microcksId: comment found into GraphQL schema to get API name and version");
         throw new MockRepositoryImportException(
               "No microcksId: comment found into GraphQL schema to get API name and version");
      }

      // We found a service, build its operations.
      service.setOperations(extractOperations());

      results.add(service);
      return results;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) throws MockRepositoryImportException {
      List<Resource> results = new ArrayList<>();

      // Just one resource: The GraphQL schema file.
      Resource schema = new Resource();
      schema.setName(service.getName() + "-" + service.getVersion() + ".graphql");
      schema.setType(ResourceType.GRAPHQL_SCHEMA);
      schema.setContent(specContent);
      results.add(schema);

      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      return new ArrayList<>();
   }

   /**
    * Extract the operations from GraphQL schema document.
    */
   private List<Operation> extractOperations() {
      List<Operation> results = new ArrayList<>();

      for (Definition definition : graphqlSchema.getDefinitions()) {
         if (definition instanceof ObjectTypeDefinition typeDefinition) {

            if (VALID_OPERATION_TYPES.contains(typeDefinition.getName().toLowerCase())) {
               List<Operation> operations = extractOperations(typeDefinition);
               results.addAll(operations);
            }
         }
      }
      return results;
   }

   private List<Operation> extractOperations(ObjectTypeDefinition typeDef) {
      List<Operation> results = new ArrayList<>();

      for (FieldDefinition fieldDef : typeDef.getFieldDefinitions()) {
         Operation operation = new Operation();
         operation.setName(fieldDef.getName());
         operation.setMethod(typeDef.getName().toUpperCase());

         // Deal with input names if any.
         if (fieldDef.getInputValueDefinitions() != null && !fieldDef.getInputValueDefinitions().isEmpty()) {
            operation.setInputName(getInputNames(fieldDef.getInputValueDefinitions()));

            boolean hasOnlyPrimitiveArgs = true;
            for (InputValueDefinition inputValueDef : fieldDef.getInputValueDefinitions()) {
               Type inputValueType = inputValueDef.getType();
               if (TypeUtil.isNonNull(inputValueType)) {
                  inputValueType = TypeUtil.unwrapOne(inputValueType);
               }
               if (TypeUtil.isList(inputValueType)) {
                  hasOnlyPrimitiveArgs = false;
               }
               TypeInfo inputValueTypeInfo = TypeInfo.typeInfo(inputValueType);
               if (!ScalarInfo.isGraphqlSpecifiedScalar(inputValueTypeInfo.getName())) {
                  hasOnlyPrimitiveArgs = false;
               }
            }
            if (hasOnlyPrimitiveArgs) {
               operation.setDispatcher(DispatchStyles.QUERY_ARGS);
               operation.setDispatcherRules(extractOperationParams(fieldDef.getInputValueDefinitions()));
            }
         }
         // Deal with output names if any.
         if (fieldDef.getType() != null) {
            operation.setOutputName(getTypeName(fieldDef.getType()));
         }

         results.add(operation);
      }
      return results;
   }

   /** Build a string representing comma separated inputs (eg. 'arg1, arg2'). */
   private String getInputNames(List<InputValueDefinition> inputsDef) {
      StringBuilder builder = new StringBuilder();

      for (InputValueDefinition inputDef : inputsDef) {
         builder.append(getTypeName(inputDef.getType())).append(", ");
      }
      return builder.substring(0, builder.length() - 2);
   }

   /** Build a string representing operation parameters as used in dispatcher rules (arg1 && arg2). */
   private String extractOperationParams(List<InputValueDefinition> inputsDef) {
      StringBuilder builder = new StringBuilder();

      for (InputValueDefinition inputDef : inputsDef) {
         builder.append(inputDef.getName()).append(" && ");
      }
      return builder.substring(0, builder.length() - 4);
   }

   /** Get the short string representation of a type. eg. 'Film' or '[Films]'. */
   private String getTypeName(Type type) {
      if (type instanceof ListType listType) {
         return "[" + getTypeName(listType.getType()) + "]";
      } else if (type instanceof TypeName typeName) {
         return typeName.getName();
      }
      return type.toString();
   }
}

public class ProtobufImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(ProtobufImporter.class);

   private static final String BINARY_DESCRIPTOR_EXT = ".pbb";
   private static final String BUILTIN_LIBRARY_PREFIX = "google/protobuf";

   private final String protoDirectory;
   private final String protoFileName;
   private final ReferenceResolver referenceResolver;
   private String specContent;
   private DescriptorProtos.FileDescriptorSet fds;


   /**
    * Build a new importer.
    * @param protoFilePath     The path to local proto spec file
    * @param referenceResolver An optional resolver for references present into the Protobuf file
    * @throws IOException if project file cannot be found or read.
    */
   public ProtobufImporter(String protoFilePath, ReferenceResolver referenceResolver) throws IOException {
      this.referenceResolver = referenceResolver;
      // Prepare file, path and name for easier process.
      File protoFile = new File(protoFilePath);
      protoDirectory = protoFile.getParentFile().getAbsolutePath();
      protoFileName = protoFile.getName();

      // Prepare protoc arguments.
      String[] args = { "-v3.21.8", "--include_std_types", "--include_imports", "--proto_path=" + protoDirectory,
            "--descriptor_set_out=" + protoDirectory + "/" + protoFileName + BINARY_DESCRIPTOR_EXT, protoFileName };

      // Track resolved imports (must be cleanup after success of failure).
      List<File> resolvedImportsLocalFiles = null;
      try {
         // Read spec bytes.
         byte[] bytes = Files.readAllBytes(Paths.get(protoFilePath));
         specContent = new String(bytes, StandardCharsets.UTF_8);

         // Resolve and retrieve imports if any.
         if (referenceResolver != null) {
            resolvedImportsLocalFiles = new ArrayList<>();
            resolveAndPrepareRemoteImports(Paths.get(protoFilePath), resolvedImportsLocalFiles);
         }

         // Run Protoc.
         int result = Protoc.runProtoc(args);

         File protoFileB = new File(protoDirectory, protoFileName + BINARY_DESCRIPTOR_EXT);
         fds = DescriptorProtos.FileDescriptorSet.parseFrom(new FileInputStream(protoFileB));
      } catch (InterruptedException ie) {
         log.error("Protobuf schema compilation has been interrupted on {}", protoFilePath);
         Thread.currentThread().interrupt();
      } catch (Exception e) {
         throw new IOException("Protobuf schema file parsing error on " + protoFilePath + ": " + e.getMessage());
      } finally {
         // Cleanup locally downloaded dependencies needed by protoc.
         if (resolvedImportsLocalFiles != null) {
            resolvedImportsLocalFiles.forEach(File::delete);
         }
      }
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> results = new ArrayList<>();

      // Prepare dependencies.
      List<Descriptors.FileDescriptor> dependencies = new ArrayList<>();
      for (DescriptorProtos.FileDescriptorProto fdp : fds.getFileList()) {
         // Retrieve version from package name.
         // org.acme package => org.acme version
         // org.acme.v1 package => v1 version
         String packageName = fdp.getPackage();
         String[] parts = packageName.split("\\.");
         String version = (parts.length > 2 ? parts[parts.length - 1] : packageName);

         Descriptors.FileDescriptor fd = null;
         try {
            fd = Descriptors.FileDescriptor.buildFrom(fdp,
                  dependencies.toArray(new Descriptors.FileDescriptor[dependencies.size()]), true);
            dependencies.add(fd);
         } catch (Descriptors.DescriptorValidationException e) {
            throw new MockRepositoryImportException(
                  "Exception while building Protobuf descriptor, probably a missing dependency issue: "
                        + e.getMessage());
         }

         for (Descriptors.ServiceDescriptor sd : fd.getServices()) {
            // Build a new service.
            Service service = new Service();
            service.setName(sd.getFullName());
            service.setVersion(version);
            service.setType(ServiceType.GRPC);
            service.setXmlNS(fd.getPackage());

            // Then build its operations.
            service.setOperations(extractOperations(sd));

            results.add(service);
         }
      }
      return results;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) throws MockRepositoryImportException {
      List<Resource> results = new ArrayList<>();

      // Build 2 resources: one with plain text, another with base64 encoded binary descriptor.
      Resource textResource = new Resource();
      textResource.setName(service.getName() + "-" + service.getVersion() + ".proto");
      textResource.setType(ResourceType.PROTOBUF_SCHEMA);
      textResource.setContent(specContent);
      results.add(textResource);

      try {
         byte[] binaryPB = Files.readAllBytes(Path.of(protoDirectory, protoFileName + BINARY_DESCRIPTOR_EXT));
         String base64PB = new String(Base64.getEncoder().encode(binaryPB), StandardCharsets.UTF_8);

         Resource descResource = new Resource();
         descResource.setName(service.getName() + "-" + service.getVersion() + BINARY_DESCRIPTOR_EXT);
         descResource.setType(ResourceType.PROTOBUF_DESCRIPTOR);
         descResource.setContent(base64PB);
         results.add(descResource);
      } catch (Exception e) {
         log.error("Exception while encoding Protobuf binary descriptor into base64", e);
         throw new MockRepositoryImportException("Exception while encoding Protobuf binary descriptor into base64");
      }

      // Now build resources for dependencies if any.
      if (referenceResolver != null) {
         referenceResolver.getRelativeResolvedReferences().forEach((p, f) -> {
            Resource protoResource = new Resource();
            protoResource.setName(service.getName() + "-" + service.getVersion() + "-" + p.replace("/", "~1"));
            protoResource.setType(ResourceType.PROTOBUF_SCHEMA);
            protoResource.setPath(p);
            try {
               protoResource.setContent(Files.readString(f.toPath(), StandardCharsets.UTF_8));
            } catch (IOException ioe) {
               log.warn("Exception while setting content of {} Protobuf resource", protoResource.getName(), ioe);
               log.warn("Pursuing on next resource as it was for information purpose only");
            }
            results.add(protoResource);
         });
         referenceResolver.cleanResolvedReferences();
      }
      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      return new ArrayList<>();
   }

   /**
    * Analyse a protofile imports, resolve and retrieve them from remote to allow protoc to run later.
    */
   private void resolveAndPrepareRemoteImports(Path protoFilePath, List<File> resolvedImportsLocalFiles) {
      String line = null;
      try (BufferedReader reader = Files.newBufferedReader(protoFilePath, StandardCharsets.UTF_8)) {
         while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.startsWith("import ")) {
               String importStr = line.substring("import ".length() + 1);
               // Remove semicolon and quotes/double-quotes.
               if (importStr.endsWith(";")) {
                  importStr = importStr.substring(0, importStr.length() - 1);
               }
               if (importStr.endsWith("\"") || importStr.endsWith("'")) {
                  importStr = importStr.substring(0, importStr.length() - 1);
               }
               if (importStr.startsWith("\"") || importStr.startsWith("'")) {
                  importStr = importStr.substring(1);
               }
               log.debug("Found an import to resolve in protobuf: {}", importStr);

               // Check that this lib is not in built-in ones.
               if (!importStr.startsWith(BUILTIN_LIBRARY_PREFIX)) {
                  // Check if import path is locally there.
                  Path importPath = protoFilePath.getParent().resolve(importStr);
                  if (!Files.exists(importPath)) {
                     // Not there, so resolve it remotely and write to local file for protoc.
                     String importContent = referenceResolver.getReferenceContent(importStr, StandardCharsets.UTF_8);
                     try {
                        Files.createDirectories(importPath.getParent());
                        Files.createFile(importPath);
                     } catch (FileAlreadyExistsException faee) {
                        log.warn("Exception while writing protobuf dependency", faee);
                     }
                     Files.write(importPath, importContent.getBytes(StandardCharsets.UTF_8));
                     resolvedImportsLocalFiles.add(importPath.toFile());

                     // Now go down the resource content and resolve its own imports.
                     resolveAndPrepareRemoteImports(importPath, resolvedImportsLocalFiles);
                  }
               }
            }
         }
      } catch (Exception e) {
         log.error("Exception while retrieving protobuf dependency", e);
      }
   }

   /**
    * Extract the operations from GRPC service methods.
    */
   private List<Operation> extractOperations(Descriptors.ServiceDescriptor service) {
      List<Operation> results = new ArrayList<>();

      for (Descriptors.MethodDescriptor method : service.getMethods()) {
         Operation operation = new Operation();
         operation.setName(method.getName());
         if (method.getInputType() != null) {
            operation.setInputName("." + method.getInputType().getFullName());

            boolean hasOnlyPrimitiveArgs = hasOnlyPrimitiveArgs(method);
            if (hasOnlyPrimitiveArgs && !method.getInputType().getFields().isEmpty()) {
               operation.setDispatcher(DispatchStyles.QUERY_ARGS);
               operation.setDispatcherRules(extractOperationParams(method.getInputType().getFields()));
            }
         }
         if (method.getOutputType() != null) {
            operation.setOutputName("." + method.getOutputType().getFullName());
         }

         results.add(operation);
      }
      return results;
   }

   /** Check if a method has only primitive arguments. */
   private static boolean hasOnlyPrimitiveArgs(Descriptors.MethodDescriptor method) {
      for (Descriptors.FieldDescriptor field : method.getInputType().getFields()) {
         Descriptors.FieldDescriptor.Type fieldType = field.getType();
         if (!isScalarType(fieldType)) {
            return false;
         }
      }
      return true;
   }

   /** Defines is a protobuf message field type is a scalar type. s */
   private static boolean isScalarType(Descriptors.FieldDescriptor.Type fieldType) {
      return fieldType != Descriptors.FieldDescriptor.Type.MESSAGE
            && fieldType != Descriptors.FieldDescriptor.Type.GROUP
            && fieldType != Descriptors.FieldDescriptor.Type.BYTES;
   }

   /** Build a string representing operation parameters as used in dispatcher rules (arg1 && arg2). */
   private static String extractOperationParams(List<Descriptors.FieldDescriptor> inputFields) {
      StringBuilder builder = new StringBuilder();

      for (Descriptors.FieldDescriptor inputField : inputFields) {
         builder.append(inputField.getName()).append(" && ");
      }
      return builder.substring(0, builder.length() - 4);
   }
}

public class HARImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(HARImporter.class);

   /** The starter marker for the comment referencing microcks service and version identifiers. */
   public static final String MICROCKS_ID_STARTER = "microcksId:";

   /** The started marker for the comment referencing the prefix to identify API and remove from URLs. */
   public static final String API_PREFIX_STARTER = "apiPrefix:";

   protected static final String REQUEST_NODE = "request";
   protected static final String RESPONSE_NODE = "response";

   protected static final String GRAPHQL_VARIABLES_NODE = "variables";
   protected static final String GRAPHQL_QUERY_NODE = "query";

   private ObjectMapper jsonMapper;

   private JsonNode spec;

   private String apiPrefix;

   private Map<Operation, List<JsonNode>> operationToEntriesMap = new HashMap<>();

   private static final List<String> VALID_VERSIONS = List.of("1.1", "1.2");

   private static final List<String> INVALID_ENTRY_EXTENSIONS = List.of(".ico", ".html", ".css", ".js", ".png", ".jpg",
         ".ttf", ".woff2");

   private static final List<String> UNWANTED_HEADERS = List.of("host", "sec-fetch-dest", "sec-fetch-mode",
         "sec-fetch-user", "sec-fetch-site", "sec-gpc", "sec-ch-ua", "sec-ch-ua-mobile", "sec-ch-ua-platform",
         "upgrade-insecure-requests", "user-agent", "date", "vary");


   /**
    * Build a new importer.
    * @param specificationFilePath The path to local HAR archive file
    * @throws IOException if project file cannot be found or read.
    */
   public HARImporter(String specificationFilePath) throws IOException {
      File specificationFile = new File(specificationFilePath);
      jsonMapper = new ObjectMapper();
      spec = jsonMapper.readTree(specificationFile);
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> results = new ArrayList<>();

      // Start checking version and comment.
      String version = spec.path("log").path("version").asText();
      if (!VALID_VERSIONS.contains(version)) {
         throw new MockRepositoryImportException(
               "HAR version is not supported. Currently supporting: " + VALID_VERSIONS);
      }
      String comment = spec.path("log").path("comment").asText();
      if (comment == null || comment.length() == 0) {
         throw new MockRepositoryImportException(
               "Expecting a comment in HAR log to specify Microcks service identifier");
      }

      // We can start building something.
      Service service = new Service();
      service.setType(ServiceType.REST);

      // 1st thing: look for comments to get service and version identifiers.
      String[] commentLines = comment.split("\\r?\\n|\\r");
      for (String commentLine : commentLines) {
         if (commentLine.trim().startsWith(MICROCKS_ID_STARTER)) {
            String identifiers = commentLine.trim().substring(MICROCKS_ID_STARTER.length());

            if (identifiers.indexOf(":") != -1) {
               String[] serviceAndVersion = identifiers.split(":");
               service.setName(serviceAndVersion[0].trim());
               service.setVersion(serviceAndVersion[1].trim());
            } else {
               log.error("microcksId comment is malformed. Expecting \'microcksId: <API_name>:<API_version>\'");
               throw new MockRepositoryImportException(
                     "microcksId comment is malformed. Expecting \'microcksId: <API_name>:<API_version>\'");
            }
         } else if (commentLine.trim().startsWith(API_PREFIX_STARTER)) {
            apiPrefix = commentLine.trim().substring(API_PREFIX_STARTER.length()).trim();
            log.info("Found an API prefix to use for shortening URLs: {}", apiPrefix);
         }
      }
      if (service.getName() == null || service.getVersion() == null) {
         log.error("No microcksId: comment found into GraphQL schema to get API name and version");
         throw new MockRepositoryImportException(
               "No microcksId: comment found into GraphQL schema to get API name and version");
      }

      // Inspect requests content to determine the most probable service type.
      Map<ServiceType, Integer> requestsCounters = countRequestsByServiceType(
            spec.path("log").path("entries").elements());
      if ((requestsCounters.get(ServiceType.GRAPHQL) > requestsCounters.get(ServiceType.REST))
            && (requestsCounters.get(ServiceType.GRAPHQL) > requestsCounters.get(ServiceType.SOAP_HTTP))) {
         service.setType(ServiceType.GRAPHQL);
      } else if ((requestsCounters.get(ServiceType.SOAP_HTTP) > requestsCounters.get(ServiceType.REST))
            && (requestsCounters.get(ServiceType.SOAP_HTTP) > requestsCounters.get(ServiceType.GRAPHQL))) {
         service.setType(ServiceType.SOAP_HTTP);
      }

      // Extract service operations.
      service.setOperations(extractOperations(service.getType(), spec.path("log").path("entries").elements()));

      results.add(service);
      return results;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) throws MockRepositoryImportException {
      return new ArrayList<>();
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      Map<Request, Response> result = new HashMap<>();

      Optional<Operation> opOperation = operationToEntriesMap.keySet().stream()
            .filter(op -> op.getName().equals(operation.getName()))
            .filter(op -> op.getMethod().equals(operation.getMethod())).findFirst();

      if (opOperation.isPresent()) {
         // If we previously override the dispatcher with a Fallback, we must be sure to get wrapped elements.
         DispatchCriteriaHelper.DispatcherDetails details = DispatchCriteriaHelper
               .extractDispatcherWithRules(operation);
         String rootDispatcher = details.rootDispatcher();
         String rootDispatcherRules = details.rootDispatcherRules();

         List<JsonNode> operationEntries = operationToEntriesMap.get(opOperation.get());
         for (JsonNode entry : operationEntries) {
            JsonNode requestNode = entry.path(REQUEST_NODE);
            JsonNode responseNode = entry.path(RESPONSE_NODE);
            String requestUrl = shortenURL(requestNode.path("url").asText());
            log.debug("Extracting message definitions for entry url {}", requestUrl);

            // startedDateTIme is the only "unique" identifier for an entry...
            String name = entry.path("startedDateTime").asText();
            Request request = buildRequest(requestNode, name);

            // Build dispatchCriteria before building response.
            String dispatchCriteria = null;

            if (DispatchStyles.URI_PARAMS.equals(rootDispatcher)) {
               dispatchCriteria = DispatchCriteriaHelper.extractFromURIParams(rootDispatcherRules, requestUrl);
            } else if (DispatchStyles.URI_PARTS.equals(rootDispatcher)) {
               // We may have null dispatcher rules here if just one request
               // (as it prevents detecting patterns in URL and deducing parts)
               if (rootDispatcherRules != null) {
                  dispatchCriteria = DispatchCriteriaHelper.extractFromURIPattern(rootDispatcherRules,
                        removeVerbFromURL(operation.getName()), requestUrl);
               }
            } else if (DispatchStyles.URI_ELEMENTS.equals(rootDispatcher)) {
               // We may have null dispatcher rules here if just one request
               // (as it prevents detecting patterns in URL and deducing parts)
               if (rootDispatcherRules != null) {
                  dispatchCriteria = DispatchCriteriaHelper.extractFromURIPattern(rootDispatcherRules,
                        removeVerbFromURL(operation.getName()), requestUrl);
               }
               dispatchCriteria += DispatchCriteriaHelper.extractFromURIParams(rootDispatcherRules, requestUrl);
            } else if (DispatchStyles.QUERY_ARGS.equals(rootDispatcher)) {
               // This dispatcher is used for GraphQL, we have to extract variables from request body.
               dispatchCriteria = extractGraphQLCriteria(rootDispatcherRules, request.getContent());
            } else {
               // If dispatcher has been overriden (to SCRIPT for example), we should still put a generic resourcePath
               // (maybe containing : parts) to later force operation matching at the mock controller level. Only do that
               // when request url is not empty (means not the root url like POST /order).
               if (requestUrl != null && requestUrl.length() > 0) {
                  operation.addResourcePath(requestUrl);
                  log.debug("Added operation generic resource path: {}", operation.getResourcePaths());
               }
            }

            if (service.getType() == ServiceType.GRAPHQL) {
               // We also have to shorten GraphQL body as we typically just display the query in Microcks.
               //adaptGraphQLRequestContent(request);
            }

            // Finalize with response and store.
            Response response = buildResponse(responseNode, name, dispatchCriteria);
            result.put(request, response);
         }
      }

      // Adapt map to list of Exchanges.
      return result.entrySet().stream().map(entry -> new RequestResponsePair(entry.getKey(), entry.getValue()))
            .collect(Collectors.toList());
   }


   /** Try to guess and count the number of requests of each type (REST, GRAPHQL, SOAP). */
   private Map<ServiceType, Integer> countRequestsByServiceType(Iterator<JsonNode> entries) {
      Map<ServiceType, Integer> requestsCounters = new EnumMap<>(ServiceType.class);
      requestsCounters.put(ServiceType.REST, 0);
      requestsCounters.put(ServiceType.GRAPHQL, 0);
      requestsCounters.put(ServiceType.SOAP_HTTP, 0);

      List<JsonNode> candidateEntries = filterValidEntries(entries);
      for (JsonNode entry : candidateEntries) {

         JsonNode responseContent = entry.path(RESPONSE_NODE).path("content");
         if (responseContent != null) {
            String mimeType = responseContent.path("mimeType").asText();
            String responseText = getContentText(responseContent);

            ServiceType responseType = ServiceType.REST;
            if ("application/json".equals(mimeType)) {
               // Try to guess between REST and GRAPHQL...
               String requestText = entry.path(REQUEST_NODE).path("postData").path("text").asText();

               if (responseText.contains("\"data\":") && (requestText.contains(GRAPHQL_QUERY_NODE)
                     || requestText.contains("mutation") || requestText.contains("fragment"))) {
                  responseType = ServiceType.GRAPHQL;
               }
            } else if ("text/xml".equals(mimeType)) {
               // Try to guess between REST and SOAP...
               if (responseText.contains(":Envelope") && responseText.contains(":Body/>")) {
                  responseType = ServiceType.SOAP_HTTP;
               }
            }
            requestsCounters.put(responseType, requestsCounters.get(responseType) + 1);
         }
      }
      return requestsCounters;
   }

   /** Extract Service Operations from entries. */
   private List<Operation> extractOperations(ServiceType serviceType, Iterator<JsonNode> entries) {
      Map<String, Operation> discoveredOperations = new HashMap<>();

      List<JsonNode> candidateEntries = filterValidEntries(entries);

      for (JsonNode entry : candidateEntries) {
         String requestMethod = entry.path(REQUEST_NODE).path("method").asText();
         String requestUrl = entry.path(REQUEST_NODE).path("url").asText();
         String requestText = entry.path(REQUEST_NODE).path("postData").path("text").asText();

         String baseRequestUrl = shortenURL(requestUrl);
         String dispatcher = DispatchStyles.URI_PARTS;
         if (baseRequestUrl.contains("?")) {
            baseRequestUrl = baseRequestUrl.substring(0, baseRequestUrl.indexOf("?"));
            dispatcher = DispatchStyles.URI_PARAMS;
         }

         // This is OK for REST only. Has to be changed for SOAP and GRAPHQL.
         String operationName = requestMethod + " " + baseRequestUrl;
         if (serviceType == ServiceType.GRAPHQL) {
            Parser requestParser = new Parser();
            try {
               Document graphqlRequest = requestParser.parseDocument(extractGraphQLQuery(requestText));
               OperationDefinition graphqlOperation = (OperationDefinition) graphqlRequest.getDefinitions().get(0);
               requestMethod = graphqlOperation.getOperation().toString();
               operationName = ((Field) graphqlOperation.getSelectionSet().getSelections().get(0)).getName();
               if ("QUERY".equals(requestMethod)) {
                  dispatcher = DispatchStyles.QUERY_ARGS;
               }
            } catch (Exception e) {
               log.warn("Error parsing GraphQL request: {}", e.getMessage());
            }
         }

         Operation existingOperation = discoveredOperations.get(operationName);
         if (existingOperation == null) {
            // Do we have other operation on different paths?
            String[] newCandidatePaths = operationName.split("/");
            final String searchedMethod = requestMethod;
            List<Operation> similarOperations = discoveredOperations.values().stream()
                  .filter(op -> searchedMethod.equals(op.getMethod()))
                  .filter(op -> newCandidatePaths.length == op.getName().split("/").length).toList();

            Operation mostSimilarOperation = findMostSimilarOperation(operationName, similarOperations);
            if (mostSimilarOperation != null) {
               List<String> uris = List.of(removeVerbFromURL(mostSimilarOperation.getName()),
                     removeVerbFromURL(operationName));

               String urlPart = DispatchCriteriaHelper.buildTemplateURLWithPartsFromURIs(uris);
               mostSimilarOperation.setName(requestMethod + " " + urlPart);

               if (DispatchStyles.URI_PARAMS.equals(mostSimilarOperation.getDispatcher())) {
                  mostSimilarOperation.setDispatcher(DispatchStyles.URI_ELEMENTS);
               } else {
                  mostSimilarOperation.setDispatcher(DispatchStyles.URI_PARTS);
                  mostSimilarOperation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIs(uris));
                  mostSimilarOperation.addResourcePath(uris.get(0));
                  mostSimilarOperation.addResourcePath(uris.get(1));
               }
               // Add current entry to similar operation.
               operationToEntriesMap.get(mostSimilarOperation).add(entry);
            } else {
               // If finally we get here, it's time to build a new operation ;-)
               Operation operation = new Operation();
               operation.setName(operationName);
               operation.setMethod(requestMethod);
               operation.setDispatcher(dispatcher);

               if (DispatchStyles.URI_PARAMS.equals(dispatcher)) {
                  operation.setDispatcherRules(DispatchCriteriaHelper.extractParamsFromURI(requestUrl));
               } else if (DispatchStyles.URI_PARTS.equals(dispatcher)) {
                  operation.addResourcePath(baseRequestUrl);
               }

               // Store this operation and initialize its entries.
               discoveredOperations.put(operationName, operation);
               List<JsonNode> operationEntries = new ArrayList<>();
               operationEntries.add(entry);
               operationToEntriesMap.put(operation, operationEntries);
            }
         } else {
            // Add current entry to existing operation.
            operationToEntriesMap.get(existingOperation).add(entry);
         }
      }

      return discoveredOperations.values().stream().toList();
   }

   /** Filter valid entries in HAR, removing static resources and calls not having the correct prefix if specified. */
   private List<JsonNode> filterValidEntries(Iterator<JsonNode> entries) {
      return Stream.generate(() -> null).takeWhile(x -> entries.hasNext()).map(next -> entries.next()).filter(entry -> {
         String url = entry.path(REQUEST_NODE).path("url").asText();
         String extension = url.substring(url.lastIndexOf("."));
         return !INVALID_ENTRY_EXTENSIONS.contains(extension);
      }).filter(entry -> {
         if (apiPrefix != null) {
            // Filter by api prefix if provided.
            String url = entry.path(REQUEST_NODE).path("url").asText();
            return url.startsWith(apiPrefix) || removeProtocolAndHostPort(url).startsWith(apiPrefix);
         }
         return true;
      }).toList();
   }

   /** Find the most similar operation among candidates. */
   private Operation findMostSimilarOperation(String operationName, List<Operation> similarOperations) {
      Operation mostSimilarOperation = null;
      if (!similarOperations.isEmpty()) {
         int maxScore = 0;
         for (Operation similarOperation : similarOperations) {
            int score = getSimilarityScore(similarOperation.getName(), operationName);
            if (score > 70 && score > maxScore) {
               maxScore = score;
               mostSimilarOperation = similarOperation;
            }
         }
      }
      return mostSimilarOperation;
   }

   /** Compute a similarity score between a base URL and a candidate one. The greater, the better. */
   private int getSimilarityScore(String base, String candidate) {
      int similarityScore = 0;
      int commonPrefixSize = 0;
      String[] basePaths = base.split("/");
      String[] candidatePaths = candidate.split("/");
      int stepScore = 100 / basePaths.length;
      boolean stillCommon = true;

      for (int i = 0; i < basePaths.length; i++) {
         String basePath = basePaths[i];
         String candidatePath = candidatePaths[i];
         if (basePath.equals(candidatePath)) {
            if (stillCommon) {
               commonPrefixSize++;
            }
            similarityScore += stepScore;
         } else {
            stillCommon = false;
         }
      }
      return similarityScore + (basePaths.length * commonPrefixSize);
   }

   /** Build Microcks request from HAR request. */
   private Request buildRequest(JsonNode requestNode, String name) {
      Request request = new Request();
      request.setName(name);
      request.setHeaders(buildHeaders(requestNode.path("headers")));
      request.setContent(requestNode.path("postData").path("text").asText());

      JsonNode queryStringNode = requestNode.path("queryString");
      if (!queryStringNode.isMissingNode() && queryStringNode.isArray()) {
         Iterator<JsonNode> queryStrings = queryStringNode.elements();
         while (queryStrings.hasNext()) {
            JsonNode queryString = queryStrings.next();
            Parameter param = new Parameter();
            param.setName(queryString.path("name").asText());
            param.setValue(queryString.path("value").asText());
            request.addQueryParameter(param);
         }
      }
      return request;
   }

   /** Build Microcks response from HAR response. */
   private Response buildResponse(JsonNode responseNode, String name, String dispatchCriteria) {
      Response response = new Response();
      response.setName(name);
      response.setStatus(responseNode.path("status").asText("200"));
      response.setHeaders(buildHeaders(responseNode.path("headers")));
      response.setContent(getContentText(responseNode.path("content")));
      response.setDispatchCriteria(dispatchCriteria);

      if (response.getHeaders() != null) {
         for (Header header : response.getHeaders()) {
            if (header.getName().equalsIgnoreCase("Content-Type")) {
               response.setMediaType(header.getValues().toArray(new String[] {})[0]);
            }
         }
      }

      return response;
   }

   /** Build Microcks headers from HAR headers. */
   private Set<Header> buildHeaders(JsonNode headerNode) {
      Map<String, Header> headers = new HashMap<>();
      Iterator<JsonNode> items = headerNode.elements();
      while (items.hasNext()) {
         JsonNode item = items.next();
         // Filter unwanted headers that are typically sent by browsers and
         // meaningless in the context of API/Service exchanges.
         String name = item.path("name").asText();
         if (!UNWANTED_HEADERS.contains(name.toLowerCase())) {
            Header header = headers.computeIfAbsent(name, k -> {
               Header h = new Header();
               h.setName(k);
               h.setValues(new HashSet<>());
               return h;
            });
            header.getValues().add(item.path("value").asText());
         }
      }
      return headers.values().stream().collect(Collectors.toSet());
   }

   /** Extract response content as string from HAR response content. */
   private String getContentText(JsonNode contentNode) {
      String text = contentNode.path("text").asText();
      if ("base64".equals(contentNode.path("encoding").asText())) {
         text = new String(Base64.getDecoder().decode(text));
      }
      return text;
   }

   /** Shorten an entry URL, removing protocol and host and API prefix if provided. */
   private String shortenURL(String url) {
      if (apiPrefix != null) {
         if (apiPrefix.startsWith("http://") || apiPrefix.startsWith("https://")) {
            // Prefix includes protocol and port, using it as is.
            return url.substring(apiPrefix.length() + 1);
         } else {
            // Start removing protocol and host and then the prefix.
            url = removeProtocolAndHostPort(url);
            return removeApiPrefix(url, apiPrefix);
         }
      }
      return removeProtocolAndHostPort(url);
   }

   private String extractGraphQLQuery(String requestContent) {
      try {
         JsonNode requestNode = jsonMapper.readTree(requestContent);
         return requestNode.path(GRAPHQL_QUERY_NODE).asText();
      } catch (Exception e) {
         log.error("Exception while extracting dispatch criteria from GraphQL variables: {}", e.getMessage(), e);
      }
      return "";
   }

   private String extractGraphQLCriteria(String dispatcherRules, String requestContent) {
      String dispatchCriteria = "";
      try {
         JsonNode requestNode = jsonMapper.readTree(requestContent);
         if (requestNode.has(GRAPHQL_VARIABLES_NODE)) {
            JsonNode variablesNode = requestNode.path(GRAPHQL_VARIABLES_NODE);
            Map<String, String> paramsMap = jsonMapper.convertValue(variablesNode,
                  TypeFactory.defaultInstance().constructMapType(TreeMap.class, String.class, String.class));
            dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(dispatcherRules, paramsMap);
         }
      } catch (Exception e) {
         log.error("Exception while extracting dispatch criteria from GraphQL variables: {}", e.getMessage(), e);
      }
      return dispatchCriteria;
   }

   private static String removeApiPrefix(String url, String apiPrefix) {
      if (url.startsWith(apiPrefix)) {
         return url.substring(apiPrefix.length());
      }
      return url;
   }

   private static String removeVerbFromURL(String operationName) {
      return operationName.substring(operationName.indexOf(" ") + 1);
   }

   private static String removeProtocolAndHostPort(String url) {
      if (url.startsWith("https://")) {
         url = url.substring(8);
      }
      if (url.startsWith("http://")) {
         url = url.substring(7);
      }
      // Remove host and port specification if any.
      if (url.indexOf('/') != -1) {
         url = url.substring(url.indexOf('/'));
      }
      return url;
   }
}

public class ExamplesImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(ExamplesImporter.class);

   private static final String REQUEST_NODE = "request";
   private static final String RESPONSE_NODE = "response";
   private static final String PARAMETERS_NODE = "parameters";
   private static final String HEADERS_NODE = "headers";
   private static final String BODY_NODE = "body";
   private static final String PAYLOAD_NODE = "payload";

   private final ObjectMapper mapper;
   private final JsonNode spec;

   /**
    * Build a new importer.
    * @param specificationFilePath The path to local APIExamples spec file
    * @throws IOException if project file cannot be found or read.
    */
   public ExamplesImporter(String specificationFilePath) throws IOException {
      try {
         // Read spec bytes.
         byte[] bytes = Files.readAllBytes(Paths.get(specificationFilePath));
         String specContent = new String(bytes, StandardCharsets.UTF_8);

         // Convert them to Node using Jackson object mapper.
         mapper = new ObjectMapper(new YAMLFactory());
         spec = mapper.readTree(specContent.getBytes(StandardCharsets.UTF_8));
      } catch (Exception e) {
         log.error("Exception while parsing APIMetadata specification file " + specificationFilePath, e);
         throw new IOException("APIMetadata spec file parsing error");
      }
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      // Build a new service.
      Service service = new Service();

      JsonNode metadataNode = spec.get("metadata");
      if (metadataNode == null) {
         log.error("Missing mandatory metadata in {}", spec.asText());
         throw new MockRepositoryImportException("Mandatory metadata property is missing in APIMetadata");
      }
      service.setName(metadataNode.path("name").asText());
      service.setVersion(metadataNode.path("version").asText());

      // Then build its operations.
      service.setOperations(extractOperations());

      result.add(service);

      return result;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) throws MockRepositoryImportException {
      return Collections.emptyList();
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      List<Exchange> result = new ArrayList<>();

      // Iterate on specification "operations" nodes.
      Iterator<Map.Entry<String, JsonNode>> operations = spec.path("operations").fields();
      while (operations.hasNext()) {
         Map.Entry<String, JsonNode> operationEntry = operations.next();

         // Select the matching operation.
         if (operation.getName().equals(operationEntry.getKey())) {
            // Browse examples and extract exchanges.
            Iterator<Map.Entry<String, JsonNode>> examples = operationEntry.getValue().fields();
            while (examples.hasNext()) {
               Map.Entry<String, JsonNode> exampleEntry = examples.next();

               // Extract and add this exchange.
               result.add(extractExchange(service, operation, exampleEntry.getKey(), exampleEntry.getValue()));
            }
         }
      }
      return result;
   }

   /** Extract the list of operations from Specification. */
   private List<Operation> extractOperations() {
      List<Operation> results = new ArrayList<>();

      // Iterate on specification "operations" nodes.
      Iterator<Map.Entry<String, JsonNode>> operations = spec.path("operations").fields();
      while (operations.hasNext()) {
         Map.Entry<String, JsonNode> operation = operations.next();

         // Build a new operation.
         Operation op = new Operation();
         op.setName(operation.getKey());

         results.add(op);
      }
      return results;
   }

   /** Extract exchange information from an example node. */
   private Exchange extractExchange(Service service, Operation operation, String exampleName, JsonNode exampleNode) {
      Exchange exchange;
      if (ServiceType.EVENT.equals(service.getType())) {
         exchange = extractUnidirectionalEvent(exampleName, exampleNode);
      } else {
         exchange = extractRequestResponsePair(service, operation, exampleName, exampleNode);
      }
      return exchange;
   }

   /** Extract unidirectional event messages from an example node. */
   private UnidirectionalEvent extractUnidirectionalEvent(String exampleName, JsonNode exampleNode) {
      if (exampleNode.has("eventMessage")) {
         JsonNode eventNode = exampleNode.get("eventMessage");

         EventMessage event = new EventMessage();
         event.setName(exampleName);

         if (eventNode.has(HEADERS_NODE)) {
            completeWithHeaders(event, eventNode.get(HEADERS_NODE));
         }
         event.setContent(getSerializedValue(eventNode.get(PAYLOAD_NODE)));

         return new UnidirectionalEvent(event);
      }
      return null;
   }

   /** Extract request/response pair from an example node. */
   private RequestResponsePair extractRequestResponsePair(Service service, Operation operation, String exampleName,
         JsonNode exampleNode) {
      // Build and return something only if request and response.
      if (exampleNode.has(REQUEST_NODE) && exampleNode.has(RESPONSE_NODE)) {
         JsonNode requestNode = exampleNode.get(REQUEST_NODE);
         JsonNode responseNode = exampleNode.get(RESPONSE_NODE);

         // Initialize and complete the request.
         Request request = new Request();
         request.setName(exampleName);
         request.setContent(getSerializedValue(requestNode.get(BODY_NODE)));

         Multimap<String, String> parameters = null;
         if (requestNode.has(PARAMETERS_NODE)) {
            parameters = completeWithParameters(request, requestNode.get(PARAMETERS_NODE));
         }
         if (requestNode.has(HEADERS_NODE)) {
            completeWithHeaders(request, requestNode.get(HEADERS_NODE));
         }

         // Initialize and complete the response.
         Response response = new Response();
         response.setName(exampleName);
         // Default response status
         response.setStatus("200");

         if (responseNode.has(HEADERS_NODE)) {
            completeWithHeaders(response, responseNode.get(HEADERS_NODE));
         }
         if (responseNode.has("mediaType")) {
            String mediaType = responseNode.get("mediaType").asText();
            response.setMediaType(mediaType);
         }
         if (responseNode.has("status")) {
            String status = responseNode.get("status").asText();
            response.setStatus(status);
            if (!status.startsWith("2") || !status.startsWith("3")) {
               response.setFault(true);
            }
         }
         response.setContent(getSerializedValue(responseNode.get(BODY_NODE)));

         // Finally, take care about dispatchCriteria and complete operation resourcePaths.
         // If we previously override the dispatcher with a Fallback, we must be sure to get wrapped elements.
         DispatchCriteriaHelper.DispatcherDetails details = DispatchCriteriaHelper
               .extractDispatcherWithRules(operation);

         // Finally, take care about dispatchCriteria and complete operation resourcePaths.
         completeDispatchCriteriaAndResourcePaths(service, operation, details.rootDispatcher(),
               details.rootDispatcherRules(), parameters, requestNode, responseNode, request, response);

         return new RequestResponsePair(request, response);
      }
      return null;
   }

   /** Complete a request by extracting parameters. */
   private Multimap<String, String> completeWithParameters(Request request, JsonNode parametersNode) {
      Multimap<String, String> result = ArrayListMultimap.create();
      Iterator<Map.Entry<String, JsonNode>> parameters = parametersNode.fields();
      while (parameters.hasNext()) {
         Map.Entry<String, JsonNode> parameterNode = parameters.next();

         Parameter parameter = new Parameter();
         parameter.setName(parameterNode.getKey());
         parameter.setValue(getSerializedValue(parameterNode.getValue()));
         request.addQueryParameter(parameter);

         // Depending on node type, extract different representations to MultiMap result.
         if (parameterNode.getValue().isArray()) {
            for (JsonNode current : parameterNode.getValue()) {
               result.put(parameterNode.getKey(), getSerializedValue(current));
            }
         } else if (parameterNode.getValue().isObject()) {
            final var fieldsIterator = parameterNode.getValue().fields();
            while (fieldsIterator.hasNext()) {
               var current = fieldsIterator.next();
               result.put(current.getKey(), getSerializedValue(current.getValue()));
            }
         } else {
            result.put(parameterNode.getKey(), getSerializedValue(parameterNode.getValue()));
         }
      }
      return result;
   }

   /** Complete a message by extracting headers. */
   private void completeWithHeaders(Message message, JsonNode headersNode) {
      Iterator<Map.Entry<String, JsonNode>> headers = headersNode.fields();
      while (headers.hasNext()) {
         Map.Entry<String, JsonNode> headerNode = headers.next();

         Header header = new Header();
         header.setName(headerNode.getKey());
         // Header value may be multiple CSV.
         Set<String> values = Arrays.stream(getSerializedValue(headerNode.getValue()).split(",")).map(String::trim)
               .collect(Collectors.toSet());
         header.setValues(values);

         message.addHeader(header);
      }
   }

   /** */
   private void completeDispatchCriteriaAndResourcePaths(Service service, Operation operation, String rootDispatcher,
         String rootDispatcherRules, Multimap<String, String> parameters, JsonNode requestNode, JsonNode responseNode,
         Request request, Response response) {
      String dispatchCriteria = null;
      String resourcePathPattern = operation.getName().contains(" ") ? operation.getName().split(" ")[1]
            : operation.getName();

      if (DispatchStyles.URI_PARAMS.equals(rootDispatcher)) {
         dispatchCriteria = DispatchCriteriaHelper.buildFromParamsMap(rootDispatcherRules, parameters);
         // We only need the pattern here.
         operation.addResourcePath(resourcePathPattern);
      } else if (DispatchStyles.URI_PARTS.equals(rootDispatcher)) {
         dispatchCriteria = DispatchCriteriaHelper.buildFromPartsMap(rootDispatcherRules, parameters);
         // We should complete resourcePath here.
         String resourcePath = URIBuilder.buildURIFromPattern(resourcePathPattern, parameters);
         operation.addResourcePath(resourcePath);
      } else if (DispatchStyles.URI_ELEMENTS.equals(rootDispatcher)) {
         // Split parameters between path and query.
         Multimap<String, String> pathParameters = Multimaps.filterEntries(parameters,
               entry -> operation.getName().contains("/{" + entry.getKey() + "}")
                     || operation.getName().contains("/:" + entry.getKey()));
         Multimap<String, String> queryParameters = Multimaps.filterEntries(parameters,
               entry -> !pathParameters.containsKey(entry.getKey()));

         dispatchCriteria = DispatchCriteriaHelper.buildFromPartsMap(rootDispatcherRules, pathParameters);
         dispatchCriteria += DispatchCriteriaHelper.buildFromParamsMap(rootDispatcherRules, queryParameters);
         // We should complete resourcePath here.
         String resourcePath = URIBuilder.buildURIFromPattern(resourcePathPattern, parameters);
         operation.addResourcePath(resourcePath);
      } else if (DispatchStyles.QUERY_HEADER.equals(rootDispatcher)) {
         if (requestNode.has(HEADERS_NODE)) {
            JsonNode headersNode = requestNode.get(HEADERS_NODE);
            Map<String, String> headersMap = extractHeaders(headersNode);
            log.debug("Headers map for dispatchCriteria computation: {}", headersMap);
            dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(rootDispatcherRules, headersMap);
         } else {
            log.debug("Missing headers node in request node");
         }
      } else if (DispatchStyles.QUERY_ARGS.equals(rootDispatcher)) {
         if (ServiceType.GRAPHQL.equals(service.getType()) && requestNode.has(BODY_NODE)) {
            JsonNode variables = requestNode.get(BODY_NODE).path("variables");
            dispatchCriteria = extractQueryArgsCriteria(rootDispatcherRules, variables);
         } else if (ServiceType.GRPC.equals(service.getType())) {
            dispatchCriteria = extractQueryArgsCriteria(rootDispatcherRules, request.getContent());
         }
      } else if (responseNode.has("dispatchCriteria")) {
         dispatchCriteria = responseNode.get("dispatchCriteria").asText();
      }

      // In any case (dispatcher forced via Metadata or set to SCRIPT, we should still put a generic resourcePath
      // (maybe containing {} parts) to later force operation matching at the mock controller level.
      operation.addResourcePath(resourcePathPattern);

      response.setDispatchCriteria(dispatchCriteria);
   }

   /** Extract the QUERY_ARGS Dispatch criteria from the variable provided as JSON string representation. */
   private String extractQueryArgsCriteria(String dispatcherRules, JsonNode variables) {
      String dispatchCriteria = "";
      try {
         Map<String, String> paramsMap = mapper.convertValue(variables,
               TypeFactory.defaultInstance().constructMapType(TreeMap.class, String.class, String.class));
         dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(dispatcherRules, paramsMap);
      } catch (Exception e) {
         log.error("Exception while converting dispatch criteria from JSON body: {}", e.getMessage());
      }
      return dispatchCriteria;
   }

   /** Extract the QUERY_ARGS Dispatch criteria from the variable provided as JSON string representation. */
   private String extractQueryArgsCriteria(String dispatcherRules, String variables) {
      String dispatchCriteria = "";
      try {
         Map<String, String> paramsMap = mapper.readValue(variables,
               TypeFactory.defaultInstance().constructMapType(TreeMap.class, String.class, String.class));
         dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(dispatcherRules, paramsMap);
      } catch (Exception e) {
         log.error("Exception while extracting dispatch criteria from JSON body: {}", e.getMessage());
      }
      return dispatchCriteria;
   }

   /** Get the serialized value of a content node, or null if node is null ;-) */
   private String getSerializedValue(JsonNode contentNode) {
      if (contentNode != null) {
         // Get string representation if array or object.
         if (contentNode.getNodeType() == JsonNodeType.ARRAY || contentNode.getNodeType() == JsonNodeType.OBJECT) {
            return contentNode.toString();
         }
         // Else get raw representation.
         return contentNode.asText();
      }
      return null;
   }

   /** Extract headers from a node to be processed for dispatch criteria computing. */
   private Map<String, String> extractHeaders(JsonNode headersNode) {
      Map<String, String> result = new HashMap<>();
      Iterator<Map.Entry<String, JsonNode>> headers = headersNode.fields();
      while (headers.hasNext()) {
         Map.Entry<String, JsonNode> headerNode = headers.next();
         result.put(headerNode.getKey(), getSerializedValue(headerNode.getValue()));
      }
      return result;
   }
}

