public class MetadataExtractor {

   /** Private constructor to hide the implicit public one and prevent instantiation. */
   private MetadataExtractor() {
      // Hidden constructor
   }

   /**
    * Complete a Metadata object with extracted metadata from JsonNode.
    * @param metadata The object to complete
    * @param node     Node representing a metadata node
    */
   public static void completeMetadata(Metadata metadata, JsonNode node) {
      JsonNode annotationsNode = node.get("annotations");
      if (annotationsNode != null) {
         annotationsNode.fields()
               .forEachRemaining(entry -> metadata.setAnnotation(entry.getKey(), entry.getValue().asText()));
      }
      JsonNode labelsNode = node.get("labels");
      if (labelsNode != null) {
         labelsNode.fields().forEachRemaining(entry -> metadata.setLabel(entry.getKey(), entry.getValue().asText()));
      }
   }

   /**
    * Complete an Operation object with extracted properties from JsonNode.
    * @param operation The object to complete
    * @param node      Node representing an operation node
    */
   public static void completeOperationProperties(Operation operation, JsonNode node) {
      if (node.has("delay")) {
         operation.setDefaultDelay(node.path("delay").asLong(0));
      }
      if (node.has("frequency")) {
         operation.setDefaultDelay(node.path("frequency").asLong());
      }
      if (node.has("dispatcher")) {
         operation.setDispatcher(node.path("dispatcher").asText());
      }
      if (node.has("dispatcherRules")) {
         operation.setDispatcherRules(node.path("dispatcherRules").asText());
      }
      if (node.has("parameterConstraints")) {
         node.get("parameterConstraints").elements().forEachRemaining(paramNode -> {
            ParameterConstraint constraint = extractParameterConstraint(paramNode);
            operation.addParameterConstraint(constraint);
         });
      }
   }

   private static ParameterConstraint extractParameterConstraint(JsonNode node) {
      ParameterConstraint constraint = new ParameterConstraint();
      constraint.setName(node.get("name").asText());
      constraint.setIn(ParameterLocation.valueOf(node.get("in").asText()));
      constraint.setRequired(node.path("required").asBoolean(false));
      constraint.setRecopy(node.path("recopy").asBoolean(false));
      if (node.has("mustMatchRegexp")) {
         constraint.setMustMatchRegexp(node.get("mustMatchRegexp").asText());
      }
      return constraint;
   }
}

public class PostmanUtil {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(PostmanUtil.class);

   /** Regular expression used to evaluate operation name matching. */
   private static final String OPERATION_NAME_EXPRESSION_PREFIX = "(GET|POST|PUT|PATCH|DELETE|OPTION)?( *)(/)?";

   /** Private constructor to hide the default one. */
   private PostmanUtil() {
   }

   /**
    * Tells if 2 operations may be equivalent giving their names. Useful when comparing OpenAPI operations (containing
    * <code>{param}</code> in path) and Postman operations (containing <code>:param</code> in path).
    * @param operationNameRef       Reference operation name (typically the one coming from OpenAPI)
    * @param operationNameCandidate Candidate operatoin name (typically the one coming from Postman Collection)
    * @return True if both are equivalent, false otherwise.
    */
   public static boolean areOperationsEquivalent(String operationNameRef, String operationNameCandidate) {
      // First check equals ignoring case.
      if (operationNameRef.equalsIgnoreCase(operationNameCandidate)) {
         return true;
      }
      // Then we may have an OpenAPI template we should convert to Postman and check again.
      if (operationNameRef.contains("/{")) {
         String transformedName = operationNameRef.replaceAll("/\\{", "/:").replace("}", "");
         if (transformedName.equalsIgnoreCase(operationNameCandidate)) {
            return true;
         }
      }

      try {
         // Finally check again adding a verb as prefix.
         return operationNameCandidate.matches(OPERATION_NAME_EXPRESSION_PREFIX + operationNameRef);
      } catch (PatternSyntaxException pse) {
         log.warn("{}{} throws a PatternSyntaxException", OPERATION_NAME_EXPRESSION_PREFIX, operationNameRef);
      }
      return false;
   }
}

