@org.springframework.web.bind.annotation.RestController
public class RestController {

   /** A safe logger for filtering user-controlled data in diagnostic messages. */
   private static final SafeLogger log = SafeLogger.getLogger(RestController.class);

   private final ServiceRepository serviceRepository;
   private final ResourceRepository resourceRepository;
   private final RestInvocationProcessor invocationProcessor;

   @Value("${mocks.rest.enable-cors-policy}")
   private Boolean enableCorsPolicy;
   @Value("${mocks.rest.cors.allowedOrigins}")
   private String corsAllowedOrigins;
   @Value("${mocks.rest.cors.allowCredentials}")
   private Boolean corsAllowCredentials;

   @Value("${validation.resourceUrl}")
   private String validationResourceUrl;

   /**
    * Build a RestController with required dependencies.
    * @param serviceRepository   The repository to access services definitions
    * @param resourceRepository  The repository to access resources definitions
    * @param invocationProcessor The invocation processor to apply REST mocks dispatching logic
    */
   public RestController(ServiceRepository serviceRepository, ResourceRepository resourceRepository,
         RestInvocationProcessor invocationProcessor) {
      this.serviceRepository = serviceRepository;
      this.resourceRepository = resourceRepository;
      this.invocationProcessor = invocationProcessor;
   }

   @SuppressWarnings("java:S3752")
   @RequestMapping(value = "/rest/{service}/{version}/**", method = { RequestMethod.HEAD, RequestMethod.OPTIONS,
         RequestMethod.GET, RequestMethod.POST, RequestMethod.PUT, RequestMethod.PATCH, RequestMethod.DELETE })
   public ResponseEntity<byte[]> execute(@PathVariable("service") String serviceName,
         @PathVariable("version") String version, @RequestParam(value = "delay", required = false) Long delay,
         @RequestBody(required = false) String body, @RequestHeader HttpHeaders headers, HttpServletRequest request,
         HttpMethod method) {

      log.info("Servicing mock response for service [{}, {}] on uri {} with verb {}", serviceName, version,
            request.getRequestURI(), method);
      log.debug("Request body: {}", body);

      long startTime = System.currentTimeMillis();

      // Find matching service and operation.
      MockInvocationContext ic = findInvocationContext(serviceName, version, request, method);
      if (ic.service() == null) {
         return new ResponseEntity<>(
               String.format("The service %s with version %s does not exist!", serviceName, version).getBytes(),
               HttpStatus.NOT_FOUND);
      }

      // Check matching operation.
      if (ic.operation() == null) {
         // Handle OPTIONS request if CORS policy is enabled.
         if (Boolean.TRUE.equals(enableCorsPolicy) && HttpMethod.OPTIONS.equals(method)) {
            log.debug("No valid operation found but Microcks configured to apply CORS policy");
            return handleCorsRequest(request);
         }

         log.debug("No valid operation found and Microcks configured to not apply CORS policy...");
         return new ResponseEntity<>(HttpStatus.NOT_FOUND);
      }
      log.debug("Found a valid operation {} with rules: {}", ic.operation().getName(),
            ic.operation().getDispatcherRules());

      return processMockInvocationRequest(ic, startTime, MockControllerCommons.getDelay(headers, delay), body, headers,
            request, method);
   }

   @SuppressWarnings("java:S3752")
   @RequestMapping(value = "/rest-valid/{service}/{version}/**", method = { RequestMethod.HEAD, RequestMethod.OPTIONS,
         RequestMethod.GET, RequestMethod.POST, RequestMethod.PUT, RequestMethod.PATCH, RequestMethod.DELETE })
   public ResponseEntity<byte[]> validateAndExecute(@PathVariable("service") String serviceName,
         @PathVariable("version") String version, @RequestParam(value = "delay", required = false) Long delay,
         @RequestBody(required = false) String body, @RequestHeader HttpHeaders headers, HttpServletRequest request,
         HttpMethod method) {

      log.info("Servicing mock response for service [{}, {}] on uri {} with verb {}", serviceName, version,
            request.getRequestURI(), method);
      log.debug("Request body: {}", body);

      long startTime = System.currentTimeMillis();

      // Find matching service and operation.
      MockInvocationContext ic = findInvocationContext(serviceName, version, request, method);
      if (ic.service() == null) {
         return new ResponseEntity<>(
               String.format("The service %s with version %s does not exist!", serviceName, version).getBytes(),
               HttpStatus.NOT_FOUND);
      }

      // Check matching operation.
      if (ic.operation() == null) {
         // Handle OPTIONS request if CORS policy is enabled.
         if (Boolean.TRUE.equals(enableCorsPolicy) && HttpMethod.OPTIONS.equals(method)) {
            log.debug("No valid operation found but Microcks configured to apply CORS policy");
            return handleCorsRequest(request);
         }

         log.debug("No valid operation found and Microcks configured to not apply CORS policy...");
         return new ResponseEntity<>(HttpStatus.NOT_FOUND);
      }
      log.debug("Found a valid operation {} with rules: {}", ic.operation().getName(),
            ic.operation().getDispatcherRules());

      // Try to validate request payload (body) if we have one.
      String shortContentType = getShortContentType(request.getContentType());
      if (body != null && !body.trim().isEmpty()
            && OpenAPITestRunner.APPLICATION_JSON_TYPES_PATTERN.matcher(shortContentType).matches()) {
         log.debug("Looking for an OpenAPI/Swagger schema to validate request body");

         Resource openapiSpecResource = findResourceCandidate(ic.service());
         if (openapiSpecResource == null) {
            return new ResponseEntity<>(
                  String.format("The service %s with version %s does not have an OpenAPI/Swagger schema!", serviceName,
                        version).getBytes(),
                  HttpStatus.PRECONDITION_FAILED);
         }

         List<String> errors = getErrors(body, ic, shortContentType, openapiSpecResource);

         log.debug("Schema validation errors: {}", errors.size());
         // Return a 400 http code with errors.
         if (!errors.isEmpty()) {
            return new ResponseEntity<>(errors.toString().getBytes(), HttpStatus.BAD_REQUEST);
         }
      }

      return processMockInvocationRequest(ic, startTime, MockControllerCommons.getDelay(headers, delay), body, headers,
            request, method);
   }

   /** Get the errors from OpenAPI/Swagger schema validation. */
   private List<String> getErrors(String body, MockInvocationContext ic, String shortContentType,
         Resource openapiSpecResource) {
      boolean isOpenAPIv3 = !ResourceType.SWAGGER.equals(openapiSpecResource.getType());

      JsonNode openApiSpec = null;
      try {
         openApiSpec = OpenAPISchemaValidator.getJsonNodeForSchema(openapiSpecResource.getContent());
      } catch (IOException ioe) {
         log.debug("OpenAPI specification cannot be transformed into valid JsonNode schema, so failing");
      }

      // Extract JsonNode corresponding to operation.
      String verb = ic.operation().getName().split(" ")[0].toLowerCase();
      String path = ic.operation().getName().split(" ")[1].trim();

      // Get body content as a string.
      JsonNode contentNode = null;
      try {
         contentNode = OpenAPISchemaValidator.getJsonNode(body);
      } catch (IOException ioe) {
         log.debug("Response body cannot be accessed or transformed as Json, returning failure");
      }
      String jsonPointer = "/paths/" + path.replace("/", "~1") + "/" + verb + "/requestBody";

      List<String> errors = null;
      if (isOpenAPIv3) {
         errors = OpenAPISchemaValidator.validateJsonMessage(openApiSpec, contentNode, jsonPointer, shortContentType,
               validationResourceUrl);
      } else {
         errors = SwaggerSchemaValidator.validateJsonMessage(openApiSpec, contentNode, jsonPointer,
               validationResourceUrl);
      }
      return errors;
   }

   /** Process REST mock invocation. */
   private ResponseEntity<byte[]> processMockInvocationRequest(MockInvocationContext ic, long startTime, Long delay,
         String body, HttpHeaders headers, HttpServletRequest request, HttpMethod method) {

      String violationMsg = validateParameterConstraintsIfAny(ic.operation(), request);
      if (violationMsg != null) {
         return new ResponseEntity<>((violationMsg + ". Check parameter constraints.").getBytes(),
               HttpStatus.BAD_REQUEST);
      }

      ResponseResult response = invocationProcessor.processInvocation(ic, startTime, delay, body, headers, request);
      return new ResponseEntity<>(response.content(), response.headers(), response.status());
   }

   /** Find the invocation context for this mock request. */
   private MockInvocationContext findInvocationContext(String serviceName, String version, HttpServletRequest request,
         HttpMethod method) {
      // Extract resourcePath for matching with correct operation and build the encoded URI fragment to retrieve simple resourcePath.
      String serviceAndVersion = MockControllerCommons.composeServiceAndVersion(serviceName, version);
      String resourcePath = MockControllerCommons.extractResourcePath(request, serviceAndVersion);
      log.debug("Found resourcePath: {}", resourcePath);

      // If serviceName was encoded with '+' instead of '%20', remove them.
      if (serviceName.contains("+")) {
         serviceName = serviceName.replace('+', ' ');
      }

      // Find matching service.
      Service service = serviceRepository.findByNameAndVersion(serviceName, version);
      if (service == null) {
         return new MockInvocationContext(null, null, resourcePath);
      }

      // Find matching operation.
      Operation operation = findOperation(service, method, resourcePath);
      return new MockInvocationContext(service, operation, resourcePath);
   }

   @CheckForNull
   private Operation findOperation(Service service, HttpMethod method, String resourcePath) {
      // Remove trailing '/' if any.
      String trimmedResourcePath = trimResourcePath(resourcePath);

      Operation result = findOperationByResourcePath(service, method, resourcePath, trimmedResourcePath);

      if (result == null) {
         // We may not have found an Operation because of not exact resource path matching with an operation
         // using a Fallback dispatcher. Try again, just considering the verb and path pattern of operation.
         result = findOperationByPathPattern(service, method, resourcePath);
      }
      return result;
   }

   @CheckForNull
   private Operation findOperationByPathPattern(Service service, HttpMethod method, String resourcePath) {
      for (Operation operation : service.getOperations()) {
         // Select operation based onto Http verb (GET, POST, PUT, etc ...)
         // ... then check is current resource path matches operation path pattern.
         if (operation.getMethod().equals(method.name()) && operation.getResourcePaths() != null) {
            // Produce a matching regexp removing {part} and :part from pattern.
            String operationPattern = getURIPattern(operation.getName());
            //operationPattern = operationPattern.replaceAll("\\{.+\\}", "([^/])+");
            operationPattern = operationPattern.replaceAll("\\{[\\w-]+\\}", "([^/])+");
            operationPattern = operationPattern.replaceAll("(/:[^:^/]+)", "\\/([^/]+)");
            if (resourcePath.matches(operationPattern)) {
               return operation;
            }
         }
      }
      return null;
   }

   @CheckForNull
   private Operation findOperationByResourcePath(Service service, HttpMethod method, String resourcePath,
         String trimmedResourcePath) {
      for (Operation operation : service.getOperations()) {
         // Select operation based onto Http verb (GET, POST, PUT, etc ...)
         // ... then check is we have a matching resource path.
         if (operation.getMethod().equals(method.name()) && operation.getResourcePaths() != null
               && (operation.getResourcePaths().contains(resourcePath)
                     || operation.getResourcePaths().contains(trimmedResourcePath))) {
            return operation;
         }
         // Check by simple name comparison if no resource path is defined.
         if (operation.getName().equals(method.name().toUpperCase() + " " + resourcePath)) {
            return operation;
         }
      }
      return null;
   }

   /** Trim the resource path if it ends with a '/'. */
   private String trimResourcePath(String resourcePath) {
      if (resourcePath.endsWith("/")) {
         return resourcePath.substring(0, resourcePath.length() - 1);
      }
      return resourcePath;
   }

   /** Get the short content type without charset information. */
   private String getShortContentType(String contentType) {
      // Sanitize charset information from media-type.
      if (contentType != null && contentType.contains("charset=") && contentType.indexOf(";") >= 1) {
         return contentType.substring(0, contentType.indexOf(";"));
      }
      return contentType;
   }

   /** Validate the parameter constraints and return a single string with violation message if any. */
   private String validateParameterConstraintsIfAny(Operation rOperation, HttpServletRequest request) {
      if (rOperation.getParameterConstraints() != null) {
         for (ParameterConstraint constraint : rOperation.getParameterConstraints()) {
            String violationMsg = ParameterConstraintUtil.validateConstraint(request, constraint);
            if (violationMsg != null) {
               return violationMsg;
            }
         }
      }
      return null;
   }

   /** Retrieve URI Pattern from operation name (remove starting verb name). */
   private String getURIPattern(String operationName) {
      if (operationName.startsWith("GET ") || operationName.startsWith("POST ") || operationName.startsWith("PUT ")
            || operationName.startsWith("DELETE ") || operationName.startsWith("PATCH ")
            || operationName.startsWith("OPTIONS ")) {
         return operationName.substring(operationName.indexOf(' ') + 1);
      }
      return operationName;
   }

   /** Handle a CORS request putting the correct headers in response entity. */
   private ResponseEntity<byte[]> handleCorsRequest(HttpServletRequest request) {
      // Retrieve and set access control headers from those coming in request.
      List<String> accessControlHeaders = new ArrayList<>();
      Collections.list(request.getHeaders("Access-Control-Request-Headers")).forEach(accessControlHeaders::add);
      HttpHeaders requestHeaders = new HttpHeaders();
      requestHeaders.setAccessControlAllowHeaders(accessControlHeaders);
      requestHeaders.setAccessControlExposeHeaders(accessControlHeaders);

      // Apply CORS headers to response with 204 response code.
      return ResponseEntity.noContent().header("Access-Control-Allow-Origin", corsAllowedOrigins)
            .header("Access-Control-Allow-Methods", "POST, PUT, GET, OPTIONS, DELETE, PATCH").headers(requestHeaders)
            .header("Access-Allow-Credentials", String.valueOf(corsAllowCredentials))
            .header("Access-Control-Max-Age", "3600").header("Vary", "Accept-Encoding, Origin").build();
   }

   private Resource findResourceCandidate(Service service) {
      Optional<Resource> candidate = Optional.empty();
      // Try resources marked within mainArtifact first.
      List<Resource> resources = resourceRepository.findMainByServiceId(service.getId());
      if (!resources.isEmpty()) {
         candidate = getResourceCandidate(resources);
      }
      // Else try all the services resources...
      if (candidate.isEmpty()) {
         resources = resourceRepository.findByServiceId(service.getId());
         if (!resources.isEmpty()) {
            candidate = getResourceCandidate(resources);
         }
      }
      return candidate.orElse(null);
   }

   private Optional<Resource> getResourceCandidate(List<Resource> resources) {
      return resources.stream()
            .filter(r -> ResourceType.OPEN_API_SPEC.equals(r.getType()) || ResourceType.SWAGGER.equals(r.getType()))
            .findFirst();
   }
}

@org.springframework.stereotype.Service
public class ImportExportService {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(ImportExportService.class);

   private final ServiceService serviceService;
   private final MessageService messageService;
   private final RequestRepository requestRepository;
   private final ResourceRepository resourceRepository;
   private final ResponseRepository responseRepository;
   private final EventMessageRepository eventMessageRepository;
   private final ServiceRepository serviceRepository;
   private final ApplicationContext applicationContext;
   private final AuthorizationChecker authorizationChecker;

   /**
    * Create a new ImportExportService with required dependencies.
    * @param serviceService         The service for services
    * @param messageService         The service for messages
    * @param requestRepository      The repository for requests
    * @param resourceRepository     The repository for resources
    * @param responseRepository     The repository for responses
    * @param eventMessageRepository The repository for event messages
    * @param serviceRepository      The repository for services
    * @param applicationContext     The Spring application context
    * @param authorizationChecker   The authorization checker service
    */
   public ImportExportService(ServiceService serviceService, MessageService messageService,
         RequestRepository requestRepository, ResourceRepository resourceRepository,
         ResponseRepository responseRepository, EventMessageRepository eventMessageRepository,
         ServiceRepository serviceRepository, ApplicationContext applicationContext,
         AuthorizationChecker authorizationChecker) {
      this.serviceService = serviceService;
      this.messageService = messageService;
      this.requestRepository = requestRepository;
      this.resourceRepository = resourceRepository;
      this.responseRepository = responseRepository;
      this.eventMessageRepository = eventMessageRepository;
      this.serviceRepository = serviceRepository;
      this.applicationContext = applicationContext;
      this.authorizationChecker = authorizationChecker;
   }

   /**
    * Import a repository from JSON definitions.
    * @param json A String encoded into json and representing repository object definitions.
    * @return A boolean indicating operation success.
    */
   public boolean importRepository(String json) {
      ObjectMapper mapper = new ObjectMapper();
      ImportExportModel model = null;
      try {
         model = mapper.readValue(json, ImportExportModel.class);
      } catch (Exception e) {
         log.error("Exception while reading json import", e);
      }

      if (model != null) {
         log.info("Retrieve {} services to import into repository", model.getServices().size());
         log.info("Retrieve {} resources to import into repository", model.getResources().size());
         log.info("Retrieve {} responses to import into repository", model.getResponses().size());
         log.info("Retrieve {} requests to import into repository", model.getRequests().size());
         log.info("Retrieve {} event messages to import into repository",
               model.getEventMessages() != null ? model.getEventMessages().size() : 0);

         serviceRepository.saveAll(model.getServices());
         resourceRepository.saveAll(model.getResources());
         responseRepository.saveAll(model.getResponses());
         requestRepository.saveAll(model.getRequests());
         // Make it optional to allow importing an old snapshot.
         if (model.getEventMessages() != null) {
            eventMessageRepository.saveAll(model.getEventMessages());
         }

         // Once everything is saved, be sure to fire a change event to allow
         // propagation.
         publishServiceChangeEvent(model);
         return true;
      }
      log.info("No services, resources or messages to import into repository");
      return false;
   }

   /** Publish a ServiceChangeEvent towards minions or some other consumers. */
   private void publishServiceChangeEvent(ImportExportModel model) {
      for (Service service : model.getServices()) {
         ServiceChangeEvent event = new ServiceChangeEvent(this, service.getId(), ChangeType.UPDATED);
         applicationContext.publishEvent(event);
         log.debug("Service change event has been published");
      }
   }

   /**
    * Get a partial export of repository using the specified services identifiers.
    * @param ids    The list of service ids to export
    * @param format The format for this export (reserved for future usage)
    * @return A string representation of this repository export
    */
   public String exportRepository(List<String> ids, String format) {
      StringBuilder result = new StringBuilder("{");
      ObjectMapper mapper = new ObjectMapper();

      // First, retrieve service list.
      List<Service> services = serviceRepository.findByIdIn(ids);
      try {
         String jsonArray = mapper.writeValueAsString(services);
         result.append("\"services\":").append(jsonArray).append(", ");
      } catch (Exception e) {
         log.error("Exception while serializing services for export", e);
      }

      // Then, get resources associated to services.
      List<Resource> resources = resourceRepository.findByServiceIdIn(ids);
      try {
         String jsonArray = mapper.writeValueAsString(resources);
         result.append("\"resources\":").append(jsonArray).append(", ");
      } catch (Exception e) {
         log.error("Exception while serializing resources for export", e);
      }

      // Finally, get requests and responses associated to the services.
      List<String> operationIds = new ArrayList<>();
      for (Service service : services) {
         for (Operation operation : service.getOperations()) {
            operationIds.add(IdBuilder.buildOperationId(service, operation));
         }
      }

      List<Request> requests = requestRepository.findByOperationIdIn(operationIds);
      List<Response> responses = responseRepository.findByOperationIdIn(operationIds);
      List<EventMessage> eventMessages = eventMessageRepository.findByOperationIdIn(operationIds);
      try {
         String jsonArray = mapper.writeValueAsString(requests);
         result.append("\"requests\":").append(jsonArray).append(", ");
         jsonArray = mapper.writeValueAsString(responses);
         result.append("\"responses\":").append(jsonArray).append(", ");
         jsonArray = mapper.writeValueAsString(eventMessages);
         result.append("\"eventMessages\":").append(jsonArray);
      } catch (Exception e) {
         log.error("Exception while serializing messages for export", e);
      }

      return result.append("}").toString();
   }

   public static class ImportExportModel {
      private List<Service> services;
      private List<Resource> resources;
      private List<Request> requests;
      private List<Response> responses;
      private List<EventMessage> eventMessages;

      public List<Service> getServices() {
         return services;
      }

      public void setServices(List<Service> services) {
         this.services = services;
      }

      public List<Resource> getResources() {
         return resources;
      }

      public void setResources(List<Resource> resources) {
         this.resources = resources;
      }

      public List<Request> getRequests() {
         return requests;
      }

      public void setRequests(List<Request> requests) {
         this.requests = requests;
      }

      public List<Response> getResponses() {
         return responses;
      }

      public void setResponses(List<Response> responses) {
         this.responses = responses;
      }

      public List<EventMessage> getEventMessages() {
         return eventMessages;
      }

      public void setEventMessages(List<EventMessage> eventMessages) {
         this.eventMessages = eventMessages;
      }
   }

   /**
    * Export a selection of exchanges for a service.
    * @param serviceId         The unique identifier of the service
    * @param exchangeSelection The selection of exchanges to export
    * @param exportFormat      The format for this export
    * @param userInfo          The user information
    * @return A string representation of this exchange selection export
    */
   public String exportExchangeSelection(String serviceId, ExchangeSelection exchangeSelection, String exportFormat,
         UserInfo userInfo) throws MockRepositoryExportException {
      Service service = serviceService.getServiceById(serviceId);
      if (service != null
            && authorizationChecker.hasRoleForService(userInfo, AuthorizationChecker.ROLE_MANAGER, service)) {

         // Create an exporter and add the service definition.
         MockRepositoryExporter exporter = MockRepositoryExporterFactory.getMockRepositoryExporter(exportFormat);
         exporter.addServiceDefinition(service);

         for (Operation operation : service.getOperations()) {
            if (exchangeSelection.getExchanges().containsKey(operation.getName())) {
               log.debug("Exporting selected exchanges for operation '{}'", operation.getName());
               String operationId = IdBuilder.buildOperationId(service, operation);

               List<? extends Exchange> selectedExchanges = null;
               if (ServiceType.EVENT.equals(service.getType())) {
                  selectedExchanges = messageService.getEventByOperation(operationId).stream()
                        .filter(unidirectionalEvent -> exchangeSelection.getExchanges().get(operation.getName())
                              .contains(unidirectionalEvent.getEventMessage().getName()))
                        .toList();
               } else {
                  selectedExchanges = messageService.getRequestResponseByOperation(operationId).stream()
                        .filter(pair -> exchangeSelection.getExchanges().get(operation.getName())
                              .contains(pair.getRequest().getName()))
                        .toList();
               }
               exporter.addMessageDefinitions(service, operation, selectedExchanges);
            }
         }
         return exporter.exportAsString();
      }
      log.warn("Didn't find any service with id {} to export or unauthorized, returning empty content", serviceId);
      return "";
   }
}

public class SafeLogger {

   private final Logger log;

   private SafeLogger(Logger log) {
      this.log = log;
   }

   /**
    * Return a logger named corresponding to the class passed as parameter, using the statically bound ILoggerFactory
    * instance.
    * @param clazz the returned logger will be named after clazz
    * @return logger
    */
   public static SafeLogger getLogger(Class<?> clazz) {
      return new SafeLogger(LoggerFactory.getLogger(clazz));
   }

   /**
    * Is the logger instance enabled for the DEBUG level?
    * @return True if this Logger is enabled for the DEBUG level, false otherwise.
    */
   public boolean isDebugEnabled() {
      return log.isDebugEnabled();
   }

   /**
    * Log a message at the DEBUG level.
    * @param message the message string to be logged
    */
   public void debug(String message) {
      if (log.isDebugEnabled()) {
         log.debug(encode(message));
      }
   }

   /**
    * Log a message at the DEBUG level according to the specified format and argument. This form avoids superfluous
    * object creation when the logger is disabled for the DEBUG level.
    * @param format the format string
    * @param arg    the argument
    */
   public void debug(String format, Object arg) {
      if (log.isDebugEnabled()) {
         log.debug(encode(format), encode(arg));
      }
   }

   /**
    * Log a message at the DEBUG level according to the specified format and arguments. This form avoids superfluous
    * object creation when the logger is disabled for the DEBUG level.
    * @param format the format string
    * @param arg1   the first argument
    * @param arg2   the second argument
    */
   public void debug(String format, Object arg1, Object arg2) {
      if (log.isDebugEnabled()) {
         log.debug(encode(format), encode(arg1), encode(arg2));
      }
   }

   /**
    * Log a message at the DEBUG level according to the specified format and arguments. This form avoids superfluous
    * string concatenation when the logger is disabled for the DEBUG level. However, this variant incurs the hidden (and
    * relatively small) cost of creating an Object[] before invoking the method, even if this logger is disabled for
    * DEBUG. The variants taking one and two arguments exist solely in order to avoid this hidden cost.
    * @param format    the format string
    * @param arguments a list of 3 or more arguments
    */
   public void debug(String format, Object... arguments) {
      if (log.isDebugEnabled()) {
         log.debug(encode(format), encode(arguments));
      }
   }

   /**
    * Is the logger instance enabled for the INFO level?
    * @return True if this Logger is enabled for the INFO level, false otherwise.
    */
   public boolean isInfoEnabled() {
      return log.isInfoEnabled();
   }

   /**
    * Log a message at the INFO level.
    * @param message the message string to be logged
    */
   public void info(String message) {
      if (log.isInfoEnabled()) {
         log.info(encode(message));
      }
   }

   /**
    * Log a message at the INFO level according to the specified format and argument. This form avoids superfluous
    * object creation when the logger is disabled for the INFO level.
    * @param format the format string
    * @param arg    the argument
    */
   public void info(String format, Object arg) {
      if (log.isInfoEnabled()) {
         log.info(encode(format), encode(arg));
      }
   }

   /**
    * Log a message at the INFO level according to the specified format and arguments. This form avoids superfluous
    * object creation when the logger is disabled for the INFO level.
    * @param format the format string
    * @param arg1   the first argument
    * @param arg2   the second argument
    */
   public void info(String format, Object arg1, Object arg2) {
      if (log.isInfoEnabled()) {
         log.info(encode(format), encode(arg1), encode(arg2));
      }
   }

   /**
    * Log a message at the INFO level according to the specified format and arguments. This form avoids superfluous
    * string concatenation when the logger is disabled for the INFO level. However, this variant incurs the hidden (and
    * relatively small) cost of creating an Object[] before invoking the method, even if this logger is disabled for
    * INFO. The variants taking one and two arguments exist solely in order to avoid this hidden cost.
    * @param format the format string
    * @param args   a list of 3 or more arguments
    */
   public void info(String format, Object... args) {
      if (log.isInfoEnabled()) {
         log.info(encode(format), encode(args));
      }
   }

   /**
    * Is the logger instance enabled for the WARN level?
    * @return True if this Logger is enabled for the WARN level, false otherwise.
    */
   public boolean isWarnEnabled() {
      return log.isWarnEnabled();
   }

   /**
    * Log an exception (throwable) at the WARN level with an accompanying message.
    * @param message the message string to be logged
    * @param t       the exception (throwable) to log
    */
   public void warn(String message, Throwable t) {
      if (log.isWarnEnabled()) {
         log.warn(encode(message), t);
      }
   }

   /**
    * Is the logger instance enabled for the ERROR level?
    * @return True if this Logger is enabled for the ERROR level, false otherwise.
    */
   public boolean isErrorEnabled() {
      return log.isErrorEnabled();
   }

   /**
    * Log a message at the ERROR level.
    * @param message the message string to be logged
    */
   public void error(String message) {
      if (log.isErrorEnabled()) {
         log.error(encode(message));
      }
   }

   /**
    * Log an exception (throwable) at the ERROR level with an accompanying message.
    * @param message the message accompanying the exception
    * @param t       the exception (throwable) to log
    */
   public void error(String message, Throwable t) {
      if (log.isErrorEnabled()) {
         log.error(encode(message), t);
      }
   }

   /**
    * Log a message at the ERROR level according to the specified format and arguments. This form avoids superfluous
    * object creation when the logger is disabled for the ERROR level.
    * @param format the format string
    * @param arg    the argument
    */
   public void error(String format, Object arg) {
      if (log.isErrorEnabled()) {
         log.error(encode(format), encode(arg));
      }
   }

   /**
    * Log a message at the ERROR level according to the specified format and arguments. This form avoids superfluous
    * object creation when the logger is disabled for the ERROR level.
    * @param format the format string
    * @param arg1   the first argument
    * @param arg2   the second argument
    */
   public void error(String format, Object arg1, Object arg2) {
      if (log.isErrorEnabled()) {
         log.error(encode(format), encode(arg1), encode(arg2));
      }
   }

   private String encode(String message) {
      return message.replaceAll("[\n\r]", "_");
   }

   private Object encode(Object argument) {
      if (argument instanceof String stringArg) {
         return encode(stringArg);
      }
      return argument;
   }

   private Object[] encode(Object... arguments) {
      return Arrays.stream(arguments).sequential().map(this::encode).toArray();
   }
}

public class MockControllerCommons {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(MockControllerCommons.class);

   /** The header name used to specify a wait delay in the request. */
   public static final String X_MICROCKS_DELAY_HEADER = "x-microcks-delay";

   private static final String RENDERING_MESSAGE = "Response contains dynamic EL expression, rendering it...";


   /** Private constructor to avoid instantiation. */
   private MockControllerCommons() {
   }

   /**
    * Retrieve a fallback specification for this operation if one is defined.
    * @param rOperation The operation to get fallback specification
    * @return A fallback specification or null if none defined
    */
   public static FallbackSpecification getFallbackIfAny(Operation rOperation) {
      FallbackSpecification fallback = null;
      if (DispatchStyles.FALLBACK.equals(rOperation.getDispatcher())) {
         try {
            fallback = FallbackSpecification.buildFromJsonString(rOperation.getDispatcherRules());
         } catch (JsonMappingException jme) {
            log.error("Dispatching rules of operation cannot be interpreted as FallbackSpecification", jme);
         }
      }
      return fallback;
   }

   /**
    * Retrieve a proxyFallback specification for this operation if one is defined.
    * @param rOperation The operation to get proxyFallback specification
    * @return A proxy specification or null if none defined
    */
   public static ProxyFallbackSpecification getProxyFallbackIfAny(Operation rOperation) {
      ProxyFallbackSpecification proxyFallback = null;
      if (DispatchStyles.PROXY_FALLBACK.equals(rOperation.getDispatcher())) {
         try {
            proxyFallback = ProxyFallbackSpecification.buildFromJsonString(rOperation.getDispatcherRules());
         } catch (JsonMappingException jme) {
            log.error("Dispatching rules of operation cannot be interpreted as ProxyFallbackSpecification", jme);
         }
      }
      return proxyFallback;
   }

   /**
    * Check if proxy behavior is requested and extract proxyUrl.
    * @param dispatcher      The original dispatcher for the Proxy dispatcher checking.
    * @param dispatcherRules The original dispatcherRules for URL extracting.
    * @param resourcePath    The original resourcePath for URL compilation.
    * @param proxyFallback   The proxyFallbackSpec for the Proxy-Fallback dispatcher checking and URL extracting.
    * @param request         The original request for URL comparing on cycling.
    * @param response        The response that was found(or not) by dispatcher.
    * @return The optional container with URI for the proxy service if the request needs to be proxied.
    */
   public static Optional<URI> getProxyUrlIfProxyIsNeeded(String dispatcher, String dispatcherRules,
         String resourcePath, ProxyFallbackSpecification proxyFallback, HttpServletRequest request, Response response) {
      String externalUrl = null;
      if (DispatchStyles.PROXY.equals(dispatcher)) {
         externalUrl = dispatcherRules;
      }
      if (response == null && proxyFallback != null) {
         externalUrl = proxyFallback.getProxyUrl();
      }
      if (externalUrl != null) {
         externalUrl = externalUrl.replaceFirst("/$", "") + resourcePath;
         if (!externalUrl.contentEquals(request.getRequestURL())) {
            try {
               return Optional
                     .of(UriComponentsBuilder.fromHttpUrl(externalUrl).query(request.getQueryString()).build().toUri());
            } catch (IllegalArgumentException ex) {
               log.warn("Invalid external URL in the dispatcher - {}", externalUrl);
            }
         }
      }
      return Optional.empty();
   }

   /**
    * Render the response headers using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized values.
    * @param evaluableRequest The request that can be evaluated in templating.
    * @param requestContext   The invocation context of the request
    * @param response         The response that was found by dispatcher
    * @return The rendered response headers values.
    */
   public static Set<Header> renderResponseHeaders(EvaluableRequest evaluableRequest,
         Map<String, Object> requestContext, Response response) {
      TemplateEngine engine = null;
      Set<Header> headers = new HashSet<>();

      if (response.getHeaders() != null) {
         for (Header header : response.getHeaders()) {
            Set<String> renderedValues = new HashSet<>();
            for (String value : header.getValues()) {
               // Only render and build an engine if we have an expression.
               if (value.contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
                  // Evaluate the header value.
                  if (engine == null) {
                     engine = TemplateEngineFactory.getTemplateEngine();
                  }
                  renderedValues.add(unguardedRenderResponseContent(evaluableRequest, requestContext, engine, value));
               } else {
                  renderedValues.add(value);
               }
            }
            headers.add(new Header(header.getName(), renderedValues));
         }
      }
      return headers;
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param requestBody    The body payload of incoming request.
    * @param requestContext The invocation context of the request
    * @param response       The response that was found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(String requestBody, Map<String, Object> requestContext,
         Response response) {
      if (response.getContent() != null && response.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug(RENDERING_MESSAGE);

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = new EvaluableRequest(requestBody, null);

         // Evaluate the response.
         return unguardedRenderResponseContent(evaluableRequest, requestContext,
               TemplateEngineFactory.getTemplateEngine(), response.getContent());
      }
      return response.getContent();
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param requestBody      The body payload of incoming request.
    * @param evaluableParams  A map of params for evaluation.
    * @param evaluableHeaders A map of headers for evaluation.
    * @param requestContext   The invocation context of the request
    * @param response         The response that was found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(String requestBody, Map<String, String> evaluableParams,
         Map<String, String> evaluableHeaders, Map<String, Object> requestContext, Response response) {
      if (response.getContent() != null && response.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug(RENDERING_MESSAGE);

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = new EvaluableRequest(requestBody, null);
         // Adding query and header parameters...
         evaluableRequest.setParams(evaluableParams);
         evaluableRequest.setHeaders(evaluableHeaders);

         // Evaluate the response.
         return unguardedRenderResponseContent(evaluableRequest, requestContext,
               TemplateEngineFactory.getTemplateEngine(), response.getContent());
      }
      return response.getContent();
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param requestBody         The body payload of incoming request.
    * @param requestResourcePath The resource path of mock request (if any, may be null)
    * @param request             The incoming servlet request
    * @param requestContext      The invocation context of the request
    * @param response            The response that was found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(String requestBody, String requestResourcePath,
         HttpServletRequest request, Map<String, Object> requestContext, Response response) {
      if (response.getContent() != null && response.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug(RENDERING_MESSAGE);

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = buildEvaluableRequest(requestBody, requestResourcePath, request);
         return unguardedRenderResponseContent(evaluableRequest, requestContext,
               TemplateEngineFactory.getTemplateEngine(), response.getContent());
      }
      return response.getContent();
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param evaluableRequest The request that can be evaluated in templating.
    * @param engine           The template engine to use for this rendering
    * @param responseContent  The response content found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(EvaluableRequest evaluableRequest, TemplateEngine engine,
         String responseContent) {
      if (responseContent != null && responseContent.contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         return unguardedRenderResponseContent(evaluableRequest, null, engine, responseContent);
      }
      return responseContent;
   }

   private static String unguardedRenderResponseContent(EvaluableRequest evaluableRequest,
         Map<String, Object> requestContext, TemplateEngine engine, String responseContent) {
      // Register the request variable and evaluate the response.
      engine.getContext().setVariable("request", evaluableRequest);
      if (requestContext != null) {
         engine.getContext().setVariables(requestContext);
      }
      try {
         return engine.getValue(responseContent);
      } catch (Throwable t) {
         log.error("Failing at evaluating template {}", responseContent, t);
      }
      return responseContent;
   }

   /**
    * Build an Evaluable request from various request elements.
    * @param requestBody         The body of request to evaluate
    * @param requestResourcePath The resource path this request is bound to
    * @param request             The underlying Http request
    * @return The Evaluable request for later templating rendering
    */
   public static EvaluableRequest buildEvaluableRequest(String requestBody, String requestResourcePath,
         HttpServletRequest request) {
      // Create and fill an evaluable request object.
      EvaluableRequest evaluableRequest = new EvaluableRequest(requestBody,
            requestResourcePath != null ? requestResourcePath.split("/") : null);
      // Adding query parameters...
      Map<String, String> evaluableParams = new HashMap<>();
      List<String> parameterNames = Collections.list(request.getParameterNames());
      for (String parameter : parameterNames) {
         evaluableParams.put(parameter, request.getParameter(parameter));
      }
      evaluableRequest.setParams(evaluableParams);
      // Adding headers...
      Map<String, String> evaluableHeaders = new HashMap<>();
      if (request.getHeaderNames() != null) {
         List<String> headerNames = Collections.list(request.getHeaderNames());
         for (String header : headerNames) {
            evaluableHeaders.put(header, request.getHeader(header));
         }
      }
      evaluableRequest.setHeaders(evaluableHeaders);

      return evaluableRequest;
   }

   /** Retrieve delay header or default to the one provided as parameter. */
   public static Long getDelay(HttpHeaders headers, Long delayParameter) {
      if (headers.containsKey(MockControllerCommons.X_MICROCKS_DELAY_HEADER)) {
         String delayHeader = headers.getFirst(MockControllerCommons.X_MICROCKS_DELAY_HEADER);
         try {
            return Long.parseLong(delayHeader);
         } catch (NumberFormatException nfe) {
            log.debug("Invalid delay header value: {}", delayHeader);
         }
      }
      return delayParameter;
   }

   /**
    * Block current thread for specified delay (if not null) from @{code startTime}.
    * @param startTime The starting time of mock request invocation
    * @param delay     The delay to wait for
    */
   public static void waitForDelay(Long startTime, Long delay) {
      if (delay != null && delay > -1) {
         log.debug("Mock delay is turned on, waiting if necessary...");
         long duration = System.currentTimeMillis() - startTime;
         if (duration < delay) {
            Object semaphore = new Object();
            synchronized (semaphore) {
               try {
                  semaphore.wait(delay - duration);
               } catch (Exception e) {
                  log.debug("Delay semaphore was interrupted");
               }
            }
         }
         log.debug("Delay now expired, releasing response !");
      }
   }

   /**
    * Publish a mock invocation event on Spring ApplicationContext internal bus.
    * @param applicationContext The context to use for publication
    * @param eventSource        The source of this event
    * @param service            The mocked Service that was invoked
    * @param response           The response it has been dispatched to
    * @param startTime          The start time of the invocation
    */
   public static void publishMockInvocation(ApplicationContext applicationContext, Object eventSource, Service service,
         Response response, Long startTime) {
      // Publish an invocation event before returning.
      MockInvocationEvent event = new MockInvocationEvent(eventSource, service.getName(), service.getVersion(),
            response.getName(), new Date(startTime), startTime - System.currentTimeMillis());
      applicationContext.publishEvent(event);
      log.debug("Mock invocation event has been published");
   }

   public static String composeServiceAndVersion(String serviceName, String version) {
      return "/" + UriUtils.encodeFragment(serviceName, "UTF-8") + "/" + version;
   }

   public static String extractResourcePath(HttpServletRequest request, String serviceAndVersion) {
      String requestURI = request.getRequestURI();
      String resourcePath = requestURI.substring(requestURI.indexOf(serviceAndVersion) + serviceAndVersion.length());
      log.debug("Found resourcePath: {}", resourcePath);

      // If resourcePath was encoded with '+' instead of '%20', replace them .
      if (resourcePath.contains("+")) {
         resourcePath = resourcePath.replace("+", "%20");
      }
      return resourcePath;
   }
}

@Component
public class RestInvocationProcessor {

   /** A safe logger for filtering user-controlled data in diagnostic messages. */
   private static final SafeLogger log = SafeLogger.getLogger(RestInvocationProcessor.class);

   private final ServiceStateRepository serviceStateRepository;
   private final ResponseRepository responseRepository;
   private final ApplicationContext applicationContext;
   private final ProxyService proxyService;

   private ScriptEngine scriptEngine;

   @Value("${mocks.enable-invocation-stats}")
   private Boolean enableInvocationStats;

   /**
    * Build a RestMockInvocationProcessor with required dependencies.
    * @param serviceStateRepository The repository to access service state
    * @param responseRepository     The repository to access responses definitions
    * @param applicationContext     The Spring application context
    * @param proxyService           The proxy to external URLs or services
    */
   public RestInvocationProcessor(ServiceStateRepository serviceStateRepository, ResponseRepository responseRepository,
         ApplicationContext applicationContext, ProxyService proxyService) {
      this.serviceStateRepository = serviceStateRepository;
      this.responseRepository = responseRepository;
      this.applicationContext = applicationContext;
      this.proxyService = proxyService;
      this.scriptEngine = new ScriptEngineManager().getEngineByExtension("groovy");
   }

   /**
    * Process a REST invocation. This method is responsible for determining the appropriate response based on the
    * request context, applying any necessary dispatching logic, and handling proxying if required.
    * @param ic        The invocation context containing information about the service and operation being invoked
    * @param startTime The start time of the invocation
    * @param delay     The delay to apply before returning the response
    * @param body      The request body
    * @param headers   The HTTP headers of the request
    * @param request   The HTTP servlet request
    * @return A ResponseResult containing the status, headers, and body of the response
    */
   public ResponseResult processInvocation(MockInvocationContext ic, long startTime, Long delay, String body,
         Map<String, List<String>> headers, HttpServletRequest request) {

      // We must find dispatcher and its rules. Default to operation ones but
      // if we have a Fallback or Proxy-Fallback this is the one who is holding the first pass rules.
      FallbackSpecification fallback = MockControllerCommons.getFallbackIfAny(ic.operation());
      ProxyFallbackSpecification proxyFallback = MockControllerCommons.getProxyFallbackIfAny(ic.operation());
      String dispatcher = getDispatcher(ic, fallback, proxyFallback);
      String dispatcherRules = getDispatcherRules(ic, fallback, proxyFallback);

      //
      DispatchContext dispatchContext = computeDispatchCriteria(ic.service(), dispatcher, dispatcherRules,
            getURIPattern(ic.operation().getName()), UriUtils.decode(ic.resourcePath(), StandardCharsets.UTF_8),
            request, body);
      log.debug("Dispatch criteria for finding response is {}", dispatchContext.dispatchCriteria());

      List<Response> responses;
      Response response = getResponse(ic, request, dispatchContext);

      if (response == null && fallback != null) {
         // If we've found nothing and got a fallback, that's the moment!
         responses = responseRepository.findByOperationIdAndName(
               IdBuilder.buildOperationId(ic.service(), ic.operation()), fallback.getFallback());
         response = getResponseByMediaType(responses, request);
      }

      // Setting delay to default one if not set.
      if (delay == null && ic.operation().getDefaultDelay() != null) {
         delay = ic.operation().getDefaultDelay();
      }

      // Check if we need to proxy the request.
      Optional<URI> proxyUrl = MockControllerCommons.getProxyUrlIfProxyIsNeeded(dispatcher, dispatcherRules,
            ic.resourcePath(), proxyFallback, request, response);
      if (proxyUrl.isPresent()) {
         // Delay response here as the returning content will be returned directly.
         MockControllerCommons.waitForDelay(startTime, delay);

         // Translate generic headers into Spring ones.
         HttpHeaders httpHeaders = new HttpHeaders();
         httpHeaders.putAll(headers);

         // If we've got a proxyUrl, that's the moment!
         ResponseEntity<byte[]> proxyResponse = proxyService.callExternal(proxyUrl.get(),
               HttpMethod.valueOf(ic.operation().getMethod()), httpHeaders, body);
         return new ResponseResult(proxyResponse.getStatusCode(), proxyResponse.getHeaders(), proxyResponse.getBody());
      }

      if (response == null) {
         if (dispatcher == null) {
            response = getOneForOperation(ic, request, response);
         } else {
            // There is a dispatcher, but we found no response => return 400 as per #819 and #1132.
            return new ResponseResult(HttpStatus.BAD_REQUEST, null,
                  String.format("The response %s does not exist!", dispatchContext.dispatchCriteria()).getBytes());
         }
      }

      if (response != null) {
         HttpStatus status = (response.getStatus() != null ? HttpStatus.valueOf(Integer.parseInt(response.getStatus()))
               : HttpStatus.OK);

         // Deal with specific headers (content-type and redirect directive).
         HttpHeaders responseHeaders = getResponseHeaders(ic, body, request, dispatchContext, response);
         String responseContent = getResponseContent(ic, startTime, delay, body, request, dispatchContext, response);

         // Return response content.
         return new ResponseResult(status, responseHeaders,
               responseContent != null ? responseContent.getBytes(StandardCharsets.UTF_8) : null);
      }

      return new ResponseResult(HttpStatus.BAD_REQUEST, null, null);
   }

   /** Get the root dispatcher for the invocation context. */
   private String getDispatcher(MockInvocationContext ic, FallbackSpecification fallback,
         ProxyFallbackSpecification proxyFallback) {
      String dispatcher = ic.operation().getDispatcher();
      if (fallback != null) {
         dispatcher = fallback.getDispatcher();
      }
      if (proxyFallback != null) {
         dispatcher = proxyFallback.getDispatcher();
      }
      return dispatcher;
   }

   /** Get the root dispatcher rules for the invocation context. */
   private String getDispatcherRules(MockInvocationContext ic, FallbackSpecification fallback,
         ProxyFallbackSpecification proxyFallback) {
      String dispatcherRules = ic.operation().getDispatcherRules();
      if (fallback != null) {
         dispatcherRules = fallback.getDispatcherRules();
      }
      if (proxyFallback != null) {
         dispatcherRules = proxyFallback.getDispatcherRules();
      }
      return dispatcherRules;
   }

   /** Get one random response for operation. */
   private Response getOneForOperation(MockInvocationContext ic, HttpServletRequest request, Response response) {
      List<Response> responses;
      // In case no response found because dispatcher is null, just get one for the operation.
      // This will allow also OPTIONS operations (like pre-flight requests) with no dispatch criteria to work.
      log.debug("No responses found so far, tempting with just bare operationId...");
      responses = responseRepository.findByOperationId(IdBuilder.buildOperationId(ic.service(), ic.operation()));
      if (!responses.isEmpty()) {
         response = getResponseByMediaType(responses, request);
      }
      return response;
   }

   /** Filter responses using the Accept header for content-type, default to the first. Return null if no responses. */
   private Response getResponseByMediaType(List<Response> responses, HttpServletRequest request) {
      if (!responses.isEmpty()) {
         String accept = request.getHeader("Accept");
         return responses.stream().filter(r -> !StringUtils.isNotEmpty(accept) || accept.equals(r.getMediaType()))
               .findFirst().orElse(responses.getFirst());
      }
      return null;
   }

   /** Retrieve URI Pattern from operation name (remove starting verb name). */
   private String getURIPattern(String operationName) {
      if (operationName.startsWith("GET ") || operationName.startsWith("POST ") || operationName.startsWith("PUT ")
            || operationName.startsWith("DELETE ") || operationName.startsWith("PATCH ")
            || operationName.startsWith("OPTIONS ")) {
         return operationName.substring(operationName.indexOf(' ') + 1);
      }
      return operationName;
   }

   /** Compute a dispatch context with a dispatchCriteria string from type, rules and request elements. */
   private DispatchContext computeDispatchCriteria(Service service, String dispatcher, String dispatcherRules,
         String uriPattern, String resourcePath, HttpServletRequest request, String body) {
      String dispatchCriteria = null;
      Map<String, Object> requestContext = null;

      // Depending on dispatcher, evaluate request with rules.
      if (dispatcher != null) {
         switch (dispatcher) {
            case DispatchStyles.SEQUENCE:
               dispatchCriteria = DispatchCriteriaHelper.extractFromURIPattern(dispatcherRules, uriPattern,
                     resourcePath);
               break;
            case DispatchStyles.SCRIPT:
               requestContext = new HashMap<>();
               Map<String, String> uriParameters = DispatchCriteriaHelper.extractMapFromURIPattern(uriPattern,
                     resourcePath);
               try {
                  // Evaluating request with script coming from operation dispatcher rules.
                  String script = ScriptEngineBinder.ensureSoapUICompatibility(dispatcherRules);
                  ScriptContext scriptContext = ScriptEngineBinder.buildEvaluationContext(scriptEngine, body,
                        requestContext, new ServiceStateStore(serviceStateRepository, service.getId()), request,
                        uriParameters);
                  dispatchCriteria = (String) scriptEngine.eval(script, scriptContext);
               } catch (Exception e) {
                  log.error("Error during Script evaluation", e);
               }
               break;
            case DispatchStyles.URI_PARAMS:
               String fullURI = request.getRequestURL() + "?" + request.getQueryString();
               dispatchCriteria = DispatchCriteriaHelper.extractFromURIParams(dispatcherRules, fullURI);
               break;
            case DispatchStyles.URI_PARTS:
               // /tenantId?t1/userId=x
               dispatchCriteria = DispatchCriteriaHelper.extractFromURIPattern(dispatcherRules, uriPattern,
                     resourcePath);
               break;
            case DispatchStyles.URI_ELEMENTS:
               dispatchCriteria = DispatchCriteriaHelper.extractFromURIPattern(dispatcherRules, uriPattern,
                     resourcePath);
               fullURI = request.getRequestURL() + "?" + request.getQueryString();
               dispatchCriteria += DispatchCriteriaHelper.extractFromURIParams(dispatcherRules, fullURI);
               break;
            case DispatchStyles.JSON_BODY:
               try {
                  JsonEvaluationSpecification specification = JsonEvaluationSpecification
                        .buildFromJsonString(dispatcherRules);
                  dispatchCriteria = JsonExpressionEvaluator.evaluate(body, specification);
               } catch (JsonMappingException jme) {
                  log.error("Dispatching rules of operation cannot be interpreted as JsonEvaluationSpecification", jme);
               }
               break;
            case DispatchStyles.QUERY_HEADER:
               // Extract headers from request and put them into a simple map to reuse extractFromParamMap().
               dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(dispatcherRules,
                     extractRequestHeaders(request));
               break;
            default:
               log.error("Unknown dispatcher type: {}", dispatcher);
               break;
         }
      }

      return new DispatchContext(dispatchCriteria, requestContext);
   }

   private Response getResponse(MockInvocationContext ic, HttpServletRequest request, DispatchContext dispatchContext) {
      Response response = null;

      // Filter depending on requested media type.
      // TODO: validate dispatchCriteria with dispatcherRules
      List<Response> responses = responseRepository.findByOperationIdAndDispatchCriteria(
            IdBuilder.buildOperationId(ic.service(), ic.operation()), dispatchContext.dispatchCriteria());
      response = getResponseByMediaType(responses, request);

      if (response == null) {
         // When using the SCRIPT or JSON_BODY dispatchers, return of evaluation may be the name of response.
         responses = responseRepository.findByOperationIdAndName(
               IdBuilder.buildOperationId(ic.service(), ic.operation()), dispatchContext.dispatchCriteria());
         response = getResponseByMediaType(responses, request);
      }
      return response;
   }

   /** Extract request headers from request. */
   private Map<String, String> extractRequestHeaders(HttpServletRequest request) {
      Map<String, String> headers = new HashMap<>();
      Collections.list(request.getHeaderNames()).forEach(name -> headers.put(name, request.getHeader(name)));
      return headers;
   }

   private HttpHeaders getResponseHeaders(MockInvocationContext ic, String body, HttpServletRequest request,
         DispatchContext dispatchContext, Response response) {
      HttpHeaders responseHeaders = new HttpHeaders();
      if (response.getMediaType() != null) {
         responseHeaders.setContentType(MediaType.valueOf(response.getMediaType() + ";charset=UTF-8"));
      }

      // Deal with headers from parameter constraints if any?
      recopyHeadersFromParameterConstraints(ic.operation(), request, responseHeaders);

      // Adding other generic headers (caching directives and so on...)
      if (response.getHeaders() != null) {
         // First check if they should be rendered.
         EvaluableRequest evaluableRequest = MockControllerCommons.buildEvaluableRequest(body, ic.resourcePath(),
               request);
         Set<Header> renderedHeaders = MockControllerCommons.renderResponseHeaders(evaluableRequest,
               dispatchContext.requestContext(), response);

         handleHeaders(ic, request, responseHeaders, renderedHeaders);
      }
      return responseHeaders;
   }

   /** Recopy headers defined with parameter constraints. */
   private void recopyHeadersFromParameterConstraints(Operation rOperation, HttpServletRequest request,
         HttpHeaders responseHeaders) {
      if (rOperation.getParameterConstraints() != null) {
         for (ParameterConstraint constraint : rOperation.getParameterConstraints()) {
            if (ParameterLocation.header == constraint.getIn() && constraint.isRecopy()) {
               String value = request.getHeader(constraint.getName());
               if (value != null) {
                  responseHeaders.set(constraint.getName(), value);
               }
            }
         }
      }
   }

   private void handleHeaders(MockInvocationContext ic, HttpServletRequest request, HttpHeaders responseHeaders,
         Set<Header> renderedHeaders) {
      for (Header renderedHeader : renderedHeaders) {
         if ("Location".equals(renderedHeader.getName())) {
            String location = renderedHeader.getValues().iterator().next();
            if (!AbsoluteUrlMatcher.matches(location)) {
               // We should process location in order to make relative URI specified an absolute one from
               // the client perspective.
               location = request.getScheme() + "://" + request.getServerName() + ":" + request.getServerPort()
                     + request.getContextPath() + "/rest"
                     + MockControllerCommons.composeServiceAndVersion(ic.service().getName(), ic.service().getVersion())
                     + location;
            }
            responseHeaders.add(renderedHeader.getName(), location);
         } else {
            if (!HttpHeaders.TRANSFER_ENCODING.equalsIgnoreCase(renderedHeader.getName())) {
               responseHeaders.put(renderedHeader.getName(), new ArrayList<>(renderedHeader.getValues()));
            }
         }
      }
   }

   private String getResponseContent(MockInvocationContext ic, long startTime, Long delay, String body,
         HttpServletRequest request, DispatchContext dispatchContext, Response response) {
      // Render response content before waiting and returning.
      String responseContent = MockControllerCommons.renderResponseContent(body, ic.resourcePath(), request,
            dispatchContext.requestContext(), response);

      // Delay response.
      MockControllerCommons.waitForDelay(startTime, delay);

      // Publish an invocation event before returning if enabled.
      if (Boolean.TRUE.equals(enableInvocationStats)) {
         MockControllerCommons.publishMockInvocation(applicationContext, this, ic.service(), response, startTime);
      }
      return responseContent;
   }
}

