public class RedirectExpression implements Expression {

   public static final char REDIRECT_MARKER = '>';

   public static final String REDIRECT_MARKER_SPLIT_REGEX = "\\>";

   private final Expression[] expressions;

   public RedirectExpression(Expression[] expressions) {
      this.expressions = expressions;
   }

   @Override
   public String getValue(EvaluationContext context) {
      String result = null;
      if (expressions.length > 0) {
         // Execute first expression for getting result.
         result = expressions[0].getValue(context);
         for (int i = 1; i < expressions.length; i++) {
            Expression exp = expressions[i];
            if (exp instanceof FunctionExpression functionExp) {
               // Clone this expression, enriching args with previous result.
               String[] clonedArgs = Arrays.copyOf(functionExp.getFunctionArgs(),
                     functionExp.getFunctionArgs().length + 1);
               clonedArgs[clonedArgs.length - 1] = result;
               FunctionExpression clonedExp = new FunctionExpression(functionExp.getFunction(), clonedArgs);
               clonedExp.getValue(context);
            }
         }
      }
      return result;
   }
}

public class VariableReferenceExpression implements Expression {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(VariableReferenceExpression.class);

   private static final String ARRAY_INDEX_REGEXP = "\\[(\\d+)\\]";
   private static final String MAP_INDEX_REGEXP = "\\[([\\.\\w-]+)\\]";
   private static final Pattern ARRAY_INDEX_PATTERN = Pattern.compile(ARRAY_INDEX_REGEXP);
   private static final Pattern MAP_INDEX_PATTERN = Pattern.compile(MAP_INDEX_REGEXP);

   private static final String[] PROPERTY_NAME_DELIMITERS = { "/", "[" };

   private Object variable;
   private String pathExpression;

   private String variableName;

   /**
    * Create a new expression with a variable and a path (property + sub-query expression).
    * @param variable       Bean from whom to extract value
    * @param pathExpression Path expression to get value from root object (property name + path sub-query)
    */
   public VariableReferenceExpression(Object variable, String pathExpression) {
      this.variable = variable;
      this.pathExpression = pathExpression;
   }

   /**
    * Create a new expression with a variable name (to be searched later into EvaluationContext)
    * @param variableName Name of a variable to get from Evaluation context.
    */
   public VariableReferenceExpression(String variableName) {
      this.variableName = variableName;
   }

   public Object getVariable() {
      return variable;
   }

   public void setVariable(Object variable) {
      this.variable = variable;
   }

   public String getPathExpression() {
      return pathExpression;
   }

   public void setPathExpression(String pathExpression) {
      this.pathExpression = pathExpression;
   }

   @Override
   public String getValue(EvaluationContext context) {
      // Use variable name if we just provide this.
      if (variableName != null && variable == null) {
         variable = context.lookupVariable(variableName);
         return (variable != null ? variable.toString() : "");
      }

      String propertyName = pathExpression;
      String propertyPath = null;
      int delimiterIndex = -1;

      // Search for a delimiter to isolate property name.
      for (String delimiter : PROPERTY_NAME_DELIMITERS) {
         delimiterIndex = pathExpression.indexOf(delimiter);
         if (delimiterIndex != -1) {
            propertyName = pathExpression.substring(0, delimiterIndex);
            propertyPath = pathExpression.substring(delimiterIndex);
            break;
         }
      }
      Object variableValue = getProperty(variable, propertyName);

      if (log.isDebugEnabled()) {
         log.debug("propertyName: {}", propertyName);
         log.debug("propertyPath: {}", propertyPath);
         log.debug("variableValue: {}", variableValue);
      }

      if (propertyPath != null) {
         if (variableValue.getClass().equals(String.class)) {
            if (propertyPath.startsWith("/")) {
               // This is a JSON Pointer or XPath expression to apply.
               String variableString = String.valueOf(variableValue);

               if (variableString.trim().startsWith("{") || variableString.trim().startsWith("[")) {
                  variableValue = getJsonPointerValue(variableString, propertyPath);
               } else if (variableString.trim().startsWith("<")) {
                  variableValue = getXPathValue(variableString, propertyPath);
               } else {
                  log.warn("Got a path query expression but content seems not to be JSON nor XML...");
                  variableValue = null;
               }
            }
         } else if (variableValue.getClass().isArray()) {
            if (propertyPath.matches(ARRAY_INDEX_REGEXP)) {
               Matcher m = ARRAY_INDEX_PATTERN.matcher(propertyPath);
               if (m.matches()) {
                  String arrayIndex = m.group(1);
                  Object[] variableValues = (Object[]) variableValue;
                  try {
                     variableValue = variableValues[Integer.parseInt(arrayIndex)];
                  } catch (ArrayIndexOutOfBoundsException ae) {
                     log.warn("Expression asked for " + arrayIndex + " but array is smaller (" + variableValues.length
                           + "). Returning null.");
                     variableValue = null;
                  }
               }
            }
         } else if (Map.class.isAssignableFrom(variableValue.getClass())) {
            if (propertyPath.matches(MAP_INDEX_REGEXP)) {
               Matcher m = MAP_INDEX_PATTERN.matcher(propertyPath);
               if (m.matches()) {
                  String mapKey = m.group(1);
                  Map variableValues = (Map) variableValue;
                  variableValue = variableValues.get(mapKey);
               }
            }
         }
      }

      return String.valueOf(variableValue);
   }

   /**
    * Fetch a property from an object. For example of you wanted to get the foo property on a bar object you would
    * normally call {@code bar.getFoo()}.
    * @param obj      The object whose property you want to fetch
    * @param property The property name
    * @return The value of the property or null if it does not exist.
    */
   private static Object getProperty(Object obj, String property) {
      Object result = null;

      try {
         String methodName = "get" + property.substring(0, 1).toUpperCase() + property.substring(1);
         Class<?> clazz = obj.getClass();
         Method method = clazz.getMethod(methodName);
         result = method.invoke(obj);
      } catch (Exception e) {
         // Do nothing, we'll return the default value
         log.warn(property + " property was requested on " + obj.getClass() + " but cannot find a valid getter", e);
      }
      return result;
   }

   /** Extract a value from JSON using a JSON Pointer expression. */
   private static String getJsonPointerValue(String jsonText, String jsonPointerExp) {
      // Parse json text ang get root node.
      JsonNode rootNode;
      try {
         ObjectMapper mapper = new ObjectMapper();
         rootNode = mapper.readTree(new StringReader(jsonText));
         // Retrieve evaluated node within JSON tree.
         JsonNode evaluatedNode = rootNode.at(jsonPointerExp);
         // Return serialized array if array type node is referenced by JsonPointer, text value otherwise
         return evaluatedNode.isArray() || evaluatedNode.isObject() ? mapper.writeValueAsString(evaluatedNode)
               : evaluatedNode.asText();
      } catch (Exception e) {
         log.warn("Exception while parsing Json text", e);
         return null;
      }
   }

   /** Extract a value from XML using a XPath expression. */
   private static String getXPathValue(String xmlText, String xPathExp) {
      XPath xpath = XPathFactory.newInstance().newXPath();
      try {
         XPathExpression expression = xpath.compile(xPathExp);
         return expression.evaluate(new InputSource(new StringReader(xmlText)));
      } catch (XPathExpressionException e) {
         log.warn("Exception while compiling/evaluating XPath", e);
         return null;
      }
   }
}

public class HttpHeadersStringToStringsMap extends StringToStringsMap {

   public HttpHeadersStringToStringsMap() {
   }

   /**
    * Override of HashMap get() to implement case-insensitive search of key.
    * @param key The Http header name (case-insensitive)
    * @return The value as List of String if nay, or null
    */
   @Override
   public List<String> get(Object key) {
      Iterator<Map.Entry<String, List<String>>> var3 = this.entrySet().iterator();

      Map.Entry<String, List<String>> stringListEntry;
      do {
         if (!var3.hasNext()) {
            return null;
         }

         stringListEntry = var3.next();
      } while (!key.toString().equalsIgnoreCase(stringListEntry.getKey()) || (stringListEntry.getValue()).isEmpty());

      return stringListEntry.getValue();
   }

   /**
    * Override of HashMap getOrDefault() to implement case-insensitive search of key.
    * @param key          The Http header name (case-insensitive)
    * @param defaultValue The default mapping of the key
    * @return The value as List of String if nay, or null
    */
   @Override
   public List<String> getOrDefault(Object key, List<String> defaultValue) {
      List<String> value;
      return (value = this.get(key)) == null ? defaultValue : value;
   }


   public boolean hasValues(String key) {
      return this.containsKeyIgnoreCase(key) && ((List) this.get(key)).size() > 0;
   }

   public void add(String key, String string) {
      List<String> updatedValue = this.getOrDefault(key, new ArrayList<String>());
      updatedValue.add(string);
      this.put(key, updatedValue);
   }

   public String get(String key, String defaultValue) {
      return getCaseInsensitive(key, defaultValue);
   }
}

public class AsyncAPICommons {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(AsyncAPICommons.class);

   public static final String MESSAGES = "messages";
   public static final String BINDINGS = "bindings";

   public static final String SCHEMA_NODE = "schema";
   public static final String CHANNEL_NODE = "channel";
   public static final String ADDRESS_NODE = "address";
   public static final String PARAMETERS_NODE = "parameters";
   public static final String LOCATION_NODE = "location";
   public static final String EXAMPLES_NODE = "examples";
   public static final String EXAMPLE_VALUE_NODE = "value";
   public static final String EXAMPLE_PAYLOAD_NODE = "payload";
   public static final String EXAMPLE_HEADERS_NODE = "headers";
   public static final String QUEUE_VALUE = "queue";
   public static final String TOPIC_VALUE = "topic";

   private AsyncAPICommons() {
      // Private constructor to hide the implicit one as it's a utility class.
   }

   /**
    * Browse and complete an operation bindings with the bindings information at Channel level.
    * @param operation The operation whose bindings should be completed
    * @param bindings  The Channel level bindings node
    */
   public static void completeChannelLevelBindings(Operation operation, JsonNode bindings) {
      Iterator<String> bindingNames = bindings.fieldNames();
      while (bindingNames.hasNext()) {
         String bindingName = bindingNames.next();
         JsonNode bindingNode = bindings.path(bindingName);

         switch (bindingName) {
            case "ws":
               Binding b = retrieveOrInitOperationBinding(operation, BindingType.WS);
               b.setMethod(bindingNode.path("method").asText(null));
               break;
            case "amqp":
               b = retrieveOrInitOperationBinding(operation, BindingType.AMQP);
               if (bindingNode.has("is")) {
                  String is = bindingNode.path("is").asText();
                  if (QUEUE_VALUE.equals(is)) {
                     b.setDestinationType(QUEUE_VALUE);
                     JsonNode queue = bindingNode.get(QUEUE_VALUE);
                     b.setDestinationName(queue.get("name").asText());
                  } else if ("routingKey".equals(is)) {
                     JsonNode exchange = bindingNode.get("exchange");
                     b.setDestinationType(exchange.get("type").asText());
                  }
               }
               break;
            case "googlepubsub":
               b = retrieveOrInitOperationBinding(operation, BindingType.GOOGLEPUBSUB);
               b.setDestinationName(bindingNode.path(TOPIC_VALUE).asText(null));
               b.setPersistent(bindingNode.path("messageRetentionDuration").asBoolean(false));
               break;
            default:
               break;
         }
      }
   }

   /**
    * Browse and complete an operation bindings with the bindings information at Operation level.
    * @param operation The operation whose bindings should be completed
    * @param bindings  The Operation level bindings node
    */
   public static void completeOperationLevelBindings(Operation operation, JsonNode bindings) {
      Iterator<String> bindingNames = bindings.fieldNames();
      while (bindingNames.hasNext()) {
         String bindingName = bindingNames.next();
         JsonNode bindingNode = bindings.path(bindingName);

         switch (bindingName) {
            case "kafka":
               break;
            case "mqtt":
               Binding b = retrieveOrInitOperationBinding(operation, BindingType.MQTT);
               b.setQoS(bindingNode.path("qos").asText(null));
               b.setPersistent(bindingNode.path("retain").asBoolean(false));
               break;
            case "amqp1":
               b = retrieveOrInitOperationBinding(operation, BindingType.AMQP1);
               b.setDestinationName(bindingNode.path("destinationName").asText(null));
               b.setDestinationType(bindingNode.path("destinationType").asText(null));
               break;
            case "nats":
               b = retrieveOrInitOperationBinding(operation, BindingType.NATS);
               b.setDestinationName(bindingNode.path(QUEUE_VALUE).asText(null));
               break;
            case "sqs":
               b = retrieveOrInitOperationBinding(operation, BindingType.SQS);
               if (bindingNode.has(QUEUE_VALUE)) {
                  b.setDestinationName(bindingNode.get(QUEUE_VALUE).path("name").asText(null));
                  b.setPersistent(bindingNode.path("messageRetentionPeriod").asBoolean(false));
               }
               break;
            case "sns":
               b = retrieveOrInitOperationBinding(operation, BindingType.SNS);
               if (bindingNode.has(TOPIC_VALUE) && bindingNode.get(TOPIC_VALUE).has("name")) {
                  b.setDestinationName(bindingNode.get(TOPIC_VALUE).path("name").asText(null));
               }
               break;
            default:
               break;
         }
      }
   }

   /**
    * Browse and complete an operation bindings with the bindings information at Message level.
    * @param operation The operation whose bindings should be completed
    * @param bindings  The Message level bindings node
    */
   public static void completeMessageLevelBindings(Operation operation, JsonNode bindings) {
      Iterator<String> bindingNames = bindings.fieldNames();
      while (bindingNames.hasNext()) {
         String bindingName = bindingNames.next();
         JsonNode bindingNode = bindings.path(bindingName);

         switch (bindingName) {
            case "kafka":
               Binding b = retrieveOrInitOperationBinding(operation, BindingType.KAFKA);
               if (bindingNode.has("key")) {
                  b.setKeyType(bindingNode.path("key").path("type").asText());
               }
               break;
            default:
               break;
         }
      }
   }

   /** Check variables parts presence into given channel address. */
   public static boolean channelAddressHasParts(String address) {
      return (address.indexOf("{") != -1);
   }

   /** Extract the list of Header from an example node. */
   public static List<Header> getExampleHeaders(JsonNode example) {
      List<Header> results = new ArrayList<>();

      if (example.has(EXAMPLE_HEADERS_NODE)) {
         Iterator<Map.Entry<String, JsonNode>> headers = null;

         if (example.path(EXAMPLE_HEADERS_NODE).isObject()) {
            headers = example.path(EXAMPLE_HEADERS_NODE).fields();
         } else if (example.path(EXAMPLE_HEADERS_NODE).isTextual()) {
            // Try to parse string as a JSON Object...
            try {
               ObjectMapper mapper = new ObjectMapper();
               JsonNode headersNode = mapper.readTree(example.path(EXAMPLE_HEADERS_NODE).asText());
               headers = headersNode.fields();
            } catch (Exception e) {
               log.warn("Headers value {} is a string but not JSON, skipping it",
                     example.path(EXAMPLE_HEADERS_NODE).asText());
            }
         }

         if (headers != null) {
            while (headers.hasNext()) {
               Map.Entry<String, JsonNode> property = headers.next();

               Header header = new Header();
               header.setName(property.getKey());
               // Values may be multiple and CSV.
               Set<String> headerValues = Arrays.stream(property.getValue().asText().split(",")).map(String::trim)
                     .collect(Collectors.toSet());
               header.setValues(headerValues);
               results.add(header);
            }
         }
      }
      return results;
   }

   /** Get existing operation binding type or initialize a new one. */
   private static Binding retrieveOrInitOperationBinding(Operation operation, BindingType type) {
      Binding binding = null;
      if (operation.getBindings() != null) {
         binding = operation.getBindings().get(type.toString());
      }
      if (binding == null) {
         binding = new Binding(type);
         operation.addBinding(type.toString(), binding);
      }
      return binding;
   }
}

public abstract class AbstractJsonRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(AbstractJsonRepositoryImporter.class);

   protected Boolean isYaml;
   protected JsonNode rootSpecification;
   protected String rootSpecificationContent;
   protected ReferenceResolver referenceResolver;
   protected List<Resource> externalResources = new ArrayList<>();
   protected Map<Resource, JsonNode> externalResourcesContent = new HashMap<>();

   /**
    * Build a new importer using the path of specification file and an optional reference resolver.
    * @param specificationFilePath The path to local JSON spec file
    * @param referenceResolver     An optional resolver for references present into the OpenAPI file
    * @throws IOException if JSON spec file cannot be found or read.
    */
   protected AbstractJsonRepositoryImporter(String specificationFilePath, ReferenceResolver referenceResolver)
         throws IOException {
      this.referenceResolver = referenceResolver;
      BufferedReader reader = null;
      try {
         // Analyse first lines of file content to guess repository type.
         String line = null;
         int lineNumber = 0;
         reader = Files.newBufferedReader(new File(specificationFilePath).toPath(), StandardCharsets.UTF_8);
         while ((line = reader.readLine()) != null && isYaml == null) {
            line = line.trim();
            // Only treat as JSON if the very first line starts with { or [
            if (lineNumber == 0 && (line.startsWith("{") || line.startsWith("["))) {
               isYaml = false;
            } else if (line.startsWith("---") || line.startsWith("-") || line.startsWith("openapi: ")
                  || line.startsWith("asyncapi: ")) {
               isYaml = true;
            }
            lineNumber++;
         }

         // Read spec bytes.
         byte[] bytes = Files.readAllBytes(Paths.get(specificationFilePath));
         rootSpecificationContent = new String(bytes, StandardCharsets.UTF_8);

         // Convert them to Node using Jackson object mapper.
         ObjectMapper mapper = getObjectMapper(isYaml);
         rootSpecification = mapper.readTree(rootSpecificationContent.getBytes(StandardCharsets.UTF_8));
      } catch (Exception e) {
         log.error("Exception while parsing JSON specification file " + specificationFilePath, e);
         throw new IOException("JSON spec file parsing error");
      } finally {
         if (reader != null) {
            reader.close();
         }
      }
   }

   /**
    * Given a service, initialize all external references that may be found via `$ref` nodes pointing to absolute or
    * relative pointers. This has the side effect to initialize the `externalResources` member.
    * @param service The main service for naming discovered resources.
    */
   protected void initializeReferencedResources(Service service) throws MockRepositoryImportException {
      if (referenceResolver != null) {
         String rootBaseUrl = referenceResolver.getBaseRepositoryUrl();

         // Keep track and collect reference resources, using absolute URL as key.
         Map<String, Resource> referenceResources = new HashMap<>();

         // We need to create a temporary root resource to initiate the recursive resolution.
         Resource rootResource = new Resource();
         rootResource.setName(service.getName() + "-" + service.getVersion());
         rootResource.setContent(rootSpecificationContent);
         referenceResources.put(rootBaseUrl, rootResource);

         // Seek, resolve and build reference resources.
         resolveExternalReferences(service, referenceResources, rootBaseUrl, "", rootSpecification);

         // Secondly: update root specification content with new reference names and
         // Refresh the root specification node with re-normalized references.
         rootSpecificationContent = rootResource.getContent();
         try {
            ObjectMapper mapper = getObjectMapper(isYaml);
            rootSpecification = mapper.readTree(rootSpecificationContent.getBytes(StandardCharsets.UTF_8));
         } catch (Exception e) {
            log.error("Exception while parsing re-normalized JSON specification file", e);
            throw new MockRepositoryImportException("Exception while parsing re-normalized JSON specification file");
         }

         // Finally try to clean up resolved references and associated resources (files)
         referenceResolver.cleanResolvedReferences();
      }
   }

   /**
    * Recursive method for browsing resource spec, finding $ref, downloading content and accumulating result in
    * referenceResources.
    */
   private void resolveExternalReferences(Service service, Map<String, Resource> referenceResources,
         String baseRepositoryUrl, String baseContext, JsonNode resourceSpecification) {
      Set<String> references = findAllExternalRefs(resourceSpecification);
      Resource currentResource = referenceResources.get(baseRepositoryUrl);

      for (String ref : references) {
         referenceResolver.setBaseRepositoryUrl(baseRepositoryUrl);
         String refUrl = referenceResolver.getReferenceURL(ref);

         Resource referenceResource = referenceResources.get(refUrl);
         if (referenceResource == null) {
            try {
               // Extract content using resolver.
               String content = referenceResolver.getReferenceContent(ref, StandardCharsets.UTF_8);

               // Build resource name from short name.
               String resourceName = ref.substring(ref.lastIndexOf('/') + 1);
               String referencePath = ref.contains("/") ? ref.substring(0, ref.lastIndexOf('/')) : ".";
               // Introduce a context tracker if it's a relative dependency.
               String referenceContext = buildContext(baseContext, referencePath);
               if (!ref.startsWith("http")) {
                  resourceName = IdBuilder.buildResourceFullName(service, resourceName, referenceContext);
               } else {
                  resourceName = IdBuilder.buildResourceFullName(service, resourceName);
               }

               // Build a new resource from content. Use the escaped operation path.
               referenceResource = new Resource();
               referenceResource.setName(resourceName);
               referenceResource.setPath(ref);
               referenceResource.setContent(content);
               referenceResource.setType(guessResourceType(ref, content));

               // Keep track of this newly created resource.
               referenceResources.put(refUrl, referenceResource);
               externalResources.add(referenceResource);

               // Now go down the resource content and resolve its embedded references.
               // Also update the references bases to track the root url for this ref in order
               ObjectMapper mapper = getObjectMapper(!ref.endsWith(".json"));
               JsonNode refResourceSpecification = mapper.readTree(content);
               resolveExternalReferences(service, referenceResources, refUrl, referenceContext,
                     refResourceSpecification);
            } catch (IOException ioe) {
               log.error("IOException while trying to resolve reference {}", ref, ioe);
               log.info("Ignoring the reference {} cause it could not be resolved", ref);
            }
         }

         if (!ref.startsWith("http") && referenceResource != null) {
            // If a relative resource, replace with new name in resource content.
            String refNewName = referenceResources.get(refUrl).getName();
            String normalizedContent = currentResource.getContent().replace(ref,
                  URLEncoder.encode(refNewName, StandardCharsets.UTF_8));
            currentResource.setContent(normalizedContent);
         }
      }
   }

   /**
    * Build a context for resource name in order to avoid name collisions (resource having same short name in different
    * folders.
    */
   private String buildContext(String baseContext, String referencePath) {
      // Treat the obvious "." case.
      if (".".equals(referencePath)) {
         return baseContext;
      }
      // Else recompose a path to append.
      String pathToAppend = referencePath;
      while (pathToAppend.startsWith("../")) {
         if (baseContext.contains("/")) {
            baseContext = baseContext.substring(0, baseContext.lastIndexOf("/"));
         }
         pathToAppend = pathToAppend.substring(3);
      }
      if (pathToAppend.startsWith("./")) {
         pathToAppend = pathToAppend.substring(2);
      }
      if (pathToAppend.startsWith("/")) {
         pathToAppend = pathToAppend.substring(1);
      }
      String result = baseContext + "/" + pathToAppend;
      return result.startsWith("/") ? result.substring(1) : result;
   }

   /** Follow the $ref if we have one. Otherwise, return given node. */
   protected JsonNode followRefIfAny(JsonNode referencableNode) {
      if (referencableNode.has("$ref")) {
         String ref = referencableNode.path("$ref").asText();
         return getNodeForRef(ref);
      }
      return referencableNode;
   }

   /** Get the string representation of a node in spec. */
   protected String getValueString(JsonNode valueNode) {
      // Get string representation if array or object.
      if (valueNode.getNodeType() == JsonNodeType.ARRAY || valueNode.getNodeType() == JsonNodeType.OBJECT) {
         return valueNode.toString();
      }
      // Else get raw representation.
      return valueNode.asText();
   }

   /** Get appropriate Yaml or Json object mapper. */
   protected ObjectMapper getObjectMapper(boolean isYaml) {
      return isYaml ? ObjectMapperFactory.getYamlObjectMapper() : ObjectMapperFactory.getJsonObjectMapper();
   }

   /** Browse Json node to extract references and store them into externalRefs. */
   private Set<String> findAllExternalRefs(JsonNode node) {
      Set<String> externalRefs = new HashSet<>();
      // If node has a $ref child, it's a stop condition.
      if (node.has("$ref")) {
         String ref = node.path("$ref").asText();
         if (!ref.startsWith("#")) {
            // Our ref could be used for examples and be something like './weather-examples.json#/0'.
            String filePath = ref;
            if (ref.contains("#/")) {
               filePath = ref.substring(0, ref.indexOf("#/"));
            }
            externalRefs.add(filePath);
         }
      } else {
         // Iterate on all other children.
         Iterator<JsonNode> children = node.elements();
         while (children.hasNext()) {
            externalRefs.addAll(findAllExternalRefs(children.next()));
         }
      }
      return externalRefs;
   }

   /** Get the JsonNode for reference within the specification. */
   private JsonNode getNodeForRef(String reference) {
      if (reference.startsWith("#/")) {
         return rootSpecification.at(reference.substring(1));
      }
      return getNodeForExternalRef(reference);
   }

   /** Get the JsonNode for reference that is localed in external resource. */
   private JsonNode getNodeForExternalRef(String externalReference) {
      String path = externalReference;

      // We may have a Json pointer to a specific place in external reference.
      String pointerInFile = null;
      if (externalReference.indexOf("#/") != -1) {
         path = externalReference.substring(0, externalReference.indexOf("#/"));
         pointerInFile = externalReference.substring(externalReference.indexOf("#/"));
      }

      for (Resource resource : externalResources) {
         // Path direct equality is for absolute ref ("http://raw.githubusercontent.com/...")
         // Path equality with resource name if for relative refs that have been re-normalized ("Service name+Service version+...))
         if (path.equals(resource.getPath())
               || path.equals(URLEncoder.encode(resource.getName(), StandardCharsets.UTF_8))) {
            JsonNode resourceNode = externalResourcesContent.computeIfAbsent(resource, k -> {
               try {
                  return ObjectMapperFactory.getYamlObjectMapper().readTree(resource.getContent());
               } catch (JsonProcessingException e) {
                  throw new JsonRepositoryParsingException("Get a JSON processing exception on " + externalReference,
                        e);
               }
            });
            if (pointerInFile != null) {
               return resourceNode.at(pointerInFile.substring(1));
            }
            return resourceNode;
         }
      }
      log.warn("Found no resource for reference {}", externalReference);
      return null;
   }

   /** Try to guess resource type from a reference name and its content. */
   private ResourceType guessResourceType(String ref, String content) {
      if (ref.endsWith(".avsc")) {
         return ResourceType.AVRO_SCHEMA;
      } else if (ref.endsWith(".proto")) {
         return ResourceType.PROTOBUF_SCHEMA;
      } else if (content.contains("$schema") || content.contains("properties:")
            || content.contains("\"properties\":")) {
         return ResourceType.JSON_SCHEMA;
      }
      return ResourceType.JSON_FRAGMENT;
   }

   /** Custom runtime exception for Json repository parsing errors. */
   public class JsonRepositoryParsingException extends RuntimeException {
      public JsonRepositoryParsingException(String message) {
         super(message);
      }

      public JsonRepositoryParsingException(String message, Throwable cause) {
         super(message, cause);
      }
   }
}

