public class MockRepositoryImporterFactory {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(MockRepositoryImporterFactory.class);

   /** A RegExp for detecting a line containing the openapi: 3 pragma. */
   public static final String OPENAPI_3_REGEXP = ".*['\\\"]?openapi['\\\"]?\\s*:\\s*['\\\"]?[3\\.].*";

   /** A RegExp for detecting a line containing the asyncapi: 2 pragma. */
   public static final String ASYNCAPI_2_REGEXP = ".*['\\\"]?asyncapi['\\\"]?\\s*:\\s*['\\\"]?[2\\.].*";

   /** A RegExp for detecting a line containing the asyncapi: 3 pragma. */
   public static final String ASYNCAPI_3_REGEXP = ".*['\\\"]?asyncapi['\\\"]?\\s*:\\s*['\\\"]?[3\\.].*";

   /** A RegExp for detecting a line containing the swagger pragma. */
   public static final String SWAGGER_REGEXP = ".*['\\\"]?swagger['\\\"]?\\s*:\\s*.*";

   private MockRepositoryImporterFactory() {
      // Private constructor to hide the implicit one as it's a utility class.
   }

   /**
    * Create the right MockRepositoryImporter implementation depending on repository type.
    * @param mockRepository    The file representing the repository type
    * @param referenceResolver The Resolver to be used during import (may be null).
    * @return An instance of MockRepositoryImporter implementation
    * @throws IOException in case of file access
    */
   public static MockRepositoryImporter getMockRepositoryImporter(File mockRepository,
         ReferenceResolver referenceResolver) throws IOException {
      MockRepositoryImporter importer = null;

      // Analyse first lines of file content to guess repository type.
      String line = null;
      try (BufferedReader reader = Files.newBufferedReader(mockRepository.toPath(), StandardCharsets.UTF_8)) {
         while ((line = reader.readLine()) != null && importer == null) {
            line = line.trim();
            // Check with basic Postman formats..
            importer = checkPostmanImporters(line, mockRepository);
            // Then try OpenAPI related ones...
            if (importer == null) {
               importer = checkOpenAPIImporters(line, mockRepository, referenceResolver);
            }
            // Then try any other else.
            if (importer == null) {
               importer = checkOtherImporters(line, mockRepository, referenceResolver);
            }
         }
      }

      // Otherwise, default to HAR project importer implementation because it has no proper identity marker.
      if (importer == null) {
         log.info("Have not found any explicit marker so applying the default HTTP Archive (HAR) importer...");
         importer = new HARImporter(mockRepository.getPath());
      }

      return importer;
   }

   private static MockRepositoryImporter checkPostmanImporters(String line, File mockRepository) throws IOException {
      if (line.startsWith("\"_postman_id\":")) {
         log.info("Found a _postman_id in file so assuming it's a Postman Collection to import");
         return new PostmanCollectionImporter(mockRepository.getPath());
      } else if (line.startsWith("\"collection\":") || line.startsWith("{\"collection\":")) {
         log.info("Found a collection in file so assuming it's a Postman Workspace Collection to import");
         return new PostmanWorkspaceCollectionImporter(mockRepository.getPath());
      }
      return null;
   }

   private static MockRepositoryImporter checkOpenAPIImporters(String line, File mockRepository,
         ReferenceResolver referenceResolver) throws IOException {
      if (line.matches(OPENAPI_3_REGEXP)) {
         log.info("Found an openapi: 3 pragma in file so assuming it's an OpenAPI spec to import");
         return new OpenAPIImporter(mockRepository.getPath(), referenceResolver);
      } else if (line.matches(SWAGGER_REGEXP)) {
         log.info("Found an swagger: pragma in file so assuming it's a Swagger spec to import");
         return new SwaggerImporter(mockRepository.getPath(), referenceResolver);
      }
      return null;
   }

   private static MockRepositoryImporter checkOtherImporters(String line, File mockRepository,
         ReferenceResolver referenceResolver) throws IOException {
      if (line.startsWith("<?xml")) {
         log.info("Found a XML pragma in file so assuming it's a SoapUI Project to import");
         return new SoapUIProjectImporter(mockRepository.getPath());
      } else if (line.matches(ASYNCAPI_2_REGEXP)) {
         log.info("Found an asyncapi: 2 pragma in file so assuming it's an AsyncAPI spec to import");
         return new AsyncAPIImporter(mockRepository.getPath(), referenceResolver);
      } else if (line.matches(ASYNCAPI_3_REGEXP)) {
         log.info("Found an asyncapi: 3 pragma in file so assuming it's an AsyncAPI spec to import");
         return new AsyncAPI3Importer(mockRepository.getPath(), referenceResolver);
      } else if (line.startsWith("syntax = \"proto3\";") || line.startsWith("syntax=\"proto3\";")) {
         log.info("Found a syntax = proto3 pragma in file so assuming it's a GRPC Protobuf spec to import");
         return new ProtobufImporter(mockRepository.getPath(), referenceResolver);
      } else if (line.contains("kind: APIMetadata")) {
         log.info("Found a kind: APIMetadata pragma in file so assuming it's a Microcks APIMetadata to import");
         return new MetadataImporter(mockRepository.getPath());
      } else if (line.contains("kind: APIExamples")) {
         log.info("Found a kind: APIExamples pragma in file so assuming it's a Microcks APIExamples to import");
         return new ExamplesImporter(mockRepository.getPath());
      } else if (line.contains("type Query {") || line.contains("type Mutation {")
            || line.startsWith("# microcksId:")) {
         log.info("Found query, mutation or microcksId: pragma in file so assuming it's a GraphQL schema to import");
         return new GraphQLImporter(mockRepository.getPath());
      }
      return null;
   }
}

public class ReferenceResolver {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(ReferenceResolver.class);

   private String baseRepositoryUrl;
   private final Secret repositorySecret;
   private final boolean disableSSLValidation;
   private boolean cleanResolvedFiles = true;

   private RelativeReferenceURLBuilder urlBuilder;

   private Map<String, File> resolvedReferences = new HashMap<>();
   private Map<String, File> relativeResolvedReferences = new HashMap<>();

   /**
    * Build a new reference resolver.
    * @param baseRepositoryUrl    The root folder representing a remote repository we want to resolved references to
    * @param repositorySecret     An optional Secret containing connection credentials to the repository
    * @param disableSSLValidation Whether to disable or enable the SSL trusting of certificates
    */
   public ReferenceResolver(String baseRepositoryUrl, Secret repositorySecret, boolean disableSSLValidation) {
      this.setBaseRepositoryUrl(baseRepositoryUrl);
      this.repositorySecret = repositorySecret;
      this.disableSSLValidation = disableSSLValidation;
      this.urlBuilder = new SimpleReferenceURLBuilder();
   }

   /**
    * Build a new reference resolver.
    * @param baseRepositoryUrl    The root folder representing a remote repository we want to resolved references to
    * @param repositorySecret     An optional Secret containing connection credentials to the repository
    * @param disableSSLValidation Whether to disable or enable the SSL trusting of certificates
    */
   public ReferenceResolver(String baseRepositoryUrl, Secret repositorySecret, boolean disableSSLValidation,
         RelativeReferenceURLBuilder urlBuilder) {
      this.setBaseRepositoryUrl(baseRepositoryUrl);
      this.repositorySecret = repositorySecret;
      this.disableSSLValidation = disableSSLValidation;
      this.urlBuilder = urlBuilder;
   }

   /** @return the current base repository url. */
   public String getBaseRepositoryUrl() {
      return baseRepositoryUrl;
   }

   /**
    * Update the base repository url to use as root for relative reference resolution.
    * @param baseRepositoryUrl The new base repository url.
    */
   public void setBaseRepositoryUrl(String baseRepositoryUrl) {
      // Remove trailing / to ease things later.
      if (baseRepositoryUrl.endsWith("/")) {
         this.baseRepositoryUrl = baseRepositoryUrl.substring(0, baseRepositoryUrl.length() - 1);
      } else {
         this.baseRepositoryUrl = baseRepositoryUrl;
      }
   }

   /**
    * Check if resolved files should be cleaned up after usage. Default behavior is true.
    * @return The current value for this flag.
    */
   public boolean isCleanResolvedFiles() {
      return cleanResolvedFiles;
   }

   /**
    * Set if resolved files should be cleaned up after usage. If set to false, resolvedReferences map will be clear but
    * files will not be deleted from the local filesystem.
    * @param cleanResolvedFiles The new value for this flag.
    */
   public void setCleanResolvedFiles(boolean cleanResolvedFiles) {
      this.cleanResolvedFiles = cleanResolvedFiles;
   }

   /**
    * Get the full URL corresponding to a reference relative path
    * @param referenceRelativePath The reference relative path to resolve
    * @return The absolute URL if a relative path, the orginal path/URL otherwise.
    */
   public String getReferenceURL(String referenceRelativePath) {
      String remoteUrl = referenceRelativePath;
      if (!referenceRelativePath.startsWith("http")) {
         remoteUrl = urlBuilder.buildRemoteURL(this.baseRepositoryUrl, referenceRelativePath);
      }
      return remoteUrl;
   }

   /**
    * Retrieve a reference content from remote repository using its relative path?
    * @param relativePath The relative path of the reference to retrieve
    * @param encoding     The encoding to use for building a string representation of content.
    * @return A string representation of reference content.
    * @throws IOException if access to remote reference fails (not found or connection issues)
    */
   public String getReferenceContent(String relativePath, Charset encoding) throws IOException {
      // Check the file first.
      String remoteUrl = getReferenceURL(relativePath);
      File referenceFile = resolvedReferences.get(remoteUrl);
      if (referenceFile == null) {
         log.info("Downloading a reference file at {}", remoteUrl);

         if (remoteUrl.startsWith("http")) {
            // We have a remote URL, let's download it.
            referenceFile = HTTPDownloader.handleHTTPDownloadToFile(remoteUrl, repositorySecret, disableSSLValidation);
         } else {
            // We have a local file, let's just use it.
            if (remoteUrl.startsWith("file://")) {
               remoteUrl = remoteUrl.substring("file://".length());
            }
            log.debug("Reading local file {}", remoteUrl);
            referenceFile = new File(remoteUrl);
         }
         // Store this relative reference into the cache.
         resolvedReferences.put(remoteUrl, referenceFile);
      }
      // Keep track on how we resolved this relativePath.
      relativeResolvedReferences.put(relativePath, referenceFile);

      return Files.readString(referenceFile.toPath(), encoding);
   }

   /**
    * Get resolved references map.
    * @return The map of resolved references with keys being absolute paths.
    */
   public Map<String, File> getResolvedReferences() {
      return resolvedReferences;
   }

   /**
    * Get relative resolved references map.
    * @return The map of resolved references with keys being relative paths.
    */
   public Map<String, File> getRelativeResolvedReferences() {
      return relativeResolvedReferences;
   }

   /** Cleans up already resolved references. */
   public void cleanResolvedReferences() {
      if (cleanResolvedFiles) {
         for (File referenceFile : resolvedReferences.values()) {
            referenceFile.delete();
         }
      }
      resolvedReferences.clear();
      relativeResolvedReferences.clear();
   }
}

public interface RelativeReferenceURLBuilder {

   /**
    * Returns the name of the file denoted by <code>baseRepositoryUrl</code>. Addiotional headers (like download
    * headers) can be optionally provided.
    * @param baseRepositoryURL The URL in repository of the file to get name for
    * @param headers           The optional additional file properties or headers
    * @return The name of this file
    */
   String getFileName(String baseRepositoryURL, Map<String, List<String>> headers);

   /**
    * Build a suitable download URL for a reference found into a base file.
    * @param baseRepositoryURL The URL in repository of the file that serves as base file
    * @param referencePath     A path like <code>my-file.yaml</code> or <code>../my-file.yaml</code> to get reference
    *                          from base
    * @return The URL to download reference from
    */
   String buildRemoteURL(String baseRepositoryURL, String referencePath);
}

public class RelativeReferenceURLBuilderFactory {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(RelativeReferenceURLBuilderFactory.class);

   /**
    * Create the right RelativeReferenceURLBuilder implementation depending on the base file properties.
    * @param baseFileProperties A map of properties (most of the time headers-like structure)
    * @return A RelativeReferenceURLBuilder that could be used to build URL for relative references in this base file.
    */
   public static RelativeReferenceURLBuilder getRelativeReferenceURLBuilder(
         Map<String, List<String>> baseFileProperties) {
      if (baseFileProperties != null) {
         if (baseFileProperties.containsKey(GitLabReferenceURLBuilder.GITLAB_FILE_NAME_HEADER)
               || baseFileProperties.containsKey(GitLabReferenceURLBuilder.GITLAB_FILE_NAME_HEADER.toLowerCase())) {
            log.debug("Found a GitLab File specific header, returning a GitLabReferenceURLBuilder");
            return new GitLabReferenceURLBuilder();
         }
      }
      log.debug("Returning a SimpleReferenceURLBuilder");
      return new SimpleReferenceURLBuilder();
   }
}

public class ResourceUtil {

   /**
    * A simple logger for diagnostic messages.
    */
   private static final Logger log = LoggerFactory.getLogger(ResourceUtil.class);
   private static final String SERVICE_PLACEHOLDER = "{service}";
   private static final String VERSION_PLACEHOLDER = "{version}";
   private static final String RESOURCE_PLACEHOLDER = "{resource}";
   private static final String SCHEMA_PLACEHOLDER = "{resourceSchema}";
   private static final String REFERENCE_PLACEHOLDER = "{reference}";

   private ResourceUtil() {
      // Private constructor to hide implicit public one.
   }

   /**
    * Load a resource from classspath using its path.
    *
    * @param resourcePath The path of resource to load.
    * @return The resource input stream
    * @throws IOException if resource cannot be found or opened
    */
   public static InputStream getClasspathResource(String resourcePath) throws IOException {
      Resource template = new ClassPathResource(resourcePath);
      return template.getInputStream();
   }

   /**
    * Given a resource stream holding placeholder patterns (aka {placeholder}), replace the patterns with actual value
    * coming from Service, an API resource name, an API schema and a reference payload.
    *
    * @param stream           The stream to scan for patterns and substitute in.
    * @param service          The Service corresponding to API
    * @param resource         The API resource
    * @param referenceSchema  An optional reference API schema
    * @param referencePayload An optional reference resource payload
    * @return The stream content with placeholders replaced by actual values.
    */
   public static String replaceTemplatesInSpecStream(InputStream stream, Service service, String resource,
         JsonNode referenceSchema, String referencePayload) {
      BufferedReader reader = new BufferedReader(new InputStreamReader(stream));
      StringWriter writer = new StringWriter();

      try (Stream<String> lines = reader.lines()) {
         lines.map(line -> replaceInLine(line, service, resource, referenceSchema, referencePayload))
               .forEach(line -> writer.write(line + "\n"));
      }
      return writer.toString();
   }

   /**
    * Do the replacement within a given stream line.
    */
   private static String replaceInLine(String line, Service service, String resource, JsonNode referenceSchema,
         String referencePayload) {
      line = line.replace(SERVICE_PLACEHOLDER, service.getName());
      line = line.replace(VERSION_PLACEHOLDER, service.getVersion());
      line = line.replace(RESOURCE_PLACEHOLDER, resource);
      if (line.contains(SCHEMA_PLACEHOLDER)) {
         if (referenceSchema != null) {
            // Serialize reference schema and replace it.
            try {
               ObjectMapper mapper = new ObjectMapper(
                     new YAMLFactory().disable(YAMLGenerator.Feature.WRITE_DOC_START_MARKER)
                           .enable(YAMLGenerator.Feature.MINIMIZE_QUOTES).disable(YAMLGenerator.Feature.INDENT_ARRAYS));
               String schema = mapper.writeValueAsString(referenceSchema);
               // find the indentation level of the schema placeholder
               int indentation = line.indexOf(SCHEMA_PLACEHOLDER);
               // add the indentation to the schema
               schema = schema.replace("\n", "\n" + line.substring(0, indentation));
               // remove the last indentation and the last newline
               schema = schema.substring(0, schema.length() - indentation - 1);
               line = line.replace(SCHEMA_PLACEHOLDER, schema);
            } catch (Exception e) {
               log.warn("Exception while replacing resource schema", e);
            }
         } else {
            // Stick to the default: an empty type definition.
            line = line.replace(SCHEMA_PLACEHOLDER, "");
         }
      }
      if (line.contains(REFERENCE_PLACEHOLDER)) {
         if (referencePayload != null) {
            // Inline Json and escape quotes.
            line = line.replace(REFERENCE_PLACEHOLDER, referencePayload.replace("\n", ""));
         } else {
            // Stick to the default: an empty reference.
            line = line.replace(REFERENCE_PLACEHOLDER, "");
         }
      }
      return line;
   }
}

public class OpenAPISchemaBuilder {

   public static final String JSON_SCHEMA_TYPE = "type";
   public static final String JSON_SCHEMA_ITEMS = "items";
   public static final String JSON_SCHEMA_OBJECT_TYPE = "object";
   public static final String JSON_SCHEMA_ARRAY_TYPE = "array";
   public static final String JSON_SCHEMA_PROPERTIES = "properties";


   private OpenAPISchemaBuilder() {
      // Hide the implicit default constructor.
   }

   /**
    * Build the Json schema for the type corresponding to given Json node provided as string.
    * @param jsonText The String representing Json node to introspect for building a Json schema
    * @return A JsonNode representing the Json Schema fragment for this type
    * @throws IOException Tf given Json string cannot be parsed as Json
    */
   public static JsonNode buildTypeSchemaFromJson(String jsonText) throws IOException {
      return buildTypeSchemaFromJson(JsonSchemaValidator.getJsonNode(jsonText));
   }

   /**
    * Build the Json schema for the type corresponding to given Json node.
    * @param node The Jackson Json node to introspect for building a Json schema
    * @return A JsonNode representing the Json Schema fragment for this type
    */
   public static JsonNode buildTypeSchemaFromJson(JsonNode node) {
      ObjectMapper mapper = new ObjectMapper();
      ObjectNode schemaNode = mapper.createObjectNode();

      traverseNode(node, schemaNode, mapper);
      return schemaNode;
   }

   /** Travers a node and complete its schema from schema parent node. */
   private static void traverseNode(JsonNode currentNode, ObjectNode parentNodeSchemaNode, ObjectMapper mapper) {
      switch (currentNode.getNodeType()) {
         case OBJECT:
            parentNodeSchemaNode.put(JSON_SCHEMA_TYPE, JSON_SCHEMA_OBJECT_TYPE);
            ObjectNode propertiesNodeSchemaNode = parentNodeSchemaNode.putObject(JSON_SCHEMA_PROPERTIES);

            Iterator<Map.Entry<String, JsonNode>> fieldsNodes = currentNode.fields();
            while (fieldsNodes.hasNext()) {
               Map.Entry<String, JsonNode> fieldsNode = fieldsNodes.next();
               ObjectNode fieldNodeSchemaNode = propertiesNodeSchemaNode.putObject(fieldsNode.getKey());
               traverseNode(fieldsNode.getValue(), fieldNodeSchemaNode, mapper);
            }
            break;
         case ARRAY:
            parentNodeSchemaNode.put(JSON_SCHEMA_TYPE, JSON_SCHEMA_ARRAY_TYPE);
            ObjectNode itemsNodeSchemaNode = parentNodeSchemaNode.putObject(JSON_SCHEMA_ITEMS);

            JsonNode firstChild = ((ArrayNode) currentNode).elements().next();
            traverseNode(firstChild, itemsNodeSchemaNode, mapper);
            break;
         default:
            parentNodeSchemaNode.put(JSON_SCHEMA_TYPE, getJsonSchemaScalarType(currentNode.getNodeType()));
      }
   }

   /** Return the actual Json schema type for given scalar type from Jackson internals. */
   private static String getJsonSchemaScalarType(JsonNodeType nodeType) {
      switch (nodeType) {
         case STRING:
            return "string";
         case BOOLEAN:
            return "boolean";
         case NUMBER:
            return "number";
         default:
            return nodeType.toString().toLowerCase();
      }
   }
}

public abstract class Message {

   private String name;
   private String content;
   private String operationId;
   private String testCaseId;
   private String sourceArtifact;

   private Set<Header> headers;

   public String getName() {
      return name;
   }

   public void setName(String name) {
      this.name = name;
   }

   public String getContent() {
      return content;
   }

   public void setContent(String content) {
      this.content = content;
   }

   public String getOperationId() {
      return operationId;
   }

   public void setOperationId(String operationId) {
      this.operationId = operationId;
   }

   public String getTestCaseId() {
      return testCaseId;
   }

   public void setTestCaseId(String testCaseId) {
      this.testCaseId = testCaseId;
   }

   public String getSourceArtifact() {
      return sourceArtifact;
   }

   public void setSourceArtifact(String sourceArtifact) {
      this.sourceArtifact = sourceArtifact;
   }

   public Set<Header> getHeaders() {
      return headers;
   }

   public void setHeaders(Set<Header> headers) {
      this.headers = headers;
   }

   public void addHeader(Header header) {
      if (this.headers == null) {
         this.headers = new HashSet<>();
      }
      headers.add(header);
   }
}

public class EvaluationContext {

   private final Map<String, Object> variables = new ConcurrentHashMap<>();

   /**
    * Put a variable into this context
    * @param name  The name of variable
    * @param value The variable itself
    */
   public void setVariable(String name, Object value) {
      variables.put(name, value);
   }

   /**
    * Put a set of variables into this context
    * @param variables key/value pairs for variables names and their values
    */
   public void setVariables(Map<String, Object> variables) {
      variables.forEach(this::setVariable);
   }

   /**
    * Retrieve a registered variable by its name.
    * @param name The name of variable to look for
    * @return The variable having this name or null if no variable.
    */
   public Object lookupVariable(String name) {
      return variables.get(name);
   }

   /**
    * Register a function using a name and the ELFunction class.
    * @param name     The name of function to register
    * @param function The class representing the function
    * @param <T>      Any implementation of {@code ELFunction} interface
    */
   public <T extends ELFunction> void registerFunction(String name, Class<T> function) {
      this.variables.put(name, function);
   }

   /**
    * Retrieve a registered function by its name.
    * @param name The name of function to look for
    * @param <T>  Any implementation of {@code ELFunction} interface
    * @return The Function class object
    */
   @SuppressWarnings("unchecked")
   public <T extends ELFunction> Class<T> lookupFunction(String name) {
      Object function = variables.get(name);
      if (function instanceof Class functionClazz) {
         if (ELFunction.class.isAssignableFrom(functionClazz)) {
            return (Class<T>) functionClazz;
         }
      }
      return null;
   }
}

