public class McpError extends RuntimeException {

   private McpSchema.JSONRPCResponse.JSONRPCError jsonRpcError;

   /**
    * Constructor for creating a new McpError from a JSONRPCError.
    * @param jsonRpcError The JSONRPCError to create the McpError from.
    */
   public McpError(McpSchema.JSONRPCResponse.JSONRPCError jsonRpcError) {
      super(jsonRpcError.message());
      this.jsonRpcError = jsonRpcError;
   }

   /**
    * Constructor for creating a new McpError from an error object string representation.
    * @param error The error object to create the McpError from.
    */
   public McpError(Object error) {
      super(error.toString());
   }

   /**
    * Get the JSONRPCError associated with this McpError.
    * @return The JSONRPCError associated with this McpError.
    */
   public McpSchema.JSONRPCResponse.JSONRPCError getJsonRpcError() {
      return jsonRpcError;
   }
}

public class McpSchema {

   public static final String LATEST_PROTOCOL_VERSION = "2025-03-26";
   public static final String FIRST_PROTOCOL_VERSION = "2024-11-05";

   public static final String JSONRPC_VERSION = "2.0";

   // ---------------------------
   // Method Names
   // ---------------------------

   // Lifecycle Methods
   public static final String METHOD_INITIALIZE = "initialize";
   public static final String METHOD_NOTIFICATION_INITIALIZED = "notifications/initialized";
   public static final String METHOD_PING = "ping";

   // Tool Methods
   public static final String METHOD_TOOLS_LIST = "tools/list";
   public static final String METHOD_TOOLS_CALL = "tools/call";
   public static final String METHOD_NOTIFICATION_TOOLS_LIST_CHANGED = "notifications/tools/list_changed";

   // Resources Methods
   public static final String METHOD_RESOURCES_LIST = "resources/list";
   public static final String METHOD_RESOURCES_READ = "resources/read";
   public static final String METHOD_NOTIFICATION_RESOURCES_LIST_CHANGED = "notifications/resources/list_changed";
   public static final String METHOD_RESOURCES_TEMPLATES_LIST = "resources/templates/list";
   public static final String METHOD_RESOURCES_SUBSCRIBE = "resources/subscribe";
   public static final String METHOD_RESOURCES_UNSUBSCRIBE = "resources/unsubscribe";

   // Prompt Methods
   public static final String METHOD_PROMPT_LIST = "prompts/list";
   public static final String METHOD_PROMPT_GET = "prompts/get";
   public static final String METHOD_NOTIFICATION_PROMPTS_LIST_CHANGED = "notifications/prompts/list_changed";

   // Logging Methods
   public static final String METHOD_LOGGING_SET_LEVEL = "logging/setLevel";
   public static final String METHOD_NOTIFICATION_MESSAGE = "notifications/message";

   // Roots Methods
   public static final String METHOD_ROOTS_LIST = "roots/list";
   public static final String METHOD_NOTIFICATION_ROOTS_LIST_CHANGED = "notifications/roots/list_changed";

   // Sampling Methods
   public static final String METHOD_SAMPLING_CREATE_MESSAGE = "sampling/createMessage";

   private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();


   // ---------------------------
   // JSON-RPC Error Codes
   // ---------------------------
   /**
    * Standard error codes used in MCP JSON-RPC responses.
    */
   public static final class ErrorCodes {

      /** Invalid JSON was received by the server. */
      public static final int PARSE_ERROR = -32700;

      /** The JSON sent is not a valid Request object. */
      public static final int INVALID_REQUEST = -32600;

      /** The method does not exist / is not available. */
      public static final int METHOD_NOT_FOUND = -32601;

      /** Invalid method parameter(s). */
      public static final int INVALID_PARAMS = -32602;

      /** Internal JSON-RPC error. */
      public static final int INTERNAL_ERROR = -32603;

   }

   /** JSON-RPC Message Types. */
   public sealed interface JSONRPCMessage permits JSONRPCRequest, JSONRPCNotification, JSONRPCResponse {
      String jsonrpc();
   }

   // spotless:off
   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record JSONRPCRequest(
         @JsonProperty("jsonrpc") String jsonrpc,
         @JsonProperty("method") String method,
         @JsonProperty("id") Object id,
         @JsonProperty("params") Object params) implements JSONRPCMessage {
   }

   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record JSONRPCNotification(
         @JsonProperty("jsonrpc") String jsonrpc, @
         JsonProperty("method") String method,
         @JsonProperty("params") Map<String, Object> params) implements JSONRPCMessage {
   }

   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record JSONRPCResponse(
         @JsonProperty("jsonrpc") String jsonrpc,
         @JsonProperty("id") Object id,
         @JsonProperty("result") Object result,
         @JsonProperty("error") JSONRPCError error) implements JSONRPCMessage {

      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      @JsonIgnoreProperties(ignoreUnknown = true)
      public record JSONRPCError(
            @JsonProperty("code") int code,
            @JsonProperty("message") String message,
            @JsonProperty("data") Object data) {
      }
   }
   // spotless:on

   // spotless:off
   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record Implementation(
         @JsonProperty("name") String name,
         @JsonProperty("version") String version) {
   }

   public enum Role {
      @JsonProperty("user") USER,
      @JsonProperty("assistant") ASSISTANT
   }

   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record ClientCapabilities(
         @JsonProperty("experimental") Map<String, Object> experimental,
         @JsonProperty("roots") ClientCapabilities.RootCapabilities roots,
         @JsonProperty("sampling") ClientCapabilities.Sampling sampling) {

      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      @JsonIgnoreProperties(ignoreUnknown = true)
      public record RootCapabilities(
            @JsonProperty("listChanged") Boolean listChanged) {
      }

      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      public record Sampling() {
      }
   }

   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record ServerCapabilities(
         @JsonProperty("experimental") Map<String, Object> experimental,
         @JsonProperty("logging") ServerCapabilities.LoggingCapabilities logging,
         @JsonProperty("prompts") ServerCapabilities.PromptCapabilities prompts,
         @JsonProperty("resources") ServerCapabilities.ResourceCapabilities resources,
         @JsonProperty("tools") ServerCapabilities.ToolCapabilities tools) {


      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      public record LoggingCapabilities() {
      }

      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      public record PromptCapabilities(
            @JsonProperty("listChanged") Boolean listChanged) {
      }

      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      public record ResourceCapabilities(
            @JsonProperty("subscribe") Boolean subscribe,
            @JsonProperty("listChanged") Boolean listChanged) {
      }

      @JsonInclude(JsonInclude.Include.NON_ABSENT)
      public record ToolCapabilities(
            @JsonProperty("listChanged") Boolean listChanged) {
      }
   }

   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record ModelPreferences(
         @JsonProperty("hints") List<ModelHint> hints,
         @JsonProperty("costPriority") Double costPriority,
         @JsonProperty("speedPriority") Double speedPriority,
         @JsonProperty("intelligencePriority") Double intelligencePriority) {
   }

   @JsonInclude(JsonInclude.Include.NON_ABSENT)
   @JsonIgnoreProperties(ignoreUnknown = true)
   public record ModelHint(@JsonProperty("name") String name) {
      public static ModelHint of(String name) {
