public abstract class McpToolConverter {
   protected final Service service;
   protected final Resource resource;

   public McpToolConverter(Service service, Resource resource) {
      this.service = service;
      this.resource = resource;
   }

   /**
    * Extract the name of the tool from the operation.
    * @param operation The operation to extract the name from.
    * @return The tool name
    */
   public String getToolName(Operation operation) {
      return operation.getName();
   }

   /**
    * Extract the description of the tool from the operation.
    * @param operation The operation to extract the description from.
    * @return The tool description
    */
   public abstract String getToolDescription(Operation operation);

   /**
    * Extract the input schema of the tool from the operation.
    * @param operation The operation to extract the input schema from.
    * @return The tool input schema following the 2024-11-05 MCP spec
    */
   public abstract McpSchema.JsonSchema getInputSchema(Operation operation);

   /**
    * Invoke the tool with the given request and return the response in Microcks domain object.
    * @param operation The operation to invoke the tool on.
    * @param request   The request to send to the tool.
    * @param headers   Simple representation of headers transmitted at the protocol level.
    * @return The response from the tool in Microcks domain object.
    */
   public abstract Response getCallResponse(Operation operation, McpSchema.CallToolRequest request,
         Map<String, List<String>> headers);

   /** Prepare the Http headers by sanitizing them. */
   protected Map<String, List<String>> sanitizeHttpHeaders(Map<String, List<String>> headers) {
      return headers.entrySet().stream().filter(entry -> !"content-length".equalsIgnoreCase(entry.getKey()))
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
   }

   /** Depending on result encoding, extract the response content as a string. */
   protected String extractResponseContent(ResponseResult result) throws IOException {
      String responseContent = null;
      if (result.headers() != null) {
         // Response content can be compressed with gzip if we used the proxy.
         List<String> encodings = result.headers().get(HttpHeaders.CONTENT_ENCODING);
         if (encodings != null && encodings.contains("gzip")) {
            // Unzip the response content.
            try (BufferedInputStream bis = new BufferedInputStream(
                  new GZIPInputStream(new ByteArrayInputStream(result.content())))) {
               byte[] uncompressedContent = bis.readAllBytes();
               responseContent = new String(uncompressedContent, StandardCharsets.UTF_8);
            }
         }
      }
      if (responseContent == null) {
         // If no response content here, we can assume it's not compressed and can be read directly.
         responseContent = new String(result.content(), StandardCharsets.UTF_8);
      }
      return responseContent;
   }
}

public class GraphQLMcpToolConverter extends McpToolConverter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(GraphQLMcpToolConverter.class);

   private final GraphQLInvocationProcessor invocationProcessor;
   private final ObjectMapper mapper;

   private Document graphqlDocument;

   /**
    * Build a new instance of GraphQLMcpToolConverter.
    * @param service             The service to which this converter is attached
    * @param resource            The resource used for GraphQL service conversion
    * @param invocationProcessor The invocation processor to use for processing the call
    * @param mapper              The ObjectMapper to use for JSON serialization
    */
   public GraphQLMcpToolConverter(Service service, Resource resource, GraphQLInvocationProcessor invocationProcessor,
         ObjectMapper mapper) {
      super(service, resource);
      this.invocationProcessor = invocationProcessor;
      this.mapper = mapper;
   }

   @Override
   public String getToolDescription(Operation operation) {
      try {
         if (graphqlDocument == null) {
            graphqlDocument = new Parser().parseDocument(resource.getContent());
         }
         FieldDefinition operationDefinition = getOperationDefinition(operation.getName());

         if (operationDefinition != null) {
            // #1 Look for a description in the operation definition.
            if (operationDefinition.getDescription() != null) {
               return operationDefinition.getDescription().content;
            } else if (operationDefinition.getComments() != null && !operationDefinition.getComments().isEmpty()) {
               // #2 Look for comments in the operation definition.
               StringBuilder result = new StringBuilder();
               operationDefinition.getComments().forEach(comment -> { result.append(comment.getContent()); });
               return result.toString().trim();
            }
         }
      } catch (Exception e) {
         log.error("Exception while trying to get tool description", e);
      }
      return null;
   }

   @Override
   public McpSchema.JsonSchema getInputSchema(Operation operation) {
      ObjectNode inputSchemaNode = mapper.createObjectNode();
      ObjectNode schemaPropertiesNode = mapper.createObjectNode();
      ArrayNode requiredPropertiesNode = mapper.createArrayNode();

      // Initialize input schema with empty object.
      inputSchemaNode.put("type", "object");
      inputSchemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, schemaPropertiesNode);
      inputSchemaNode.set(JSON_SCHEMA_REQUIRED_ELEMENT, requiredPropertiesNode);
      inputSchemaNode.put(JSON_SCHEMA_ADD_PROPERTIES_ELEMENT, false);

      try {
         if (graphqlDocument == null) {
            graphqlDocument = new Parser().parseDocument(resource.getContent());
         }
         FieldDefinition operationDefinition = getOperationDefinition(operation.getName());

         if (operationDefinition != null && operationDefinition.getInputValueDefinitions() != null
               && !operationDefinition.getInputValueDefinitions().isEmpty()) {
            for (InputValueDefinition inputValueDef : operationDefinition.getInputValueDefinitions()) {
               visitProperty(inputValueDef.getName(), inputValueDef.getType(), schemaPropertiesNode,
                     requiredPropertiesNode);
            }
         }
      } catch (Exception e) {
         log.error("Exception while trying to get input schema", e);
      }
      return mapper.convertValue(inputSchemaNode, McpSchema.JsonSchema.class);
   }

   @Override
   public Response getCallResponse(Operation operation, McpSchema.CallToolRequest request,
         Map<String, List<String>> headers) {
      // Build a mock invocation context needed for the invocation processor.
      MockInvocationContext ic = new MockInvocationContext(service, operation, null);

      try {
         String query = null;
         if (operation.getDispatcher() != null && !operation.getDispatcher().startsWith("PROXY")) {
            // We target Microcks so query can be simple due to permissive parsing.
            query = operation.getName();
         } else {
            // We target a real GraphQL service so query, we must build a full and correct query.
            query = buildCompleteGraphQLQuery(operation, request).replace("\"", "\\\"");
         }

         // De-serialize remaining arguments as the body variables.
         String body = "{\"variables\": " + mapper.writeValueAsString(request.arguments()) + ", \"query\": \"" + query
               + "\" }";

         ObjectNode variables = mapper.convertValue(request.arguments(), ObjectNode.class);
         GraphQLHttpRequest graphqlRequest = GraphQLHttpRequest.from(operation.getName(), variables);

         // Query parameters are actually the body but simplified to a map of string values.
         Map<String, String> queryParams = request.arguments().entrySet().stream()
               .map(entry -> Map.entry(entry.getKey(), entry.getValue().toString()))
               .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

         // Execute the invocation processor after having cleaned the headers to propagate.
         headers = sanitizeHttpHeaders(headers);
         ResponseResult result = invocationProcessor.processInvocation(ic, System.currentTimeMillis(), queryParams,
               body, graphqlRequest, headers,
               new BasicHttpServletRequest(
                     "http://localhost:8080/graphql/"
                           + MockControllerCommons.composeServiceAndVersion(service.getName(), service.getVersion()),
                     "POST", "", "", Map.of(), headers));

         // Build a Microcks Response from the result.
         Response response = new Response();
         response.setStatus(result.status().toString());
         response.setHeaders(null);

         String resultContent = extractResponseContent(result);

         // As we're no longer tied to the GraphQL semantics, we can get rid of the data/<operationName> wrapper.
         JsonNode responseNode = mapper.readTree(resultContent);
         if (responseNode.has("data") && responseNode.get("data").has(operation.getName())) {
            response.setContent(mapper.writeValueAsString(responseNode.get("data").get(operation.getName())));
         } else {
            // Default to the full response.
            response.setContent(resultContent);
         }

         if (result.status().isError()) {
            response.setFault(true);
         }
         return response;
      } catch (Exception e) {
         log.error("Exception while processing the MCP call invocation", e);
      }
      return null;
   }

   /** Retrieve the correct operation definition in GraphQL schema document. */
   private FieldDefinition getOperationDefinition(String operationName) {
      for (ObjectTypeDefinition typeDefinition : graphqlDocument.getDefinitionsOfType(ObjectTypeDefinition.class)) {
         if (VALID_OPERATION_TYPES.contains(typeDefinition.getName().toLowerCase())) {
            for (FieldDefinition fieldDef : typeDefinition.getFieldDefinitions()) {
               if (fieldDef.getName().equals(operationName)) {
                  return fieldDef;
               }
            }
         }
      }
      return null;
   }

   /** Check if the type is a scalar type. */
   private boolean isScalarType(String typeName) {
      return ScalarInfo.isGraphqlSpecifiedScalar(typeName)
            || graphqlDocument.getDefinitionsOfType(ScalarTypeDefinition.class).stream()
                  .anyMatch(scalarTypeDefinition -> scalarTypeDefinition.getName().equals(typeName));
   }

   /** Retrieve the correct type definition in GraphQL schema document. */
   private ObjectTypeDefinition getTypeDefinition(String typeName) {
      for (ObjectTypeDefinition typeDefinition : graphqlDocument.getDefinitionsOfType(ObjectTypeDefinition.class)) {
         if (typeDefinition.getName().equals(typeName)) {
            return typeDefinition;
         }
      }
      return null;
   }

   /** Retrieve the correct enum type definition in GraphQL schema document. */
   private EnumTypeDefinition getEnumTypeDefinition(String typeName) {
      for (EnumTypeDefinition enumTypeDefinition : graphqlDocument.getDefinitionsOfType(EnumTypeDefinition.class)) {
         if (enumTypeDefinition.getName().equals(typeName)) {
            return enumTypeDefinition;
         }
      }
      return null;
   }

   /** Retrieve the correct input value definition in GraphQL schema document. */
   private InputObjectTypeDefinition getInputValueDefinition(String typeName) {
      for (InputObjectTypeDefinition inputObjectTypeDefinition : graphqlDocument
            .getDefinitionsOfType(InputObjectTypeDefinition.class)) {
         if (inputObjectTypeDefinition.getName().equals(typeName)) {
            return inputObjectTypeDefinition;
         }
      }
      return null;
   }

   /** Visit a property and add it to the input schema elements (properties and required properties). */
   private void visitProperty(String propertyName, Type propertyType, ObjectNode propertiesNode,
         ArrayNode requiredPropertiesNode) {
      if (TypeUtil.isNonNull(propertyType)) {
         requiredPropertiesNode.add(propertyName);
         propertyType = TypeUtil.unwrapOne(propertyType);
      }

      TypeInfo propertyTypeInfo = TypeInfo.typeInfo(propertyType);

      // Check if the field is a scalar.
      if (isScalarType(propertyTypeInfo.getName())) {
         ObjectNode propertySchemaNode = mapper.createObjectNode();
         propertySchemaNode.put("type", "string");
         if (propertyName != null) {
            propertiesNode.set(propertyName, propertySchemaNode);
         } else {
            // We may have no name if inside an array items.
            propertiesNode.setAll(propertySchemaNode);
         }

      } else if (TypeUtil.isList(propertyType)) {
         // We must convert to a type array.
         ObjectNode arraySchemaNode = mapper.createObjectNode();
         ObjectNode subitemsNode = mapper.createObjectNode();

         arraySchemaNode.put("type", "array");
         arraySchemaNode.set(JSON_SCHEMA_ITEMS_ELEMENT, subitemsNode);
         propertiesNode.set(propertyName, arraySchemaNode);

         visitProperty(null, TypeUtil.unwrapAll(propertyType), subitemsNode, requiredPropertiesNode);
      } else {
         // We must check if it's an enum type.
         EnumTypeDefinition enumTypeDefinition = getEnumTypeDefinition(propertyTypeInfo.getName());
         if (enumTypeDefinition != null) {
            ObjectNode enumSchemaNode = mapper.createObjectNode();
            enumSchemaNode.put("type", "string");
            ArrayNode enumValuesNode = mapper.createArrayNode();
            for (EnumValueDefinition valueDef : enumTypeDefinition.getEnumValueDefinitions()) {
               enumValuesNode.add(valueDef.getName());
            }
            enumSchemaNode.set(JSON_SCHEMA_ENUM, enumValuesNode);
            if (propertyName != null) {
               propertiesNode.set(propertyName, enumSchemaNode);
            } else {
               // We may have no name if inside an array items.
               propertiesNode.setAll(enumSchemaNode);
            }
         } else {
            // So finally, it should be an object type.
            // Initialize a new subschema node we must visit to resolve all possible references.
            ObjectNode subschemaNode = mapper.createObjectNode();
            ObjectNode subpropertiesNode = mapper.createObjectNode();
            ArrayNode requiredSubpropertiesNode = mapper.createArrayNode();

            subschemaNode.put("type", "object");
            subschemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, subpropertiesNode);
            subschemaNode.set(JSON_SCHEMA_REQUIRED_ELEMENT, requiredSubpropertiesNode);
            subschemaNode.put(JSON_SCHEMA_ADD_PROPERTIES_ELEMENT, false);
            if (propertyName != null) {
               propertiesNode.set(propertyName, subschemaNode);
            } else {
               // We may have no name if inside an array items.
               propertiesNode.setAll(subschemaNode);
            }

            ObjectTypeDefinition typeDef = getTypeDefinition(propertyTypeInfo.getName());
            if (typeDef != null) {
               visitObjectTypeDefinition(typeDef, subpropertiesNode, requiredSubpropertiesNode);
            } else {
               // It could be an input type definition.
               InputObjectTypeDefinition inputTypeDef = getInputValueDefinition(propertyTypeInfo.getName());
               if (inputTypeDef != null) {
                  visitInputObjectTypeDefinition(inputTypeDef, subpropertiesNode, requiredSubpropertiesNode);
               } else {
                  log.warn("Cannot find type definition for {}", propertyTypeInfo.getName());
               }
            }
         }
      }
   }

   /** Visit a GraphQL object type definition and add its properties to the input schema. */
   private void visitObjectTypeDefinition(ObjectTypeDefinition typeDefinition, ObjectNode propertiesNode,
         ArrayNode requiredPropertiesNode) {
      for (FieldDefinition fieldDef : typeDefinition.getFieldDefinitions()) {
         visitProperty(fieldDef.getName(), fieldDef.getType(), propertiesNode, requiredPropertiesNode);
      }
   }

   /** Visit a GraphQL input object type definition and add its properties to the input schema. */
   private void visitInputObjectTypeDefinition(InputObjectTypeDefinition typeDefinition, ObjectNode propertiesNode,
         ArrayNode requiredPropertiesNode) {
      for (InputValueDefinition fieldDef : typeDefinition.getInputValueDefinitions()) {
         visitProperty(fieldDef.getName(), fieldDef.getType(), propertiesNode, requiredPropertiesNode);
      }
   }

   /** Build a complete a query with all the fields to fetch. */
   private String buildCompleteGraphQLQuery(Operation operation, McpSchema.CallToolRequest request) {
      // Extract the type information from the operation.
      if (graphqlDocument == null) {
         graphqlDocument = new Parser().parseDocument(resource.getContent());
      }
      FieldDefinition operationDefinition = getOperationDefinition(operation.getName());
      Type operationOutputType = operationDefinition.getType();
      TypeInfo operationOutputTypeInfo = TypeInfo.typeInfo(operationOutputType);
      ObjectTypeDefinition typeDef = getTypeDefinition(operationOutputTypeInfo.getName());

      StringBuilder queryBuilder = new StringBuilder();
      queryBuilder.append("query {");
      queryBuilder.append("  ").append(operation.getName()).append("(");

      // Append the arguments to the operation.
      queryBuilder.append(request.arguments().entrySet().stream()
            .map(entry -> entry.getKey() + ": \"" + entry.getValue() + "\"").collect(Collectors.joining(", ", "", "")));

      queryBuilder.append("){\\n");

      if (typeDef != null) {
         for (FieldDefinition fd : typeDef.getFieldDefinitions()) {
            TypeInfo fdTypeInfo = TypeInfo.typeInfo(fd.getType());
            if (isScalarType(fdTypeInfo.getName())) {
               queryBuilder.append(fd.getName()).append("\\n");
            } else {
               // We must check if it's an enum type.
               EnumTypeDefinition enumTypeDefinition = getEnumTypeDefinition(fdTypeInfo.getName());
               if (enumTypeDefinition != null) {
                  queryBuilder.append(fd.getName()).append("\\n");
               }
            }
         }
      }

      // Finalize query before returning it.
      queryBuilder.append("}}");
      return queryBuilder.toString();
   }
}

public class GrpcMcpToolConverter extends McpToolConverter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(GrpcMcpToolConverter.class);

   private final GrpcInvocationProcessor invocationProcessor;
   private final ObjectMapper mapper;

   private Descriptors.ServiceDescriptor sd;

   /**
    * Build a new instance of GrpcMcpToolConverter.
    * @param service             The service to which this converter is attached
    * @param resource            The resource used for OpenAPI service conversion
    * @param invocationProcessor The invocation processor to use for processing the call
    * @param mapper              The ObjectMapper to use for JSON serialization
    */
   public GrpcMcpToolConverter(Service service, Resource resource, GrpcInvocationProcessor invocationProcessor,
         ObjectMapper mapper) {
      super(service, resource);
      this.invocationProcessor = invocationProcessor;
      this.mapper = mapper;
   }

   @Override
   public String getToolDescription(Operation operation) {
      return null;
   }

   @Override
   public McpSchema.JsonSchema getInputSchema(Operation operation) {
      ObjectNode inputSchemaNode = mapper.createObjectNode();
      ObjectNode schemaPropertiesNode = mapper.createObjectNode();
      ArrayNode requiredPropertiesNode = mapper.createArrayNode();

      // Initialize input schema with empty object.
      inputSchemaNode.put("type", "object");
      inputSchemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, schemaPropertiesNode);
      inputSchemaNode.set(JSON_SCHEMA_REQUIRED_ELEMENT, requiredPropertiesNode);
      inputSchemaNode.put(JSON_SCHEMA_ADD_PROPERTIES_ELEMENT, false);
      try {
         if (sd == null) {
            sd = GrpcUtil.findServiceDescriptor(resource.getContent(), service.getName());
         }

         Descriptors.MethodDescriptor md = sd.findMethodByName(operation.getName());
         if (md.getInputType() != null) {
            // Visit the input type descriptor.
            visitDescriptor(md.getInputType(), schemaPropertiesNode, requiredPropertiesNode);
         }
      } catch (Exception e) {
         log.error("Exception while trying to get input schema", e);
      }
      return mapper.convertValue(inputSchemaNode, McpSchema.JsonSchema.class);
   }

   @Override
   public Response getCallResponse(Operation operation, McpSchema.CallToolRequest request,
         Map<String, List<String>> headers) {
      // Build a mock invocation context needed for the invocation processor.
      MockInvocationContext ic = new MockInvocationContext(service, operation, null);

      try {
         // De-serialize remaining arguments as the request body.
         String body = mapper.writeValueAsString(request.arguments());

         // Execute the invocation processor.
         GrpcResponseResult result = invocationProcessor.processInvocation(ic, System.currentTimeMillis(), body);

         // Build a Microcks Response from the result.
         Response response = new Response();
         if (result.content() != null) {
            response.setContent(result.content());
         }
         if (result.isError()) {
            response.setFault(true);
            response.setStatus("500");
            response.setContent(result.errorDescription());
         }
         return response;
      } catch (Exception e) {
         log.error("Exception while processing the MCP call invocation", e);
      }
      return null;
   }

   /** Visit a protobuf message descriptor and extract its properties. */
   private void visitDescriptor(Descriptors.Descriptor inputType, ObjectNode propertiesNode,
         ArrayNode requiredPropertiesNode) {
      for (Descriptors.FieldDescriptor fd : inputType.getFields()) {

         // Get the field name and type.
         String fieldName = fd.getName();

         // Check if the field is required.
         if (fd.isRequired()) {
            requiredPropertiesNode.add(fieldName);
         }

         // Check if the field is an array/a repeated field.
         if (fd.isRepeated()) {
            // We must convert to a type array.
            ObjectNode arraySchemaNode = mapper.createObjectNode();

            arraySchemaNode.put("type", "array");
            propertiesNode.set(fieldName, arraySchemaNode);

            if (isMessageType(fd.getType())) {
               ObjectNode subschemaNode = mapper.createObjectNode();
               ObjectNode subitemsNode = mapper.createObjectNode();
               ArrayNode requiredSubitemsPropertiesNode = mapper.createArrayNode();

               visitDescriptor(fd.getMessageType(), subitemsNode, requiredSubitemsPropertiesNode);

               // Add the required properties to the subschema.
               subschemaNode.put("type", "object");
               subschemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, subitemsNode);

               // Add the items definition to the current property.
               arraySchemaNode.set(JSON_SCHEMA_ITEMS_ELEMENT, subschemaNode);
               propertiesNode.set(fieldName, arraySchemaNode);
            } else if (isEnumType(fd.getType())) {
               arraySchemaNode.set(JSON_SCHEMA_ITEMS_ELEMENT, buildEnumTypeNode(fd));
            } else if (isScalarType(fd.getType())) {
               arraySchemaNode.set(JSON_SCHEMA_ITEMS_ELEMENT, buildScalarTypeNode(fd));
            }
         } else {
            // Check if the field is an object/message type.
            if (isMessageType(fd.getType())) {
               // Initialize a new subschema node we must visit to resolve message fields.
               ObjectNode subschemaNode = mapper.createObjectNode();
               ObjectNode subpropertiesNode = mapper.createObjectNode();
               ArrayNode requiredSubpropertiesNode = mapper.createArrayNode();

               subschemaNode.put("type", "object");
               subschemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, subpropertiesNode);
               subschemaNode.set(JSON_SCHEMA_REQUIRED_ELEMENT, requiredSubpropertiesNode);
               subschemaNode.put(JSON_SCHEMA_ADD_PROPERTIES_ELEMENT, false);
               propertiesNode.set(fieldName, subschemaNode);

               visitDescriptor(fd.getMessageType(), subpropertiesNode, requiredSubpropertiesNode);
            } else if (isEnumType(fd.getType())) {
               propertiesNode.set(fieldName, buildEnumTypeNode(fd));
            } else if (isScalarType(fd.getType())) {
               propertiesNode.set(fieldName, buildScalarTypeNode(fd));
            }
         }
      }
   }

   /** Defines is a protobuf message field type is an message type. */
   private static boolean isMessageType(Descriptors.FieldDescriptor.Type fieldType) {
      return fieldType == Descriptors.FieldDescriptor.Type.MESSAGE
            || fieldType == Descriptors.FieldDescriptor.Type.GROUP;
   }

   /** Defines is a protobuf message field type is an enum type. */
   private static boolean isEnumType(Descriptors.FieldDescriptor.Type fieldType) {
      return fieldType == Descriptors.FieldDescriptor.Type.ENUM;
   }

   /** Defines is a protobuf message field type is a scalar type. */
   private static boolean isScalarType(Descriptors.FieldDescriptor.Type fieldType) {
      return fieldType != Descriptors.FieldDescriptor.Type.MESSAGE
            && fieldType != Descriptors.FieldDescriptor.Type.GROUP
            && fieldType != Descriptors.FieldDescriptor.Type.BYTES;
   }

   /** Build a leaf node that is an enum type. */
   private ObjectNode buildEnumTypeNode(Descriptors.FieldDescriptor fd) {
      ObjectNode subschemaNode = mapper.createObjectNode();
      ArrayNode enumsArrayNode = mapper.createArrayNode();

      subschemaNode.put("type", toMcpJsonType(fd.getType()));
      subschemaNode.set("enum", enumsArrayNode);

      // Put the enum values in enum array.
      for (Descriptors.EnumValueDescriptor evd : fd.getEnumType().getValues()) {
         enumsArrayNode.add(evd.getName());
      }
      return subschemaNode;
   }

   /** Build a leaf node that is a scalar type. */
   private ObjectNode buildScalarTypeNode(Descriptors.FieldDescriptor fd) {
      ObjectNode subschemaNode = mapper.createObjectNode();
      subschemaNode.put("type", toMcpJsonType(fd.getType()));
      return subschemaNode;
   }

   /** Convert a scalar Field Protobuf type into a MCP Json compatible one. */
   private static String toMcpJsonType(Descriptors.FieldDescriptor.Type fieldType) {
      switch (fieldType) {
         case DOUBLE:
         case FLOAT:
         case INT64:
         case UINT64:
         case INT32:
         case FIXED64:
         case FIXED32:
            return "number";
         case BOOL:
            return "boolean";
         case STRING:
         case BYTES:
         default:
            return "string";
      }
   }
}

public class OpenAPIMcpToolConverter extends McpToolConverter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(OpenAPIMcpToolConverter.class);

   private static final String OPEN_API_PATHS_ELEMENT = "/paths/";

   private final RestInvocationProcessor invocationProcessor;
   private final ObjectMapper mapper;

   private JsonNode schemaNode;

   /**
    * Build a new instance of OpenAPIMcpToolConverter.
    * @param service             The service to which this converter is attached
    * @param resource            The resource used for OpenAPI service conversion
    * @param invocationProcessor The invocation processor to use for processing the call
    * @param mapper              The ObjectMapper to use for JSON serialization
    */
   public OpenAPIMcpToolConverter(Service service, Resource resource, RestInvocationProcessor invocationProcessor,
         ObjectMapper mapper) {
      super(service, resource);
      this.invocationProcessor = invocationProcessor;
      this.mapper = mapper;
   }

   @Override
   public String getToolName(Operation operation) {
      // Anthropic Claude tools must respect ^[a-zA-Z0-9_-]{1,64}$ regular expression that doesn't match with our URI.
      return operation.getName().replace(" ", "_").replace("/", "_").replace("{", "").replace("}", "")
            .replace("__", "_").toLowerCase();
   }

   @Override
   public String getToolDescription(Operation operation) {
      try {
         if (schemaNode == null) {
            schemaNode = OpenAPISchemaValidator.getJsonNodeForSchema(resource.getContent());
         }

         // Extract JsonNode corresponding to operation.
         String verb = operation.getName().split(" ")[0].toLowerCase();
         String path = operation.getName().split(" ")[1].trim().replace("/", "~1");

         String operationPointer = OPEN_API_PATHS_ELEMENT + path + "/" + verb;
         JsonNode operationNode = schemaNode.at(operationPointer);
         if (operationNode.has("description")) {
            return operationNode.path("description").asText();
         }
         if (operationNode.has("summary")) {
            return operationNode.path("summary").asText();
         }
      } catch (Exception e) {
         log.error("Exception while trying to get tool description", e);
      }
      return null;
   }

   @Override
   public McpSchema.JsonSchema getInputSchema(Operation operation) {
      ObjectNode inputSchemaNode = mapper.createObjectNode();
      ObjectNode schemaPropertiesNode = mapper.createObjectNode();
      ArrayNode requiredPropertiesNode = mapper.createArrayNode();

      // Initialize input schema with empty object.
      inputSchemaNode.put("type", "object");
      inputSchemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, schemaPropertiesNode);
      inputSchemaNode.set(JSON_SCHEMA_REQUIRED_ELEMENT, requiredPropertiesNode);
      inputSchemaNode.put(JSON_SCHEMA_ADD_PROPERTIES_ELEMENT, false);
      try {
         if (schemaNode == null) {
            schemaNode = OpenAPISchemaValidator.getJsonNodeForSchema(resource.getContent());
         }

         // Extract JsonNode corresponding to request body.
         String verb = operation.getName().split(" ")[0].toLowerCase();
         String path = operation.getName().split(" ")[1].trim().replace("/", "~1");

         String schemaPointer = OPEN_API_PATHS_ELEMENT + path + "/" + verb
               + "/requestBody/content/application~1json/schema";
         JsonNode requestSchemaNode = schemaNode.at(schemaPointer);
         if (!requestSchemaNode.isMissingNode()) {
            requestSchemaNode = followRefIfAny(requestSchemaNode);

            // May be null if not resolved.
            if (requestSchemaNode != null) {
               visitNodeWithProperties(requestSchemaNode, schemaPropertiesNode, requiredPropertiesNode);
            }
         }

         // Add parameters to input schema.
         String paramsPointer = OPEN_API_PATHS_ELEMENT + path + "/" + verb + "/parameters";
         JsonNode paramsNode = schemaNode.at(paramsPointer);

         Iterator<JsonNode> parameters = paramsNode.elements();
         while (parameters.hasNext()) {
            JsonNode parameter = followRefIfAny(parameters.next());
            String paramName = parameter.path("name").asText();

            // Create a property node for the parameter.
            ObjectNode propertyNode = mapper.createObjectNode();
            propertyNode.put("type", "string");
            schemaPropertiesNode.set(paramName, propertyNode);
            if (parameter.path(JSON_SCHEMA_REQUIRED_ELEMENT).asBoolean(false)) {
               requiredPropertiesNode.add(paramName);
            }
         }
      } catch (Exception e) {
         log.error("Exception while trying to get input schema", e);
      }
      return mapper.convertValue(inputSchemaNode, McpSchema.JsonSchema.class);
   }

   @Override
   public Response getCallResponse(Operation operation, McpSchema.CallToolRequest request,
         Map<String, List<String>> headers) {
      String queryString = "";
      String verb = operation.getName().split(" ")[0];
      String resourcePath = operation.getName().split(" ")[1].trim();
      Map<String, String> pathParams = new HashMap<>();
      Map<String, String> queryParams = new HashMap<>();

      // Unwrap the request parameters and headers and remove them from request.
      try {
         if (schemaNode == null) {
            schemaNode = OpenAPISchemaValidator.getJsonNodeForSchema(resource.getContent());
         }

         // Extract JsonNode corresponding to request parameters.
         String path = resourcePath.replace("/", "~1");
         String paramsPointer = OPEN_API_PATHS_ELEMENT + path + "/" + verb.toLowerCase() + "/parameters";
         JsonNode paramsNode = schemaNode.at(paramsPointer);

         Iterator<JsonNode> parameters = paramsNode.elements();
         while (parameters.hasNext()) {
            JsonNode parameter = followRefIfAny(parameters.next());
            String paramName = parameter.path("name").asText();
            String paramIn = parameter.path("in").asText(); // Check if it's "path" or "query"

            if (request.arguments().containsKey(paramName)) {
               String paramValue = request.arguments().remove(paramName).toString();
               if ("path".equals(paramIn)) {
                  pathParams.put(paramName, paramValue);
               } else if ("query".equals(paramIn)) {
                  queryParams.put(paramName, paramValue);
               } else if ("header".equals(paramIn)) {
                  headers.put(paramName, List.of(paramValue));
               }
            }
         }
      } catch (Exception e) {
         log.error("Exception while extracting URI parameters from arguments", e);
      }

      // Re-build the resource path with parameters if needed.
      if (operation.getName().contains("{")) {
         resourcePath = URIBuilder.buildURIFromPattern(resourcePath, pathParams);
      }
      // Re-build the query string with parameters if needed.
      if (!queryParams.isEmpty()) {
         queryString = URIBuilder.buildURIFromPattern("", queryParams);
         if (queryString.startsWith("?")) {
            queryString = queryString.substring(1);
         }
      }

      // Create a mock request to pass to the invocation processor.
      MockInvocationContext ic = new MockInvocationContext(service, operation, resourcePath);

      try {
         // Serialize remaining arguments as the request body.
         String body = mapper.writeValueAsString(request.arguments());

         // Execute the invocation processor after having cleaned the headers to propagate.
         headers = sanitizeHttpHeaders(headers);
         ResponseResult result = invocationProcessor.processInvocation(ic, System.currentTimeMillis(), null, body,
               headers,
               new BasicHttpServletRequest(
                     "http://localhost:8080/rest/"
                           + MockControllerCommons.composeServiceAndVersion(service.getName(), service.getVersion()),
                     verb, resourcePath, queryString, queryParams, headers));

         // Build a Microcks Response from the result.
         Response response = new Response();
         response.setStatus(result.status().toString());
         response.setHeaders(null);
         response.setContent(extractResponseContent(result));

         if (result.status().isError()) {
            response.setFault(true);
         }
         return response;
      } catch (Exception e) {
         log.error("Exception while processing the MCP call invocation", e);
      }
      return null;
   }

   /** Follow the $ref if we have one. Otherwise, return given node. */
   protected JsonNode followRefIfAny(JsonNode referencableNode) {
      if (referencableNode.has("$ref")) {
         String ref = referencableNode.path("$ref").asText();
         return getNodeForRef(ref);
      }
      return referencableNode;
   }

   /** Get the JsonNode for reference within the specification. */
   private JsonNode getNodeForRef(String reference) {
      if (reference.startsWith("#/")) {
         return schemaNode.at(reference.substring(1));
      }
      // TODO: handle external references reusing imported resources?
      return null;
   }

   /** Visit a node and extract its properties. */
   private void visitNodeWithProperties(JsonNode node, ObjectNode propertiesNode, ArrayNode requiredPropertiesNode) {
      JsonNode requiredNode = node.path(JSON_SCHEMA_REQUIRED_ELEMENT);
      Iterator<Map.Entry<String, JsonNode>> propertiesList = node.path(JSON_SCHEMA_PROPERTIES_ELEMENT).fields();

      while (propertiesList.hasNext()) {
         Map.Entry<String, JsonNode> property = propertiesList.next();
         String propertyName = property.getKey();
         JsonNode propertyValue = followRefIfAny(property.getValue());

         if (propertyValue.has(JSON_SCHEMA_PROPERTIES_ELEMENT)) {
            // Initialize a new subschema node we must visit to resolve all possible references.
            ObjectNode subschemaNode = mapper.createObjectNode();
            ObjectNode subpropertiesNode = mapper.createObjectNode();
            ArrayNode requiredSubpropertiesNode = mapper.createArrayNode();

            subschemaNode.put("type", "object");
            subschemaNode.set(JSON_SCHEMA_PROPERTIES_ELEMENT, subpropertiesNode);
            subschemaNode.set(JSON_SCHEMA_REQUIRED_ELEMENT, requiredSubpropertiesNode);
            subschemaNode.put(JSON_SCHEMA_ADD_PROPERTIES_ELEMENT, false);
            propertiesNode.set(propertyName, subschemaNode);

            visitNodeWithProperties(propertyValue, subpropertiesNode, requiredSubpropertiesNode);
         } else {
            propertiesNode.set(propertyName, dereferencedNode(propertyValue));
            if (!requiredNode.isMissingNode() && requiredNode.isArray()
                  && arrayNodeContains((ArrayNode) requiredNode, property.getKey())) {
               requiredPropertiesNode.add(property.getKey());
            }
         }
      }
   }

   private JsonNode dereferencedNode(JsonNode node) {
      if (node.isObject()) {
         Iterator<String> fieldNames = node.fieldNames();
         while (fieldNames.hasNext()) {
            String fieldName = fieldNames.next();
            JsonNode fieldValue = node.get(fieldName);
            if (fieldValue.has("$ref")) {
               JsonNode target = followRefIfAny(fieldValue);
               if (target != null) {
                  // Replace the field value with the dereferenced node.
                  ((ObjectNode) node).replace(fieldName, dereferencedNode(target));
               } else {
                  // If the target is null, remove the field.
                  ((ObjectNode) node).remove(fieldName);
               }
            } else if (fieldValue.isObject() || fieldValue.isArray()) {
               // Recursively process nested objects or arrays.
               dereferencedNode(fieldValue);
            }
         }
      } else if (node.isArray()) {
         for (int i = 0; i < node.size(); i++) {
            JsonNode arrayElement = node.get(i);
            if (arrayElement.has("$ref")) {
               JsonNode target = followRefIfAny(arrayElement);
               if (target != null) {
                  JsonNode dereferencedTarget = dereferencedNode(target);
                  // Replace the array element with the dereferenced node.
                  ((ArrayNode) node).set(i, dereferencedTarget);
               } else {
                  // If the target is null, remove the array element.
                  ((ArrayNode) node).remove(i);
               }
            } else if (arrayElement.isObject() || arrayElement.isArray()) {
               // Recursively process nested objects or arrays.
               dereferencedNode(arrayElement);
            }
         }
      }
      return node;
   }

   /** Check if the arrayNode contains the given value. */
   private boolean arrayNodeContains(ArrayNode arrayNode, String value) {
      // Iterate over arrayNode elements and check if any element matches the value.
      for (JsonNode element : arrayNode) {
         if (element.asText().equals(value)) {
            return true;
         }
      }
      return false;
   }
}

public class MockControllerCommons {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(MockControllerCommons.class);

   /** The header name used to specify a wait delay in the request. */
   public static final String X_MICROCKS_DELAY_HEADER = "x-microcks-delay";

   private static final String RENDERING_MESSAGE = "Response contains dynamic EL expression, rendering it...";


   /** Private constructor to avoid instantiation. */
   private MockControllerCommons() {
   }

   /**
    * Retrieve a fallback specification for this operation if one is defined.
    * @param rOperation The operation to get fallback specification
    * @return A fallback specification or null if none defined
    */
   public static FallbackSpecification getFallbackIfAny(Operation rOperation) {
      FallbackSpecification fallback = null;
      if (DispatchStyles.FALLBACK.equals(rOperation.getDispatcher())) {
         try {
            fallback = FallbackSpecification.buildFromJsonString(rOperation.getDispatcherRules());
         } catch (JsonMappingException jme) {
            log.error("Dispatching rules of operation cannot be interpreted as FallbackSpecification", jme);
         }
      }
      return fallback;
   }

   /**
    * Retrieve a proxyFallback specification for this operation if one is defined.
    * @param rOperation The operation to get proxyFallback specification
    * @return A proxy specification or null if none defined
    */
   public static ProxyFallbackSpecification getProxyFallbackIfAny(Operation rOperation) {
      ProxyFallbackSpecification proxyFallback = null;
      if (DispatchStyles.PROXY_FALLBACK.equals(rOperation.getDispatcher())) {
         try {
            proxyFallback = ProxyFallbackSpecification.buildFromJsonString(rOperation.getDispatcherRules());
         } catch (JsonMappingException jme) {
            log.error("Dispatching rules of operation cannot be interpreted as ProxyFallbackSpecification", jme);
         }
      }
      return proxyFallback;
   }

   /**
    * Check if proxy behavior is requested and extract proxyUrl.
    * @param dispatcher      The original dispatcher for the Proxy dispatcher checking.
    * @param dispatcherRules The original dispatcherRules for URL extracting.
    * @param resourcePath    The original resourcePath for URL compilation.
    * @param proxyFallback   The proxyFallbackSpec for the Proxy-Fallback dispatcher checking and URL extracting.
    * @param request         The original request for URL comparing on cycling.
    * @param response        The response that was found(or not) by dispatcher.
    * @return The optional container with URI for the proxy service if the request needs to be proxied.
    */
   public static Optional<URI> getProxyUrlIfProxyIsNeeded(String dispatcher, String dispatcherRules,
         String resourcePath, ProxyFallbackSpecification proxyFallback, HttpServletRequest request, Response response) {
      String externalUrl = null;
      if (DispatchStyles.PROXY.equals(dispatcher)) {
         externalUrl = dispatcherRules;
      }
      if (response == null && proxyFallback != null) {
         externalUrl = proxyFallback.getProxyUrl();
      }
      if (externalUrl != null) {
         externalUrl = externalUrl.replaceFirst("/$", "") + resourcePath;
         if (!externalUrl.contentEquals(request.getRequestURL())) {
            try {
               return Optional
                     .of(UriComponentsBuilder.fromHttpUrl(externalUrl).query(request.getQueryString()).build().toUri());
            } catch (IllegalArgumentException ex) {
               log.warn("Invalid external URL in the dispatcher - {}", externalUrl);
            }
         }
      }
      return Optional.empty();
   }

   /**
    * Render the response headers using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized values.
    * @param evaluableRequest The request that can be evaluated in templating.
    * @param requestContext   The invocation context of the request
    * @param response         The response that was found by dispatcher
    * @return The rendered response headers values.
    */
   public static Set<Header> renderResponseHeaders(EvaluableRequest evaluableRequest,
         Map<String, Object> requestContext, Response response) {
      TemplateEngine engine = null;
      Set<Header> headers = new HashSet<>();

      if (response.getHeaders() != null) {
         for (Header header : response.getHeaders()) {
            Set<String> renderedValues = new HashSet<>();
            for (String value : header.getValues()) {
               // Only render and build an engine if we have an expression.
               if (value.contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
                  // Evaluate the header value.
                  if (engine == null) {
                     engine = TemplateEngineFactory.getTemplateEngine();
                  }
                  renderedValues.add(unguardedRenderResponseContent(evaluableRequest, requestContext, engine, value));
               } else {
                  renderedValues.add(value);
               }
            }
            headers.add(new Header(header.getName(), renderedValues));
         }
      }
      return headers;
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param requestBody    The body payload of incoming request.
    * @param requestContext The invocation context of the request
    * @param response       The response that was found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(String requestBody, Map<String, Object> requestContext,
         Response response) {
      if (response.getContent() != null && response.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug(RENDERING_MESSAGE);

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = new EvaluableRequest(requestBody, null);

         // Evaluate the response.
         return unguardedRenderResponseContent(evaluableRequest, requestContext,
               TemplateEngineFactory.getTemplateEngine(), response.getContent());
      }
      return response.getContent();
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param requestBody      The body payload of incoming request.
    * @param evaluableParams  A map of params for evaluation.
    * @param evaluableHeaders A map of headers for evaluation.
    * @param requestContext   The invocation context of the request
    * @param response         The response that was found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(String requestBody, Map<String, String> evaluableParams,
         Map<String, String> evaluableHeaders, Map<String, Object> requestContext, Response response) {
      if (response.getContent() != null && response.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug(RENDERING_MESSAGE);

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = new EvaluableRequest(requestBody, null);
         // Adding query and header parameters...
         evaluableRequest.setParams(evaluableParams);
         evaluableRequest.setHeaders(evaluableHeaders);

         // Evaluate the response.
         return unguardedRenderResponseContent(evaluableRequest, requestContext,
               TemplateEngineFactory.getTemplateEngine(), response.getContent());
      }
      return response.getContent();
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param requestBody         The body payload of incoming request.
    * @param requestResourcePath The resource path of mock request (if any, may be null)
    * @param request             The incoming servlet request
    * @param requestContext      The invocation context of the request
    * @param response            The response that was found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(String requestBody, String requestResourcePath,
         HttpServletRequest request, Map<String, Object> requestContext, Response response) {
      if (response.getContent() != null && response.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug(RENDERING_MESSAGE);

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = buildEvaluableRequest(requestBody, requestResourcePath, request);
         return unguardedRenderResponseContent(evaluableRequest, requestContext,
               TemplateEngineFactory.getTemplateEngine(), response.getContent());
      }
      return response.getContent();
   }

   /**
    * Render the response content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized response.
    * @param evaluableRequest The request that can be evaluated in templating.
    * @param engine           The template engine to use for this rendering
    * @param responseContent  The response content found by dispatcher
    * @return The rendered response body payload.
    */
   public static String renderResponseContent(EvaluableRequest evaluableRequest, TemplateEngine engine,
         String responseContent) {
      if (responseContent != null && responseContent.contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         return unguardedRenderResponseContent(evaluableRequest, null, engine, responseContent);
      }
      return responseContent;
   }

   private static String unguardedRenderResponseContent(EvaluableRequest evaluableRequest,
         Map<String, Object> requestContext, TemplateEngine engine, String responseContent) {
      // Register the request variable and evaluate the response.
      engine.getContext().setVariable("request", evaluableRequest);
      if (requestContext != null) {
         engine.getContext().setVariables(requestContext);
      }
      try {
         return engine.getValue(responseContent);
      } catch (Throwable t) {
         log.error("Failing at evaluating template {}", responseContent, t);
      }
      return responseContent;
   }

   /**
    * Build an Evaluable request from various request elements.
    * @param requestBody         The body of request to evaluate
    * @param requestResourcePath The resource path this request is bound to
    * @param request             The underlying Http request
    * @return The Evaluable request for later templating rendering
    */
   public static EvaluableRequest buildEvaluableRequest(String requestBody, String requestResourcePath,
         HttpServletRequest request) {
      // Create and fill an evaluable request object.
      EvaluableRequest evaluableRequest = new EvaluableRequest(requestBody,
            requestResourcePath != null ? requestResourcePath.split("/") : null);
      // Adding query parameters...
      Map<String, String> evaluableParams = new HashMap<>();
      List<String> parameterNames = Collections.list(request.getParameterNames());
      for (String parameter : parameterNames) {
         evaluableParams.put(parameter, request.getParameter(parameter));
      }
      evaluableRequest.setParams(evaluableParams);
      // Adding headers...
      Map<String, String> evaluableHeaders = new HashMap<>();
      if (request.getHeaderNames() != null) {
         List<String> headerNames = Collections.list(request.getHeaderNames());
         for (String header : headerNames) {
            evaluableHeaders.put(header, request.getHeader(header));
         }
      }
      evaluableRequest.setHeaders(evaluableHeaders);

      return evaluableRequest;
   }

   /** Retrieve delay header or default to the one provided as parameter. */
   public static Long getDelay(HttpHeaders headers, Long delayParameter) {
      if (headers.containsKey(MockControllerCommons.X_MICROCKS_DELAY_HEADER)) {
         String delayHeader = headers.getFirst(MockControllerCommons.X_MICROCKS_DELAY_HEADER);
         try {
            return Long.parseLong(delayHeader);
         } catch (NumberFormatException nfe) {
            log.debug("Invalid delay header value: {}", delayHeader);
         }
      }
      return delayParameter;
   }

   /**
    * Block current thread for specified delay (if not null) from @{code startTime}.
    * @param startTime The starting time of mock request invocation
    * @param delay     The delay to wait for
    */
   public static void waitForDelay(Long startTime, Long delay) {
      if (delay != null && delay > -1) {
         log.debug("Mock delay is turned on, waiting if necessary...");
         long duration = System.currentTimeMillis() - startTime;
         if (duration < delay) {
            Object semaphore = new Object();
            synchronized (semaphore) {
               try {
                  semaphore.wait(delay - duration);
               } catch (Exception e) {
                  log.debug("Delay semaphore was interrupted");
               }
            }
         }
         log.debug("Delay now expired, releasing response !");
      }
   }

   /**
    * Publish a mock invocation event on Spring ApplicationContext internal bus.
    * @param applicationContext The context to use for publication
    * @param eventSource        The source of this event
    * @param service            The mocked Service that was invoked
    * @param response           The response it has been dispatched to
    * @param startTime          The start time of the invocation
    */
   public static void publishMockInvocation(ApplicationContext applicationContext, Object eventSource, Service service,
         Response response, Long startTime) {
      // Publish an invocation event before returning.
      MockInvocationEvent event = new MockInvocationEvent(eventSource, service.getName(), service.getVersion(),
            response.getName(), new Date(startTime), startTime - System.currentTimeMillis());
      applicationContext.publishEvent(event);
      log.debug("Mock invocation event has been published");
   }

   public static String composeServiceAndVersion(String serviceName, String version) {
      return "/" + UriUtils.encodeFragment(serviceName, "UTF-8") + "/" + version;
   }

   public static String extractResourcePath(HttpServletRequest request, String serviceAndVersion) {
      String requestURI = request.getRequestURI();
      String resourcePath = requestURI.substring(requestURI.indexOf(serviceAndVersion) + serviceAndVersion.length());
      log.debug("Found resourcePath: {}", resourcePath);

      // If resourcePath was encoded with '+' instead of '%20', replace them .
      if (resourcePath.contains("+")) {
         resourcePath = resourcePath.replace("+", "%20");
      }
      return resourcePath;
   }
}

