      this.name = name;
      this.values = values;
   }

   public String getName() {
      return name;
   }

   public void setName(String name) {
      this.name = name;
   }

   public Set<String> getValues() {
      return values;
   }

   public void setValues(Set<String> values) {
      this.values = values;
   }
}

