public class TestRunnerCommons {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(TestRunnerCommons.class);

   /**
    * Render the request content using the Expression Language compatible {@code TemplateEngine} if required. If
    * rendering template fails, we just produce a log error message and stick to templatized content.
    * @param request The request that will be sent for test.
    * @param headers The set of computed headers to use for request body evaluation
    * @return The rendered response body payload.
    */
   public static String renderRequestContent(Request request, Set<Header> headers) {
      if (request.getContent().contains(TemplateEngine.DEFAULT_EXPRESSION_PREFIX)) {
         log.debug("Response contains dynamic EL expression, rendering it...");
         TemplateEngine engine = TemplateEngineFactory.getTemplateEngine();

         // Create and fill an evaluable request object.
         EvaluableRequest evaluableRequest = new EvaluableRequest(request.getContent(), null);
         // Adding query parameters...
         Map<String, String> evaluableParams = new HashMap<>();
         for (Parameter parameter : request.getQueryParameters()) {
            evaluableParams.put(parameter.getName(), parameter.getValue());
         }
         evaluableRequest.setParams(evaluableParams);
         // Adding headers...
         Map<String, String> evaluableHeaders = new HashMap<>();
         for (Header header : request.getHeaders()) {
            evaluableHeaders.put(header.getName(), String.join(",", header.getValues()));
         }
         evaluableRequest.setHeaders(evaluableHeaders);

         // Register the request variable and evaluate the request body.
         engine.getContext().setVariable("request", evaluableRequest);
         try {
            return engine.getValue(request.getContent());
         } catch (Throwable t) {
            log.error("Failing at evaluating template " + request.getContent(), t);
            return request.getContent();
         }
      }
      return request.getContent();
   }

   /**
    * Construct set of headers given specification of request, operations and testResult. TestResult operation-specific
    * headers overrule testResult global headers which overrule request headers.
    * @param testResult The configured test run containing global and operation-specific headers.
    * @param request    The example request with headers.
    * @param operation  The operation to be run.
    * @return A set of headers for the given operation
    */
   public static Set<Header> collectHeaders(TestResult testResult, Request request, Operation operation) {
      Set<Header> headers = new HashSet<>();

      // Set headers to request if any. Start with those coming from request itself.
      if (request.getHeaders() != null) {
         headers.addAll(request.getHeaders());
      }

      // Add or override existing headers with test specific ones for operation and globals.
      if (testResult.getOperationsHeaders() != null) {
         if (testResult.getOperationsHeaders().getGlobals() != null) {
            headers.addAll(testResult.getOperationsHeaders().getGlobals());
         }
         if (testResult.getOperationsHeaders().get(operation.getName()) != null) {
            headers.addAll(testResult.getOperationsHeaders().get(operation.getName()));
         }
      }

      return headers;
   }
}

public class URIBuilder {

   private URIBuilder() {
      // Hide default no argument constructor as it's a utility class.
   }

   /**
    * Build a URI from a URI pattern (using {} or /: for marked variable parts) and using other query parameters
    * @param pattern    The URI pattern to use
    * @param parameters The set of parameters (whether template or query based)
    * @return The instanciated URI from template and parameters
    */
   public static String buildURIFromPattern(String pattern, List<Parameter> parameters) {
      if (parameters != null) {
         // Browse parameters and choose between template or query one.
         for (Parameter parameter : parameters) {
            String wadlTemplate = "{" + parameter.getName() + "}";
            String swaggerTemplate = "/:" + parameter.getName();
            if (pattern.contains(wadlTemplate)) {
               // It's a template parameter.
               pattern = pattern.replace(wadlTemplate, encodePath(parameter.getValue()));
            } else if (pattern.contains(swaggerTemplate)) {
               // It's a template parameter.
               pattern = pattern.replace(":" + parameter.getName(), encodePath(parameter.getValue()));
            } else {
               // It's a query parameter, ensure we have started delimiting them.
               if (!pattern.contains("?")) {
                  pattern += "?";
               }
               if (pattern.contains("=")) {
                  pattern += "&";
               }
               pattern += parameter.getName() + "=" + encodeValue(parameter.getValue());
            }
         }
      }
      return pattern;
   }

   /**
    * Build a URI from a URI pattern (using {} or /: for marked variable parts) and using other query parameters
    * @param pattern    The URI pattern to use
    * @param parameters The map of parameters K/V (whether template or query based)
    * @return The instanciated URI from template and parameters
    */
   public static String buildURIFromPattern(String pattern, Map<String, String> parameters) {
      if (parameters != null) {
         Multimap<String, String> multimap = parameters.entrySet().stream().collect(ArrayListMultimap::create,
               (m, e) -> m.put(e.getKey(), e.getValue()), Multimap::putAll);
         return buildURIFromPattern(pattern, multimap);
      }
      return pattern;
   }

   /**
    * Build a URI from a URI pattern (using {} or /: for marked variable parts) and using other query parameters
    * @param pattern    The URI pattern to use
    * @param parameters The Multimap of parameters K/V (whether template or query based)
    * @return The instanciated URI from template and parameters
    */
   public static String buildURIFromPattern(String pattern, Multimap<String, String> parameters) {
      if (parameters != null) {
         // Browse parameters and choose from template of query one.
         for (String parameterName : parameters.keySet()) {
            String wadltemplate = "{" + parameterName + "}";
            String swaggerTemplate = "/:" + parameterName;

            for (String parameterValue : parameters.get(parameterName)) {

               if (pattern.contains(wadltemplate)) {
                  // It's a template parameter.
                  pattern = pattern.replace(wadltemplate, encodePath(parameterValue));
               } else if (pattern.contains(swaggerTemplate)) {
                  // It's a template parameter.
                  pattern = pattern.replace(":" + parameterName, encodePath(parameterValue));
               } else {
                  // It's a query parameter, ensure we have started delimiting them.
                  if (!pattern.contains("?")) {
                     pattern += "?";
                  }
                  if (pattern.contains("=")) {
                     pattern += "&";
                  }
                  pattern += parameterName + "=" + encodeValue(parameterValue);
               }
            }
         }
      }
      return pattern;
   }

   /** Utility method for getting URL encoding of query parameter. */
   private static String encodeValue(String value) {
      return URLEncoder.encode(value, StandardCharsets.UTF_8);
   }

   /**
    * Utility method for getting URL encoding of path parameter. We cannot use JDK method that only deal with query
    * parameters value. See https://stackoverflow.com/a/2678602 and https://www.baeldung.com/java-url-encoding-decoding.
    */
   private static String encodePath(String path) {
      return UriUtils.encodePath(path, StandardCharsets.UTF_8);
   }
}

