public class OpenAPIImporter extends AbstractJsonRepositoryImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(OpenAPIImporter.class);

   private static final List<String> VALID_VERBS = Arrays.asList("get", "put", "post", "delete", "options", "head",
         "patch", "trace");

   private static final String PARAMETERS_NODE = "parameters";
   private static final String PARAMETERS_QUERY_VALUE = "query";
   private static final String CONTENT_NODE = "content";
   private static final String HEADERS_NODE = "headers";
   private static final String EXAMPLES_NODE = "examples";
   private static final String EXAMPLE_VALUE_NODE = "value";

   /**
    * Build a new importer.
    * @param specificationFilePath The path to local OpenAPI spec file
    * @param referenceResolver     An optional resolver for references present into the OpenAPI file
    * @throws IOException if project file cannot be found or read.
    */
   public OpenAPIImporter(String specificationFilePath, ReferenceResolver referenceResolver) throws IOException {
      super(specificationFilePath, referenceResolver);
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      // Build a new service.
      Service service = new Service();
      service.setName(rootSpecification.path("info").path("title").asText());
      service.setVersion(rootSpecification.path("info").path("version").asText());
      service.setType(ServiceType.REST);

      // Complete metadata if specified via extension.
      if (rootSpecification.path("info").has(MetadataExtensions.MICROCKS_EXTENSION)) {
         Metadata metadata = new Metadata();
         MetadataExtractor.completeMetadata(metadata,
               rootSpecification.path("info").path(MetadataExtensions.MICROCKS_EXTENSION));
         service.setMetadata(metadata);
      }

      // Before extraction operations, we need to get and build external reference if we have a resolver.
      initializeReferencedResources(service);

      // Then build its operations.
      service.setOperations(extractOperations());

      result.add(service);
      return result;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) {
      List<Resource> results = new ArrayList<>();

      // Build a suitable name.
      String name = service.getName() + "-" + service.getVersion();
      if (Boolean.TRUE.equals(isYaml)) {
         name += ".yaml";
      } else {
         name += ".json";
      }

      // Build a brand-new resource just with spec content.
      Resource resource = new Resource();
      resource.setName(name);
      resource.setType(ResourceType.OPEN_API_SPEC);
      results.add(resource);
      // Set the content of main OpenAPI that may have been updated with normalized dependencies with initializeReferencedResources().
      resource.setContent(rootSpecificationContent);

      // Add the external resources that were imported during service discovery.
      results.addAll(externalResources);

      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      Map<Request, Response> result = new HashMap<>();

      // Iterate on specification "paths" nodes.
      Iterator<Entry<String, JsonNode>> paths = rootSpecification.path("paths").fields();
      while (paths.hasNext()) {
         Entry<String, JsonNode> path = paths.next();
         String pathName = path.getKey();
         JsonNode pathValue = followRefIfAny(path.getValue());

         // Find examples fragments defined at the path level.
         Map<String, Multimap<String, String>> pathPathParametersByExample = extractParametersByExample(pathValue,
               "path");

         // Iterate on specification path, "verbs" nodes.
         Iterator<Entry<String, JsonNode>> verbs = pathValue.fields();
         while (verbs.hasNext()) {
            Entry<String, JsonNode> verb = verbs.next();
            String verbName = verb.getKey();

            // Find the correct operation.
            if (operation.getName().equals(verbName.toUpperCase() + " " + pathName.trim())) {
               // Find examples fragments defined at the verb level.
               Map<String, Multimap<String, String>> pathParametersByExample = extractParametersByExample(
                     verb.getValue(), "path");
               pathParametersByExample.putAll(pathPathParametersByExample);
               Map<String, Multimap<String, String>> queryParametersByExample = extractParametersByExample(
                     verb.getValue(), PARAMETERS_QUERY_VALUE);
               Map<String, Multimap<String, String>> headerParametersByExample = extractParametersByExample(
                     verb.getValue(), "header");
               Map<String, Request> requestBodiesByExample = extractRequestBodies(verb.getValue());

               // No need to go further if no examples.
               if (verb.getValue().has("responses")) {

                  // If we previously override the dispatcher with a Fallback, we must be sure to get wrapped elements.
                  DispatchCriteriaHelper.DispatcherDetails details = DispatchCriteriaHelper
                        .extractDispatcherWithRules(operation);
                  String rootDispatcher = details.rootDispatcher();
                  String rootDispatcherRules = details.rootDispatcherRules();

                  Iterator<Entry<String, JsonNode>> responseCodes = verb.getValue().path("responses").fields();
                  while (responseCodes.hasNext()) {
                     Entry<String, JsonNode> responseCode = responseCodes.next();
                     Iterator<Entry<String, JsonNode>> contents = getResponseContent(responseCode.getValue()).fields();

                     if (!contents.hasNext() && responseCode.getValue().has("x-microcks-refs")) {
                        result.putAll(getNoContentRequestResponsePair(operation, rootDispatcher, rootDispatcherRules,
                              requestBodiesByExample, pathParametersByExample, queryParametersByExample,
                              headerParametersByExample, responseCode));
                     }
                     while (contents.hasNext()) {
                        Entry<String, JsonNode> content = contents.next();
                        result.putAll(getContentRequestResponsePairs(operation, rootDispatcher, rootDispatcherRules,
                              requestBodiesByExample, pathParametersByExample, queryParametersByExample,
                              headerParametersByExample, responseCode, content));
                     }
                  }
               }
            }
         }
      }

      // Adapt map to list of Exchanges.
      return result.entrySet().stream().map(entry -> new RequestResponsePair(entry.getKey(), entry.getValue()))
            .collect(Collectors.toList());
   }

   /**
    * Extract the list of operations from Specification.
    */
   private List<Operation> extractOperations() {
      List<Operation> results = new ArrayList<>();

      // Iterate on specification "paths" nodes.
      Iterator<Entry<String, JsonNode>> paths = rootSpecification.path("paths").fields();
      while (paths.hasNext()) {
         Entry<String, JsonNode> path = paths.next();
         String pathName = path.getKey();
         JsonNode pathValue = followRefIfAny(path.getValue());

         // Iterate on specification path, "verbs" nodes.
         Iterator<Entry<String, JsonNode>> verbs = pathValue.fields();
         while (verbs.hasNext()) {
            Entry<String, JsonNode> verb = verbs.next();
            String verbName = verb.getKey();

            // Only deal with real verbs for now.
            if (VALID_VERBS.contains(verbName)) {
               String operationName = verbName.toUpperCase() + " " + pathName.trim();

               Operation operation = new Operation();
               operation.setName(operationName);
               operation.setMethod(verbName.toUpperCase());

               // Complete operation properties if any.
               if (verb.getValue().has(MetadataExtensions.MICROCKS_OPERATION_EXTENSION)) {
                  MetadataExtractor.completeOperationProperties(operation,
                        verb.getValue().path(MetadataExtensions.MICROCKS_OPERATION_EXTENSION));
               }

               // Deal with dispatcher stuffs if needed.
               completeOperationWithDispatcher(operation, verb, pathName);

               // Deal with parameter constraints if required parameters.
               completeOperationWithParameterConstraints(operation, verb.getValue());

               results.add(operation);
            }
         }
      }
      return results;
   }

   /** Complete operation with dispatcher rules if not already set. */
   private void completeOperationWithDispatcher(Operation operation, Entry<String, JsonNode> verb, String pathName) {
      if (operation.getDispatcher() == null) {
         if (operationHasParameters(verb.getValue(), PARAMETERS_QUERY_VALUE) && urlHasParts(pathName)) {
            operation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIPattern(pathName) + " ?? "
                  + extractOperationParams(verb.getValue()));
            operation.setDispatcher(DispatchStyles.URI_ELEMENTS);
         } else if (operationHasParameters(verb.getValue(), PARAMETERS_QUERY_VALUE)) {
            operation.setDispatcherRules(extractOperationParams(verb.getValue()));
            operation.setDispatcher(DispatchStyles.URI_PARAMS);
         } else if (urlHasParts(pathName)) {
            operation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIPattern(pathName));
            operation.setDispatcher(DispatchStyles.URI_PARTS);
         } else {
            operation.addResourcePath(pathName);
         }
      } else {
         // If dispatcher has been forced via Metadata, we should still put a generic resourcePath
         // (maybe containing {} parts) to later force operation matching at the mock controller level.
         operation.addResourcePath(pathName);
      }
   }

   /** Add ParameterConstraints to operation if required parameters are found. */
   private void completeOperationWithParameterConstraints(Operation operation, JsonNode operationNode) {
      Iterator<JsonNode> parameters = operationNode.path(PARAMETERS_NODE).elements();
      while (parameters.hasNext()) {
         JsonNode parameter = followRefIfAny(parameters.next());
         boolean required = parameter.path("required").asBoolean(false);
         String location = parameter.path("in").asText();

         if (required && !"path".equals(location)) {
            ParameterConstraint constraint = new ParameterConstraint();
            constraint.setRequired(true);
            constraint.setName(parameter.path("name").asText());
            constraint.setIn(ParameterLocation.valueOf(parameter.path("in").asText()));
            operation.addParameterConstraint(constraint);
         }
      }
   }

   /**
    * Extract parameters within a specification node and organize them by example. Parameter can be of type 'path',
    * 'query', 'header' or 'cookie'. Allow to filter them using parameterType. Key of returned map is example name. Key
    * of value map is param name. Value of value map is param value ;-)
    */
   private Map<String, Multimap<String, String>> extractParametersByExample(JsonNode node, String parameterType) {
      Map<String, Multimap<String, String>> results = new HashMap<>();

      Iterator<JsonNode> parameters = node.path(PARAMETERS_NODE).elements();
      while (parameters.hasNext()) {
         JsonNode parameter = followRefIfAny(parameters.next());
         String parameterName = parameter.path("name").asText();

         if (parameter.has("in") && parameter.path("in").asText().equals(parameterType)
               && parameter.has(EXAMPLES_NODE)) {
            Iterator<String> exampleNames = parameter.path(EXAMPLES_NODE).fieldNames();
            while (exampleNames.hasNext()) {
               String exampleName = exampleNames.next();
               JsonNode example = parameter.path(EXAMPLES_NODE).path(exampleName);
               JsonNode exampleValue = getExampleValue(example);

               if (exampleValue == null) {
                  log.warn("Couldn't find example value for example node: name: {}, data: {}", exampleName, example);
                  continue;
               }

               Multimap<String, String> exampleParams = results.computeIfAbsent(exampleName,
                     k -> ArrayListMultimap.create());

               if (PARAMETERS_QUERY_VALUE.equals(parameterType) && exampleValue.isArray()) {
                  // Array of query params.
                  for (JsonNode current : (ArrayNode) exampleValue) {
                     exampleParams.put(parameterName, getValueString(current));
                  }
               } else if (PARAMETERS_QUERY_VALUE.equals(parameterType) && exampleValue.isObject()) {
                  final var fieldsIterator = ((ObjectNode) exampleValue).fields();
                  while (fieldsIterator.hasNext()) {
                     var current = fieldsIterator.next();
                     exampleParams.put(current.getKey(), getValueString(current.getValue()));
                  }

               } else {
                  exampleParams.put(parameterName, getValueString(exampleValue));
               }
            }
         }
      }
      return results;
   }

   /**
    * Extract request bodies within verb specification and organize them by example. Key of returned map is example
    * name. Value is basic Microcks Request object (no query params, no headers)
    */
   private Map<String, Request> extractRequestBodies(JsonNode verbNode) {
      Map<String, Request> results = new HashMap<>();

      JsonNode requestBody = verbNode.path("requestBody");
      Iterator<String> contentTypeNames = requestBody.path(CONTENT_NODE).fieldNames();
      while (contentTypeNames.hasNext()) {
         String contentTypeName = contentTypeNames.next();
         JsonNode contentType = requestBody.path(CONTENT_NODE).path(contentTypeName);

         if (contentType.has(EXAMPLES_NODE)) {
            Iterator<String> exampleNames = contentType.path(EXAMPLES_NODE).fieldNames();
            while (exampleNames.hasNext()) {
               String exampleName = exampleNames.next();
               JsonNode example = contentType.path(EXAMPLES_NODE).path(exampleName);
               String exampleValue = getSerializedExampleValue(example);

               // Build and store a request object.
               Request request = new Request();
               request.setName(exampleName);
               request.setContent(exampleValue);

               // We should add a Content-type header here for request body.
               Header header = new Header();
               header.setName("Content-Type");
               HashSet<String> values = new HashSet<>();
               values.add(contentTypeName);
               header.setValues(values);
               request.addHeader(header);

               results.put(exampleName, request);
            }
         }
      }
      return results;
   }

   /**
    * Extract headers within a header specification node and organize them by example. Key of returned map is example
    * name. Value is a list of Microcks Header objects.
    */
   private Map<String, List<Header>> extractHeadersByExample(JsonNode responseNode) {
      Map<String, List<Header>> results = new HashMap<>();

      responseNode = followRefIfAny(responseNode);
      if (responseNode.has(HEADERS_NODE)) {
         JsonNode headersNode = responseNode.path(HEADERS_NODE);
         Iterator<String> headerNames = headersNode.fieldNames();

         while (headerNames.hasNext()) {
            String headerName = headerNames.next();
            JsonNode headerNode = headersNode.path(headerName);

            if (headerNode.has(EXAMPLES_NODE)) {
               Iterator<String> exampleNames = headerNode.path(EXAMPLES_NODE).fieldNames();
               while (exampleNames.hasNext()) {
                  String exampleName = exampleNames.next();
                  JsonNode example = headerNode.path(EXAMPLES_NODE).path(exampleName);
                  String exampleValue = getSerializedExampleValue(example);

                  List<Header> headersForExample = results.computeIfAbsent(exampleName, k -> new ArrayList<>());

                  // Example may be multiple CSV.
                  Set<String> values = Arrays.stream(exampleValue.split(",")).map(String::trim)
                        .collect(Collectors.toSet());

                  Header header = new Header();
                  header.setName(headerName);
                  header.setValues(values);

                  headersForExample.add(header);
                  results.put(exampleName, headersForExample);
               }
            }
         }
      }
      return results;
   }

   /**
    * Get the request/response pairs for a response content.
    */
   private Map<Request, Response> getContentRequestResponsePairs(Operation operation, String rootDispatcher,
         String rootDispatcherRules, Map<String, Request> requestBodiesByExample,
         Map<String, Multimap<String, String>> pathParametersByExample,
         Map<String, Multimap<String, String>> queryParametersByExample,
         Map<String, Multimap<String, String>> headerParametersByExample, Entry<String, JsonNode> responseCode,
         Entry<String, JsonNode> content) {

      Map<Request, Response> results = new HashMap<>();

      String contentValue = content.getKey();
      // Find here potential headers for output of this operation examples.
      Map<String, List<Header>> headersByExample = extractHeadersByExample(responseCode.getValue());

      JsonNode examplesNode = followRefIfAny(content.getValue().path(EXAMPLES_NODE));

      Iterator<String> exampleNames = examplesNode.fieldNames();
      while (exampleNames.hasNext()) {
         String exampleName = exampleNames.next();
         JsonNode example = examplesNode.path(exampleName);

         // We should have everything at hand to build response here.
         Response response = new Response();
         response.setName(exampleName);
         response.setMediaType(contentValue);
         response.setStatus(responseCode.getKey());
         response.setContent(getSerializedExampleValue(example));
         if (!responseCode.getKey().startsWith("2")) {
            response.setFault(true);
         }
         List<Header> responseHeaders = headersByExample.get(exampleName);
         if (responseHeaders != null) {
            responseHeaders.stream().forEach(response::addHeader);
         }

         // Do we have a request for this example?
         Request request = requestBodiesByExample.get(exampleName);
         if (request == null) {
            request = new Request();
            request.setName(exampleName);
         }

         // Complete request accept-type with response content-type.
         Header header = new Header();
         header.setName("Accept");
         HashSet<String> values = new HashSet<>();
         values.add(contentValue);
         header.setValues(values);
         request.addHeader(header);

         // Do we have to complete request with path parameters?
         Multimap<String, String> pathParameters = pathParametersByExample.get(exampleName);
         if (pathParameters != null) {
            completeRequestWithPathParameters(request, pathParameters);
         } else if (DispatchStyles.URI_PARTS.equals(operation.getDispatcher())
               || DispatchStyles.URI_ELEMENTS.equals(operation.getDispatcher())) {
            // We must have at least one path parameters but none!
            // Do not register this request / response pair.
            break;
         }

         // Complete request with query parameters if any.
         completeRequestWithQueryParameters(request, queryParametersByExample.get(exampleName));
         // Complete request with header parameters if any.
         completeRequestWithHeaderParameters(request, headerParametersByExample.get(exampleName));

         // Finally, take care about dispatchCriteria and complete operation resourcePaths.
         completeDispatchCriteriaAndResourcePaths(operation, rootDispatcher, rootDispatcherRules,
               pathParametersByExample, queryParametersByExample, headerParametersByExample, exampleName, response);

         results.put(request, response);
      }

      return results;
   }

   /**
    * Get the request/response pairs for a response without content. A response without content has a x-microcks-refs
    * property to get bounds to requests.
    */
   private Map<Request, Response> getNoContentRequestResponsePair(Operation operation, String rootDispatcher,
         String rootDispatcherRules, Map<String, Request> requestBodiesByExample,
         Map<String, Multimap<String, String>> pathParametersByExample,
         Map<String, Multimap<String, String>> queryParametersByExample,
         Map<String, Multimap<String, String>> headerParametersByExample, Entry<String, JsonNode> responseCode) {

      Map<Request, Response> results = new HashMap<>();
      JsonNode requestRefs = responseCode.getValue().path("x-microcks-refs");

      if (requestRefs.isArray()) {
         // Find here potential headers for output of this operation examples.
         Map<String, List<Header>> headersByExample = extractHeadersByExample(responseCode.getValue());

         Iterator<JsonNode> requestRefsIterator = requestRefs.elements();
         while (requestRefsIterator.hasNext()) {
            String exampleName = requestRefsIterator.next().textValue();

            // Do we have a request or path or query or header parameters?
            Request request = requestBodiesByExample.get(exampleName);
            Multimap<String, String> pathParameters = pathParametersByExample.get(exampleName);
            Multimap<String, String> queryParameters = queryParametersByExample.get(exampleName);
            Multimap<String, String> headerParameters = headerParametersByExample.get(exampleName);

            if (request != null || pathParameters != null || queryParameters != null || headerParameters != null) {
               if (request == null) {
                  request = new Request();
                  request.setName(exampleName);
               }

               if (pathParameters != null) {
                  completeRequestWithPathParameters(request, pathParameters);
               } else if (DispatchStyles.URI_PARTS.equals(operation.getDispatcher())
                     || DispatchStyles.URI_ELEMENTS.equals(operation.getDispatcher())) {
                  // We must have at least one path parameters but none!
                  // Do not register this request / response pair.
                  break;
               }

               // We should have everything at hand to build response here.
               Response response = new Response();
               response.setName(exampleName);
               response.setStatus(responseCode.getKey());
               if (!responseCode.getKey().startsWith("2")) {
                  response.setFault(true);
               }
               List<Header> responseHeaders = headersByExample.get(exampleName);
               if (responseHeaders != null) {
                  responseHeaders.stream().forEach(response::addHeader);
               }

               // Complete request with query parameters if any.
               completeRequestWithQueryParameters(request, queryParametersByExample.get(exampleName));
               // Complete request with header parameters if any.
               completeRequestWithHeaderParameters(request, headerParametersByExample.get(exampleName));

               // Finally, take care about dispatchCriteria and complete operation resourcePaths.
               completeDispatchCriteriaAndResourcePaths(operation, rootDispatcher, rootDispatcherRules,
                     pathParametersByExample, queryParametersByExample, headerParametersByExample, exampleName,
                     response);

               results.put(request, response);
            }
         }
      }
      return results;
   }

   private void completeRequestWithPathParameters(Request request, Multimap<String, String> pathParameters) {
      for (Entry<String, String> paramEntry : pathParameters.entries()) {
         Parameter param = new Parameter();
         param.setName(paramEntry.getKey());
         param.setValue(paramEntry.getValue());
         request.addQueryParameter(param);
      }
   }

   private void completeRequestWithQueryParameters(Request request, Multimap<String, String> queryParameters) {
      if (queryParameters != null) {
         for (Entry<String, String> paramEntry : queryParameters.entries()) {
            Parameter param = new Parameter();
            param.setName(paramEntry.getKey());
            param.setValue(paramEntry.getValue());
            request.addQueryParameter(param);
         }
      }
   }

   private void completeRequestWithHeaderParameters(Request request, Multimap<String, String> headerParameters) {
      if (headerParameters != null) {
         for (Entry<String, String> headerEntry : headerParameters.entries()) {
            Header header = new Header();
            header.setName(headerEntry.getKey());
            // Values may be multiple and CSV.
            Set<String> headerValues = Arrays.stream(headerEntry.getValue().split(",")).map(String::trim)
                  .collect(Collectors.toSet());
            header.setValues(headerValues);
            request.addHeader(header);
         }
      }
   }

   private void completeDispatchCriteriaAndResourcePaths(Operation operation, String rootDispatcher,
         String rootDispatcherRules, Map<String, Multimap<String, String>> pathParametersByExample,
         Map<String, Multimap<String, String>> queryParametersByExample,
         Map<String, Multimap<String, String>> headerParametersByExample, String exampleName, Response response) {
      String dispatchCriteria = null;
      String resourcePathPattern = operation.getName().split(" ")[1];

      if (DispatchStyles.URI_PARAMS.equals(rootDispatcher)) {
         Multimap<String, String> queryParams = queryParametersByExample.get(exampleName);
         dispatchCriteria = DispatchCriteriaHelper.buildFromParamsMap(rootDispatcherRules, queryParams);
         // We only need the pattern here.
         operation.addResourcePath(resourcePathPattern);
      } else if (DispatchStyles.URI_PARTS.equals(rootDispatcher)) {
         Multimap<String, String> parts = pathParametersByExample.get(exampleName);
         dispatchCriteria = DispatchCriteriaHelper.buildFromPartsMap(rootDispatcherRules, parts);
         // We should complete resourcePath here.
         String resourcePath = URIBuilder.buildURIFromPattern(resourcePathPattern, parts);
         operation.addResourcePath(resourcePath);
      } else if (DispatchStyles.URI_ELEMENTS.equals(rootDispatcher)) {
         Multimap<String, String> parts = pathParametersByExample.get(exampleName);
         Multimap<String, String> queryParams = queryParametersByExample.get(exampleName);
         dispatchCriteria = DispatchCriteriaHelper.buildFromPartsMap(rootDispatcherRules, parts);
         dispatchCriteria += DispatchCriteriaHelper.buildFromParamsMap(rootDispatcherRules, queryParams);
         // We should complete resourcePath here.
         String resourcePath = URIBuilder.buildURIFromPattern(resourcePathPattern, parts);
         operation.addResourcePath(resourcePath);
      } else if (DispatchStyles.QUERY_HEADER.equals(rootDispatcher)) {
         Multimap<String, String> headerParams = headerParametersByExample.get(exampleName);
         dispatchCriteria = DispatchCriteriaHelper.buildFromParamsMap(rootDispatcherRules, headerParams);
         // We only need the pattern here.
         operation.addResourcePath(resourcePathPattern);
      }
      response.setDispatchCriteria(dispatchCriteria);
   }

   /** Get the value of an example. This can be direct value field or those of followed $ref */
   private JsonNode getExampleValue(JsonNode example) {
      if (example.has(EXAMPLE_VALUE_NODE)) {
         return followRefIfAny(example.path(EXAMPLE_VALUE_NODE));
      }
      if (example.has("$ref")) {
         JsonNode component = followRefIfAny(example);
         return getExampleValue(component);
      }
      return null;
   }

   /** Get the serialized value of an example. This can be direct value field or those of followed $ref */
   private String getSerializedExampleValue(JsonNode example) {
      JsonNode exampleValue = getExampleValue(example);
      return exampleValue != null ? getValueString(exampleValue) : null;
   }

   /** Get the content of a response. This can be direct content field or those of followed $ref */
   private JsonNode getResponseContent(JsonNode response) {
      if (response.has("$ref")) {
         JsonNode component = followRefIfAny(response);
         return getResponseContent(component);
      }
      return response.path(CONTENT_NODE);
   }

   /** Build a string representing operation parameters as used in dispatcher rules (param1 && param2) */
   private String extractOperationParams(JsonNode operation) {
      StringBuilder params = new StringBuilder();
      Iterator<JsonNode> parameters = operation.path(PARAMETERS_NODE).elements();
      while (parameters.hasNext()) {
         JsonNode parameter = followRefIfAny(parameters.next());
         String parameterIn = parameter.path("in").asText();
         String parameterType = followRefIfAny(parameter.path("schema")).path("type").asText();
         if (!"path".equals(parameterIn)) {
            if (params.length() > 0) {
               params.append(" && ");
            }
            if (parameterType.equals("object")) {
               params.append(StreamSupport.stream(Spliterators.spliteratorUnknownSize(
                     followRefIfAny(parameter.path("schema")).path("properties").fieldNames(), Spliterator.ORDERED),
                     false).collect(Collectors.joining(" && ")));
            } else {
               params.append(parameter.path("name").asText());
            }
         }
      }
      return params.toString();
   }

   /** Check parameters presence into given operation node. */
   private boolean operationHasParameters(JsonNode operation, String parameterType) {
      if (!operation.has(PARAMETERS_NODE)) {
         return false;
      }
      Iterator<JsonNode> parameters = operation.path(PARAMETERS_NODE).elements();
      while (parameters.hasNext()) {
         JsonNode parameter = followRefIfAny(parameters.next());

         String parameterIn = parameter.path("in").asText();
         if (parameterIn.equals(parameterType)) {
            return true;
         }
      }
      return false;
   }

   /** Check variables parts presence into given url. */
   private static boolean urlHasParts(String url) {
      return (url.indexOf("/:") != -1 || url.indexOf("/{") != -1);
   }
}

public class PostmanCollectionImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(PostmanCollectionImporter.class);

   /** Postman collection property that references service version property. */
   public static final String SERVICE_VERSION_PROPERTY = "version";
   /** We only support Postman Collection v2. Here's the error message otherwise. */
   public static final String COLLECTION_VERSION_ERROR_MESSAGE = "Only Postman v2 Collection are supported.";

   private static final String INFO_NODE = "info";
   private static final String REQUEST_NODE = "request";
   private static final String RESPONSE_NODE = "response";
   private static final String QUERY_NODE = "query";
   private static final String VARIABLE_NODE = "variable";
   private static final String GRAPHQL_NODE = "graphql";
   private static final String VARIABLES_NODE = "variables";
   private static final String VALUE_NODE = "value";

   private ObjectMapper mapper;
   private JsonNode collection;
   private String collectionContent;
   // Flag telling if V2 format is used.
   private boolean isV2Collection = false;

   /** Default constructor for package protected extensions. */
   protected PostmanCollectionImporter() {
   }

   /**
    * Build a new importer.
    * @param collectionFilePath The path to local Postman collection file
    * @throws IOException if project file cannot be found or read.
    */
   public PostmanCollectionImporter(String collectionFilePath) throws IOException {
      try {
         // Read Json bytes.
         byte[] jsonBytes = Files.readAllBytes(Paths.get(collectionFilePath));
         collectionContent = new String(jsonBytes, StandardCharsets.UTF_8);
         // Convert them to Node using Jackson object mapper.
         mapper = new ObjectMapper();
         collection = mapper.readTree(jsonBytes);
      } catch (Exception e) {
         log.error("Exception while parsing Postman collection file " + collectionFilePath, e);
         throw new IOException("Postman collection file parsing error");
      }
   }

   protected void setCollection(JsonNode collection) {
      this.collection = collection;
   }

   protected void setCollectionContent(String collectionContent) {
      this.collectionContent = collectionContent;
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      // Build a new service.
      Service service = new Service();

      // Collection V2 as an info node.
      if (collection.has(INFO_NODE)) {
         isV2Collection = true;
         fillServiceDefinition(service);
      } else {
         throw new MockRepositoryImportException(COLLECTION_VERSION_ERROR_MESSAGE);
      }

      // Then build its operations.
      try {
         service.setOperations(extractOperations());
      } catch (Throwable t) {
         log.error("Runtime exception while extracting Operations for {}", service.getName());
         throw new MockRepositoryImportException("Runtime exception for " + service.getName() + ": " + t.getMessage());
      }

      result.add(service);
      return result;
   }

   private void fillServiceDefinition(Service service) throws MockRepositoryImportException {
      JsonNode infoNode = collection.path(INFO_NODE);
      service.setName(infoNode.path("name").asText());
      service.setType(ServiceType.REST);

      String version = null;

      // On v2.1 collection format, we may have a version attribute under info.
      // See https://schema.getpostman.com/json/collection/v2.1.0/docs/index.html
      if (infoNode.has(SERVICE_VERSION_PROPERTY)) {
         version = extractStructuredVersion(infoNode.path(SERVICE_VERSION_PROPERTY));
      } else {
         String description = infoNode.path("description").asText();
         if (description != null && description.contains(SERVICE_VERSION_PROPERTY + "=")) {
            description = description.substring(description.indexOf(SERVICE_VERSION_PROPERTY + "="));
            if (description.indexOf(' ') > -1) {
               description = description.substring(0, description.indexOf(' '));
            }
            if (description.split("=").length > 1) {
               version = description.split("=")[1];
            }
         }
      }

      if (version == null) {
         log.error(
               "Version property is missing in Collection. Use either 'version' for v2.1 Collection or 'version=x.y - something' description syntax.");
         throw new MockRepositoryImportException("Version property is missing in Collection description");
      }
      service.setVersion(version);
   }

   private String extractStructuredVersion(JsonNode versionNode) {
      String version = null;
      if (versionNode.has("identifier")) {
         version = versionNode.path("identifier").asText();
      } else if (versionNode.has("major") && versionNode.has("minor") && versionNode.has("patch")) {
         version = versionNode.path("major").asText();
         version += "." + versionNode.path("minor").asText();
         version += "." + versionNode.path("patch").asText();
      } else {
         version = versionNode.asText();
      }
      return version;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) {
      List<Resource> results = new ArrayList<>();

      // Build a suitable name.
      String name = service.getName() + "-" + service.getVersion() + ".json";

      Resource resource = new Resource();
      resource.setName(name);
      resource.setType(ResourceType.POSTMAN_COLLECTION);
      resource.setContent(collectionContent);
      results.add(resource);

      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {

      if (isV2Collection) {
         return getMessageDefinitionsV2(service, operation);
      } else {
         throw new MockRepositoryImportException(COLLECTION_VERSION_ERROR_MESSAGE);
      }
   }

   private List<Exchange> getMessageDefinitionsV2(Service service, Operation operation) {
      Map<Request, Response> result = new HashMap<>();

      Iterator<JsonNode> items = collection.path("item").elements();
      while (items.hasNext()) {
         JsonNode item = items.next();
         result.putAll(getMessageDefinitionsV2("", item, operation));
      }

      // Adapt map to list of Exchanges.
      return result.entrySet().stream().map(entry -> new RequestResponsePair(entry.getKey(), entry.getValue()))
            .collect(Collectors.toList());
   }

   private Map<Request, Response> getMessageDefinitionsV2(String folderName, JsonNode itemNode, Operation operation) {
      log.debug("Extracting message definitions in folder {}", folderName);
      Map<Request, Response> result = new HashMap<>();
      String itemNodeName = itemNode.path("name").asText();

      if (!itemNode.has(REQUEST_NODE)) {
         // Item is simply a folder that may contain some other folders recursively.
         Iterator<JsonNode> items = itemNode.path("item").elements();
         while (items.hasNext()) {
            JsonNode item = items.next();
            result.putAll(getMessageDefinitionsV2(folderName + "/" + itemNodeName, item, operation));
         }
      } else {
         // Item is here an operation description.
         String operationName = buildOperationName(itemNode, folderName);

         // Select item based onto operation name.
         if (PostmanUtil.areOperationsEquivalent(operation.getName(), operationName)) {
            // If we previously override the dispatcher with a Fallback, we must be sure to get wrapped elements.
            DispatchCriteriaHelper.DispatcherDetails details = DispatchCriteriaHelper
                  .extractDispatcherWithRules(operation);
            String rootDispatcher = details.rootDispatcher();
            String rootDispatcherRules = details.rootDispatcherRules();

            Iterator<JsonNode> responses = itemNode.path(RESPONSE_NODE).elements();
            while (responses.hasNext()) {
               JsonNode responseNode = responses.next();
               JsonNode requestNode = responseNode.path("originalRequest");

               // Build dispatchCriteria and complete operation resourcePaths.
               String dispatchCriteria = null;
               String requestUrl = requestNode.path("url").path("raw").asText();

               if (DispatchStyles.URI_PARAMS.equals(rootDispatcher)) {
                  dispatchCriteria = DispatchCriteriaHelper.extractFromURIParams(operation.getDispatcherRules(),
                        requestUrl);
                  // We only need the pattern here.
                  operation.addResourcePath(extractResourcePath(requestUrl, null));
               } else if (DispatchStyles.URI_PARTS.equals(rootDispatcher)) {
                  Map<String, String> parts = buildRequestParts(requestNode);
                  dispatchCriteria = DispatchCriteriaHelper.buildFromPartsMap(rootDispatcherRules, parts);
                  // We should complete resourcePath here.
                  String resourcePath = extractResourcePath(requestUrl, null);
                  operation.addResourcePath(URIBuilder.buildURIFromPattern(resourcePath, parts));
               } else if (DispatchStyles.URI_ELEMENTS.equals(rootDispatcher)) {
                  Map<String, String> parts = buildRequestParts(requestNode);
                  dispatchCriteria = DispatchCriteriaHelper.buildFromPartsMap(rootDispatcherRules, parts);
                  dispatchCriteria += DispatchCriteriaHelper.extractFromURIParams(rootDispatcherRules, requestUrl);
                  // We should complete resourcePath here.
                  String resourcePath = extractResourcePath(requestUrl, null);
                  operation.addResourcePath(URIBuilder.buildURIFromPattern(resourcePath, parts));
               } else if (DispatchStyles.QUERY_HEADER.equals(rootDispatcher)) {
                  Map<String, String> paramsMap = buildRequestHeaders(requestNode);
                  dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(rootDispatcherRules, paramsMap);
                  // We only need the pattern here.
                  operation.addResourcePath(extractResourcePath(requestUrl, null));
               } else if (DispatchStyles.QUERY_ARGS.equals(rootDispatcher)) {
                  // This dispatcher is used for GraphQL
                  if (requestNode.path("body").has(GRAPHQL_NODE)) {
                     // We must transform JSON representing variables into a Map<String, String>
                     // before building a dispatchCriteria matching the rules.
                     String variables = requestNode.path("body").path(GRAPHQL_NODE).path(VARIABLES_NODE).asText();
                     dispatchCriteria = extractQueryArgsCriteria(rootDispatcherRules, variables);
                  }
                  // or for gRPC.
                  if (requestNode.path("body").has("raw")) {
                     String variables = requestNode.path("body").path("raw").asText();
                     dispatchCriteria = extractQueryArgsCriteria(rootDispatcherRules, variables);
                  }

               } else {
                  // If dispatcher has been overriden (to SCRIPT for example), we should still put a generic resourcePath
                  // (maybe containing : parts) to later force operation matching at the mock controller level. Only do that
                  // when request url is not empty (means not the root url like POST /order).
                  if (requestUrl != null && !requestUrl.isEmpty()) {
                     operation.addResourcePath(extractResourcePath(requestUrl, null));
                     log.debug("Added operation generic resource path: {}", operation.getResourcePaths());
                  }
               }

               Request request = buildRequest(requestNode, responseNode.path("name").asText());
               Response response = buildResponse(responseNode, dispatchCriteria);
               result.put(request, response);
            }
         }
      }
      return result;
   }

   private Request buildRequest(JsonNode requestNode, String name) {
      Request request = new Request();
      request.setName(name);

      if (isV2Collection) {
         request.setHeaders(buildHeaders(requestNode.path("header")));
         if (requestNode.has("body") && requestNode.path("body").has("raw")) {
            request.setContent(requestNode.path("body").path("raw").asText());
         } else if (requestNode.has("body") && requestNode.path("body").has(GRAPHQL_NODE)) {
            // We got to rebuild a specific HTTP request for GraphQL.
            String query = requestNode.path("body").path(GRAPHQL_NODE).path(QUERY_NODE).asText();
            String variables = requestNode.path("body").path(GRAPHQL_NODE).path(VARIABLES_NODE).asText();
            // Initialize with query field.
            StringBuilder requestContent = new StringBuilder("{\"query\": \"").append(query.replace("\n", "\\n"))
                  .append("\"");

            try {
               // See if we have to add variables.
               JsonNode variablesNode = mapper.readTree(variables);
               if (variablesNode.isObject() && !variablesNode.isEmpty()) {
                  requestContent.append(", \"variables\": ").append(variables);
               }
            } catch (JsonProcessingException jpe) {
               log.warn("Json processing excpetion while parsing GraphQL variables, ignoring them: {}",
                     jpe.getMessage());
            }
            requestContent.append("}");
            request.setContent(requestContent.toString());
         }
         if (requestNode.path("url").has(VARIABLE_NODE)) {
            JsonNode variablesNode = requestNode.path("url").path(VARIABLE_NODE);
            for (JsonNode variableNode : variablesNode) {
               Parameter param = new Parameter();
               param.setName(variableNode.path("key").asText());
               param.setValue(variableNode.path(VALUE_NODE).asText());
               request.addQueryParameter(param);
            }
         }
         if (requestNode.path("url").has(QUERY_NODE)) {
            JsonNode queryNode = requestNode.path("url").path(QUERY_NODE);
            for (JsonNode variableNode : queryNode) {
               Parameter param = new Parameter();
               param.setName(variableNode.path("key").asText());
               param.setValue(variableNode.path(VALUE_NODE).asText());
               request.addQueryParameter(param);
            }
         }
      } else {
         request.setHeaders(buildHeaders(requestNode.path("headers")));
      }
      return request;
   }

   private Map<String, String> buildRequestParts(JsonNode requestNode) {
      Map<String, String> parts = new HashMap<>();
      if (requestNode.has("url") && requestNode.path("url").has(VARIABLE_NODE)) {
         Iterator<JsonNode> variables = requestNode.path("url").path(VARIABLE_NODE).elements();
         while (variables.hasNext()) {
            JsonNode variable = variables.next();
            parts.put(variable.path("key").asText(), variable.path(VALUE_NODE).asText());
         }
      }
      return parts;
   }

   private Map<String, String> buildRequestHeaders(JsonNode requestNode) {
      Map<String, String> headers = new HashMap<>();
      if (requestNode.has("header")) {
         Iterator<JsonNode> headerNodes = requestNode.path("header").elements();
         while (headerNodes.hasNext()) {
            JsonNode headerNode = headerNodes.next();
            headers.put(headerNode.path("key").asText(), headerNode.path(VALUE_NODE).asText());
         }
      }
      return headers;
   }

   private String extractQueryArgsCriteria(String dispatcherRules, String variables) {
      String dispatchCriteria = "";
      try {
         Map<String, String> paramsMap = mapper.readValue(variables,
               TypeFactory.defaultInstance().constructMapType(TreeMap.class, String.class, String.class));
         dispatchCriteria = DispatchCriteriaHelper.extractFromParamMap(dispatcherRules, paramsMap);
      } catch (Exception e) {
         log.error("Exception while extracting dispatch criteria from JSON body: {}", e.getMessage());
      }
      return dispatchCriteria;
   }

   private Response buildResponse(JsonNode responseNode, String dispatchCriteria) {
      Response response = new Response();
      response.setName(responseNode.path("name").asText());

      if (isV2Collection) {
         response.setStatus(responseNode.path("code").asText("200"));
         response.setHeaders(buildHeaders(responseNode.path("header")));
         response.setContent(responseNode.path("body").asText(""));
      } else {
         response.setStatus(responseNode.path("responseCode").path("code").asText());
         response.setHeaders(buildHeaders(responseNode.path("headers")));
         response.setContent(responseNode.path("text").asText());
      }
      if (response.getHeaders() != null) {
         for (Header header : response.getHeaders()) {
            if (header.getName().equalsIgnoreCase("Content-Type")) {
               response.setMediaType(header.getValues().toArray(new String[] {})[0]);
            }
         }
      }
      // For V1 Collection, if no Content-Type header but response expressed as a language,
      // assume it is its content-type.
      if (!isV2Collection && response.getMediaType() == null) {
         if ("json".equals(responseNode.path("language").asText())) {
            response.setMediaType("application/json");
         }
      }
      // For V2 Collection, if no Content-Type header but response expressed as a language,
      // assume it is its content-type.
      if (isV2Collection && response.getMediaType() == null) {
         if ("json".equals(responseNode.path("_postman_previewlanguage").asText())) {
            response.setMediaType("application/json");
         } else if ("xml".equals(responseNode.path("_postman_previewlanguage").asText())) {
            response.setMediaType("text/xml");
         }
      }
      response.setDispatchCriteria(dispatchCriteria);
      return response;
   }

   private Set<Header> buildHeaders(JsonNode headerNode) {
      if (headerNode == null || headerNode.isEmpty()) {
         return null;
      }

      // Prepare and map the set of headers.
      Set<Header> headers = new HashSet<>();
      Iterator<JsonNode> items = headerNode.elements();
      while (items.hasNext()) {
         JsonNode item = items.next();
         Header header = new Header();
         header.setName(item.path("key").asText());
         Set<String> values = new HashSet<>();
         values.add(item.path(VALUE_NODE).asText());
         header.setValues(values);
         headers.add(header);
      }
      return headers;
   }

   /** Extract the list of operations from Collection. */
   private List<Operation> extractOperations() throws MockRepositoryImportException {
      if (isV2Collection) {
         return extractOperationsV2();
      }
      throw new MockRepositoryImportException(COLLECTION_VERSION_ERROR_MESSAGE);
   }

   private List<Operation> extractOperationsV2() {
      // Items corresponding to same operations may be defined multiple times in Postman
      // with different names and resource path. We have to track them to complete them in second step.
      Map<String, Operation> collectedOperations = new HashMap<>();

      Iterator<JsonNode> items = collection.path("item").elements();
      while (items.hasNext()) {
         JsonNode item = items.next();
         extractOperationV2("", item, collectedOperations);
      }

      return new ArrayList<>(collectedOperations.values());
   }

   private void extractOperationV2(String folderName, JsonNode itemNode, Map<String, Operation> collectedOperations) {
      log.debug("Extracting operation in folder {}", folderName);
      String itemNodeName = itemNode.path("name").asText();

      // Item may be a folder or an operation description.
      if (!itemNode.has(REQUEST_NODE)) {
         // Item is simply a folder that may contain some other folders recursively.
         Iterator<JsonNode> items = itemNode.path("item").elements();
         while (items.hasNext()) {
            JsonNode item = items.next();
            extractOperationV2(folderName + "/" + itemNodeName, item, collectedOperations);
         }
      } else {
         // Item is here an operation description.
         String operationName = buildOperationName(itemNode, folderName);
         Operation operation = collectedOperations.get(operationName);
         String url = itemNode.path(REQUEST_NODE).path("url").asText("");
         if ("".equals(url)) {
            url = itemNode.path(REQUEST_NODE).path("url").path("raw").asText("");
         }

         // Collection may have been used for testing so it may contain a valid URL with prefix that will bother us.
         // Ex: http://localhost:8080/prefix1/prefix2/order/123456 or http://petstore.swagger.io/v2/pet/1. Trim it.
         if (url.contains(folderName + "/")) {
            url = removeProtocolAndHostPort(url);
         }

         if (operation == null) {
            // Build a new operation.
            operation = new Operation();
            operation.setName(operationName);

            // Complete with REST specific fields.
            operation.setMethod(itemNode.path(REQUEST_NODE).path("method").asText());

            // Deal with dispatcher stuffs.
            if (urlHasParameters(url) && urlHasParts(url)) {
               operation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIPattern(url) + " ?? "
                     + DispatchCriteriaHelper.extractParamsFromURI(url));
               operation.setDispatcher(DispatchStyles.URI_ELEMENTS);
            } else if (urlHasParameters(url)) {
               operation.setDispatcherRules(DispatchCriteriaHelper.extractParamsFromURI(url));
               operation.setDispatcher(DispatchStyles.URI_PARAMS);
               operation.addResourcePath(extractResourcePath(url, null));
            } else if (urlHasParts(url)) {
               operation.setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIPattern(url));
               operation.setDispatcher(DispatchStyles.URI_PARTS);
            } else {
               operation.addResourcePath(extractResourcePath(url, null));
               log.debug("Added operation generic resource path: {}", operation.getResourcePaths());
            }
         }

         // Do not deal with resource path now as it will be done when extracting messages.
         collectedOperations.put(operationName, operation);
      }
   }

   /**
    * Build a coherent operation name from the JsonNode of collection representing operation (ie. having a request item)
    * and an operationNameRadix (ie. a subcontext or nested subcontext folder where operation is stored).
    * @param operationNode JSON node for operation
    * @param folderName    String representing radix of operation name
    * @return Operation name
    */
   public static String buildOperationName(JsonNode operationNode, String folderName) {
      String url = operationNode.path(REQUEST_NODE).path("url").asText("");
      if ("".equals(url)) {
         url = operationNode.path(REQUEST_NODE).path("url").path("raw").asText();
      }

      // New way of computing operation name.
      if (url.indexOf('?') != -1) {
         // Remove query parameters.
         url = url.substring(0, url.indexOf('?'));
      }
      // Remove protocol pragma and host/port stuffs.
      url = removeProtocolAndHostPort(url);
      return operationNode.path(REQUEST_NODE).path("method").asText() + " " + url;
   }

   /**
    * Extract a resource path from a complete url and an optional operationName radix (context or subcontext).
    * https://petstore-api-2445581593402.apicast.io:443/v2/pet/findByStatus?user_key=998bac0775b1d5f588e0a6ca7c11b852&status=available
    * => /v2/pet/findByStatus if no operationNameRadix => /pet/findByStatus if operationNameRadix=/pet
    */
   private String extractResourcePath(String url, String operationNameRadix) {
      // Remove protocol, host and port specification.
      String result = removeProtocolAndHostPort(url);
      // Remove trailing parameters.
      if (result.indexOf('?') != -1) {
         result = result.substring(0, result.indexOf('?'));
      }
      // Remove prefix of radix if specified.
      if (operationNameRadix != null && result.contains(operationNameRadix)) {
         result = result.substring(result.indexOf(operationNameRadix));
      }
      // Remove trailing / if present.
      if (result.endsWith("/")) {
         result = result.substring(0, result.length() - 1);
      }
      return result;
   }

   /** Check parameters presence into given url. */
   private static boolean urlHasParameters(String url) {
      return url.indexOf('?') != -1 && url.indexOf('=') != -1;
   }

   /** Check variables parts presence into given url. */
   private static boolean urlHasParts(String url) {
      return url.indexOf("/:") != -1;
   }

   private static String removeProtocolAndHostPort(String url) {
      if (url.startsWith("https://")) {
         url = url.substring("https://".length());
      }
      if (url.startsWith("http://")) {
         url = url.substring("http://".length());
      }
      // Remove host and port specification if any.
      if (url.indexOf('/') != -1) {
         url = url.substring(url.indexOf('/'));
      }
      return url;
   }
}

public class PostmanWorkspaceCollectionImporter extends PostmanCollectionImporter {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(PostmanWorkspaceCollectionImporter.class);

   private static final String COLLECTION_WRAPPER_PROPERTY = "collection";

   /**
    * Build a new importer.
    * @param collectionFilePath The path to local Postman collection file
    * @throws IOException if project file cannot be found or read.
    */
   public PostmanWorkspaceCollectionImporter(String collectionFilePath) throws IOException {
      super();
      try {
         // Read Json bytes.
         byte[] jsonBytes = Files.readAllBytes(Paths.get(collectionFilePath));
         setCollectionContent(new String(jsonBytes, StandardCharsets.UTF_8));
         // Convert them to Node using Jackson object mapper.
         ObjectMapper mapper = new ObjectMapper();
         JsonNode collectionWrapper = mapper.readTree(jsonBytes);
         setCollection(collectionWrapper.path(COLLECTION_WRAPPER_PROPERTY));
      } catch (Exception e) {
         log.error("Exception while parsing Postman workspace collection file " + collectionFilePath, e);
         throw new IOException("Postman workspace collection file parsing error");
      }
   }
}

public class SoapUIProjectImporter implements MockRepositoryImporter {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(SoapUIProjectImporter.class);

   /** SoapUI project property that references service version property. */
   public static final String SERVICE_VERSION_PROPERTY = "version";

   protected static final String NAME_ATTRIBUTE = "name";
   protected static final String ELEMENT_ATTRIBUTE = "element";
   protected static final String MOCK_SERVICE_TAG = "mockService";
   protected static final String REST_MOCK_SERVICE_TAG = "restMockService";
   protected static final String MOCK_OPERATION_TAG = "mockOperation";
   protected static final String REST_MOCK_ACTION_TAG = "restMockAction";
   protected static final String QUERY_TAG = "query";
   protected static final String REQUEST_TAG = "request";
   protected static final String RESPONSE_TAG = "response";
   protected static final String CONTENT_TAG = "content";
   protected static final String VALUE_TAG = "value";

   private final String projectContent;
   private final DocumentBuilder documentBuilder;
   private final Element projectElement;

   private final Map<String, Element> interfaces = new HashMap<>();

   private Element serviceInterface;

   /**
    * Build a new importer.
    * @param projectFilePath The path to local SoapUI project file
    * @throws IOException if project file cannot be found
    */
   public SoapUIProjectImporter(String projectFilePath) throws IOException {
      try {
         // Read project content as string.
         byte[] projectBytes = Files.readAllBytes(Paths.get(projectFilePath));
         projectContent = new String(projectBytes, StandardCharsets.UTF_8);
         // Then parse it to get DOM root Element.
         DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
         factory.setNamespaceAware(true);
         documentBuilder = factory.newDocumentBuilder();
         projectElement = documentBuilder.parse(new InputSource(new StringReader(projectContent))).getDocumentElement();
      } catch (Exception e) {
         log.error("Exception while parsing SoapUI file {}", projectFilePath, e);
         throw new IOException("SoapUI project file parsing error");
      }
   }

   @Override
   public List<Service> getServiceDefinitions() throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      List<Element> interfaceNodes = getConfigDirectChildren(projectElement, "interface");
      for (Element interfaceNode : interfaceNodes) {
         // Filter complete interface definition with name as attribute.
         if (interfaceNode.getAttribute(NAME_ATTRIBUTE) != null) {
            log.info("Found a service interface named: {}", interfaceNode.getAttribute(NAME_ATTRIBUTE));
            interfaces.put(interfaceNode.getAttribute(NAME_ATTRIBUTE), interfaceNode);
            serviceInterface = interfaceNode;
         }
      }

      // Try loading definitions from Soap mock services.
      List<Element> mockServices = getConfigDirectChildren(projectElement, MOCK_SERVICE_TAG);
      if (!mockServices.isEmpty()) {
         result.addAll(getSoapServicesDefinitions(mockServices));
      }
      // Then try loading from Rest mock services.
      List<Element> restMockServices = getConfigDirectChildren(projectElement, REST_MOCK_SERVICE_TAG);
      if (!restMockServices.isEmpty()) {
         result.addAll(getRestServicesDefinitions(restMockServices));
      }

      return result;
   }

   private List<Service> getSoapServicesDefinitions(List<Element> mockServices) throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      try {
         for (Element mockService : mockServices) {
            // Build a new Service.
            Service service = new Service();
            service.setName(mockService.getAttribute(NAME_ATTRIBUTE));
            service.setType(ServiceType.SOAP_HTTP);

            // Check version property that is mandatory.
            Element properties = getConfigUniqueDirectChild(mockService, "properties");
            service.setVersion(extractVersion(properties));

            List<Element> mockOperations = getConfigDirectChildren(mockService, MOCK_OPERATION_TAG);
            for (Element mockOperation : mockOperations) {

               Element interfaceElement = interfaces.get(mockOperation.getAttribute("interface"));
               if (interfaceElement != null) {
                  log.info("Got matching service interface");
                  String bindingQName = interfaceElement.getAttribute("bindingName");
                  service.setXmlNS(extractNSFromQName(bindingQName));
               }

               // Build a new operation from mockOperation.
               Operation operation = new Operation();
               operation.setName(mockOperation.getAttribute(NAME_ATTRIBUTE));

               Element interfaceOperation = getInterfaceOperation(interfaceElement, operation.getName());
               operation.setAction(interfaceOperation.getAttribute("action"));

               try {
                  completeOperationPartsFromWsdl(interfaceElement, operation);
               } catch (Exception e) {
                  // Fallback to input name as a (mostly?) safe default.
                  log.warn(
                        "Was not able to extract element names for input/output payload from WSDL. Defaulting to input and output names.");
               } finally {
                  if (operation.getInputName() == null) {
                     operation.setInputName(interfaceOperation.getAttribute("inputName"));
                  }
                  if (operation.getOutputName() == null) {
                     operation.setOutputName(interfaceOperation.getAttribute("outputName"));
                  }
               }

               Element dispatchStyle = getConfigUniqueDirectChild(mockOperation, "dispatchStyle");
               operation.setDispatcher(dispatchStyle.getTextContent());

               if (DispatchStyles.QUERY_MATCH.equals(operation.getDispatcher())) {
                  // XPath matching rules are under dispatchConfig.query, consider 1st item only.
                  Element dispatchConfig = getConfigUniqueDirectChild(mockOperation, "dispatchConfig");
                  Element firstQuery = getConfigDirectChildren(dispatchConfig, QUERY_TAG).get(0);
                  operation.setDispatcherRules(getConfigUniqueDirectChild(firstQuery, QUERY_TAG).getTextContent());
               } else if (DispatchStyles.SCRIPT.equals(operation.getDispatcher())) {
                  // Groovy script is located into dispatchPath element.
                  operation
                        .setDispatcherRules(getConfigUniqueDirectChild(mockOperation, "dispatchPath").getTextContent());
               }

               service.addOperation(operation);
            }
            result.add(service);
         }
      } catch (MalformedXmlException mspe) {
         log.error("Your SoapUI Project seems to be malformed: {}", mspe.getMessage(), mspe);
         throw new MockRepositoryImportException("Your SoapUI Project seems to be malformed: " + mspe.getMessage(),
               mspe);
      }
      return result;
   }

   private void completeOperationPartsFromWsdl(Element interfaceElement, Operation operation) throws Exception {
      Element definitionCache = getConfigUniqueDirectChild(interfaceElement, "definitionCache");
      List<Element> parts = getConfigDirectChildren(definitionCache, "part");

      Element wsdlPart = parts.get(0);
      Element wsdlContent = getConfigUniqueDirectChild(wsdlPart, CONTENT_TAG);
      String wsdlTextContent = wsdlContent.getTextContent();

      Element wsdlDoc = documentBuilder.parse(new InputSource(new StringReader(wsdlTextContent))).getDocumentElement();
      Element binding = getUniqueDirectChild(wsdlDoc, WSDL_NS, "binding");
      List<Element> wsdlOperations = getDirectChildren(binding, WSDL_NS, "operation");
      for (Element wsdlOperation : wsdlOperations) {

         if (operation.getName().equals(wsdlOperation.getAttribute(NAME_ATTRIBUTE))) {
            Element input = getUniqueDirectChild(wsdlOperation, WSDL_NS, "input");
            Element output = getUniqueDirectChild(wsdlOperation, WSDL_NS, "output");
            String inputName = input.getAttribute(NAME_ATTRIBUTE);
            String outputName = output.getAttribute(NAME_ATTRIBUTE);

            List<Element> messages = getDirectChildren(wsdlDoc, WSDL_NS, "message");
            Optional<Element> inputMsg = messages.stream().filter(m -> inputName.equals(m.getAttribute(NAME_ATTRIBUTE)))
                  .findFirst();
            Optional<Element> outputMsg = messages.stream()
                  .filter(m -> outputName.equals(m.getAttribute(NAME_ATTRIBUTE))).findFirst();
            if (inputMsg.isPresent()) {
               Element firstPart = getDirectChildren(inputMsg.get(), WSDL_NS, "part").get(0);
               String localTag = firstPart.getAttribute(ELEMENT_ATTRIBUTE)
                     .substring(firstPart.getAttribute(ELEMENT_ATTRIBUTE).indexOf(":") + 1);
               operation.setInputName(localTag);
            }
            if (outputMsg.isPresent()) {
               Element firstPart = getDirectChildren(outputMsg.get(), WSDL_NS, "part").get(0);
               String localTag = firstPart.getAttribute(ELEMENT_ATTRIBUTE)
                     .substring(firstPart.getAttribute(ELEMENT_ATTRIBUTE).indexOf(":") + 1);
               operation.setOutputName(localTag);
            }
         }
      }
   }

   private List<Service> getRestServicesDefinitions(List<Element> restMockServices)
         throws MockRepositoryImportException {
      List<Service> result = new ArrayList<>();

      try {
         for (Element mockService : restMockServices) {
            // Build a new Service.
            Service service = new Service();
            service.setName(mockService.getAttribute(NAME_ATTRIBUTE));
            service.setType(ServiceType.REST);

            // Check version property that is mandatory.
            Element properties = getConfigUniqueDirectChild(mockService, "properties");
            service.setVersion(extractVersion(properties));

            // Actions corresponding to same operations may be defined multiple times in SoapUI
            // with different resourcePaths. We have to track them to complete them in second step.
            Map<String, Operation> collectedOperations = new HashMap<>();

            List<Element> mockOperations = getConfigDirectChildren(mockService, REST_MOCK_ACTION_TAG);
            for (Element mockOperation : mockOperations) {
               // Check already found operation.
               Operation operation = collectedOperations.get(mockOperation.getAttribute(NAME_ATTRIBUTE));

               if (operation == null) {
                  // Build a new operation from mockRestAction.
                  operation = new Operation();
                  operation.setName(mockOperation.getAttribute(NAME_ATTRIBUTE));
                  operation.setMethod(mockOperation.getAttribute("method"));

                  Element dispatchStyle = getConfigUniqueDirectChild(mockOperation, "dispatchStyle");
                  operation.setDispatcher(dispatchStyle.getTextContent());

                  if (DispatchStyles.SEQUENCE.equals(operation.getDispatcher())) {
                     // Extract simple dispatcher rules from operation name.
                     operation
                           .setDispatcherRules(DispatchCriteriaHelper.extractPartsFromURIPattern(operation.getName()));
                  } else if (DispatchStyles.SCRIPT.equals(operation.getDispatcher())) {
                     // Groovy script is located into dispatchPath element.
                     operation.setDispatcherRules(
                           getConfigUniqueDirectChild(mockOperation, "dispatchPath").getTextContent());
                  }
                  service.addOperation(operation);
               }
               // Add this configuration resource path.
               operation.addResourcePath(mockOperation.getAttribute("resourcePath"));
               collectedOperations.put(mockOperation.getAttribute("name"), operation);
            }
            result.add(service);
         }
      } catch (MalformedXmlException mspe) {
         log.error("Your SoapUI Project seems to be malformed: {}", mspe.getMessage(), mspe);
         throw new MockRepositoryImportException("Your SoapUI Project seems to be malformed: " + mspe.getMessage(),
               mspe);
      }
      return result;
   }

   @Override
   public List<Resource> getResourceDefinitions(Service service) {
      List<Resource> results = new ArrayList<>();

      // First record the project itself as an artifact.
      Resource projectResource = new Resource();
      projectResource.setName(service.getName() + "-" + service.getVersion() + ".xml");
      projectResource.setType(ResourceType.SOAP_UI_PROJECT);
      projectResource.setContent(projectContent);
      results.add(projectResource);

      try {
         Element definitionCache = getConfigUniqueDirectChild(serviceInterface, "definitionCache");
         List<Element> parts = getConfigDirectChildren(definitionCache, "part");

         if (!parts.isEmpty()) {
            Element wsdlPart = parts.get(0);
            Element wsdlContent = getConfigUniqueDirectChild(wsdlPart, CONTENT_TAG);
            String wsdlTextContent = wsdlContent.getTextContent();

            for (int i = 1; i < parts.size(); i++) {
               Element xsdPart = parts.get(i);
               String xsdUrl = getConfigUniqueDirectChild(xsdPart, "url").getTextContent().trim();
               String xsdName = xsdUrl.substring(xsdUrl.lastIndexOf('/') + 1);
               // Try also Windows style path separators.
               if (xsdUrl.contains("\\")) {
                  xsdName = xsdUrl.substring(xsdUrl.lastIndexOf("\\") + 1);
               }

               String xsdContent = getConfigUniqueDirectChild(xsdPart, CONTENT_TAG).getTextContent();

               Resource xsdResource = new Resource();
               xsdResource.setName(xsdName);
               xsdResource.setType(ResourceType.XSD);
               xsdResource.setContent(xsdContent);
               results.add(xsdResource);

               // URL references within WSDL must be replaced by their local counterpart.
               wsdlTextContent = wsdlTextContent.replace(xsdUrl, "./" + xsdName);
               // TODO: have a in-depth review on how xsd are actually resolved (and should probably be fixed)
               // wsdlTextContent = wsdlTextContent.replaceAll("schemaLocation=\"(.*)\\/(" + xsdName + ")", "schemaLocation=\"./" + xsdName + "\"");
            }

            Resource wsdlResource = new Resource();
            wsdlResource.setName(service.getName() + "-" + service.getVersion() + ".wsdl");
            wsdlResource.setType(ResourceType.WSDL);
            wsdlResource.setContent(wsdlTextContent);
            results.add(wsdlResource);
         }
      } catch (MalformedXmlException mxe) {
         log.warn("Got a MalformedXmlException while trying to extract WSDL and XSD: {}", mxe.getMessage());
         log.warn("Just failing silently as it's not a critical stuff in SoapUI implementation");
      }

      return results;
   }

   @Override
   public List<Exchange> getMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      List<Exchange> results = new ArrayList<>();

      if (ServiceType.SOAP_HTTP == service.getType()) {
         results.addAll(getSoapMessageDefinitions(service, operation));
      } else if (ServiceType.REST == service.getType()) {
         results.addAll(getRestMessageDefinitions(service, operation));
      }
      return results;
   }

   private List<Exchange> getSoapMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      Map<Request, Response> result = new HashMap<>();
      try {
         List<Element> mockServices = getConfigDirectChildren(projectElement, MOCK_SERVICE_TAG);
         for (Element mockService : mockServices) {
            // Find the appropriate mock service.
            if (service.getName().equals(mockService.getAttribute(NAME_ATTRIBUTE))) {

               List<Element> mockOperations = getConfigDirectChildren(mockService, MOCK_OPERATION_TAG);
               for (Element mockOperation : mockOperations) {
                  // Find the appropriate mock service operation.
                  if (operation.getName().equals(mockOperation.getAttribute("operation"))) {
                     // Collect available test requests for this operation.
                     Map<String, Element> availableRequests = collectTestStepsRequests(operation);
                     // Then filter only those that are candidates to mock response matching.
                     List<Element> candidateRequests = new ArrayList<>();

                     List<Element> mockResponses = getConfigDirectChildren(mockOperation, RESPONSE_TAG);
                     for (Element mockResponse : mockResponses) {
                        String responseName = mockResponse.getAttribute(NAME_ATTRIBUTE);
                        Element matchingRequest = availableRequests.get(responseName);
                        if (matchingRequest == null) {
                           matchingRequest = availableRequests.get(responseName + " Request");
                        }
                        if (matchingRequest == null && responseName.contains("Response")) {
                           matchingRequest = availableRequests.get(responseName.replace("Response", "Request"));
                        }

                        if (matchingRequest == null) {
                           log.warn("No request found for response '{}' into SoapUI project '{}'", responseName,
                                 projectElement.getAttribute("name"));
                           continue;
                        }
                        candidateRequests.add(matchingRequest);
                     }

                     if (DispatchStyles.QUERY_MATCH.equals(operation.getDispatcher())) {
                        // Browse candidates and apply query dispatcher criterion to find corresponding response.
                        try {
                           XPathExpression xpath = initializeXPathMatcher(operation);

                           Map<String, String> matchToResponseMap = buildQueryMatchDispatchCriteriaToResponseMap(
                                 mockOperation);
                           for (Element candidateRequest : candidateRequests) {
                              // Evaluate matcher against request and get name of corresponding response.
                              String requestContent = getConfigUniqueDirectChild(candidateRequest, REQUEST_TAG)
                                    .getTextContent();
                              String dispatchCriteria = xpath
                                    .evaluate(new InputSource(new StringReader(requestContent)));
                              String correspondingResponse = matchToResponseMap.get(dispatchCriteria);

                              Element matchingResponse = getMockResponseByName(mockOperation, correspondingResponse);
                              if (matchingResponse != null) {
                                 // Build response from MockResponse and response from matching one.
                                 Response response = buildResponse(matchingResponse, dispatchCriteria);
                                 Request request = buildRequest(candidateRequest);
                                 result.put(request, response);
                              }
                           }
                        } catch (XPathExpressionException e) {
                           throw new RuntimeException(e);
                        }
                     } else if (DispatchStyles.SCRIPT.equals(operation.getDispatcher())) {
                        for (Element candidateRequest : candidateRequests) {
                           Element mockResponse = getMockResponseByName(mockOperation,
                                 candidateRequest.getAttribute(NAME_ATTRIBUTE));
                           if (mockResponse == null
                                 && candidateRequest.getAttribute(NAME_ATTRIBUTE).contains("Request")) {
                              mockResponse = getMockResponseByName(mockOperation,
                                    candidateRequest.getAttribute(NAME_ATTRIBUTE).replace(" Request", " Response"));
                           }

                           if (mockResponse == null) {
                              log.warn("No response found for request {} into SoapUI project {}",
                                    candidateRequest.getAttribute(NAME_ATTRIBUTE),
                                    projectElement.getAttribute(NAME_ATTRIBUTE));
                              continue;
                           }

                           // Build response from MockResponse and response from matching one.
                           Response response = buildResponse(mockResponse, mockResponse.getAttribute(NAME_ATTRIBUTE));
                           Request request = buildRequest(candidateRequest);
                           result.put(request, response);
                        }
                     } else if (DispatchStyles.RANDOM.equals(operation.getDispatcher())) {
                        if (availableRequests.isEmpty()) {
                           log.warn(
                                 "A request is mandatory even for a RANDOM dispatch. Operation {} into SoapUI project  {}",
                                 operation.getName(), projectElement.getAttribute(NAME_ATTRIBUTE));
                        } else {
                           // Use the first one for all the responses
                           Element mockRequest = availableRequests.values().iterator().next();

                           for (Element mockResponse : mockResponses) {
                              // Build response from MockResponse and response from matching one.
                              Response response = buildResponse(mockResponse, DispatchStyles.RANDOM);
                              Request request = buildRequest(mockRequest);
                              request.setName(operation.getName());
                              result.put(request, response);
                           }
                        }
                     }
                     break;
                  }
               }
               break;
            }
         }
      } catch (Throwable t) {
         throw new MockRepositoryImportException(t.getMessage());
      }

      // Adapt map to list of Exchanges.
      return result.entrySet().stream().map(entry -> new RequestResponsePair(entry.getKey(), entry.getValue()))
            .collect(Collectors.toList());
   }

   private List<Exchange> getRestMessageDefinitions(Service service, Operation operation)
         throws MockRepositoryImportException {
      Map<Request, Response> result = new HashMap<>();
      try {
         List<Element> mockServices = getConfigDirectChildren(projectElement, REST_MOCK_SERVICE_TAG);
         for (Element mockService : mockServices) {
            // Find the appropriate mock service.
            if (service.getName().equals(mockService.getAttribute(NAME_ATTRIBUTE))) {

               List<Element> mockOperations = getConfigDirectChildren(mockService, REST_MOCK_ACTION_TAG);
               for (Element mockOperation : mockOperations) {
                  // Find the appropriate mock service operation.
                  if (operation.getName().equals(mockOperation.getAttribute(NAME_ATTRIBUTE))) {

                     // Collect available test requests for this operation.
                     Map<String, Element> availableRequests = collectTestStepsRestRequests(operation);
                     // Collection also mock responses that are sparsly dispatched under mockRestActions having the name same.
                     List<Element> mockResponses = getMockRestResponses(mockService, operation);

                     // Then filter only those that are matching with a mock response.
                     Map<Element, Element> requestToResponses = new HashMap<>();

                     for (Element mockResponse : mockResponses) {
                        String responseName = mockResponse.getAttribute(NAME_ATTRIBUTE);
                        Element matchingRequest = availableRequests.get(responseName);
                        if (matchingRequest == null) {
                           matchingRequest = availableRequests.get(responseName + " Request");
                        }
                        if (matchingRequest == null && responseName.contains("Response")) {
                           matchingRequest = availableRequests.get(responseName.replace("Response", "Request"));
                        }

                        if (matchingRequest == null) {
                           log.warn("No request found for response '{}' into SoapUI project '{}'", responseName,
                                 projectElement.getAttribute("name"));
                           continue;
                        }
                        requestToResponses.put(matchingRequest, mockResponse);
                     }

                     for (Map.Entry<Element, Element> entry : requestToResponses.entrySet()) {
                        String dispatchCriteria = null;

                        if (DispatchStyles.SEQUENCE.equals(operation.getDispatcher())) {
                           // Build a dispatch criteria from operation name projected onto resourcePath pattern
                           // eg. /deployment/byComponent/{component}/{version}.json  => /deployment/byComponent/testREST/1.2.json
                           // for producing /component=testREST/version=1.2
                           // resourcePath is actually available in restMockAction wrapping response. Navigate to parent.
                           String resourcePath = ((Element) entry.getValue().getParentNode())
                                 .getAttribute("resourcePath");
                           dispatchCriteria = DispatchCriteriaHelper.extractFromURIPattern(
                                 operation.getDispatcherRules(), operation.getName(), resourcePath);
                        } else if (DispatchStyles.SCRIPT.equals(operation.getDispatcher())) {
                           // Build a dispatch criteria that is equal to response name (that script evaluation should return...)
                           dispatchCriteria = entry.getValue().getAttribute(NAME_ATTRIBUTE);
                        }

                        Response response = buildResponse(entry.getValue(), dispatchCriteria);
                        Request request = buildRequest(entry.getKey());
                        result.put(request, response);
                     }
                     break;
                  }
               }
            }
         }
      } catch (Throwable t) {
         throw new MockRepositoryImportException(t.getMessage());
      }

      // Adapt map to list of Exchanges.
      return result.entrySet().stream().map(entry -> new RequestResponsePair(entry.getKey(), entry.getValue()))
            .collect(Collectors.toList());
   }

   private String extractNSFromQName(String qName) {
      if (qName.startsWith("{") && qName.indexOf("}") > 1) {
         return qName.substring(1, qName.indexOf("}"));
      }
      return qName;
   }

   /** Extract version from mockService properties. */
   private String extractVersion(Element properties) throws MockRepositoryImportException, MalformedXmlException {
      List<Element> propertyList = getConfigDirectChildren(properties, "property");
      for (Element property : propertyList) {
         Element propertyName = getConfigUniqueDirectChild(property, NAME_ATTRIBUTE);
         Element propertyValue = getConfigUniqueDirectChild(property, VALUE_TAG);
         if (SERVICE_VERSION_PROPERTY.equals(propertyName.getTextContent())) {
            return propertyValue.getTextContent();
         }
      }
      log.error("Version property is missing in Project properties");
      throw new MockRepositoryImportException("Version property is missing in Project properties");
   }

   private Element getInterfaceOperation(Element serviceInterface, String operationName)
         throws MockRepositoryImportException {
      List<Element> operations = getConfigDirectChildren(serviceInterface, "operation");
      for (Element operation : operations) {
         if (operationName.equals(operation.getAttribute(NAME_ATTRIBUTE))) {
            return operation;
         }
      }
      log.error("Operation {} is missing into Service interface", operationName);
      throw new MockRepositoryImportException("Operation " + operationName + " is missing into Service interface");
   }

   private Map<String, Element> collectTestStepsRequests(Operation operation) throws MalformedXmlException {
      Map<String, Element> results = new HashMap<>();

      List<Element> testSuites = getConfigDirectChildren(projectElement, "testSuite");
      for (Element testSuite : testSuites) {
         List<Element> testCases = getConfigDirectChildren(testSuite, "testCase");
         for (Element testCase : testCases) {
            List<Element> testSteps = getConfigDirectChildren(testCase, "testStep");
            for (Element testStep : testSteps) {

               Element config = getConfigUniqueDirectChild(testStep, "config");
               String interfaceName = getConfigUniqueDirectChild(config, "interface").getTextContent();
               String operationName = getConfigUniqueDirectChild(config, "operation").getTextContent();

               if (operation.getName().equals(operationName)) {
                  results.put(testStep.getAttribute(NAME_ATTRIBUTE), getConfigUniqueDirectChild(config, REQUEST_TAG));
               }
            }
         }
      }
      return results;
   }

   private Map<String, Element> collectTestStepsRestRequests(Operation operation) throws MalformedXmlException {
      Map<String, Element> results = new HashMap<>();

      List<Element> testSuites = getConfigDirectChildren(projectElement, "testSuite");
      for (Element testSuite : testSuites) {
         List<Element> testCases = getConfigDirectChildren(testSuite, "testCase");
         for (Element testCase : testCases) {
            List<Element> testSteps = getConfigDirectChildren(testCase, "testStep");
            for (Element testStep : testSteps) {
               Element config = getConfigUniqueDirectChild(testStep, "config");
               String operationName = config.getAttribute("resourcePath");
               if (operation.getName().equals(operationName)) {
                  results.put(testStep.getAttribute(NAME_ATTRIBUTE), getConfigUniqueDirectChild(config, "restRequest"));
               } else {
                  // If this artifact is second one and OpenAPI was the main one, operationName may
                  // start with the verb. We have to extract the verb from elsewhere.
                  String methodName = config.getAttribute("methodName");
                  Optional<Element> method = getRestInterfaceResourceMethod(operationName, methodName);
                  if (method.isPresent()) {
                     String methodString = method.get().getAttribute("method");
                     if (operation.getName().equals(methodString.toUpperCase() + " " + operationName)) {
                        results.put(testStep.getAttribute(NAME_ATTRIBUTE),
                              getConfigUniqueDirectChild(config, "restRequest"));
                     }
                  }
               }
            }
         }
      }
      return results;
   }

   private Optional<Element> getRestInterfaceResourceMethod(String resourcePath, String methodName)
         throws MalformedXmlException {
      return getConfigDirectChildren(serviceInterface, "resource").stream()
            .filter(resource -> resourcePath.equals(resource.getAttribute("path")))
            .flatMap(resource -> getConfigDirectChildren(resource, "method").stream())
            .filter(method -> methodName.equals(method.getAttribute("name"))).findFirst();
   }

   private List<Element> getMockRestResponses(Element restMockService, Operation operation) {
      List<Element> responses = new ArrayList<>();
      List<Element> mockActions = getConfigDirectChildren(restMockService, REST_MOCK_ACTION_TAG);
      for (Element mockAction : mockActions) {
         if (operation.getName().equals(mockAction.getAttribute(NAME_ATTRIBUTE))) {
            responses.addAll(getConfigDirectChildren(mockAction, RESPONSE_TAG));
         }
      }
      return responses;
   }

   /** Build a XPathMatcher based on operation dispatcher rules. */
   private XPathExpression initializeXPathMatcher(Operation operation) throws XPathExpressionException {
      return SoapUIXPathBuilder.buildXPathMatcherFromRules(operation.getDispatcherRules());
   }

   private Map<String, String> buildQueryMatchDispatchCriteriaToResponseMap(Element mockOperation)
         throws MalformedXmlException {
      Map<String, String> matchResponseMap = new HashMap<>();

      String dispatcher = getConfigUniqueDirectChild(mockOperation, "dispatchStyle").getTextContent();
      if (DispatchStyles.QUERY_MATCH.equals(dispatcher)) {
         Element dispatchConfig = getConfigUniqueDirectChild(mockOperation, "dispatchConfig");

         List<Element> queries = SoapUIProjectParserUtils.getConfigDirectChildren(dispatchConfig, QUERY_TAG);
         for (Element query : queries) {
            String match = getConfigUniqueDirectChild(query, "match").getTextContent();
            String response = getConfigUniqueDirectChild(query, RESPONSE_TAG).getTextContent();
            matchResponseMap.put(match, response);
         }
      }
      return matchResponseMap;
   }

   private Element getMockResponseByName(Element mockOperation, String responseName) {
      List<Element> responses = getConfigDirectChildren(mockOperation, RESPONSE_TAG);
      for (Element response : responses) {
         if (responseName.equals(response.getAttribute(NAME_ATTRIBUTE))) {
            return response;
         }
      }
      return null;
   }

   private Response buildResponse(Element mockResponse, String dispatchCriteria)
         throws MockRepositoryImportException, Exception {
      Response response = new Response();
      response.setName(mockResponse.getAttribute(NAME_ATTRIBUTE));
      response.setContent(getConfigUniqueDirectChild(mockResponse, "responseContent").getTextContent());
      response.setHeaders(buildHeaders(mockResponse));
      response.setDispatchCriteria(dispatchCriteria);
      response.setStatus(mockResponse.getAttribute("httpResponseStatus"));
      if ("500".equals(response.getStatus())) {
         response.setFault(true);
      }
      response.setMediaType(mockResponse.getAttribute("mediaType"));
      return response;
   }

   private Request buildRequest(Element testRequest) throws MockRepositoryImportException, Exception {
      Request request = new Request();
      request.setName(testRequest.getAttribute(NAME_ATTRIBUTE));
      if (hasConfigDirectChild(testRequest, REQUEST_TAG)) {
         request.setContent(getConfigUniqueDirectChild(testRequest, REQUEST_TAG).getTextContent());
      }
      request.setHeaders(buildHeaders(testRequest));

      // Add query parameters only if presents.
      if (hasConfigDirectChild(testRequest, "parameters")) {
         List<Element> entries = getConfigDirectChildren(getConfigUniqueDirectChild(testRequest, "parameters"),
               "entry");
         for (Element entry : entries) {
            Parameter param = new Parameter();
            param.setName(entry.getAttribute("key"));
            param.setValue(entry.getAttribute(VALUE_TAG));
            request.addQueryParameter(param);
         }
      }
      return request;
   }

   private Set<Header> buildHeaders(Element requestOrResponse) throws Exception {
      if (hasConfigDirectChild(requestOrResponse, "settings")) {
         Element settingsElt = getConfigUniqueDirectChild(requestOrResponse, "settings");
         List<Element> settings = getConfigDirectChildren(settingsElt, "setting");
         for (Element setting : settings) {
            if (setting.getAttribute("id").contains("@request-headers")) {

               // 2 possibilities here:
               // 1) &lt;xml-fragment xmlns:con="http://eviware.com/soapui/config">
               //      &lt;con:entry key="Authorization" value="Basic YWRtaW46YWRtaW4="/>
               //      &lt;con:entry key="x-userid" value="s026210"/>
               //    &lt;/xml-fragment>
               // 2) &lt;entry key="toto"
               //                value="tata" xmlns="http://eviware.com/soapui/config"/>
               String headersContent = setting.getTextContent();
               Element fragment = documentBuilder.parse(new InputSource(new StringReader(headersContent)))
                     .getDocumentElement();

               Set<Header> headers = new HashSet<>();
               if (headersContent.contains("xml-fragment")) {
                  List<Element> entries = getConfigDirectChildren(fragment, "entry");
                  for (Element entry : entries) {
                     Header header = new Header();
                     header.setName(entry.getAttribute("key"));
                     header.setValues(Set.of(entry.getAttribute(VALUE_TAG)));
                     headers.add(header);
                  }
               } else {
                  Header header = new Header();
                  header.setName(fragment.getAttribute("key"));
                  header.setValues(Set.of(fragment.getAttribute(VALUE_TAG)));
                  headers.add(header);
               }
               return headers;
            }
         }
      }
      return null;
   }
}

public class SwaggerImporter extends OpenAPIImporter {

   /**
