public class SimpleReferenceURLBuilder implements RelativeReferenceURLBuilder {

   @Override
   public String getFileName(String baseRepositoryURL, Map<String, List<String>> headers) {
      return baseRepositoryURL.substring(baseRepositoryURL.lastIndexOf("/") + 1);
   }

   @Override
   public String buildRemoteURL(String baseRepositoryURL, String referencePath) {
      // Rebuild a downloadable URL to retrieve file.
      String remoteUrl = baseRepositoryURL.substring(0, baseRepositoryURL.lastIndexOf("/"));
      String pathToAppend = referencePath;
      while (pathToAppend.startsWith("../")) {
         remoteUrl = remoteUrl.substring(0, remoteUrl.lastIndexOf("/"));
         pathToAppend = pathToAppend.substring(3);
      }
      if (pathToAppend.startsWith("./")) {
         pathToAppend = pathToAppend.substring(2);
      }
      if (pathToAppend.startsWith("/")) {
         pathToAppend = pathToAppend.substring(1);
      }
      remoteUrl += "/" + pathToAppend;
      return remoteUrl;
   }
}

public class GitLabReferenceURLBuilder extends SimpleReferenceURLBuilder {

   /** Header used by GitLab APIs to provide the downloaded file name. */
   public static final String GITLAB_FILE_NAME_HEADER = "X-Gitlab-File-Name";

   private static final String REPOSITORY_FILES_MARKER = "/repository/files/";
   private static final String ENCODED_FILE_SEPARATOR = "%2F";

   @Override
   public String getFileName(String baseRepositoryURL, Map<String, List<String>> headers) {
      if (headers != null) {
         for (String key : headers.keySet()) {
            if (key != null && key.equalsIgnoreCase(GITLAB_FILE_NAME_HEADER)) {
               return headers.get(key).get(0);
            }
         }
      }

      // If not present, extract from raw URL.
      String lastPath = baseRepositoryURL.substring(baseRepositoryURL.lastIndexOf("/") + 1);
      if (lastPath.startsWith("raw?ref=") || lastPath.indexOf('.') == -1) {
         String[] pathElements = baseRepositoryURL.split("/");
         int i = pathElements.length;
         while (i > 0) {
            String path = pathElements[i - 1];
            if (path.contains(".") && path.contains(ENCODED_FILE_SEPARATOR)) {
               return path.substring(path.indexOf(ENCODED_FILE_SEPARATOR) + ENCODED_FILE_SEPARATOR.length());
            }
            i--;
         }
      }
      return null;
   }

   @Override
   public String buildRemoteURL(String baseRepositoryURL, String referencePath) {
      // https://gitlab.com/api/v4/projects/35980862/repository/files/folder%2Fsubfolder%2Ffilename/raw?ref=branch

      // https://gitlab.com/api/v4/projects/35980862/repository/files
      String rootURL = baseRepositoryURL.substring(0,
            baseRepositoryURL.indexOf(REPOSITORY_FILES_MARKER) + REPOSITORY_FILES_MARKER.length() - 1);

      // folder%2Fsubfolder%2Ffilename
      String basePath = baseRepositoryURL.substring(
            baseRepositoryURL.indexOf(REPOSITORY_FILES_MARKER) + REPOSITORY_FILES_MARKER.length(),
            baseRepositoryURL.lastIndexOf("/"));

      // raw?ref=branch
      String formatOptions = baseRepositoryURL.substring(baseRepositoryURL.lastIndexOf("/") + 1);

      // Now do a simple reference url build. We need to ensure that there's a root
      // by adding a starting /. We'll remove it after the build when recomposing result.
      String pathFragment = super.buildRemoteURL("/" + URLDecoder.decode(basePath, StandardCharsets.UTF_8),
            referencePath);

      return rootURL + "/" + URLEncoder.encode(pathFragment.substring(1), StandardCharsets.UTF_8) + "/" + formatOptions;
   }
}

public class AuthorizationException extends Exception {

   public AuthorizationException(String message) {
      super(message);
   }

   public AuthorizationException(String message, Throwable cause) {
      super(message, cause);
   }
}

public class OAuth2AuthorizedClientProvider {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(OAuth2AuthorizedClientProvider.class);

   /**
    * Realize OAuth2 authorization trying to get an access token from the given OAuth2 client context. Token as well as
    * traceability information are then transferred as a result in the OAuth2AuthorizedClient
    * @param oAuth2ClientContext The client context for OAuth2 authorization flow
    * @return An authorized client with traceability elements being principal and access token.
    * @throws AuthorizationException
    */
   public OAuth2AuthorizedClient authorize(OAuth2ClientContext oAuth2ClientContext) throws AuthorizationException {

      OAuth2AccessToken accessToken = null;
      try {
         switch (oAuth2ClientContext.getGrantType()) {
            case PASSWORD -> accessToken = getResourceOwnerPasswordAccessToken(oAuth2ClientContext);
            case CLIENT_CREDENTIALS -> accessToken = getClientCredentialsAccessToken(oAuth2ClientContext);
            case REFRESH_TOKEN -> accessToken = getRefreshTokenAccessToken(oAuth2ClientContext);
         }
      } catch (OAuth2AuthorizationException oAuth2AuthorizationException) {
         log.error("Error during {} grant type fetching", oAuth2ClientContext.getGrantType(),
               oAuth2AuthorizationException);
         throw new AuthorizationException("Error during " + oAuth2ClientContext.getGrantType() + " grant type fetching",
               oAuth2AuthorizationException);
      }

      String principalName = oAuth2ClientContext.getClientId();
      if (oAuth2ClientContext.getGrantType() == OAuth2GrantType.PASSWORD) {
         principalName = oAuth2ClientContext.getUsername();
      }

      return new OAuth2AuthorizedClient(oAuth2ClientContext.getGrantType(), principalName,
            oAuth2ClientContext.getTokenUri(), String.join(" ", accessToken.getScopes()), accessToken.getTokenValue());
   }

   private OAuth2AccessToken getResourceOwnerPasswordAccessToken(OAuth2ClientContext oAuth2ClientContext) {
      // Build a ClientRegistration with PASSWORD grant type.
      ClientRegistration registration = initializeClientRegistration(oAuth2ClientContext)
            .authorizationGrantType(AuthorizationGrantType.PASSWORD).build();

      DefaultPasswordTokenResponseClient client = new DefaultPasswordTokenResponseClient();
      OAuth2PasswordGrantRequest request = new OAuth2PasswordGrantRequest(registration,
            oAuth2ClientContext.getUsername(), oAuth2ClientContext.getPassword());
      OAuth2AccessTokenResponse response = client.getTokenResponse(request);

      return response.getAccessToken();
   }

   private OAuth2AccessToken getClientCredentialsAccessToken(OAuth2ClientContext oAuth2ClientContext) {
      // Build a ClientRegistration with CLIENT_CREDENTIALS grant type.
      ClientRegistration registration = initializeClientRegistration(oAuth2ClientContext)
            .authorizationGrantType(AuthorizationGrantType.CLIENT_CREDENTIALS).build();

      DefaultClientCredentialsTokenResponseClient client = new DefaultClientCredentialsTokenResponseClient();
      OAuth2ClientCredentialsGrantRequest request = new OAuth2ClientCredentialsGrantRequest(registration);
      OAuth2AccessTokenResponse response = client.getTokenResponse(request);

      return response.getAccessToken();
   }

   private OAuth2AccessToken getRefreshTokenAccessToken(OAuth2ClientContext oAuth2ClientContext) {
      // Build a ClientRegistration with REFRESH_TOKEN grant type.
      ClientRegistration registration = initializeClientRegistration(oAuth2ClientContext)
            .authorizationGrantType(AuthorizationGrantType.REFRESH_TOKEN).build();

      DefaultRefreshTokenTokenResponseClient clientRT = new DefaultRefreshTokenTokenResponseClient();
      OAuth2RefreshTokenGrantRequest requestRT = new OAuth2RefreshTokenGrantRequest(registration,
            new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, "fake-one", null, null),
            new OAuth2RefreshToken(oAuth2ClientContext.getRefreshToken(), null));
      OAuth2AccessTokenResponse response = clientRT.getTokenResponse(requestRT);

      return response.getAccessToken();
   }

   private ClientRegistration.Builder initializeClientRegistration(OAuth2ClientContext oAuth2ClientContext) {
      ClientRegistration.Builder builder = ClientRegistration.withRegistrationId("microcks-test-idp")
            .clientId(oAuth2ClientContext.getClientId()).clientSecret(oAuth2ClientContext.getClientSecret())
            .tokenUri(oAuth2ClientContext.getTokenUri());

      if (oAuth2ClientContext.getScopes() != null) {
         String[] scopes = (oAuth2ClientContext.getScopes() + " openid").split(" ");
         builder.scope(Arrays.asList(scopes));
      } else {
         builder.scope("openid");
      }

      return builder;
   }
}

public class AsyncAPITestRunner extends AbstractTestRunner<HttpMethod> {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(AsyncAPITestRunner.class);

   private ObjectMapper mapper = new ObjectMapper();

   private ResourceRepository resourceRepository;

   private SecretRepository secretRepository;

   private ClientHttpRequestFactory clientHttpRequestFactory;

   private String asyncMinionUrl = null;

   /**
    * Build a new AsyncAPITestRunner using a resource repository for retrieving AsyncAPI specification.
    * @param resourceRepository The repository that contains AsyncAPI specification to validate
    * @param secretRepository   The repository for accessing secrets for connecting test endpoints
    */
   public AsyncAPITestRunner(ResourceRepository resourceRepository, SecretRepository secretRepository) {
      this.resourceRepository = resourceRepository;
      this.secretRepository = secretRepository;
   }

   /**
    * Set the ClientHttpRequestFactory used for reaching endpoint.
    * @param clientHttpRequestFactory The ClientHttpRequestFactory used for reaching endpoint
    */
   public void setClientHttpRequestFactory(ClientHttpRequestFactory clientHttpRequestFactory) {
      this.clientHttpRequestFactory = clientHttpRequestFactory;
   }

   public void setAsyncMinionUrl(String asyncMinionUrl) {
      this.asyncMinionUrl = asyncMinionUrl;
   }

   @Override
   public List<TestReturn> runTest(Service service, Operation operation, TestResult testResult, List<Request> requests,
         String endpointUrl, HttpMethod method) throws URISyntaxException, IOException {

      if (log.isDebugEnabled()) {
         log.debug("Launching test run on " + endpointUrl + " for ms");
      }

      // Retrieve the resource corresponding to OpenAPI specification if any.
      Resource asyncAPISpecResource = null;
      List<Resource> resources = resourceRepository.findByServiceId(service.getId());
      for (Resource resource : resources) {
         if (ResourceType.ASYNC_API_SPEC.equals(resource.getType())) {
            asyncAPISpecResource = resource;
            break;
         }
      }

      // Microcks-async-minion interface object building.
      ObjectNode jsonArg = mapper.createObjectNode();
      jsonArg.put("runnerType", TestRunnerType.ASYNC_API_SCHEMA.toString());
      jsonArg.put("testResultId", testResult.getId());
      jsonArg.put("serviceId", service.getId());
      jsonArg.put("operationName", operation.getName());
      jsonArg.put("endpointUrl", endpointUrl);
      jsonArg.put("timeoutMS", testResult.getTimeout());
      jsonArg.put("asyncAPISpec", asyncAPISpecResource.getContent());

      if (testResult.getSecretRef() != null) {
         Secret secret = secretRepository.findById(testResult.getSecretRef().getSecretId()).orElse(null);
         if (secret != null) {
            log.debug("Adding the secret '{}' to test specification request", secret.getName());
            jsonArg.set("secret", mapper.valueToTree(secret));
         }
      }

      URI asyncMinionURI = new URI(asyncMinionUrl + "/api/tests");
      ClientHttpRequest httpRequest = clientHttpRequestFactory.createRequest(asyncMinionURI, HttpMethod.POST);
      httpRequest.getBody().write(mapper.writeValueAsBytes(jsonArg));
      httpRequest.getHeaders().add("Content-Type", "application/json");

      // Actually execute request.
      ClientHttpResponse httpResponse = null;
      try {
         httpResponse = httpRequest.execute();
      } catch (IOException ioe) {
         log.error("IOException while executing request ", ioe);
      } finally {
         if (httpResponse != null) {
            httpResponse.close();
         }
      }

      return new ArrayList<>();
   }

   @Override
   public HttpMethod buildMethod(String method) {
      return null;
   }
}

public class GraphQLTestRunner extends HttpTestRunner {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(GraphQLTestRunner.class);

   /** Content-type for JSON that is the sole valid response type. */
   private static final String APPLICATION_JSON_TYPE = "application/json";

   private ObjectMapper mapper = new ObjectMapper();

   private ResourceRepository resourceRepository;

   private String lastQueryContent = null;
   private List<String> lastValidationErrors = null;

   /**
    * Build a new GraphQLTestRunner.
    * @param resourceRepository Access to resources repository
    */
   public GraphQLTestRunner(ResourceRepository resourceRepository) {
      this.resourceRepository = resourceRepository;
   }


   @Override
   protected void prepareRequest(Request request) {
      try {
         JsonNode requestNode = mapper.readTree(request.getContent());
         lastQueryContent = requestNode.path("query").asText();
      } catch (JsonProcessingException jpe) {
         log.error("JsonProcessingException while preparing GraphQL test query", jpe);
         lastQueryContent = "";
      }
   }

   @Override
   protected int extractTestReturnCode(Service service, Operation operation, Request request,
         ClientHttpResponse httpResponse, String responseContent) {

      int code = TestReturn.SUCCESS_CODE;

      int responseCode = 0;
      try {
         responseCode = httpResponse.getStatusCode().value();
         log.debug("Response status code : {}", responseCode);
      } catch (IOException ioe) {
         log.debug("IOException while getting raw status code in response", ioe);
         return TestReturn.FAILURE_CODE;
      }

      // Check that we're in the 20x family.
      if (!String.valueOf(responseCode).startsWith("20")) {
         log.debug("Response code if not in 20x range, assuming it's a failure");
         return TestReturn.FAILURE_CODE;
      }

      // Extract response content-type in any case.
      String contentType = null;
      if (httpResponse.getHeaders().getContentType() != null) {
         log.debug("Response media-type is {}", httpResponse.getHeaders().getContentType());
         contentType = httpResponse.getHeaders().getContentType().toString();
         // Sanitize charset information from media-type.
         if (contentType.contains("charset=") && contentType.indexOf(";") > 0) {
            contentType = contentType.substring(0, contentType.indexOf(";"));
         }
      }

      // Do not try to validate response content if no content provided ;-)
      // Also do not try to schema validate something that is not application/json for now...
      if (responseCode != 204 && APPLICATION_JSON_TYPE.equals(contentType)) {
         // Retrieve the resource corresponding to OpenAPI specification if any.
         Resource graphqlSchemaResource = null;
         List<Resource> resources = resourceRepository.findByServiceIdAndType(service.getId(),
               ResourceType.GRAPHQL_SCHEMA);
         if (!resources.isEmpty()) {
            graphqlSchemaResource = resources.get(0);
         }
         if (graphqlSchemaResource == null) {
            log.debug("Found no GraphQL specification resource for service {}, so failing validating", service.getId());
            return TestReturn.FAILURE_CODE;
         }

         JsonNode responseSchema = null;
         try {
            responseSchema = GraphQLSchemaValidator.buildResponseJsonSchema(graphqlSchemaResource.getContent(),
                  lastQueryContent);
            log.debug("responseSchema: {}", responseSchema);
            lastValidationErrors = GraphQLSchemaValidator.validateJson(responseSchema,
                  mapper.readTree(responseContent));
         } catch (IOException ioe) {
            log.debug("Response body cannot be accessed or transformed as Json, returning failure");
            return TestReturn.FAILURE_CODE;
         }

         if (!lastValidationErrors.isEmpty()) {
            log.debug(
                  "GraphQL schema validation errors found: {}, marking test as failed." + lastValidationErrors.size());
            return TestReturn.FAILURE_CODE;
         }
         log.debug("GraphQL schema validation of response is successful !");
      }
      return code;
   }

   @Override
   protected String extractTestReturnMessage(Service service, Operation operation, Request request,
         ClientHttpResponse httpResponse) {
      StringBuilder builder = new StringBuilder();
      if (lastValidationErrors != null && !lastValidationErrors.isEmpty()) {
         for (String error : lastValidationErrors) {
            builder.append(error).append("/n");
         }
      }
      // Reset just after consumption so avoid side-effects.
      lastValidationErrors = null;
      return builder.toString();
   }

   /**
    * Build the HttpMethod corresponding to string.
    */
   @Override
   public HttpMethod buildMethod(String method) {
      return HttpMethod.POST;
   }
}

public class GrpcTestRunner extends AbstractTestRunner<HttpMethod> {

   /* Call Option used to pass gRPC Metadata from client invocation to header client interceptor */
   public static final String CUSTOM_CALL_OPTION_NAME = "request-metadata";
   public static final CallOptions.Key<Metadata> METADATA_CUSTOM_CALL_OPTION = CallOptions.Key
         .createWithDefault(CUSTOM_CALL_OPTION_NAME, null);

   class HeaderInterceptor implements ClientInterceptor {

      @Override
      public <ReqT, RespT> ClientCall<ReqT, RespT> interceptCall(MethodDescriptor<ReqT, RespT> method,
            CallOptions callOptions, Channel next) {
         return new ForwardingClientCall.SimpleForwardingClientCall<ReqT, RespT>(next.newCall(method, callOptions)) {
            /**
             * Extension of the AttachHeadersInterceptor by allowing custom headers on each request, passed through via
             * custom CallOption.
             */
            @Override
            public void start(Listener<RespT> responseListener, Metadata headers) {
               // Extract custom headers from CallOptions
               Metadata customHeaders = callOptions.getOption(METADATA_CUSTOM_CALL_OPTION);
               if (customHeaders != null) {
                  log.debug("Adding headers to client request: {}", customHeaders.keys());
                  headers.merge(customHeaders);
               }
               super.start(responseListener, headers);
            }
         };

      }

   }

   /** A simple logger for diagnostic messages. */
   private final static Logger log = LoggerFactory.getLogger(GrpcTestRunner.class);

   private long timeout = 10000L;

   private Secret secret;

   private final ResourceRepository resourceRepository;

   /**
    * Build a new GrpcTestRunner.
    * @param resourceRepository Access to resources repository
    */
   public GrpcTestRunner(ResourceRepository resourceRepository) {
      this.resourceRepository = resourceRepository;
   }

   /**
    * Set the timeout to apply for each request tests.
    * @param timeout Timeout value in milliseconds.
    */
   public void setTimeout(long timeout) {
      this.timeout = timeout;
   }

   /**
    * Set the Secret used for securing the requests.
    * @param secret The Secret used or securing the requests.
    */
   public void setSecret(Secret secret) {
      this.secret = secret;
   }

   @Override
   public List<TestReturn> runTest(Service service, Operation operation, TestResult testResult, List<Request> requests,
         String endpointUrl, HttpMethod method) throws URISyntaxException, IOException {

      log.debug("Launching test run on {} for {} request(s)", endpointUrl, requests.size());

      if (requests.isEmpty()) {
         return null;
      }

      // Initialize results.
      List<TestReturn> results = new ArrayList<>();

      // Rebuild the GRPC fullMethodName.
      String fullMethodName = service.getName() + "/" + operation.getName();

      // Build a new GRPC Channel from endpoint URL.
      URL endpoint = new URL(endpointUrl);

      ManagedChannel originChannel;
      if (endpointUrl.startsWith("https://") || endpoint.getPort() == 443) {
         TlsChannelCredentials.Builder tlsBuilder = TlsChannelCredentials.newBuilder();
         if (secret != null && secret.getCaCertPem() != null) {
            // Install a trust manager with custom CA certificate.
            tlsBuilder.trustManager(new ByteArrayInputStream(secret.getCaCertPem().getBytes(StandardCharsets.UTF_8)));
         } else {
            // Install a trust manager that accepts everything and does not validate certificate chains.
            tlsBuilder.trustManager(new X509TrustManager() {
               public java.security.cert.X509Certificate[] getAcceptedIssuers() {
                  return null;
               }

               public void checkClientTrusted(X509Certificate[] certs, String authType) {
                  // Accept everything.
               }

               public void checkServerTrusted(X509Certificate[] certs, String authType) {
                  // Accept everything.
               }
            });
         }
         // Build a Channel using the TLS Builder.
         originChannel = Grpc.newChannelBuilderForAddress(endpoint.getHost(), endpoint.getPort(), tlsBuilder.build())
               .build();
      } else {
         // Build a simple Channel using no creds (now default to plain text so usePlainText() is no longer necessary).
         originChannel = Grpc
               .newChannelBuilderForAddress(endpoint.getHost(), endpoint.getPort(), InsecureChannelCredentials.create())
               .build();
      }
      // Add a custom header interceptor which adds the request-specific headers to
      // every operation
      ClientInterceptor headerInterceptor = new HeaderInterceptor();
      Channel channel = ClientInterceptors.intercept(originChannel, headerInterceptor);

      // In order to produce outgoing byte array, we need the Protobuf binary descriptor that should
      // have been processed while importing the .proto schema for the service.
      List<Resource> resources = resourceRepository.findByServiceIdAndType(service.getId(),
            ResourceType.PROTOBUF_DESCRIPTOR);
      if (resources == null || resources.size() != 1) {
         log.error("Could not found any pre-processed Protobuf binary descriptor...");
         results.add(new TestReturn(TestReturn.FAILURE_CODE, 0,
               "Could not found any pre-processed Protobuf binary descriptor...", null, null));
         return results;
      }
      Resource pbResource = resources.get(0);

      Descriptors.MethodDescriptor md = null;
      try {
         md = GrpcUtil.findMethodDescriptor(pbResource.getContent(), service.getName(), operation.getName());
      } catch (Exception e) {
         log.error("Protobuf descriptor cannot be read or parsed: {}", e.getMessage());
         results.add(new TestReturn(TestReturn.FAILURE_CODE, 0,
               "Protobuf descriptor cannot be read or parsed: " + e.getMessage(), null, null));
         return results;
      }

      // Use a builder for out type with a Json parser to merge content and build outMsg.
      DynamicMessage.Builder reqBuilder = DynamicMessage.newBuilder(md.getInputType());
      DynamicMessage.Builder resBuilder = DynamicMessage.newBuilder(md.getOutputType());
      JsonFormat.Parser parser = JsonFormat.parser();
      JsonFormat.Printer printer = JsonFormat.printer();

      for (Request request : requests) {
         // Reset status code, message and request each time.
         int code = TestReturn.SUCCESS_CODE;
         String message = null;
         String contentResponse = null;
         String statusCode = null;

         reqBuilder.clear();
         resBuilder.clear();

         // Now produce the request message byte array.
         parser.merge(request.getContent(), reqBuilder);
         byte[] requestBytes = reqBuilder.build().toByteArray();

         CallOptions callOptions = CallOptions.DEFAULT.withDeadline(Deadline.after(timeout, TimeUnit.MILLISECONDS));

         if (secret != null && secret.getToken() != null) {
            log.debug("Secret contains token and maybe token header, adding them as call credentials");
            callOptions = callOptions
                  .withCallCredentials(new TokenCallCredentials(secret.getToken(), secret.getTokenHeader()));
         }
         // Add all headers as customOptions to callOptions
         Set<Header> headers = TestRunnerCommons.collectHeaders(testResult, request, operation);
         callOptions = callOptions.withOption(METADATA_CUSTOM_CALL_OPTION, convertHeadersToMetadata(headers));

         // Actually execute request.
         long startTime = System.currentTimeMillis();
         byte[] responseBytes = null;
         try {
            responseBytes = ClientCalls.blockingUnaryCall(channel,
                  GrpcUtil.buildGenericUnaryMethodDescriptor(fullMethodName), callOptions, requestBytes);
         } catch (StatusRuntimeException sre) {
            log.error("StatusRuntimeException while executing grpc request {} on {}", fullMethodName, endpointUrl, sre);
            code = TestReturn.FAILURE_CODE;
            Status status = sre.getStatus();
            statusCode = status.getCode().name();
            message = String.format("Request failed with %s and description %s", statusCode, status.getDescription());
         }
         long duration = System.currentTimeMillis() - startTime;

         // If still in success, validate and parse response
         if (code == TestReturn.SUCCESS_CODE) {
            statusCode = Code.OK.name();
            contentResponse = new String(responseBytes, StandardCharsets.UTF_8);

            try {
               // Validate incoming message parsing a DynamicMessage.
               DynamicMessage respMsg = DynamicMessage.parseFrom(md.getOutputType(), responseBytes);

               // Now update response content with readable content.
               contentResponse = printer.print(respMsg);
            } catch (InvalidProtocolBufferException ipbe) {
               log.error("Received bytes cannot be transformed in {}", md.getOutputType().getFullName());
               code = TestReturn.FAILURE_CODE;
               message = "Received bytes cannot be transformed in " + md.getOutputType().getFullName();
            }
         }

         // Create a Response object for returning.
         Response response = new Response();
         response.setStatus(statusCode);
         response.setMediaType("application/x-protobuf");
         response.setContent(contentResponse);

         results.add(new TestReturn(code, duration, message, request, response));
      }
      return results;
   }

   private static Metadata convertHeadersToMetadata(Set<Header> headers) {
      Metadata metadata = new Metadata();
      for (Header header : headers) {
         for (String value : header.getValues()) {
            metadata.put(Metadata.Key.of(header.getName(), Metadata.ASCII_STRING_MARSHALLER), value);
         }
      }
      return metadata;
   }

   /**
    * Build the HttpMethod corresponding to string.
    */
   @Override
   public HttpMethod buildMethod(String method) {
      return HttpMethod.POST;
   }

}

public class PostmanTestStepsRunner extends AbstractTestRunner<HttpMethod> {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(PostmanTestStepsRunner.class);

   private ObjectMapper mapper = new ObjectMapper();

   private JsonNode collection;

   private ResourceRepository resourceRepository;
   private ClientHttpRequestFactory clientHttpRequestFactory;

   private String testsCallbackUrl = null;

   private String postmanRunnerUrl = null;

   /**
    * Build a new PostmanTestStepsRunner for a collection.
    * @param resourceRepository The repository that contains Postman Collection to test
    */
   public PostmanTestStepsRunner(ResourceRepository resourceRepository) {
      this.resourceRepository = resourceRepository;
   }

   /**
    * Set the ClientHttpRequestFactory used for reaching endpoint.
    * @param clientHttpRequestFactory The ClientHttpRequestFactory used for reaching endpoint
    */
   public void setClientHttpRequestFactory(ClientHttpRequestFactory clientHttpRequestFactory) {
      this.clientHttpRequestFactory = clientHttpRequestFactory;
