   }

   @Override
   public List<TestReturn> runTest(Service service, Operation operation, TestResult testResult, List<Request> requests,
         String endpointUrl, HttpMethod method) throws URISyntaxException, IOException {
      if (log.isDebugEnabled()) {
         log.debug("Launching test run on {} for {} request(s)", endpointUrl, requests.size());
      }

      // Retrieve the resource corresponding to OpenAPI specification if any.
      Resource collectionResource = null;
      List<Resource> resources = resourceRepository.findByServiceId(service.getId());
      for (Resource resource : resources) {
         if (ResourceType.POSTMAN_COLLECTION.equals(resource.getType())) {
            collectionResource = resource;
            break;
         }
      }

      // Convert them to Node using Jackson object mapper.
      try {
         collection = mapper.readTree(collectionResource.getContent());
      } catch (Exception e) {
         throw new IOException("Postman collection file cannot be found or parsed", e);
      }

      // Sanitize endpoint url.
      if (endpointUrl.endsWith("/")) {
         endpointUrl = endpointUrl.substring(0, endpointUrl.length() - 1);
      }

      // Microcks-postman-runner interface object building.
      ObjectNode jsonArg = mapper.createObjectNode();
      jsonArg.put("operation", operation.getName());
      jsonArg.put("callbackUrl", testsCallbackUrl + "/api/tests/" + testResult.getId() + "/testCaseResult");

      // First we have to retrieved and add the test script for this operation from within Postman collection.
      JsonNode testScript = extractOperationTestScript(operation);
      if (testScript != null) {
         log.debug("Found a testScript for this operation !");
         jsonArg.set("testScript", testScript);
      } else {
         // We have nothing to test and Postman runner will reject the request without testScript.
         log.info("No testScript found for operation '{}', marking it as failed", operation.getName());
         return requests.stream().map(request -> new TestReturn(TestReturn.FAILURE_CODE, 0,
               "Not executed cause no Test Script found for this operation", request, new Response())).toList();
      }

      // Then we have to add the corresponding 'requests' objects.
      ArrayNode jsonRequests = mapper.createArrayNode();
      for (Request request : requests) {
         ObjectNode jsonRequest = mapper.createObjectNode();

         String operationName = operation.getName().substring(operation.getName().indexOf(" ") + 1);
         String customizedEndpointUrl = endpointUrl
               + URIBuilder.buildURIFromPattern(operationName, request.getQueryParameters());
         log.debug("Using customized endpoint url: {}", customizedEndpointUrl);

         jsonRequest.put("endpointUrl", customizedEndpointUrl);
         jsonRequest.put("method", operation.getMethod());
         jsonRequest.put("name", request.getName());

         if (request.getContent() != null && !request.getContent().isEmpty()) {
            jsonRequest.put("body", request.getContent());
         }
         if (request.getQueryParameters() != null && !request.getQueryParameters().isEmpty()) {
            ArrayNode jsonParams = buildQueryParams(request.getQueryParameters());
            jsonRequest.set("queryParams", jsonParams);
         }
         // Set headers to request if any. Start with those coming from request itself.
         // Add or override existing headers with test specific ones for operation and globals.
         Set<Header> headers = TestRunnerCommons.collectHeaders(testResult, request, operation);
         if (!headers.isEmpty()) {
            ArrayNode jsonHeaders = buildHeaders(headers);
            jsonRequest.set("headers", jsonHeaders);
         }

         jsonRequests.add(jsonRequest);
      }
      jsonArg.set("requests", jsonRequests);

      URI postmanRunnerURI = new URI(postmanRunnerUrl + "/tests/" + testResult.getId());
      ClientHttpRequest httpRequest = clientHttpRequestFactory.createRequest(postmanRunnerURI, HttpMethod.POST);
      httpRequest.getBody().write(mapper.writeValueAsBytes(jsonArg));
      httpRequest.getHeaders().add("Content-Type", "application/json");

      // Actually execute request.
      ClientHttpResponse httpResponse = null;
      try {
         httpResponse = httpRequest.execute();
      } catch (IOException ioe) {
         log.error("IOException while executing request ", ioe);
      } finally {
         if (httpResponse != null) {
            httpResponse.close();
         }
      }

      return new ArrayList<>();
   }

   @Override
   public HttpMethod buildMethod(String method) {
      return null;
   }

   private JsonNode extractOperationTestScript(Operation operation) {
      List<JsonNode> collectedScripts = new ArrayList<>();

      Iterator<JsonNode> items = collection.path("item").elements();
      while (items.hasNext()) {
         JsonNode item = items.next();
         extractTestScript("", item, operation, collectedScripts);
      }
      if (!collectedScripts.isEmpty()) {
         return collectedScripts.get(0);
      }
      return null;
   }

   private void extractTestScript(String operationNameRadix, JsonNode itemNode, Operation operation,
         List<JsonNode> collectedScripts) {
      String itemNodeName = itemNode.path("name").asText();

      // Item may be a folder or an operation description.
      if (!itemNode.has("request")) {
         // Item is simply a folder that may contain some other folders recursively.
         Iterator<JsonNode> items = itemNode.path("item").elements();
         while (items.hasNext()) {
            JsonNode item = items.next();
            extractTestScript(operationNameRadix + "/" + itemNodeName, item, operation, collectedScripts);
         }
      } else {
         // Item is here an operation description.
         String operationName = PostmanCollectionImporter.buildOperationName(itemNode, operationNameRadix);
         log.debug("Found operation '{}', comparing with '{}'", operationName, operation.getName());
         if (PostmanUtil.areOperationsEquivalent(operation.getName(), operationName)) {
            // We've got the correct operation.
            JsonNode events = itemNode.path("event");
            for (JsonNode event : events) {
               if ("test".equals(event.path("listen").asText())) {
                  log.debug("Found a matching event where listen=test");
                  collectedScripts.add(event);
               }
            }
         }
      }
   }

   private ArrayNode buildQueryParams(List<Parameter> queryParameters) {
      ArrayNode jsonQPS = mapper.createArrayNode();
      for (Parameter parameter : queryParameters) {
         ObjectNode jsonQP = mapper.createObjectNode();
         jsonQP.put("key", parameter.getName());
         jsonQP.put("value", parameter.getValue());
         jsonQPS.add(jsonQP);
      }
      return jsonQPS;
   }

   private ArrayNode buildHeaders(Set<Header> headers) {
      ArrayNode jsonHS = mapper.createArrayNode();
      for (Header header : headers) {
         ObjectNode jsonH = mapper.createObjectNode();
         jsonH.put("key", header.getName());
         jsonH.put("value", buildValue(header.getValues()));
         jsonHS.add(jsonH);
      }
      return jsonHS;
   }
}

public class SoapUIAssertionsTestRunner extends HttpTestRunner {

   /** A simple logger for diagnostic messages. */
   private static final Logger log = LoggerFactory.getLogger(SoapUIAssertionsTestRunner.class);

   /** The URL of resources used for validation. */
   private String resourceUrl = null;

   private final ResourceRepository resourceRepository;
   private final Map<ResourceType, Resource> cachedResources = new HashMap<>();

   private Element projectElement;

   private List<String> lastValidationErrors = null;

   private long startTimestamp;


   public SoapUIAssertionsTestRunner(ResourceRepository resourceRepository) {
      this.resourceRepository = resourceRepository;
   }

   /**
    * The URL of resources used for validation.
    * @return The URL of resources used for validation
    */
   public String getResourceUrl() {
      return resourceUrl;
   }

   /**
    * The URL of resources used for validation.
    * @param resourceUrl The URL of resources used for validation.
    */
   public void setResourceUrl(String resourceUrl) {
      this.resourceUrl = resourceUrl;
   }

   @Override
   public HttpMethod buildMethod(String method) {
      return super.buildMethod(method);
   }

   @Override
   protected void prepareRequest(Request request) {
      startTimestamp = System.currentTimeMillis();
   }

   @Override
   protected int extractTestReturnCode(Service service, Operation operation, Request request,
         ClientHttpResponse httpResponse, String responseContent) {
      // Stop timer and initialize code.
      long duration = System.currentTimeMillis() - startTimestamp;
      int code = TestReturn.SUCCESS_CODE;

      // If first request of this runner, we should retrieve resources and cache them.
      if (cachedResources.isEmpty()) {
         List<Resource> resources = resourceRepository.findByServiceId(service.getId());
         for (Resource resource : resources) {
            cachedResources.put(resource.getType(), resource);
         }
      }

      // If first request of this runner, we should parse SoapUI project.
      if (projectElement == null) {
         Resource soapuiProject = cachedResources.get(ResourceType.SOAP_UI_PROJECT);
         try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setNamespaceAware(true);
            DocumentBuilder documentBuilder = factory.newDocumentBuilder();
            projectElement = documentBuilder.parse(new InputSource(new StringReader(soapuiProject.getContent())))
                  .getDocumentElement();
         } catch (Exception e) {
            log.error("Exception while parsing SoapUI resource content {}", soapuiProject.getName(), e);
            return TestReturn.FAILURE_CODE;
         }
      }

      try {
         Map<String, Element> testConfigRequests = collectTestStepsConfigRequest(operation);
         Element testRequest = testConfigRequests.get(getRequestShortName(request.getName()));

         // Now validate the embedded assertions.
         List<Element> assertions = getConfigDirectChildren(testRequest, "assertion");
         for (Element assertion : assertions) {
            String type = assertion.getAttribute("type");
            Map<String, String> configParams = buildParamsMapFromConfiguration(assertion);

            SoapUIAssertion sAssertion = AssertionFactory.intializeAssertion(type, configParams);
            AssertionStatus status = sAssertion.assertResponse(
                  new RequestResponseExchange(request, httpResponse, responseContent, duration),
                  new ExchangeContext(service, operation, List.copyOf(cachedResources.values()), resourceUrl));

            if (status == AssertionStatus.FAILED) {
               code = TestReturn.FAILURE_CODE;
               if (lastValidationErrors == null) {
                  lastValidationErrors = new ArrayList<>();
               }
               lastValidationErrors.addAll(sAssertion.getErrorMessages());
            }
         }
      } catch (MalformedXmlException e) {
         log.error("Exception while parsing SoapUI resource content for assertion on {}", operation.getName(), e);
         return TestReturn.FAILURE_CODE;
      }

      return code;
   }

   @Override
   protected String extractTestReturnMessage(Service service, Operation operation, Request request,
         ClientHttpResponse httpResponse) {
      StringBuilder builder = new StringBuilder();
      if (lastValidationErrors != null && !lastValidationErrors.isEmpty()) {
         for (String error : lastValidationErrors) {
            builder.append(error).append('\n');
         }
      }
      // Reset just after consumption so avoid side-effects.
      lastValidationErrors = null;
      return builder.toString();
   }

   private Map<String, Element> collectTestStepsConfigRequest(Operation operation) throws MalformedXmlException {
      Map<String, Element> results = new HashMap<>();

      List<Element> testSuites = getConfigDirectChildren(projectElement, "testSuite");
      for (Element testSuite : testSuites) {
         List<Element> testCases = getConfigDirectChildren(testSuite, "testCase");
         for (Element testCase : testCases) {
            List<Element> testSteps = getConfigDirectChildren(testCase, "testStep");
            for (Element testStep : testSteps) {
               Element config = getConfigUniqueDirectChild(testStep, "config");

               String operationName = null;
               if (hasConfigDirectChild(config, "operation")) {
                  // Soap/Wsdl test request with operation reference.
                  operationName = getConfigUniqueDirectChild(config, "operation").getTextContent();
                  if (operation.getName().equals(operationName)) {
                     results.put(getRequestShortName(testStep.getAttribute("name")),
                           getConfigUniqueDirectChild(config, "request"));
                  }
               } else if (config.hasAttribute("resourcePath")) {
                  // Rest test request with resourcePath as operation reference.
                  operationName = config.getAttribute("resourcePath");
                  if (operation.getName().equals(operationName)) {
                     results.put(getRequestShortName(testStep.getAttribute("name")),
                           SoapUIProjectParserUtils.getConfigUniqueDirectChild(config, "restRequest"));
                  }
               }
            }
         }
      }
      return results;
   }

   /** If a request name ends with " Request", we remove it to get a short name. */
   private String getRequestShortName(String longName) {
      if (longName.endsWith(" Request")) {
         return longName.substring(0, longName.length() - " Request".length());
      }
      return longName;
   }

   private Map<String, String> buildParamsMapFromConfiguration(Element assertion) {
      Map<String, String> params = new HashMap<>();
      if (hasConfigDirectChild(assertion, "configuration")) {
         try {
            Element configuration = getConfigUniqueDirectChild(assertion, "configuration");
            NodeList children = configuration.getChildNodes();
            for (int i = 0; i < children.getLength(); i++) {
               Node child = children.item(i);
               params.put(child.getLocalName(), child.getTextContent());
            }
         } catch (MalformedXmlException mfe) {
            // Just ignore this as it must not happen.
         }
      }
      return params;
   }
}

public abstract class AbstractTestRunner<T> {

   /**
    * Run a test for a specified service and operation.
    * @param service     The service under test
    * @param operation   The operation to test
    * @param testResult  The container for test results
    * @param requests    A set of reference requests for operation
    * @param endpointUrl The URL of endpoint to test
    * @param method      The method that applies for requesting service (retrieved using buildMethod() method)
    * @return A list of TestReturn corresponding to the result of test for each reference requests. Returns indices
    *         matches reference request indices.
    * @throws java.net.URISyntaxException if endpointUrl cannot be transformed as URI
    * @throws java.io.IOException         in case of network failure mainly
    */
   public abstract List<TestReturn> runTest(Service service, Operation operation, TestResult testResult,
         List<Request> requests, String endpointUrl, T method) throws URISyntaxException, IOException;

   /**
    * (interpretation is subject to implementation)
    * @param method String representation of method
    * @return Object representing method
    */
   public abstract T buildMethod(String method);

   /**
    * Build a single string value from values set.
    * @param values Strings to build value from
    * @return Comma separated string of values
    */
   protected String buildValue(Set<String> values) {
      if (values == null || values.isEmpty()) {
         return null;
      }
      StringBuilder result = new StringBuilder();
      Iterator<String> iterator = values.iterator();
      result.append(iterator.next());
      while (iterator.hasNext()) {
         result.append(",");
         result.append(iterator.next());
      }

      return result.toString();
   }
}

