   private String id;
   private String serviceId;
   private String key;
   private String value;
   @Indexed(expireAfterSeconds = 0)
   private Date expireAt;


   /** Build a ServiceState. */
   public ServiceState() {
   }

   /**
    * Build a ServiceState with required information.
    * @param serviceId The unique identifier of Service this state relates to
    * @param key       The key a value will be stored for
    */
   public ServiceState(String serviceId, String key) {
      this.serviceId = serviceId;
      this.key = key;
   }

   public String getId() {
      return id;
   }

   public void setId(String id) {
      this.id = id;
   }

   public String getServiceId() {
      return serviceId;
   }

   public void setServiceId(String serviceId) {
      this.serviceId = serviceId;
   }

   public String getKey() {
      return key;
   }

   public void setKey(String key) {
      this.key = key;
   }

   public String getValue() {
      return value;
   }

   public void setValue(String value) {
      this.value = value;
   }

   public Date getExpireAt() {
      return expireAt;
   }

   public void setExpireAt(Date expireAt) {
      this.expireAt = expireAt;
   }
}

public interface StateStore {

   /**
    * Put a KV into the store.
    * @param key   The unique key
    * @param value The value corresponding to key
    */
   void put(String key, String value);

   /**
    * Put a KV into the store with a specific Time To Live.
    * @param key        The unique key
    * @param value      The value corresponding to key
    * @param secondsTTL The TTL in seconds
    */
   void put(String key, String value, int secondsTTL);

   /**
    * Retrieve a state value using its unique key.
    * @param key The unique key to get value for
    * @return The state value (it may be null)
    */
   @Nullable
   String get(String key);

   /**
    * Delete a key corresponding to this unique key.
    * @param key The unique key to remove value for
    */
   void delete(String key);
}

