public class JsonPathContentAssertion extends WildcardMatchingAssertion {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(JsonPathContentAssertion.class);

   /** The JsonPath expression. Value is a string with a valid JsonPath expression. */
   public static final String PATH_PARAM = "path";

   /** The expected content param. Value is a string that may contain wildcards if `allowWildcards` is set to true. */
   public static final String EXPECTED_CONTENT_PARAM = "content";


   private String path;

   private String expectedContent;

   private String errorMessage;


   @Override
   public void configure(Map<String, String> configParams) {
      super.configure(configParams);
      path = configParams.get(PATH_PARAM);
      expectedContent = configParams.get(EXPECTED_CONTENT_PARAM);
   }

   @Override
   public AssertionStatus assertResponse(RequestResponseExchange exchange, ExchangeContext context) {
      log.debug("Asserting JsonPath on {}, expecting: {}", path, expectedContent);

      if (path == null) {
         errorMessage = "Missing path for JsonPath assertion";
         return AssertionStatus.FAILED;
      }
      if (expectedContent == null) {
         errorMessage = "Missing content for JsonPath assertion";
         return AssertionStatus.FAILED;
      }

      try {
         // Parse json text ang get root node.
         ObjectMapper mapper = new ObjectMapper();
         JsonNode rootNode = mapper.readTree(new StringReader(exchange.responseContent()));

         // Retrieve evaluated node within JSON tree.
         JsonNode evaluatedNode = rootNode.at(path);
         String result = evaluatedNode.asText();

         if (allowWildcards) {
            if (!isSimilar(expectedContent, result)) {
               errorMessage = "Comparison failed for path [" + path + "], expecting [" + expectedContent
                     + "], actual was [" + result + "]";
               return AssertionStatus.FAILED;
            }
         } else {
            if (!expectedContent.equals(result)) {
               errorMessage = "Comparison failed for path [" + path + "], expecting [" + expectedContent
                     + "], actual was [" + result + "]";
               return AssertionStatus.FAILED;
            }
         }
      } catch (Exception e) {
         log.warn("Exception while compiling/evaluating JsonPointer", e);
         errorMessage = "Exception while compiling/evaluating JoinPointer: " + path;
         return AssertionStatus.FAILED;
      }
      return AssertionStatus.VALID;
   }

   @Override
   public List<String> getErrorMessages() {
      return List.of(errorMessage);
   }
}

public class NotSoapFaultAssertion implements SoapUIAssertion {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(NotSoapFaultAssertion.class);

   /** Regular expression pattern for capturing Soap Fault name from body. */
   private static final Pattern FAULT_CAPTURE_PATTERN = Pattern.compile("(.*):Body>(\\s*)<((\\w+):|)Fault(.*)(/)?>(.*)",
         Pattern.DOTALL);

   private String errorMessage;

   @Override
   public void configure(Map<String, String> configParams) {
   }

   @Override
   public AssertionStatus assertResponse(RequestResponseExchange exchange, ExchangeContext context) {
      log.debug("Asserting response is not a SOAP Fault");

      String responseContent = exchange.responseContent();
      // First check presence of Fault tag in content.
      if (responseContent.contains(":Fault") || responseContent.contains("<Fault")) {
         log.debug("Found some Fault in body");
         Matcher matcher = FAULT_CAPTURE_PATTERN.matcher(responseContent);
         if (matcher.find()) {
            log.debug("RegExp is matching, that's a fault!");
            errorMessage = "Response is a SOAP Fault";
            return AssertionStatus.FAILED;
         }
      }
      return AssertionStatus.VALID;
   }

   @Override
   public List<String> getErrorMessages() {
      return List.of(errorMessage);
   }
}

public class SchemaConformanceAssertion implements SoapUIAssertion {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(SchemaConformanceAssertion.class);

   /** The definition parameter to embed a schema definition as a string. */
   public static final String DEFINITION_PARAM = "definition";

   private String definition;

   private List<String> errorMessages;

   @Override
   public void configure(Map<String, String> configParams) {
      if (configParams.containsKey(DEFINITION_PARAM)) {
         definition = configParams.get(DEFINITION_PARAM);
      }
   }

   @Override
   public AssertionStatus assertResponse(RequestResponseExchange exchange, ExchangeContext context) {

      if (context.service().getType() == ServiceType.SOAP_HTTP) {
         log.debug("Asserting Soap response is valid against WSDL");

         // Validate against Soap message against WSDL.
         Resource wsdl = context.resources().stream().filter(r -> r.getType() == ResourceType.WSDL).findFirst().get();
         QName partQName = new QName(context.service().getXmlNS(), context.operation().getOutputName());
         errorMessages = SoapMessageValidator.validateSoapMessage(wsdl.getContent(), partQName,
               exchange.responseContent(), context.resourceUrl());
         if (!errorMessages.isEmpty()) {
            log.debug("Soap response is not valid: {} errors", errorMessages.size());
            return AssertionStatus.FAILED;
         }
      } else if (definition != null) {
         // Only managed Xml validation at the moment.
         if (exchange.response().getHeaders().getConnection() != null
               && exchange.response().getHeaders().getConnection().contains("xml")) {
            log.debug("Asserting Xml response is valid against local definition");

            try {
               errorMessages = XmlSchemaValidator.validateXml(
                     new ByteArrayInputStream(definition.getBytes(StandardCharsets.UTF_8)), exchange.responseContent(),
                     context.resourceUrl());
            } catch (Exception e) {
