public class XmlSchemaValidator {

   private XmlSchemaValidator() {
      // Hide the implicit default constructor.
   }

   /**
    * Validation the Xml string with provided stream on its Xml schema.
    * @param schemaStream A stream on reference Xml Schema
    * @param xmlString    String representation of Xml to validate
    * @return A list of validation errors that mey be empty if validation is ok
    * @throws Exception if validator cannot be initialized (in case of malformed schema stream)
    */
   public static List<String> validateXml(InputStream schemaStream, String xmlString) throws Exception {
      return validateXml(schemaStream, xmlString, null);
   }

   /**
    * Validation the Xml string with provided stream on its Xml schema. A resource URL can be provided to resolved
    * relative includes found into Xml Schema stream.
    * @param schemaStream    A stream on reference Xml Schema
    * @param xmlString       String representation of Xml to validate
    * @param baseResourceUrl Base resource URL for resolving relative dependencies
    * @return A list of validation errors that mey be empty if validation is ok
    * @throws Exception if validator cannot be initialized (in case of malformed schema stream)
    */
   public static List<String> validateXml(InputStream schemaStream, String xmlString, String baseResourceUrl)
         throws Exception {
      SchemaFactory factory = SchemaFactory.newDefaultInstance();
      factory.setResourceResolver(new XmlSchemaURLResolver(baseResourceUrl));

      Source schemaFile = new StreamSource(schemaStream);
      Schema schema = factory.newSchema(schemaFile);
      Validator validator = schema.newValidator();

      XmlErrorHandler errorHandler = new XmlErrorHandler();
      validator.setErrorHandler(errorHandler);

      validator.validate(new StreamSource(new StringReader(xmlString)));

      return errorHandler.getExceptions().stream().map(e -> "line " + e.getLineNumber() + ": " + e.getMessage())
            .toList();
   }
}

public abstract class WildcardMatchingAssertion implements SoapUIAssertion {

   /** A simple logger for diagnostic messages. */
   private static Logger log = LoggerFactory.getLogger(WildcardMatchingAssertion.class);

   /**
    * Allow wildcards configuration parameter. Value is expected to be parsed as boolean: "true" or "false". Default is
    * false.
    */
   public static final String ALLOW_WILDCARDS = "allowWildcards";

   protected boolean allowWildcards = false;

   @Override
   public void configure(Map<String, String> configParams) {
      if (configParams.containsKey(ALLOW_WILDCARDS)) {
         allowWildcards = Boolean.valueOf(configParams.get(ALLOW_WILDCARDS));
      }
   }

   /**
    * Managed wildcards specified in expected content to check if real content is similar.
    * @param expectedContent Expected content with wildcards
    * @param realContent     Real content to match
    * @return true if matching, false otherwise
    */
   protected boolean isSimilar(String expectedContent, String realContent) {
      // Build a pattern from expected content.
      StringBuilder patternBuilder = new StringBuilder();
      if (expectedContent.startsWith("*")) {
         patternBuilder.append(".*");
      }
      String[] tokens = expectedContent.split(Pattern.quote("*"));
      boolean first = true;
      for (int i = 0; i < tokens.length; ++i) {
         String token = tokens[i];
         if (!token.isEmpty()) {
            if (!first) {
               patternBuilder.append(".*");
            }
            first = false;
            patternBuilder.append(Pattern.quote(token));
         }
      }
      if (expectedContent.endsWith("*")) {
         patternBuilder.append(".*");
      }

      log.debug("Compiled a pattern for wildcard match, will use '{}'", patternBuilder);

      return Pattern.compile(patternBuilder.toString()).matcher(realContent).matches();
   }
}

